function genCatId(prefix){ return prefix+'_'+Date.now(); }

// ── Per-category weekly budget ────────────────────────────────────
// The category's own `budget` field is the single source of truth for its weekly target.
// Before this, the target lived in budgetConfig — a second, independently-edited list that
// shared no ids with these categories, so the two drifted (a category added in the Budget
// tab had no plan entry; a plan entry renamed in Settings stopped matching). Anything that
// wants "the target for this category" reads catBudget(); nothing name-matches any more.
const BUD_CAT_KEY={fix:'daily_budget_fix_cats', var:'daily_budget_var_cats', inc:'daily_budget_inc_cats'};
const BUD_CFG_KEY={fix:'fixedExpenses', var:'variableExpenses', inc:'incomeStreams'};
// ── Billing cycles ────────────────────────────────────────────────
// A fixed expense is often billed on a cycle that isn't weekly — rego yearly, a subscription
// monthly — and converting that by hand every time is exactly what the old, separate
// subscriptions list existed to do. A category can now carry the amount it's ACTUALLY billed
// plus its cycle; `budget` stays the canonical weekly figure everything else reads, and is
// recomputed from those two whenever either changes (see catUpdateField).
// 52/12 rather than the 4.33 used elsewhere: exact, so a yearly and a monthly entry of the
// same annual cost agree to the cent.
const CAT_CYCLES=[
  {id:'weekly',  label:'Weekly',  suffix:'/wk', perWeek:1},
  {id:'monthly', label:'Monthly', suffix:'/mo', perWeek:12/52},
  {id:'yearly',  label:'Yearly',  suffix:'/yr', perWeek:1/52},
];
function cyclePerWeek(cycle){ const c=CAT_CYCLES.find(x=>x.id===cycle); return c?c.perWeek:1; }
function catWeeklyFromAmount(amount,cycle){
  const a=parseFloat(amount);
  if(isNaN(a)) return '';
  return Math.round(a*cyclePerWeek(cycle)*100)/100;
}
// What the user typed, in the cycle they typed it in. Falls back to the weekly budget for
// categories that predate cycles (they're weekly by definition).
function catAmount(c){
  if(!c) return '';
  if(c.amount!=null&&c.amount!=='') return c.amount;
  if(c.budget!=null&&c.budget!=='') return c.budget;
  return (c.default!=null&&c.default!=='')?c.default:'';
}
function catCycle(c){ return (c&&c.cycle)||'weekly'; }
const CAT_CHARGE_TYPES=[
  {id:'subscription', label:'Subscription'},
  {id:'bill',         label:'Bill'},
  {id:'payment_plan', label:'Payment plan'},
  {id:'commitment',   label:'Other commitment'}
];
// Older records have no type. Infer it at read time instead of running a boot migration that
// could stamp defaults as new data and outrank the cloud. Saving any edit makes the choice
// explicit through the Settings selector.
function catChargeType(c){
  const explicit=c&&String(c.chargeType||'');
  if(CAT_CHARGE_TYPES.some(x=>x.id===explicit)) return explicit;
  const name=String(c&&c.name||'').toLowerCase();
  const site=String(c&&c.site||'').toLowerCase();
  const text=name+' '+site;
  if(/rego|registration|ctp|green.?slip|insurance|budget direct|roadside/.test(name)) return 'bill';
  if(/fine|repay|payment plan|revenue nsw|service nsw/.test(text)) return 'payment_plan';
  if(/insurance|budget direct|roadside/.test(text)) return 'bill';
  if(/fitness|gym|netflix|spotify|disney|binge|stan|kayo|youtube|amazon prime|paramount|claude|chatgpt|openai|icloud|apple music|apple tv|uber one|telstra|optus|vodafone|belong|canva/.test(text)) return 'subscription';
  return catCycle(c)==='weekly'?'commitment':'subscription';
}
function catChargeTypeLabel(value){
  const id=typeof value==='string'?value:catChargeType(value);
  return (CAT_CHARGE_TYPES.find(x=>x.id===id)||CAT_CHARGE_TYPES[3]).label;
}
function catIsRecurring(c){ return catChargeType(c)!=='commitment'; }
// ── Category logos ────────────────────────────────────────────────
// A category can carry the website of the thing it pays for; its favicon becomes the row
// icon. DuckDuckGo's icon service is used rather than Google's: no key either way, but this
// one doesn't feed an advertising profile with the list of services you pay for.
// Note a real limitation — a mistyped domain does NOT error, both services just hand back a
// generic globe. There's no way to tell "no logo" from "wrong domain" from the image alone,
// so the field stays freely editable and the letter placeholder is always a valid choice.
function catSiteDomain(raw){
  let s=String(raw||'').trim().toLowerCase();
  if(!s) return '';
  s=s.replace(/^[a-z]+:\/\//,'').replace(/^www\./,'');   // strip scheme + www
  s=s.split('/')[0].split('?')[0].split('#')[0];          // host only
  return /^[a-z0-9.-]+\.[a-z]{2,}$/.test(s)?s:'';
}
function catLogoUrl(c){
  const d=catSiteDomain(c&&c.site);
  return d?'https://icons.duckduckgo.com/ip3/'+d+'.ico':'';
}
// Emoji were how these rows used to be identified, before logos. They're still sitting in
// some names as a decorative prefix ("☁️ Claude"), which would double up next to a logo —
// strip them for display only, leaving the stored name untouched.
function catDisplayName(name){
  return String(name||'').replace(/^[^\p{L}\p{N}$]+/u,'').trim()||String(name||'').trim();
}
function catInitial(name){
  const n=catDisplayName(name);
  return n?n.charAt(0).toUpperCase():'?';
}
// Falls back to the initial if there's no site, and also if the logo fails to load.
function catIconHtml(c,size){
  const px=size||22;
  const url=catLogoUrl(c);
  const style='width:'+px+'px;height:'+px+'px;border-radius:'+Math.round(px*0.27)+'px;flex-shrink:0';
  const fallback='<span class="cat-icon-letter" style="'+style+';font-size:'+Math.round(px*0.5)+'px">'+_catEscHtml(catInitial(c&&c.name))+'</span>';
  if(!url) return fallback;
  // Not loading="lazy": these are ~20px icons in a short list, so deferring them saves
  // nothing and just risks them never resolving if the list renders off-screen.
  return '<img class="cat-icon-img" src="'+url+'" alt="" style="'+style+'" '+
    'onerror="this.outerHTML='+_catEsc(JSON.stringify(fallback))+'">';
}
function catBudget(c){
  if(!c) return 0;
  if(c.budget!=null&&c.budget!=='') return parseFloat(c.budget)||0;
  return parseFloat(c.default)||0;   // pre-migration fixed categories
}
function catBudgetTotal(type){ return activeCats(BUD_CAT_LOAD[type]?BUD_CAT_LOAD[type]():[]).reduce((s,c)=>s+catBudget(c),0); }
// One-time fold of the separate subscriptions list into the fixed categories. The two lists
// were never actually connected — subscriptions only ever wrote to a legacy defaults key and
// to a DOM input that usually wasn't on screen — so a $125/wk subscription load sat entirely
// outside the weekly budget. Each subscription becomes a real fixed category billed on its
// own cycle, so it now counts.
// Best-effort website for a well-known name, so migrated entries arrive with a logo instead
// of a wall of letter placeholders. Substring match on a stripped name; anything not listed
// just gets no site, which is a perfectly valid state — the field is editable.
const CAT_SITE_GUESSES=[
  ['claude','claude.ai'],['chatgpt','openai.com'],['openai','openai.com'],
  ['applecare','apple.com'],['icloud','icloud.com'],['appletv','apple.com'],['applemusic','apple.com'],
  ['netflix','netflix.com'],['spotify','spotify.com'],['disney','disneyplus.com'],
  ['hbomax','hbomax.com'],['binge','binge.com.au'],['stan','stan.com.au'],['kayo','kayosports.com.au'],
  ['youtube','youtube.com'],['amazonprime','amazon.com.au'],['paramount','paramountplus.com'],
  ['ozlotto','thelott.com'],['powerball','thelott.com'],['thelott','thelott.com'],
  ['anytimefitness','anytimefitness.com.au'],['fitnessfirst','fitnessfirst.com.au'],['goodlife','goodlifehealthclubs.com.au'],
  ['budgetdirect','budgetdirect.com.au'],['nrma','nrma.com.au'],['ctpgreenslip','nrma.com.au'],
  ['rego','service.nsw.gov.au'],['servicensw','service.nsw.gov.au'],['opal','transportnsw.info'],
  ['telstra','telstra.com.au'],['optus','optus.com.au'],['vodafone','vodafone.com.au'],['belong','belong.com.au'],
  ['agl','agl.com.au'],['originenergy','originenergy.com.au'],['medibank','medibank.com.au'],['bupa','bupa.com.au'],
];
function guessCatSite(name){
  const n=String(name||'').toLowerCase().replace(/[^a-z0-9]/g,'');
  if(!n) return '';
  const hit=CAT_SITE_GUESSES.find(([k])=>n.includes(k));
  return hit?hit[1]:'';
}
function migrateSubscriptionsToFixedOnce(){
  if(localStorage.getItem('daily_subs_merged_into_fixed')) return;
  try{
    const subs=lsLoad('daily_subscriptions', []);
    if(Array.isArray(subs)&&subs.length){
      const cats=loadFixCats();
      // Some expenses were tracked in BOTH lists (a gym membership as a fixed category and
      // again as a subscription). Importing those blindly would silently inflate the weekly
      // budget, so skip any whose name already exists as a fixed category — that expense is
      // already being counted. Exact match on a stripped-down name only: deliberately not
      // fuzzy, since a wrong merge here quietly loses a real expense.
      const norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');
      const existing=new Set(cats.map(c=>norm(c.name)).filter(Boolean));
      const skipped=[];
      subs.forEach((s,i)=>{
        const cycle=(s&&s.cycle==='yearly')?'yearly':'monthly';
        // originalCost is what was actually billed for that cycle; monthlyCost is derived.
        const raw=parseFloat(s&&s.originalCost);
        const amount=isNaN(raw)?(parseFloat(s&&s.monthlyCost)||0):raw;
        const name=((s&&s.emoji?s.emoji+' ':'')+((s&&s.name)||'Subscription')).trim();
        if(existing.has(norm(name))){ skipped.push(name); return; }
        cats.push({id:'sub'+Date.now()+'_'+i, name, amount, cycle, chargeType:'subscription',
          budget:catWeeklyFromAmount(amount,cycle), site:guessCatSite(name)});
      });
      if(skipped.length) try{ localStorage.setItem('daily_subs_merge_skipped', JSON.stringify(skipped)); }catch(e){}
      // The built-in 'subs' category existed only to hold the subscriptions TOTAL, which the
      // individual entries above now represent — so it has to go entirely, not just have its
      // budget zeroed. A zeroed category still double-counts wherever an amount was typed
      // into its weekly row, and those rows exist. Removing it doesn't lose history either:
      // each imported category's budget applies to EVERY week including past ones (a blank
      // row falls back to the budget), so the recurring block already covers what fix_subs
      // used to. The old per-week fix_subs values stay in storage, simply unread.
      saveFixCats(cats.filter(c=>c.id!=='subs'));
    }
    // Backfill a website onto any fixed category that doesn't have one yet — including the
    // ones that predate subscriptions entirely (a gym, a transport card), so the list arrives
    // with logos rather than a column of letter placeholders. Never overwrites a set value.
    const all=loadFixCats();
    let touched=false;
    all.forEach(c=>{
      if(c.site) return;
      const g=guessCatSite(c.name);
      if(g){ c.site=g; touched=true; }
    });
    if(touched) saveFixCats(all);
  }catch(e){}
  // daily_subscriptions is deliberately left in storage — nothing is destroyed, so the old
  // list is still recoverable if this migration got something wrong.
  localStorage.setItem('daily_subs_merged_into_fixed','1');
}
// Follow-up to the merge above. Its first version zeroed the aggregate 'subs' category's
// budget instead of removing it, on the mistaken reasoning that past weeks needed it for
// their history. They don't — every imported category's budget already applies retroactively
// — and a zeroed category still counts twice on any week where an amount was typed into its
// row, which is exactly what happened. Drops the leftover aggregate for anyone who ran that
// earlier version.
// Recovery hatch. The subscriptions→fixed merge is rebuildable because daily_subscriptions
// was deliberately never deleted — so if a stale device ever overwrites the merged categories
// with a pre-merge copy, the merge can simply be run again from that surviving source rather
// than re-entered by hand. Clears the one-shot flags and re-runs, then re-renders.
function rebuildSubscriptionCategories(){
  const subs=lsLoad('daily_subscriptions', []);
  if(!Array.isArray(subs)||!subs.length){
    alert('No saved subscriptions found to rebuild from.');
    return false;
  }
  localStorage.removeItem('daily_subs_merged_into_fixed');
  localStorage.removeItem('daily_subs_aggregate_dropped');
  migrateSubscriptionsToFixedOnce();
  migrateDropSubsAggregateOnce();
  if(typeof renderBudgetTab==='function'&&S.view==='budget') renderBudgetTab();
  if(typeof renderBudgetEditor==='function') renderBudgetEditor();
  return true;
}
function migrateDropSubsAggregateOnce(){
  if(localStorage.getItem('daily_subs_aggregate_dropped')) return;
  try{
    // Only when subscriptions were actually imported — otherwise a category that happens to
    // use the built-in 'subs' id is a legitimate expense and must be left alone.
    const hadSubs=(lsLoad('daily_subscriptions', [])||[]).length>0;
    if(hadSubs){
      const cats=loadFixCats();
      const agg=cats.find(c=>c.id==='subs');
      // Guard on the zeroed budget the earlier migration set, so a category the user has
      // since given a real budget to isn't silently deleted.
      if(agg&&(agg.budget===0||agg.budget===''||agg.budget==null)){
        saveFixCats(cats.filter(c=>c.id!=='subs'));
      }
    }
  }catch(e){}
  localStorage.setItem('daily_subs_aggregate_dropped','1');
}
// One-time lift of the old budgetConfig amounts onto the categories they were describing.
// Name-matched one-to-one — the same imperfect bridge as before, but run exactly once here
// instead of on every read, so from now on the number lives with the category.
function migrateCatBudgetsOnce(){
  if(localStorage.getItem('daily_cat_budgets_migrated')) return;
  const norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');
  ['inc','fix','var'].forEach(type=>{
    if(localStorage.getItem(BUD_CAT_KEY[type])==null) return;   // untouched defaults; nothing to migrate
    const cats=BUD_CAT_LOAD[type]();
    const plan=((budgetConfig&&budgetConfig[BUD_CFG_KEY[type]])||[]).map(p=>({n:norm(p.name), amt:parseFloat(p.weeklyAmount)||0, used:false}));
    let changed=false;
    const take=(c,hit)=>{ if(hit){ hit.used=true; c.budget=hit.amt; changed=true; } };
    cats.forEach(c=>{ if(c.budget!=null&&c.budget!=='') return; const n=norm(c.name); if(n) take(c, plan.find(p=>!p.used&&p.n===n)); });
    cats.forEach(c=>{ if(c.budget!=null&&c.budget!=='') return; const n=norm(c.name); if(!n) return;
      take(c, plan.find(p=>!p.used&&p.n&&(p.n.includes(n)||n.includes(p.n)))); });
    // No plan entry: fall back to the category's own legacy `default`, else leave it unset
    // so the UI shows an empty field rather than a fabricated $0 target.
    cats.forEach(c=>{ if((c.budget==null||c.budget==='')&&c.default!=null&&c.default!==''){ c.budget=parseFloat(c.default)||0; changed=true; } });
    if(changed) BUD_CAT_SAVE[type](cats);
  });
  localStorage.setItem('daily_cat_budgets_migrated','1');
}

// ── Per-week frozen recurring rates ───────────────────────────────
// A blank fixed cell means "the standard amount was charged" — but resolving that to the
// category's CURRENT budget made past weeks rewrite themselves: raising Netflix from $15 to
// $20 today retroactively made every historical week with a blank Netflix cell report $20,
// and adding a brand-new fixed category made it appear in weeks that pre-dated it entirely.
// Each week therefore freezes the rates that applied to it, once, the first time it is
// written: d.fixRates = {catId: amountAtTheTime}.
//   • A category IN fixRates with a blank cell resolves to the frozen rate, not today's price.
//   • A category NOT in fixRates did not exist when that week was live, so it contributes
//     nothing — which is what stops a new expense back-dating itself across your history.
// Weeks written before this existed have no fixRates and keep the old behaviour, so nothing
// silently changes value; budFreezeLegacyRatesOnce() below pins them at what they currently
// display, which stops the drift without inventing numbers.
// What a category actually contributes to a week's fixed total. A paused or cancelled
// recurring charge is kept (its history and price record are worth having) but stops costing
// money — which is the practical reason to record the state at all rather than deleting it.
function catChargeableBudget(c){ return !catIsArchived(c)&&catIsCharging(c) ? catBudget(c) : 0; }
function budEnsureFixRates(d){
  if(!d || d.fixRates) return;
  const rates={};
  loadFixCats().forEach(c=>{ rates[c.id]=catChargeableBudget(c); });
  d.fixRates=rates;
}
function openBudgetWeekFromStats(key){
  if(!key) return;
  const returnView=S.view==='notes'?'notes':'stats';
  const cur=getMondayOf(0), target=localMidnight(key);
  currentWeekIdx=Math.round((target-cur)/(7*864e5));
  budgetView='week'; budPastEdit=false;
  setView('budget');
  showSourceReturn(returnView,returnView==='stats'?'finance':'');
}
let _sourceReturn=null;
function clearSourceReturn(){
  _sourceReturn=null;
  const bar=document.getElementById('source-return-bar');
  if(bar){ bar.classList.add('hidden'); bar.textContent=''; }
}
function showSourceReturn(view,tab){
  _sourceReturn={view,tab};
  const bar=document.getElementById('source-return-bar'); if(!bar) return;
  bar.textContent=view==='notes'?'← Back to Journal':'← Back to Finance analysis';
  bar.classList.remove('hidden');
}
function returnFromSourceView(){
  const dest=_sourceReturn; _sourceReturn=null;
  if(!dest) return;
  setView(dest.view);
  if(dest.view==='stats') setStatsTab(dest.tab||'finance');
}
// Forward-only analysis context. A week must carry the category names and targets that meant
// something when it was live; otherwise Stats can only reinterpret it through today's setup.
// Existing historical weeks are deliberately left untouched — current labels are not evidence
// of what an old category was called.
function budEnsureStatsSnapshot(d,key,refreshTargets){
  if(!d||key!==weekKey(getMondayOf(0))) return;
  if(!d.statsSnapshot){
    d.statsSnapshot={
      version:1,
      capturedOn:getLocalDate()
    };
  }
  // The current week is still live, so its category identity follows deliberate edits until
  // the week closes. Once the key is historical this helper refuses to touch it.
  d.statsSnapshot.capturedOn=getLocalDate();
  d.statsSnapshot.fixed=loadFixCats().map(c=>({id:c.id,label:catLabel(c),budget:catBudget(c)}));
  d.statsSnapshot.variable=loadVarCats().map(c=>({id:c.id,label:catLabel(c),budget:catBudget(c)}));
  if(refreshTargets||d.statsSnapshot.totalTarget===undefined){
    const varGoal=parseFloat(d.var_goal);
    d.statsSnapshot.fixedTarget=catBudgetTotal('fix');
    d.statsSnapshot.variableTarget=!isNaN(varGoal)&&varGoal>0?varGoal:catBudgetTotal('var');
    d.statsSnapshot.totalTarget=d.statsSnapshot.fixedTarget+d.statsSnapshot.variableTarget;
    d.statsSnapshot.savingsTarget=getSavingsGoal();
  }
}
// One-time pin for weeks that predate fixRates. Without this they keep floating forever: the
// fix above only protects weeks written from now on. Freezing them at TODAY'S rates is
// deliberately not a guess at history — it is exactly the number each of those weeks is
// already displaying, so nothing a user has seen changes, and it can never drift again.
// Only weeks that actually hold data are touched; empty placeholders are left alone.
function budFreezeLegacyRatesOnce(){
  if(localStorage.getItem('daily_budget_rates_frozen')) return;
  try{
    let changed=false;
    Object.keys(budgetData||{}).forEach(k=>{
      const d=budgetData[k];
      if(!d || typeof d!=='object' || d.fixRates) return;
      if(!Object.keys(d).length) return;       // nothing recorded for that week
      budEnsureFixRates(d);
      changed=true;
    });
    // Local-only on purpose. Budget weeks sync per-week (syncBudgetDataToFirebase), not as a
    // blob, so lsSave's blob path would be the wrong channel; and because the frozen value is
    // identical to what the week already displayed, there is nothing here another device needs
    // urgently — each device pins its own copy on first boot, and the next real edit to a week
    // syncs it through the normal path.
    if(changed) localStorage.setItem('daily_budget', JSON.stringify(budgetData));
  }catch(e){}
  localStorage.setItem('daily_budget_rates_frozen','1');
}
function weekFixedTotal(d){
  let t=0;
  const rates=d&&d.fixRates;
  const current=loadFixCats(), byId={}; current.forEach(c=>{ byId[c.id]=c; });
  const rawIds=new Set(Object.keys(d||{}).filter(k=>k.startsWith('fix_')).map(k=>k.slice(4)));
  // Explicit historical fields define their own legacy category set. Only a truly fieldless,
  // unfrozen object falls back to current defaults (the pre-dynamic-category behaviour).
  const ids=new Set((rates||rawIds.size)?[...rawIds]:current.map(c=>c.id));
  if(rates) Object.keys(rates).forEach(id=>ids.add(id));
  ids.forEach(id=>{
    const v=d&&d['fix_'+id];
    if(v!==undefined&&v!=='') { t+=parseFloat(v)||0; return; }   // explicit entry always wins
    if(rates){
      // Frozen week: only categories that existed then count, at the rate that applied then.
      if(Object.prototype.hasOwnProperty.call(rates,id)) t+=parseFloat(rates[id])||0;
      return;
    }
    if(byId[id]) t += catChargeableBudget(byId[id]);   // legacy week with no frozen rates — original behaviour
  });
  return t;
}
// What weekFixedTotal() above actually contributed for ONE category in a given week.
// The pay-cycle forecast needs this to give back exactly what the weekly accrual took, and
// "its weekly budget" is NOT the same answer: a frozen week counts only the categories that
// existed when its rates were frozen, and a week carrying explicit fix_ fields counts only
// those ids — so a charge added later contributes nothing at all and must not be credited.
// This mirrors the three precedence rules above deliberately; keep the two in step.
function weekFixedContribution(d, id){
  const rates=d&&d.fixRates;
  const rawIds=new Set(Object.keys(d||{}).filter(k=>k.startsWith('fix_')).map(k=>k.slice(4)));
  const current=loadFixCats();
  const ids=new Set((rates||rawIds.size)?[...rawIds]:current.map(c=>c.id));
  if(rates) Object.keys(rates).forEach(k=>ids.add(k));
  if(!ids.has(id)) return 0;                       // not part of this week's fixed total
  const v=d&&d['fix_'+id];
  if(v!==undefined&&v!=='') return parseFloat(v)||0;   // explicit entry always wins
  if(rates) return Object.prototype.hasOwnProperty.call(rates,id)?(parseFloat(rates[id])||0):0;
  const c=current.find(x=>x.id===id);
  return c?catChargeableBudget(c):0;
}
// ── Transaction ledger ────────────────────────────────────────────
// Variable spending used to be one number per category per week: spend $18 then $42 and you
// had to do the arithmetic yourself and overwrite the field, leaving no record of what was
// actually bought. Transactions are individual purchases — {id, date, catId, amount, merchant,
// note} — and they roll up into the same weekly category totals the rest of the Budget tab
// already reads, so nothing downstream had to change.
// PRECEDENCE, deliberately: for a given week+category, if any transactions exist they ARE the
// total and the manual field is ignored. Adding them together would silently double-count
// every week that already has a manual figure, which is every week that exists today. Manual
// entry therefore still works exactly as before wherever no transaction has been logged, which
// is what makes this safe to roll out onto live data.
function loadTxns(){ const a=lsLoad('daily_transactions', []); return Array.isArray(a)?a:[]; }
let txnData = loadTxns();
function saveTxns(){ lsSave('daily_transactions', txnData, 'transactions'); }
function genTxnId(){ return 'txn_'+Date.now()+'_'+Math.floor(Math.random()*1e4); }
// Every transaction dated inside the week starting `mondayStr`.
function txnsForWeek(mondayStr){
  if(!mondayStr) return [];
  const mon=localMidnight(mondayStr);
  const sun=new Date(mon.getFullYear(),mon.getMonth(),mon.getDate()+6);
  const sunStr=dateStr(sun);
  return txnData.filter(t=>t&&t.date>=mondayStr&&t.date<=sunStr);
}
function txnsForWeekCat(mondayStr,catId){
  return txnsForWeek(mondayStr).filter(t=>t.catId===catId)
    .sort((a,b)=> a.date===b.date ? (b.createdAt||0)-(a.createdAt||0) : (a.date<b.date?1:-1));
}
function txnCatTotal(mondayStr,catId){
  return txnsForWeekCat(mondayStr,catId).reduce((s,t)=>s+(parseFloat(t.amount)||0),0);
}
// The effective spend for one variable category in one week: transactions if any exist,
// otherwise the manually-typed weekly figure.
function varCatAmount(d,mondayStr,catId){
  const n=txnsForWeekCat(mondayStr,catId).length;
  if(n) return txnCatTotal(mondayStr,catId);
  return parseFloat(d&&d['var_'+catId])||0;
}
// Which week a budget object belongs to. budgetData is KEYED by the Monday string, so the
// object itself doesn't inherently know — but every caller of weekVarTotal/weekSpending passes
// only the object. Rather than thread a key through a dozen call sites (and miss one), the
// object resolves its own: d.wk is stamped on write, and anything older is found by identity
// in budgetData. That means every existing caller became transaction-aware without changing.
function weekKeyOf(d){
  if(!d) return null;
  if(d.wk) return d.wk;
  try{
    for(const k in budgetData){ if(budgetData[k]===d){ d.wk=k; return k; } }
  }catch(e){}
  return null;
}
function weekVarTotal(d,mondayStr){
  const wk=mondayStr||weekKeyOf(d);
  let t=0;
  if(wk){
    const ids=new Set(loadVarCats().map(c=>c.id));
    Object.keys(d||{}).filter(k=>k.startsWith('var_')&&k!=='var_goal').forEach(k=>ids.add(k.slice(4)));
    txnsForWeek(wk).forEach(tx=>{ if(tx&&tx.catId) ids.add(tx.catId); });
    ids.forEach(id=>{ t += varCatAmount(d,wk,id); });
    return t;
  }
  // No resolvable week (a detached object) — fall back to the manual figures, as before.
  const ids=new Set(loadVarCats().map(c=>c.id));
  Object.keys(d||{}).filter(k=>k.startsWith('var_')&&k!=='var_goal').forEach(k=>ids.add(k.slice(4)));
  ids.forEach(id=>{ t += parseFloat(d&&d['var_'+id])||0; });
  return t;
}
// Sum of all fixed-category amounts for a week (same pattern as weekSpending's fixed half).
function weekFixed(d){ return weekFixedTotal(d); }
// ── Budget palette ────────────────────────────────────────────────────────────
// Was six unrelated hues — emerald income, orange variable, grey fixed, blue saved, a second
// emerald for the rate and a red spending — used at equal strength on every chart AND on the
// summary figures beside them. That spent all the colour the interface had on saying which
// category a number belonged to, leaving none to say whether anything was going well.
// Neutral-first instead:
//   · saved / rate  → the live accent, because "what stuck" is the series worth following
//   · income        → a strong neutral: the reference bar everything else is measured against
//   · fixed         → a quiet neutral: committed money is not a choice, so it recedes
//   · variable      → ONE muted warm tone, the only non-neutral hue on the chart
// The savings-rate LINE shares the accent with the saved BAR on purpose and is separated by
// line style (dashed) and markers rather than by inventing a fifth hue.
// Read at render time, not frozen at load: currentAccentHex() changes with the training day,
// the weather scene and the Appearance picker, and a canvas cannot inherit a CSS variable.
const BUD_WARM='#B5814A';          // muted terracotta — variable/discretionary spending
const BUD_WARM_DARK='#C08E56';
// Chart marks use --accent-text, not --accent. The CSS rule of thumb ("fills get --accent")
// assumes white text will sit on the fill; a chart bar is a graphic read AGAINST the card, and
// --accent is only guaranteed to carry white — the night weather scenes measure 1.7:1 against
// the dark background, which would draw the Saved series as a bar you cannot see. The
// corrected variant keeps the hue and clears 5:1, which is what a mark on a card needs.
function budAccentHex(){
  try{
    const raw=(typeof currentAccentHex==='function' && currentAccentHex()) || '#5C5C5C';
    const dark=(typeof S==='object')?S.theme!=='light':true;
    return (typeof accentTextHex==='function') ? accentTextHex(raw, dark) : raw;
  }catch(e){ return '#5C5C5C'; }
}
function budPalette(){
  const dark = (typeof S==='object') ? S.theme!=='light' : true;
  const accent=budAccentHex();
  return {
    saved:    accent,
    rate:     accent,
    // Income is the reference bar in its own stack; Committed is the quietest thing on the
    // chart. Both neutral, and far enough apart in value that they never trade places — the
    // gap between them is also what leaves room for Saved to sit between them legibly when
    // the accent is the app's default neutral grey.
    income:   dark?'rgba(255,255,255,.34)':'rgba(28,28,30,.30)',
    fixed:    dark?'rgba(255,255,255,.13)':'rgba(28,28,30,.17)',
    variable: dark?BUD_WARM_DARK:BUD_WARM,
    spending: dark?BUD_WARM_DARK:BUD_WARM
  };
}
// Kept as a name because ~25 call sites read it, but it is now a live getter over budPalette()
// so every chart picks up an accent or theme change on its next redraw.
const BUD_CHART_COLORS=new Proxy({},{get:(t,k)=>budPalette()[k]});
// rgba() form of the accent, for chart fills that sit under a line.
function budAccentRgba(a){ return 'rgba('+hexToRgb(budAccentHex())+','+a+')'; }
// A tint of the warm tone — variable-spending fills and the per-category bars, which are all
// one family separated by opacity rather than by a rainbow.
function budWarmRgba(a){
  const dark=(typeof S==='object')?S.theme!=='light':true;
  return 'rgba('+hexToRgb(dark?BUD_WARM_DARK:BUD_WARM)+','+a+')';
}

// ── Tonal status chip ─────────────────────────────────────────────────────────
// The semantic half of a figure, so the figure itself can stay neutral. kind is
// 'pos' | 'warn' | 'neg'; dir adds a direction glyph where one is meaningful.
// Never emit one of these unless the interface is actually making a judgement — a chip on
// every value is the same as a chip on none.
const TSTAT_ICONS={
  up:'<path d="M12 19V5M6 11l6-6 6 6"/>',
  down:'<path d="M12 5v14M6 13l6 6 6-6"/>',
  check:'<path d="M4 12.5 9.5 18 20 6.5"/>',
  alert:'<path d="M12 8v5M12 16.5v.01M12 3 2.5 20h19z"/>',
  flat:'<path d="M4 12h16"/>'
};
function tstatIcon(name){
  const d=TSTAT_ICONS[name]; if(!d) return '';
  return '<svg viewBox="0 0 24 24" aria-hidden="true">'+d+'</svg>';
}
function tstat(kind, label, icon, small){
  const k=(kind==='pos'||kind==='warn'||kind==='neg')?kind:'warn';
  return '<span class="tstat '+k+(small?' sm':'')+'">'+tstatIcon(icon)+'<span>'+escText(label)+'</span></span>';
}
// Inline legend pills rendered above a Chart.js canvas (more legible on mobile than
// the built-in legend). items = [{c:'#hex', l:'Label'}, …]
function budChartLegend(items){
  // it.dash marks a series drawn as a dashed LINE rather than a filled bar, so the legend
  // distinguishes them by shape too — the savings rate shares the accent with Saved, and a
  // legend that separated them by colour alone would be separating them by nothing.
  return items.map(it=>'<span class="chart-legend-pill"><span class="chart-legend-dot'+(it.dash?' dash':'')+'" style="'+(it.dash?'border-color:':'background:')+it.c+'"></span>'+it.l+'</span>').join('');
}
// Grid + tick colours that adapt to the active theme (same values as renderBudTrend).
function budChartGridColors(){
  const isDark=S.theme==='dark';
  return {gc:isDark?'rgba(255,255,255,0.07)':'rgba(0,0,0,0.06)', tc:isDark?'#888':'#94a3b8'};
}
const _catEsc=s=>(s||'').replace(/"/g,'&quot;');
const _catEscHtml=s=>(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
// Two escapers because the HTML contexts are NOT interchangeable, and using the text-node one
// on an attribute is exactly how stored prose used to be destroyed: a note titled `5" pipe`
// loaded into value="..." as `5`, because the raw quote closed the attribute early, and the
// next Save wrote that truncation back permanently. escAttr additionally escapes both quote
// characters. Better still, where an element can be built empty, assign .value/.textContent as
// a property and escape nothing — see jrnOpenEditor().
const escText=s=>_catEscHtml(s==null?'':String(s));
const escAttr=s=>escText(s).replace(/"/g,'&quot;').replace(/'/g,'&#39;');
// Collapsible section header (shared markup) — collapse handled by the delegated
// .bud-toggle listener + restoreBudgetCollapseState (data-bud-key persistence).
const BUD_CHEVRON='<svg class="bud-chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="6 9 12 15 18 9"/></svg>';
// Per-card edit mode (current week only). When off, add/delete/rename controls are not
// rendered at all — so a stray tap can't delete a category; amounts stay editable always.
const budEditMode = {inc:false, fix:false, var:false, vargoal:false};
// A past week temporarily unlocked for backfill editing (e.g. fixing last week's income).
// Reset whenever the viewed week changes so history stays read-only by default.
let budPastEdit = false;
// Collapsible card header with an Edit/Done toggle (current week only). The toggle lives
// inside .bud-toggle but the collapse listener ignores taps on it (see that handler).
// icon is a CARD_ICONS name. It used to be an emoji baked into the label string ("📌 Fixed
// expenses"), which put four uncontrollable hues across the Budget tab's chrome — and those
// emoji sat in the same strings as the user's own stored category names, so nothing could be
// changed here without risking their content. The icon is now a separate argument, and the
// label is plain text.
function budCardHead(type, label, isCur, icon){
  const editing=budEditMode[type];
  const editBtn = isCur
    ? '<button class="bud-edit-btn'+(editing?' active':'')+'" data-type="'+type+'" data-action="bud-edit-toggle">'+(editing?'Done':'Edit')+'</button>'
    : '';
  const ico = icon ? cardIcon(icon) : '';
  // bud-head-sum carries the card's total so a collapsed card still states its figure; it is
  // shown only while collapsed (the row below says the same thing when open). Filled by
  // budRecalc, which already computes every one of these totals.
  return '<div class="sec-label bud-toggle"><span class="bud-head-label">'+ico+'<span>'+label+'</span></span>'+
    '<span class="bud-head-right"><span class="bud-head-sum" id="sum-'+type+'"></span>'+editBtn+BUD_CHEVRON+'</span></div>';
}
// In edit mode (current week) category names are editable inputs; otherwise plain labels.
// A brand-new unnamed row also gets an input so it can be named without window.prompt().
function budCatNameHtml(type,c,isCur,editMode){
  if(editMode && isCur){
    return '<input class="bud-cat-name-input" id="catname-'+type+'-'+c.id+'" value="'+_catEsc(c.name||'')+'" placeholder="Name this category…" oninput="budRenameCat(\''+type+'\',\''+c.id+'\',this.value)">';
  }
  // Fixed rows lead with the category's logo (or its initial); the stored name may still
  // carry a legacy emoji prefix, so display the stripped form to avoid showing both.
  if(c.name) return '<div class="bud-row-left">'+
    (type==='fix'?catIconHtml(c,20):'')+
    '<div class="bud-row-name">'+_catEscHtml(type==='fix'?catDisplayName(c.name):c.name)+'</div></div>';
  return '<input class="bud-cat-name-input" id="catname-'+type+'-'+c.id+'" value="" placeholder="Name this category…" oninput="budRenameCat(\''+type+'\',\''+c.id+'\',this.value)" onchange="renderBudgetTab()"'+(isCur?'':' disabled')+'>';
}
// A scheduled subscription, bill or payment plan accrues its prorated share automatically —
// typing into it would double-count what's already been counted. Other weekly commitments
// keep their editable weekly input.
function renderFixedCard(data,isCur){
  const editing=budEditMode.fix && isCur;
  const cats=activeCats(loadFixCats()); // archived keep counting in totals, just no row
  const weeklyCats=cats.filter(c=>!catIsRecurring(c));
  const recurCats=cats.filter(catIsRecurring);

  const rows=weeklyCats.map(c=>{
    const raw=data['fix_'+c.id];
    const val=(raw!==undefined&&raw!=='')?raw:'';
    // Placeholder is the amount a blank row actually contributes, so an empty field reads as
    // "the usual $50" rather than the old, misleading "$0".
    return '<div class="bud-row bud-cat-row" data-cat-id="'+c.id+'">'+
      budCatNameHtml('fix',c,isCur,editing)+
      '<input class="bud-row-input" type="number" inputmode="decimal" id="fix-'+c.id+'" placeholder="$'+catBudget(c).toFixed(0)+'" value="'+val+'" oninput="budRecalc();budSaveDraft()"'+(isCur?'':' disabled')+'>'+
      (editing?'<button class="delete-cat-btn" data-type="fix" data-id="'+c.id+'" aria-label="Remove category">×</button>':'')+
    '</div>';
  }).join('');

  // Recurring block: one summary row that expands to a read-only breakdown. Toggled inline
  // (same idiom as the Home accounts list) so it never triggers a re-render mid-tap.
  let recurBlock='';
  if(recurCats.length){
    const recurTotal=recurCats.reduce((s,c)=>s+catBudget(c),0);
    const items=recurCats.map(c=>
      '<div class="bud-recur-item">'+
        '<div class="bud-row-left">'+catIconHtml(c,18)+
          '<div class="bud-row-name">'+_catEscHtml(catDisplayName(c.name))+'</div></div>'+
        '<div class="bud-recur-amt">$'+catBudget(c).toFixed(2)+
          '<span class="bud-recur-per">/wk</span></div>'+
      '</div>').join('');
    recurBlock=
      '<div class="bud-row bud-recur-head" onclick="var l=this.nextElementSibling;var open=l.style.display!==\'none\';l.style.display=open?\'none\':\'block\';var ch=this.querySelector(\'.bud-recur-chev\');if(ch)ch.textContent=open?\'▾\':\'▴\'">'+
        '<div class="bud-row-left"><span class="bud-recur-ic">'+cardIcon('repeat')+'</span>'+
          '<div class="bud-row-name">Recurring<span class="bud-recur-count">'+recurCats.length+'</span></div></div>'+
        '<div class="bud-row-calc bud-recur-total">$'+recurTotal.toFixed(2)+
          '<span class="bud-recur-chev">▾</span></div>'+
      '</div>'+
      '<div class="bud-recur-list" style="display:none">'+items+
        '<div class="bud-recur-note">Counted automatically each week from their billing cycle — nothing to enter. Edit them in Settings → Budget setup.</div>'+
      '</div>';
  }

  return '<div class="card" data-bud-key="fix">'+budCardHead('fix','Fixed expenses',isCur,'pin')+rows+recurBlock+
    '<div class="bud-row"><div class="bud-row-name" style="font-weight:700">Total fixed</div><div class="bud-row-calc" id="calc-fixed" style="color:var(--text)">—</div></div>'+
    (editing?'<button class="add-cat-btn" data-type="fix">+ Add fixed expense</button>':'')+
  '</div>';
}
// ── Weekly variable-spend goal ────────────────────────────────────
// A self-imposed ceiling on the Variable card below, separate from "money left over":
// leftover is whatever income happens to leave behind, this is a number Francois picks and
// tries to stay under. Per-week, so a week with things on can carry a bigger goal without
// rewriting the usual one. The usual goal lives in budDefaults.varGoal; each week stores the
// number that actually applied to it (var_goal), so past weeks aren't rewritten when the
// usual goal changes later.
function getVarGoalDefault(){ const n=parseFloat(budDefaults&&budDefaults.varGoal); return isNaN(n)?null:n; }
function getWeekVarGoal(data){
  const raw=data?data.var_goal:'';
  if(raw!==undefined&&raw!==''&&raw!==null){ const n=parseFloat(raw); if(!isNaN(n)) return n; }
  return getVarGoalDefault();
}
// Days remaining in the viewed week, today included. Only meaningful for the current week —
// a past week has no "rest of the week" left to pace.
function varGoalDaysLeft(){
  const dow=(new Date().getDay()+6)%7; // 0 = Monday … 6 = Sunday
  return 7-dow;
}
function renderVarGoalCard(data,editable){
  const goal=getWeekVarGoal(data);
  const editing=budEditMode.vargoal && editable;
  // Read-only by default (same Edit-button convention as the Income/Fixed/Variable cards):
  // the goal is already spelled out in "left of your $250 goal", so an always-visible input
  // was just clutter on a card you only change occasionally.
  const goalRow=editing
    ? '<div class="bud-row">'+
        '<div class="bud-row-left"><div class="bud-row-name">Goal for this week</div></div>'+
        '<input class="bud-row-input" type="number" inputmode="decimal" id="vargoal-input" placeholder="$0" '+
          'value="'+(goal===null?'':goal)+'" oninput="budVarGoalInput()">'+
      '</div>'
    : '';
  // The goal has to survive the input disappearing — updateVarGoalCard falls back to this.
  return '<div class="card vg-card" data-bud-key="vargoal" data-vg-goal="'+(goal===null?'':goal)+'">'+
    budCardHead('vargoal','Spending goal',editable,'target')+
    goalRow+
    '<div class="vg-body">'+
      '<div class="vg-head"><span class="vg-amt" id="vargoal-amt">—</span><span id="vargoal-status"></span></div>'+
      '<div class="vg-sub" id="vargoal-sub">Set a goal to start tracking it</div>'+
      '<div class="vg-bar-wrap"><div class="vg-bar-fill" id="vargoal-bar" style="width:0%"></div></div>'+
      '<div class="vg-foot"><span id="vargoal-spent">$0 spent</span><span id="vargoal-pace"></span></div>'+
    '</div>'+
    '<div class="vg-default-line" id="vargoal-defaultline"></div>'+
  '</div>';
}
// Live update from budRecalc — never a re-render, which would drop focus out of the goal
// input mid-typing (the same reason the category rows update by id rather than re-rendering).
function currentVarGoal(){
  const inputEl=document.getElementById('vargoal-input');
  const raw=inputEl ? inputEl.value
                    : (document.querySelector('#bud-vargoal-card .vg-card')||{dataset:{}}).dataset.vgGoal;
  if(raw===undefined||raw===null||raw==='') return null;
  const n=parseFloat(raw);
  return isNaN(n)?null:n;
}
function updateVarGoalCard(totalVar){
  const cardEl=document.querySelector('#bud-vargoal-card .vg-card'); if(!cardEl) return;
  const goal=currentVarGoal();
  const $=(id,t)=>{ const el=document.getElementById(id); if(el) el.textContent=t; };
  const amtEl=document.getElementById('vargoal-amt');
  const barEl=document.getElementById('vargoal-bar');

  $('vargoal-spent','$'+totalVar.toFixed(0)+' spent');

  if(goal===null||isNaN(goal)||goal<=0){
    if(amtEl){ amtEl.textContent='—'; amtEl.style.color='var(--muted)'; }
    $('vargoal-sub',document.getElementById('vargoal-input')?'Enter a goal to start tracking it':'Tap Edit to set a weekly goal');
    $('vargoal-pace','');
    const st0=document.getElementById('vargoal-status'); if(st0) st0.innerHTML='';
    if(barEl){ barEl.style.width='0%'; barEl.style.background='var(--muted)'; }
    if(cardEl) cardEl.classList.remove('vg-over');
    updateVarGoalDefaultLine(goal);
    return;
  }

  const left=goal-totalVar;
  const over=left<0;
  const pct=Math.min(100,Math.round(totalVar/goal*100));
  // The BAR keeps the semantic colour — green under, amber from 85% (close enough to pull up),
  // red the moment it ticks over — but the figure does not. A 34px number that changes colour
  // says "something is wrong" without ever saying what; the chip beside it says which.
  const col=over?'var(--danger)':(totalVar/goal>=0.85?'var(--warn)':'var(--success)');
  if(amtEl){ amtEl.textContent=(over?'-$':'$')+Math.abs(left).toFixed(0); amtEl.style.color='var(--text)'; }
  const statusEl=document.getElementById('vargoal-status');
  if(statusEl){
    statusEl.innerHTML = over ? tstat('neg','$'+Math.abs(left).toFixed(0)+' over','alert')
      : totalVar/goal>=0.85 ? tstat('warn','Close to goal','flat')
      : tstat('pos','Under goal','check');
  }
  $('vargoal-sub',over?'over your $'+goal.toFixed(0)+' goal':'left of your $'+goal.toFixed(0)+' goal');
  if(barEl){ barEl.style.width=pct+'%'; barEl.style.background=col; }
  if(cardEl) cardEl.classList.toggle('vg-over',over);

  // Pace only makes sense for the week actually in progress.
  if(currentWeekIdx===0 && !over){
    const days=varGoalDaysLeft();
    $('vargoal-pace','$'+(left/days).toFixed(0)+'/day for '+days+' more day'+(days===1?'':'s'));
  } else if(currentWeekIdx===0 && over){
    // The amount over is already the headline — the useful extra here is how long you still
    // have to hold the line for.
    const days=varGoalDaysLeft();
    $('vargoal-pace',days+' day'+(days===1?'':'s')+' still to go');
  } else {
    $('vargoal-pace','');
  }
  updateVarGoalDefaultLine(goal);
}
// "Usual goal" controls: only shown when this week's number differs from the saved default.
function updateVarGoalDefaultLine(goal){
  const el=document.getElementById('vargoal-defaultline'); if(!el) return;
  if(!document.getElementById('vargoal-input')){ el.innerHTML=''; return; } // read-only card
  const def=getVarGoalDefault();
  if(goal===null||isNaN(goal)||def===null||goal===def){
    el.innerHTML = def===null ? '' : '<span class="vg-default-txt">Your usual goal: $'+def.toFixed(0)+'</span>';
    return;
  }
  el.innerHTML='<span class="vg-default-txt">Usual: $'+def.toFixed(0)+'</span>'+
    '<button class="vg-default-btn" onclick="budVarGoalReset()">Use usual</button>'+
    '<button class="vg-default-btn" onclick="budVarGoalSaveDefault()">Make this my usual</button>';
}
function budVarGoalInput(){
  // First goal ever set becomes the usual one — otherwise the "usual" line would stay empty
  // until the user found the button, and there'd be nothing for new weeks to inherit.
  if(getVarGoalDefault()===null){
    const n=parseFloat(document.getElementById('vargoal-input')?.value);
    if(!isNaN(n)&&n>0){ budDefaults.varGoal=n; budPersistDefaults(); }
  }
  budRecalc(); budSaveDraft();
}
function budVarGoalSaveDefault(){
  const n=parseFloat(document.getElementById('vargoal-input')?.value);
  if(isNaN(n)||n<=0) return;
  budDefaults.varGoal=n; budPersistDefaults();
  budRecalc();
  if(typeof showToast==='function') showToast('Usual goal set to $'+n.toFixed(0));
}
function budVarGoalReset(){
  const def=getVarGoalDefault(); if(def===null) return;
  const el=document.getElementById('vargoal-input'); if(!el) return;
  el.value=def;
  budRecalc(); budSaveDraft();
}
// budSaveDefaults() rewrites the four legacy fixed-expense fields from the DOM, which isn't
// what we want here — this just persists whatever is already on the object, and syncs.
function budPersistDefaults(){
  localStorage.setItem('daily_budget_defaults', JSON.stringify(budDefaults));
  syncBudDefaultsToFirebase();
}
// ── Add / edit expense ────────────────────────────────────────────
let _txnEditId=null;      // set when editing an existing transaction rather than adding
let _txnCatId=null;       // currently selected category in the modal
// Categories the user actually spends in, most-recently-used first, so the common choice is
// the first thing under the thumb rather than alphabetical luck.
function txnRecentCatIds(){
  const seen=[];
  [...txnData].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).forEach(t=>{
    if(t&&t.catId&&seen.indexOf(t.catId)<0) seen.push(t.catId);
  });
  return seen;
}
function txnRecentMerchants(catId){
  const seen=[];
  [...txnData].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).forEach(t=>{
    if(!t||!t.merchant) return;
    if(catId && t.catId!==catId) return;
    if(seen.indexOf(t.merchant)<0 && seen.length<6) seen.push(t.merchant);
  });
  return seen;
}
function openTxnModal(opts){
  const o=opts||{};
  const modal=document.getElementById('txn-modal');
  // #app is a fixed iOS shell while the persistent phone nav sits above it in the document.
  // Transaction capture must cover that nav, so promote this one full-screen flow to <body>
  // before displaying it rather than relying on an inner z-index that cannot escape the shell.
  if(modal&&modal.parentElement!==document.body) document.body.appendChild(modal);
  _txnEditId=o.id||null;
  const existing=_txnEditId?txnData.find(t=>t&&t.id===_txnEditId):null;
  _txnCatId = existing ? existing.catId : (o.catId || txnRecentCatIds()[0] || (activeCats(loadVarCats())[0]||{}).id || null);
  document.getElementById('txn-modal-title').textContent = existing?'Edit expense':'Add expense';
  document.getElementById('txn-amount').value = existing?existing.amount:'';
  document.getElementById('txn-merchant').value = existing?(existing.merchant||''):'';
  document.getElementById('txn-note').value = existing?(existing.note||''):'';
  document.getElementById('txn-date').value = existing?existing.date:(o.date||getLocalDate());
  txnRenderAccounts(existing?existing.acctId:null);
  document.getElementById('txn-err').textContent='';
  document.getElementById('txn-delete-btn').classList.toggle('hidden', !existing);
  document.getElementById('txn-save-btn').textContent = existing?'Save changes':'Save expense';
  txnRenderCats();
  txnRenderMerchants();
  // Always open from clean geometry: a previous session's visual-viewport inset must not
  // survive a hidden modal, or the form opens already shifted up by a keyboard that is gone.
  _txnPending=null;
  txnHideConflict();
  vpClearOverlayGeometry(modal);
  const body=document.getElementById('txn-modal-body'); if(body) body.scrollTop=0;
  if(modal) modal.classList.remove('hidden');
  vpSync();
  setTimeout(()=>{ const a=document.getElementById('txn-amount'); if(a){ a.focus(); a.select(); } },60);
}
function closeTxnModal(){
  const modal=document.getElementById('txn-modal');
  // Blur first: on iOS the keyboard only retracts when focus actually leaves, and the shell
  // cannot be resynchronised to the full viewport until it has.
  const active=document.activeElement;
  if(active && modal && modal.contains(active) && active.blur) active.blur();
  if(modal) modal.classList.add('hidden');
  _txnEditId=null;
  _txnPending=null;
  txnHideConflict();
  const body=document.getElementById('txn-modal-body'); if(body) body.scrollTop=0;
  const err=document.getElementById('txn-err'); if(err) err.textContent='';
  vpClearOverlayGeometry(modal);
  vpSettle();
}
function txnRenderCats(){
  const wrap=document.getElementById('txn-cat-list'); if(!wrap) return;
  const cats=activeCats(loadVarCats());
  if(!cats.length){ wrap.innerHTML='<div class="txn-empty">Add a variable spending category first.</div>'; return; }
  const recent=txnRecentCatIds();
  const ordered=[...cats].sort((a,b)=>{
    const ia=recent.indexOf(a.id), ib=recent.indexOf(b.id);
    if(ia<0&&ib<0) return 0;
    if(ia<0) return 1;
    if(ib<0) return -1;
    return ia-ib;
  });
  if(!_txnCatId || !cats.some(c=>c.id===_txnCatId)) _txnCatId=ordered[0].id;
  wrap.innerHTML=ordered.map(c=>
    '<button type="button" class="txn-cat'+(c.id===_txnCatId?' on':'')+'" data-cat="'+_catEsc(c.id)+'" '+
    'onclick="txnPickCat(this.dataset.cat)">'+_catEscHtml(catLabel(c))+'</button>').join('');
}
function txnPickCat(id){ _txnCatId=id; txnRenderCats(); txnRenderMerchants(); }
function txnRenderMerchants(){
  const wrap=document.getElementById('txn-recent-merchants'); if(!wrap) return;
  const list=txnRecentMerchants(_txnCatId);
  wrap.innerHTML=list.length
    ? list.map(m=>'<button type="button" class="txn-chip" data-m="'+_catEsc(m)+'" onclick="txnPickMerchant(this.dataset.m)">'+_catEscHtml(m)+'</button>').join('')
    : '';
}
function txnPickMerchant(m){ const el=document.getElementById('txn-merchant'); if(el) el.value=m; }
// Which account paid. Recorded ONLY — it deliberately does not move the account's balance.
// Doing that safely would mean modelling transfers and card repayments too, and without those
// a spend would decrement an account that a later manual balance update then decrements again,
// so cash and debt figures would drift apart in a way that is very hard to unpick. This is the
// read-only half the review asked for: it enables "what went on the Visa this week" and lets
// you eyeball tracked spending against a card's real balance movement.
function txnRenderAccounts(selectedId){
  const sel=document.getElementById('txn-account'); if(!sel) return;
  const list=(typeof accounts!=='undefined'&&Array.isArray(accounts))?accounts:[];
  if(!list.length){ sel.innerHTML='<option value="">No accounts set up</option>'; sel.disabled=true; return; }
  sel.disabled=false;
  // Default to the account used most recently, since it is nearly always the same card.
  const lastUsed=[...txnData].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).find(t=>t&&t.acctId);
  const want=selectedId!==undefined&&selectedId!==null?selectedId:(lastUsed?lastUsed.acctId:'');
  sel.innerHTML='<option value="">Not recorded</option>'+
    list.map(a=>'<option value="'+_catEsc(a.id)+'"'+(a.id===want?' selected':'')+'>'+_catEscHtml(a.name||'Account')+'</option>').join('');
}
// The ONE place a transaction record is created. The modal below and the AI Inbox both go
// through it, so there is a single writer and a single record shape — a second one would drift
// from this the first time a field is added. Callers own saveTxns()/txnAfterChange().
// `meta` carries the optional {aiActionId, aiSource} provenance stamp; ordinary manual entry
// passes nothing and the record is byte-identical to what it always was.
function txnCreateRecord(f, meta){
  const rec={id:genTxnId(), date:f.date, catId:f.catId, amount:f.amount,
    merchant:f.merchant||'', note:f.note||'', acctId:f.acctId||'', createdAt:Date.now()};
  if(meta&&meta.aiActionId){ rec.aiActionId=meta.aiActionId; rec.aiSource=meta.aiSource||''; }
  txnData.push(rec);
  return rec;
}
// A carry record is an old manual weekly total turned into a ledger line. New ones carry
// explicit provenance; records written before that field existed can only be recognised by
// the exact merchant/note pair the retired auto-conversion used, so that fallback stays
// deliberately narrow - a user who types "Earlier spending" themselves is not one of ours.
const TXN_CARRY_MERCHANT='Earlier spending';
const TXN_CARRY_NOTE='Converted from the previous weekly total.';
const TXN_CARRY_SOURCE='manual-weekly-total';
function txnIsCarryRecord(t){
  if(!t) return false;
  if(t.carrySource) return t.carrySource===TXN_CARRY_SOURCE;
  return t.merchant===TXN_CARRY_MERCHANT && t.note===TXN_CARRY_NOTE;
}
// The Monday key a transaction date falls in.
function txnWeekOf(date){
  const day=localMidnight(date);
  day.setDate(day.getDate()-((day.getDay()+6)%7));
  return weekKey(day);
}
// The manual weekly figure still sitting on a category that is about to gain its FIRST
// itemised expense. This used to be converted into an "Earlier spending" transaction
// automatically, which silently double-counted whenever that figure was an estimate already
// covering the purchase being logged (a $50 fuel estimate plus a $518 tyre bill read as
// $568). Nothing is converted now without the user choosing it - see txnResolveConflict.
function txnManualConflict(date,catId,excludeTxnId){
  const wk=txnWeekOf(date);
  if(txnsForWeekCat(wk,catId).filter(t=>t.id!==excludeTxnId).length) return null;
  const d=budgetData[wk];
  const amount=parseFloat(d&&d['var_'+catId]);
  if(!d||isNaN(amount)||amount===0) return null;
  return {wk, catId, amount};
}
// Transactions own a category once itemisation starts, so a manual figure left over from
// before must not become the total again the moment the last purchase is removed. Park it
// under varDormant_<id> - preserved, not deleted, and offered back through the conflict
// banner - so the category reads as a deliberate empty rather than silently reverting.
// (varDormant_ deliberately does not start with "var_", so no total reader picks it up.)
function txnParkDormantManual(wk,catId){
  const d=budgetData[wk]; if(!d||!catId) return false;
  if(txnsForWeekCat(wk,catId).length) return false;
  const field='var_'+catId;
  const amount=parseFloat(d[field]);
  if(isNaN(amount)||amount===0) return false;
  d['varDormant_'+catId]=d[field];
  delete d[field];
  d.updatedAt=Date.now();
  budSaveData(wk);
  return true;
}
// Form values captured while the manual-total conflict panel is on screen, so the decision
// and the save are one user action rather than two independent writes.
let _txnPending=null;
function txnReadForm(){
  const amtRaw=(document.getElementById('txn-amount').value||'').replace(/[^0-9.\-]/g,'');
  const amt=parseFloat(amtRaw);
  const err=document.getElementById('txn-err');
  if(isNaN(amt)||amt===0){ err.textContent='Enter an amount.'; document.getElementById('txn-amount').focus(); return null; }
  if(!_txnCatId){ err.textContent='Pick a category.'; return null; }
  err.textContent='';
  return {date:document.getElementById('txn-date').value||getLocalDate(),
    catId:_txnCatId, amount:amt,
    merchant:(document.getElementById('txn-merchant').value||'').trim(),
    note:(document.getElementById('txn-note').value||'').trim(),
    acctId:(document.getElementById('txn-account')||{}).value||''};
}
function txnSave(){
  const f=txnReadForm(); if(!f) return;
  const conflict=txnManualConflict(f.date,f.catId,_txnEditId||null);
  if(conflict){ _txnPending=f; txnShowConflict(conflict); return; }
  txnCommitSave(f,null);
}
// The conflict choice replaces the form body rather than appearing beneath it: the decision
// changes what Save means, so leaving the form (and its Save button) live alongside it would
// offer two different saves at once.
function txnShowConflict(c){
  const box=document.getElementById('txn-conflict');
  const body=document.getElementById('txn-modal-body');
  const foot=document.getElementById('txn-modal-footer');
  if(!box||!body){ txnCommitSave(_txnPending,'replace'); return; }
  const cat=(loadVarCats().find(x=>x&&x.id===c.catId))||null;
  const name=cat?catLabel(cat):'This category';
  const money=fmtMoneyExact(c.amount);
  document.getElementById('txn-conflict-title').textContent=name+' already has a weekly total';
  document.getElementById('txn-conflict-body').textContent=
    name+' has '+money+' typed in as this week\u2019s total. From here on its total is the sum '+
    'of the expenses you log, so choose what should happen to that '+money+'.';
  document.getElementById('txn-conflict-replace').textContent='Replace the '+money+' manual total with itemised expenses';
  document.getElementById('txn-conflict-keep').textContent='Keep '+money+' as separate earlier spending';
  box.classList.remove('hidden');
  body.classList.add('hidden');
  if(foot) foot.classList.add('hidden');
  const first=document.getElementById('txn-conflict-replace');
  if(first) setTimeout(function(){ first.focus(); },40);
}
function txnHideConflict(){
  const box=document.getElementById('txn-conflict');
  const body=document.getElementById('txn-modal-body');
  const foot=document.getElementById('txn-modal-footer');
  if(box) box.classList.add('hidden');
  if(body) body.classList.remove('hidden');
  if(foot) foot.classList.remove('hidden');
}
function txnCancelConflict(){ _txnPending=null; txnHideConflict(); }
function txnResolveConflict(mode){
  const f=_txnPending; _txnPending=null;
  txnHideConflict();
  if(f) txnCommitSave(f,mode);
}
// The ONE write path for the modal, whichever resolution was chosen. Replace/keep both clear
// the manual field in the same pass as the transaction is written, so no dormant value can
// survive the decision.
function txnCommitSave(f,mode){
  const wk=txnWeekOf(f.date);
  const d=budgetData[wk];
  const field='var_'+f.catId;
  if(mode==='keep'){
    const amount=parseFloat(d&&d[field])||0;
    if(amount){
      const rec=txnCreateRecord({date:f.date, catId:f.catId, amount,
        merchant:TXN_CARRY_MERCHANT, note:TXN_CARRY_NOTE});
      rec.carrySource=TXN_CARRY_SOURCE;
      rec.carryWeek=wk;
      rec.createdAt-=1;   // sorts above the purchase that triggered the conversion
    }
  }
  if(mode==='keep'||mode==='replace'){
    if(d){ delete d[field]; delete d['varDormant_'+f.catId]; d.updatedAt=Date.now(); budSaveData(wk); }
  }
  // An edit can move a transaction out of a category/week; the one it LEFT may now be empty
  // with an old manual figure still sitting behind it.
  let fromWk=null, fromCat=null;
  const wasEdit=!!_txnEditId;
  if(wasEdit){
    const t=txnData.find(x=>x&&x.id===_txnEditId);
    if(t){
      fromWk=txnWeekOf(t.date); fromCat=t.catId;
      t.amount=f.amount; t.catId=f.catId; t.date=f.date; t.merchant=f.merchant; t.note=f.note; t.acctId=f.acctId;
    }
  } else {
    txnCreateRecord(f);
  }
  saveTxns();
  if(fromCat && (fromWk!==wk || fromCat!==f.catId)) txnParkDormantManual(fromWk,fromCat);
  closeTxnModal();
  txnAfterChange();
  if(typeof showToast==='function') showToast(wasEdit?'Expense updated':'Expense added');
}
function txnDeleteCurrent(){
  if(!_txnEditId) return;
  const t=txnData.find(x=>x&&x.id===_txnEditId);
  const wk=t?txnWeekOf(t.date):null, catId=t?t.catId:null;
  txnData=txnData.filter(x=>x&&x.id!==_txnEditId);
  saveTxns();
  if(wk&&catId) txnParkDormantManual(wk,catId);
  closeTxnModal();
  txnAfterChange();
  if(typeof showToast==='function') showToast('Expense deleted');
}
// A transaction changes the week's variable total, so anything showing that figure has to
// re-read. The manual per-category inputs are rebuilt by renderBudgetTab.
function txnAfterChange(){
  try{ if(typeof renderBudgetTab==='function' && S.view==='budget') renderBudgetTab(); }catch(e){}
  try{ if(typeof renderHome==='function' && S.view==='home') renderHome(); }catch(e){}
  try{ if(S.view==='stats') refreshStatsForData(['overview','review','finance']); }catch(e){}
  try{ if(typeof updateNavBadges==='function') updateNavBadges(); }catch(e){}
}
// Expand/collapse a category's purchase list inside the Variable card.
const _txnOpenCats=new Set();
function txnToggleCat(catId){
  if(_txnOpenCats.has(catId)) _txnOpenCats.delete(catId); else _txnOpenCats.add(catId);
  if(typeof renderBudgetTab==='function') renderBudgetTab();
}
// ── Upcoming charges ──────────────────────────────────────────────
// "$3.23/week" tells you how to budget for Spotify; it does not tell you that $13.99 leaves
// your account on Thursday. This is the forward-looking half of recurring costs, and the only
// place in the app that answers "what is about to be charged?" before it happens.
// Only renders when at least one charge has a date set — with none, it would be an empty card
// asking to be configured, which is worse than not being there.
function renderUpcomingCard(){
  const list=upcomingCharges(30);
  const recur=loadFixCats().filter(c=>catIsRecurring(c)&&catIsCharging(c));
  if(!recur.length) return '';
  const dated=recur.filter(c=>c.dueDate).length;
  if(!dated) return '';
  const total=list.reduce((s,x)=>s+x.amount,0);
  // A cluster of charges landing together is the thing that actually catches people out, so
  // it gets called out rather than left to be inferred from the list.
  const within7=list.filter(x=>x.days<=7);
  const cluster=within7.length>=2
    ? '<div class="up-warn">'+within7.length+' charges land within 7 days — '+fmtMoney(within7.reduce((s,x)=>s+x.amount,0))+' total</div>'
    : '';
  const rows=list.length
      ? list.map(x=>{
        const soon=x.days<=3;
        const when=x.days===0?'today':x.days===1?'tomorrow':'in '+x.days+' days';
        const account=catPaymentAccount(x.cat);
        return '<div class="up-row'+(soon?' soon':'')+'">'+
          '<span class="up-when">'+when+'</span>'+
          '<span class="up-name"><span class="up-title">'+_catEscHtml(catLabel(x.cat))+
            (catStatus(x.cat)==='trial'?'<span class="up-trial">trial</span>':'')+'</span>'+
            (account?'<span class="up-account">'+_catEscHtml(account.name||'Linked account')+'</span>':'')+'</span>'+
          '<span class="up-amt">'+fmtMoneyExact(x.amount)+'</span>'+
        '</div>';
      }).join('')
    : '<div class="up-none">Nothing due in the next 30 days.</div>';
  const undated=recur.length-dated;
  return '<div class="card" data-bud-key="upcoming">'+
    budCardHead('upcoming','Upcoming charges',false,'calendar')+
    cluster+rows+
    (list.length?'<div class="up-total"><span>Next 30 days</span><span>'+fmtMoney(total)+'</span></div>':'')+
    (undated?'<div class="up-hint">'+undated+' recurring charge'+(undated===1?'':'s')+' without a billing date — add one in Settings → Budget setup to see '+(undated===1?'it':'them')+' here.</div>':'')+
    // 30 days is the horizon this card is for; anything further out belongs to the calendar.
    '<button type="button" class="up-cal-link" onclick="openBillsCalendar()">View bills calendar →</button>'+
  '</div>';
}
// ── Bills calendar view ───────────────────────────────────────────
// Forward planning for scheduled charges, not a history of what was spent. Three months is
// the window that answers "what is coming" without becoming a second Yearly view.
function _billDayLabel(d){ return d.toLocaleDateString('en-AU',{day:'numeric',month:'short'}); }
function _billWeekday(d){ return d.toLocaleDateString('en-AU',{weekday:'short'}); }
// One bill row, shared by the calendar and the forecast. A statement is visibly a balance
// rather than a fixed charge — it moves week to week, so presenting it as a scheduled amount
// without saying what it is would be misleading.
function billRowHtml(o){
  const isStmt=o.kind==='statement';
  const icon=isStmt
    ? '<span class="bill-row-ic">'+acctIcon('card',18)+'</span>'
    : catIconHtml(o.cat,18);
  const meta=isStmt ? 'Statement balance' : o.acctName;
  return '<div class="bill-row'+(isStmt?' is-stmt':'')+'">'+
    '<span class="bill-row-when"><b>'+_billDayLabel(o.date)+'</b><small>'+_billWeekday(o.date)+'</small></span>'+
    icon+
    '<span class="bill-row-name"><span class="bill-row-title">'+_catEscHtml(o.name)+'</span>'+
      (meta?'<span class="bill-row-meta">'+_catEscHtml(meta)+'</span>':'')+'</span>'+
    '<span class="bill-row-amt">'+fmtMoneyExact(o.amount)+'</span>'+
  '</div>';
}
// The three-month chart. Deliberately CSS bars rather than Chart.js: three values need a
// shape, not a chart, and a canvas here would need its own theme-change redraw.
// Colour never carries the message on its own — the heaviest month is also named in the
// summary sentence above and carries a "Most bills" badge under its label.
function billsChartHtml(months, heaviest){
  const max=Math.max.apply(null, months.map(m=>m.total).concat([1]));
  return '<div class="bills-chart" role="img" aria-label="Scheduled bills by month: '+
      months.map(m=>m.label+' '+fmtMoney(m.total)).join(', ')+
      (heaviest?'. Heaviest month: '+heaviest.label+'.':'')+'">'+
    months.map(m=>{
      const on=!!heaviest&&m.label===heaviest.label&&m.total>0;
      const pct=m.total>0?Math.max(4,Math.round(m.total/max*100)):0;
      return '<div class="bills-col'+(on?' is-top':'')+'">'+
        '<div class="bills-col-amt">'+(m.total>0?fmtMoney(m.total):'—')+'</div>'+
        '<div class="bills-col-track">'+
          '<div class="bills-col-bar" style="height:'+pct+'%">'+
            // The cap marks the amount worth setting aside — the top of the heaviest bar.
            // A lighter band inside the fill, so it reads on the bar rather than floating.
            (on?'<span class="bills-col-cap"></span>':'')+
          '</div>'+
        '</div>'+
        '<div class="bills-col-lbl">'+m.short+'</div>'+
        // Always emitted, empty when not the heaviest, so every column is the same height
        // and the three month labels sit on one line.
        '<div class="bills-col-tag">'+(on?'Most bills':'')+'</div>'+
      '</div>';
    }).join('')+
  '</div>';
}
function renderBillsView(){
  const wrap=document.getElementById('budget-bills-view'); if(!wrap) return;
  const months=billsMonths();
  const undated=billsUndatedCount();
  const anyDated=months.some(m=>m.items.length>0);
  // Heaviest of the three, only meaningful once something is actually scheduled.
  const heaviest=anyDated
    ? months.reduce((a,b)=>b.total>a.total?b:a)
    : null;
  const undatedHint=undated
    ? '<div class="bills-hint">'+undated+' recurring charge'+(undated===1?'':'s')+
      ' do'+(undated===1?'es':'')+' not have a billing date yet — add one in Settings → Budget setup'+
      ' to include '+(undated===1?'it':'them')+' here.</div>'
    : '';

  const summary=
    '<div class="card bills-summary">'+
      cardHeader('calendar','Bills calendar')+
      (anyDated
        ? '<div class="card-fig">'+fmtMoney(heaviest.total)+'</div>'+
          '<div class="card-fig-u">'+_catEscHtml(heaviest.label)+' has the most scheduled bills — set aside '+
            fmtMoney(heaviest.total)+'.</div>'
        : '<div class="bills-empty-lead">Nothing scheduled in the next three months.</div>'+
          '<div class="card-fig-u">Add a billing date to a recurring charge in Settings → Budget setup and it will appear here.</div>')+
      undatedHint+
    '</div>';

  const chart=anyDated ? '<div class="card bills-chart-card">'+billsChartHtml(months,heaviest)+'</div>' : '';

  const lists=months.map(m=>
    '<div class="card bills-month">'+
      '<div class="bills-month-hd">'+
        '<span class="bills-month-name">'+_catEscHtml(m.label)+'<small>'+m.year+'</small></span>'+
        '<span class="bills-month-total">'+(m.items.length?fmtMoney(m.total):'—')+'</span>'+
      '</div>'+
      (m.items.length
        ? m.items.map(billRowHtml).join('')
        : '<div class="bills-month-empty">No scheduled bills this month.</div>')+
    '</div>').join('');

  wrap.innerHTML=summary+chart+lists;
}

// ── Until next pay ────────────────────────────────────────────────
// One question: after the bills due before my next pay, what will I have available?
// A projection, never a balance — the wording says "projected" everywhere, and it creates
// nothing: no transactions, no changes to the week, no date is rolled forward.
// Hidden entirely when no income source is named, rather than inventing a pay day.
function renderForecastCard(available, week){
  const el=document.getElementById('bud-forecast-card'); if(!el) return;
  // Forecasting only makes sense from the current week — a past week has no future to project.
  if(!budIsCurrentWeek()){ el.innerHTML=''; return; }
  const f=payCycleForecast(available, week);
  if(!f){ el.innerHTML=''; return; }
  const payTxt='Payday '+f.pay.date.toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short'})+
    ' · '+(f.pay.inDays===1?'tomorrow':f.pay.inDays+' days away');
  const tone=(f.projected==null) ? '' : (f.projected<0 ? ' is-over' : (f.projected<50 ? ' is-tight' : ''));

  let figure, unit;
  if(f.projected==null){
    // No income entered yet — state the bills, don't invent a projection.
    figure=fmtMoneyExact(f.scheduled);
    unit='in scheduled bills before then · enter this week’s income to project what’s left';
  } else {
    figure=(f.projected<0?'-':'')+fmtMoney(Math.abs(f.projected)).replace('-','');
    unit=f.projected<0
      ? 'projected shortfall after planned bills'
      : 'projected after planned bills';
  }

  const billLines=f.bills.length
    ? '<div class="fc-bills">'+f.bills.slice(0,4).map(b=>
        '<div class="fc-bill"><span class="fc-bill-when">'+_billDayLabel(b.date)+'</span>'+
        '<span class="fc-bill-name">'+_catEscHtml(b.name)+
          (b.kind==='statement'?'<em>statement</em>':'')+'</span>'+
        '<span class="fc-bill-amt">'+fmtMoneyExact(b.amount)+'</span></div>').join('')+
      (f.bills.length>4?'<div class="fc-more">+'+(f.bills.length-4)+' more before payday</div>':'')+
      '</div>'
    : '';

  el.innerHTML='<div class="card fc-card'+tone+'" data-bud-key="forecast">'+
    '<div class="sec-label bud-toggle"><span class="bud-head-label">'+cardIcon('calendar')+'<span>Until next pay</span></span>'+
      '<span class="bud-head-right"><span class="bud-head-sum">'+figure+'</span>'+BUD_CHEVRON+'</span></div>'+
    '<div class="bud-collapse-body">'+
      '<div class="fc-fig">'+figure+'</div>'+
      '<div class="fc-unit">'+unit+'</div>'+
      '<div class="fc-line">'+payTxt+'</div>'+
      (f.bills.length
        // Exact, not rounded: this list is short and usually holds one or two per-cent
        // amounts, so a rounded total disagrees with its own visible arithmetic ($13.99
        // summarised as $14 directly above the row that says $13.99).
        ? '<div class="fc-line fc-line-2">'+fmtMoneyExact(f.scheduled)+' in scheduled bills before then</div>'+billLines
        : '<div class="fc-line fc-ok">No scheduled bills before your next pay.</div>')+
    '</div>'+
  '</div>';
  // budRecalc replaces this markup after every edited amount. Reapply the keyed saved state so
  // recalculating the projection cannot silently reopen a forecast the user minimised.
  restoreBudgetCollapseState();
}

// ── Home: Finance check-in ────────────────────────────────────────
// A one-glance summary that links into Budget, not a second finance dashboard: at most three
// information lines and one action. Renders empty — and so disappears from Home entirely —
// when there is neither a scheduled bill nor a named income source, rather than showing
// placeholder figures for a setup that does not exist.
function buildFinanceCheckinCard(){
  const today=localMidnight(getLocalDate());
  const horizon=new Date(today.getFullYear(), today.getMonth()+3, 0);
  const next=billOccurrences(today, horizon)[0]||null;
  const pay=nextPayInfo();
  if(!next&&!pay) return '';
  // The same projection the Budget tab shows, from the saved week rather than live inputs —
  // Home has no budget fields on screen to read.
  const monday=getMondayOf(0), mk=weekKey(monday);
  const wk=budCurrentWeekBasis();
  const inc=weekIncome(wk);
  const avail=inc>0 ? (inc - weekVarTotal(wk,mk) - weekFixedTotal(wk) - (parseFloat(wk.sav_amount)||0)) : null;
  const f=pay?payCycleForecast(avail, wk):null;

  const lines=[];
  if(next){
    const days=Math.round((next.date-today)/864e5);
    const when=days===0?'today':days===1?'tomorrow':'in '+days+' days';
    lines.push('<div class="fin-line"><span class="fin-line-l">'+_catEscHtml(next.name)+
      (next.kind==='statement'?' <em>statement</em>':'')+
      '<small>'+when+'</small></span><span class="fin-line-r">'+fmtMoneyExact(next.amount)+'</span></div>');
  }
  if(f&&f.projected!=null){
    lines.push('<div class="fin-line"><span class="fin-line-l">Projected after bills</span>'+
      '<span class="fin-line-r'+(f.projected<0?' is-over':'')+'">'+
      (f.projected<0?'-':'')+fmtMoney(Math.abs(f.projected))+'</span></div>');
  }
  if(pay){
    lines.push('<div class="fin-line"><span class="fin-line-l">Next pay · '+_catEscHtml(pay.name)+'</span>'+
      '<span class="fin-line-r">'+pay.date.toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short'})+'</span></div>');
  }
  if(!lines.length) return '';
  return '<div class="card fin-card" onclick="openBudgetWeek()" style="cursor:pointer">'+
    cardHeader('calendar','Finance check-in')+
    lines.slice(0,3).join('')+
    '<button type="button" class="fin-act" onclick="event.stopPropagation();openBudgetWeek()">Open Budget →</button>'+
  '</div>';
}
// Home's Finance check-in and the Upcoming card both need "take me to Budget's Week view",
// which is not the same as setView('budget') — the tab remembers whichever view was last open.
function openBudgetWeek(){
  setView('budget');
  setBudgetView('week');
}
function openBillsCalendar(){
  setView('budget');
  setBudgetView('bills');
}
// A new transaction is always dated today (openTxnModal defaults to getLocalDate()), so every
// "log a purchase" affordance has to be gated on the CURRENT week being on screen — not on the
// week being editable. Unlocking a past week with "Edit week" makes it editable, and offering
// capture there would file the purchase into this week while the user believes they are
// editing that one.
function budIsCurrentWeek(){ return currentWeekIdx===0; }
// Record spending. The primary capture action for the whole spending system, given its own
// card rather than living as a dashed control inside Variable expenses, where it read as
// configuration for that one category list. One button, one path — it opens the same
// openTxnModal() the Home quick-capture and the per-category inline adds use.
// Onboarding used to collect income and fixed expenses on one dense screen, before the user
// had seen anything Daily does. That moved here, where the numbers can be set against a real
// week — but the gap has to be covered, or a new account quietly shows the app's built-in
// starter categories with nothing saying why. Shown until this week has a real income figure,
// and dismissible for good.
function budSetupDismissed(){
  try{ return localStorage.getItem('daily_budget_setup_done')==='1'; }catch(e){ return false; }
}
function budSetupDismiss(){
  try{ localStorage.setItem('daily_budget_setup_done','1'); }catch(e){}
  if(typeof renderBudgetTab==='function') renderBudgetTab();
}
// Puts them where the numbers are actually typed, with both cards already unlocked, rather
// than sending them to Settings to find it.
function openBudgetSetup(){
  budEditMode.inc=true;
  budEditMode.fix=true;
  if(typeof renderBudgetTab==='function') renderBudgetTab();
  const el=document.getElementById('bud-income-card');
  if(el && typeof safeScrollIntoView==='function') safeScrollIntoView(el,{behavior:'smooth',block:'start'});
}
function renderBudgetSetupCard(){
  if(budSetupDismissed()) return '';
  const d=budgetData[weekKey(getMondayOf(0))]||{};
  // "Set up" means this week carries at least one real income figure. Until then the tab is
  // showing starter categories rather than the user's own.
  const hasIncome=loadIncCats().some(c=>{
    const v=d['inc_'+c.id];
    return v!==undefined && v!=='' && (parseFloat(v)||0)>0;
  });
  if(hasIncome) return '';
  return '<div class="card bud-setup" data-bud-key="setup">'+
    cardHeader('wallet','Finish setting up Budget',
      '<button type="button" class="bud-setup-x" onclick="budSetupDismiss()" aria-label="Dismiss setup card">\u00d7</button>')+
    '<p class="bud-setup-body">The categories below are starters. Add your income and your fixed weekly bills and every figure on this page becomes yours \u2014 the weekly hero, the spending goal and Stats all read from them.</p>'+
    '<div class="bud-setup-actions">'+
      '<button type="button" class="bud-setup-btn primary" onclick="openBudgetSetup()">Add income &amp; bills</button>'+
      '<button type="button" class="bud-setup-btn" onclick="budSetupDismiss()">Not now</button>'+
    '</div>'+
  '</div>';
}
function renderRecordCard(){
  const cur=budIsCurrentWeek();
  return '<div class="card">'+
    cardHeader('receipt','Record spending')+
    (cur
      ? '<div class="rec-spend-cap">Log a purchase and Daily will update the category totals below.</div>'+
        '<button type="button" class="rec-add-btn" onclick="openTxnModal()">'+
          '<span class="rec-add-plus" aria-hidden="true">+</span>Add expense</button>'
      : '<div class="rec-spend-cap">You’re looking at a past week. New purchases are always dated today, so they’d land in the current week — switch back to this week to log one.</div>')+
  '</div>';
}
// Desktop splits the one mobile stack into two columns of roughly equal workload. The cards are
// MOVED, so the DOM (and therefore tab order and screen-reader order) always matches what is on
// screen — no CSS `order`, no duplicate copies with duplicate ids and handlers. Every id below
// is a stable wrapper element; its renderer replaces innerHTML, never the element itself, so
// re-parenting survives any number of re-renders and keeps each card's data-bud-key intact.
const BUD_LAYOUT={
  // Mobile: one linear stack, in the order the week is actually worked through.
  mobile:[['bud-col-left',['bud-income-card','bud-savings-card','bud-fixed-card','bud-upcoming-card',
    'bud-setup-card','bud-vargoal-card','bud-record-card','bud-variable-card','bud-forecast-card','bud-stranded-card','bud-result-card',
    'prev-weeks-section','bud-calc-card']]],
  // Desktop: left is the plan and this week's entry, right is the action, the outcome and the
  // supporting tools. Upcoming and the calculator move right because the left stack (a long
  // Variable card especially) is what makes the page tall.
  desktop:[
    ['bud-col-left',['bud-income-card','bud-savings-card','bud-fixed-card','bud-vargoal-card',
      'bud-variable-card','bud-forecast-card','bud-stranded-card']],
    ['bud-col-right',['bud-record-card','bud-result-card','bud-upcoming-card','prev-weeks-section',
      'bud-calc-card']]
  ]
};
let _budLayoutMode=null;
function budApplyLayout(force){
  const mode=window.innerWidth>=1024?'desktop':'mobile';
  if(mode===_budLayoutMode && !force) return;
  const plan=BUD_LAYOUT[mode];
  // Bail rather than half-apply if the markup isn't there (Budget lives in index.html, but this
  // also runs before first render on some paths).
  if(!plan.every(([colId])=>document.getElementById(colId))) return;
  plan.forEach(([colId,ids])=>{
    const col=document.getElementById(colId);
    const want=ids.map(id=>document.getElementById(id)).filter(Boolean);
    const have=Array.from(col.children);
    // Leave the DOM completely alone when it is already right. Re-appending a node that is
    // already in place still detaches and re-inserts it, which would drop focus out of a
    // budget input mid-typing on any stray call.
    if(have.length===want.length && want.every((el,i)=>have[i]===el)) return;
    want.forEach(el=>col.appendChild(el));
  });
  _budLayoutMode=mode;
}
// A manual weekly figure rendered for a text input: no thousands separator (budRecalc and
// budWriteFields both parseFloat this value straight back, and a comma would truncate it),
// but cents kept when there are any, so a saved 84.4 reads as 84.40 next to its $ prefix
// instead of looking like an unfinished number.
function budFmtInputVal(raw){
  const n=parseFloat(raw);
  if(isNaN(n)||n===0) return '';
  return (Math.round(Math.abs(n)*100)%100!==0) ? n.toFixed(2) : String(n);
}
function budFormatMoneyInput(el){
  if(!el) return;
  const f=budFmtInputVal(el.value);
  if(f!==el.value) el.value=f;
}
// Both sides of the single-source-of-truth rule, surfaced rather than silently applied:
// a manual figure still sitting under live transactions ('live'), or one parked out of the
// way when the last transaction was removed ('dormant'). Either way transactions win and the
// figure is preserved until the user says what to do with it.
function varConflictFor(d,wk,catId){
  const n=txnsForWeekCat(wk,catId).length;
  const live=parseFloat(d&&d['var_'+catId]);
  if(n && !isNaN(live) && live!==0) return {kind:'live', amount:live};
  const dormant=parseFloat(d&&d['varDormant_'+catId]);
  if(!isNaN(dormant) && dormant!==0) return {kind:'dormant', amount:dormant};
  return null;
}
function budResolveConflict(catId,action){
  const wk=weekKey(getMondayOf(currentWeekIdx));
  const d=budgetData[wk]; if(!d) return;
  const field='var_'+catId, dfield='varDormant_'+catId;
  const amount=parseFloat(d[field])||parseFloat(d[dfield])||0;
  if(action==='convert'&&amount){
    const rec=txnCreateRecord({date:wk, catId, amount,
      merchant:TXN_CARRY_MERCHANT, note:TXN_CARRY_NOTE});
    rec.carrySource=TXN_CARRY_SOURCE;
    rec.carryWeek=wk;
    saveTxns();
  }
  if(action==='restore'){
    if(d[dfield]!==undefined){ d[field]=d[dfield]; delete d[dfield]; }
  } else {
    delete d[field]; delete d[dfield];
  }
  d.updatedAt=Date.now();
  budSaveData(wk);
  txnAfterChange();
  if(typeof showToast==='function'){
    showToast(action==='convert'?'Added as an expense':action==='restore'?'Weekly total restored':'Weekly total removed');
  }
}
function renderVarConflict(c,conf,isCur){
  if(!conf) return '';
  const money=fmtMoneyExact(conf.amount);
  const name=_catEscHtml(catLabel(c));
  const id=_catEsc(c.id);
  const text = conf.kind==='live'
    ? money+' is also saved as this week\u2019s typed total for '+name+
      '. The itemised expenses are what counts \u2014 this figure is not being added on top.'
    : money+' was this category\u2019s typed weekly total before it was itemised. It is kept here '+
      'rather than counted, so removing the last expense does not silently bring it back.';
  const actions = isCur
    ? (conf.kind==='live'
        ? '<button type="button" class="bud-conflict-btn primary" onclick="budResolveConflict(\''+id+'\',\'drop\')">Remove the '+money+' total</button>'+
          '<button type="button" class="bud-conflict-btn" onclick="budResolveConflict(\''+id+'\',\'convert\')">Add it as an expense</button>'
        : '<button type="button" class="bud-conflict-btn primary" onclick="budResolveConflict(\''+id+'\',\'drop\')">Discard the '+money+'</button>'+
          '<button type="button" class="bud-conflict-btn" onclick="budResolveConflict(\''+id+'\',\'restore\')">Restore it as the weekly total</button>')
    : '';
  return '<div class="bud-conflict" role="status"><div class="bud-conflict-text">'+text+'</div>'+
    (actions?'<div class="bud-conflict-actions">'+actions+'</div>':'')+'</div>';
}
function renderVariableCard(data,isCur){
  const editing=budEditMode.var && isCur;
  const cats=activeCats(loadVarCats()); // archived keep counting in totals, just no row
  const wk=weekKey(getMondayOf(currentWeekIdx));
  const rows=cats.map(c=>{
    const txns=txnsForWeekCat(wk,c.id);
    const hasTxns=txns.length>0;
    // Show empty placeholder for no/zero spend — never a filled "0"
    const val=budFmtInputVal(data['var_'+c.id]);
    // With transactions logged, the weekly figure IS their sum — showing an editable field
    // beside it would imply the two combine, which they deliberately don't (see varCatAmount).
    // Without any, the manual field behaves exactly as it always has. The two modes are
    // labelled rather than left to be inferred from "input vs button", which reads as the
    // control having gone missing.
    const amountCell = hasTxns
      ? '<button type="button" class="bud-row-calc txn-total" onclick="txnToggleCat(\''+_catEsc(c.id)+'\')" '+
          'title="'+txns.length+' purchase'+(txns.length===1?'':'s')+' — tap to see them">'+
          fmtMoneyExact(txnCatTotal(wk,c.id))+
          '<span class="txn-count">'+txns.length+'</span></button>'
      : '<span class="bud-money-field"><span class="bud-money-prefix" aria-hidden="true">$</span>'+
        '<input class="bud-row-input" type="text" inputmode="decimal" id="var-'+c.id+'" '+
        'aria-label="'+escAttr(catLabel(c))+' weekly total in dollars" placeholder="0" value="'+escAttr(val)+'" '+
        'oninput="budRecalc();budSaveDraft()" onblur="budFormatMoneyInput(this);budRecalc();budSaveDraft()"'+(isCur?'':' disabled')+'></span>';
    const modeTag = hasTxns
      ? '<span class="bud-mode-tag itemised">Itemised</span>'
      : '<span class="bud-mode-tag">Weekly total</span>';
    let row='<div class="bud-row bud-cat-row'+(hasTxns?' bud-row-itemised':'')+'" data-cat-id="'+c.id+'">'+
      budCatNameHtml('var',c,isCur,editing)+
      modeTag+
      amountCell+
      (editing?'<button class="delete-cat-btn" data-type="var" data-id="'+c.id+'" aria-label="Remove category">×</button>':'')+
    '</div>';
    row+=renderVarConflict(c,varConflictFor(data,wk,c.id),isCur);
    if(hasTxns && _txnOpenCats.has(c.id)){
      row+='<div class="txn-list">'+txns.map(t=>{
        const carry=txnIsCarryRecord(t);
        return '<button type="button" class="txn-item'+(carry?' txn-item-carry':'')+'" data-id="'+_catEsc(t.id)+'" onclick="openTxnModal({id:this.dataset.id})">'+
          '<span class="txn-item-l">'+
            '<span class="txn-item-name">'+(t.merchant?_catEscHtml(t.merchant):'Expense')+
              (carry?'<span class="txn-badge">Converted weekly total</span>':'')+'</span>'+
            '<span class="txn-item-meta">'+fmtDate(t.date)+
              (t.acctId?' · '+_catEscHtml(((accounts||[]).find(a=>a&&a.id===t.acctId)||{}).name||''):'')+
              (t.note?' · '+_catEscHtml(t.note):'')+'</span>'+
            (carry?'<span class="txn-item-meta txn-item-carry-hint">Not a purchase \u2014 a typed weekly total that was moved into this list. Tap to edit or delete it.</span>':'')+
          '</span>'+
          '<span class="txn-item-amt">'+fmtMoneyExact(parseFloat(t.amount)||0)+'</span>'+
        '</button>';
      }).join('')+
        (budIsCurrentWeek()?'<button type="button" class="txn-add-inline" data-cat="'+_catEsc(c.id)+'" onclick="openTxnModal({catId:this.dataset.cat})">+ Add to '+_catEscHtml(catLabel(c))+'</button>':'')+
      '</div>';
    }
    return row;
  }).join('');
  return '<div class="card" data-bud-key="var">'+budCardHead('var','Variable expenses',isCur,'cart')+
    rows+
    '<div class="bud-row"><div class="bud-row-name" style="font-weight:700">Total variable</div><div class="bud-row-calc" id="calc-variable" style="color:var(--text)">$0</div></div>'+
    (editing?'<button class="add-cat-btn" data-type="var">+ Add variable expense</button>':'')+
  '</div>';
}
function renderIncomeCard(data,isCur){
  const editing=budEditMode.inc && isCur;
  const cats=activeCats(loadIncCats()); // archived keep counting in totals, just no row
  const rows=cats.map(c=>{
    const raw=data['inc_'+c.id];
    const val=(raw!==undefined&&raw!=='')?raw:'';
    const hrsRaw=data['hrs_'+c.id];
    const hrsVal=(hrsRaw!==undefined&&hrsRaw!=='')?hrsRaw:'';
    // Optional hours-worked companion input (hrs_<id>), independent of the dollar figure.
    // Hidden while category-editing to keep room for the rename/delete controls.
    const hrsInput=editing?'':'<input class="bud-row-input" type="number" inputmode="decimal" id="hrs-'+c.id+'" placeholder="hrs" value="'+hrsVal+'" style="width:58px;margin-right:6px;font-size:14px" oninput="budHoursInput(\''+c.id+'\')"'+(isCur?'':' disabled')+'>';
    return '<div class="bud-row bud-cat-row" data-cat-id="'+c.id+'">'+
      budCatNameHtml('inc',c,isCur,editing)+
      hrsInput+
      '<input class="bud-row-input" type="number" inputmode="decimal" id="inc-'+c.id+'" placeholder="$0" value="'+val+'" oninput="this.removeAttribute(\'data-autofilled\');budRecalc();budSaveDraft()"'+(isCur?'':' disabled')+'>'+
      (editing?'<button class="delete-cat-btn" data-type="inc" data-id="'+c.id+'" aria-label="Remove income source">×</button>':'')+
    '</div>';
  }).join('');
  return '<div class="card" data-bud-key="inc">'+budCardHead('inc','Income',isCur,'wallet')+rows+
    // Neutral, like every other total on this tab: green here asserted that earning is a good
    // outcome, which is a judgement the app has not made and cannot make from one figure.
    '<div class="bud-row"><div class="bud-row-name" style="font-weight:700">Total income</div><div class="bud-row-calc" id="calc-income" style="color:var(--text)">$0</div></div>'+
    (editing?'<button class="add-cat-btn" data-type="inc">+ Add income source</button>':'')+
  '</div>';
}
// Hours-worked companion input. If the source has an hourly rate configured, entering hours
// pre-fills the dollar field with hours × rate as a starting ESTIMATE — only while the dollar
// field is empty or still holding a previous estimate (data-autofilled). Typing in the dollar
// field clears that flag, and a manually-typed value is never overwritten (actual pay can
// include penalty rates/tips/tax adjustments that don't equal hours × rate).
function budHoursInput(id){
  const hrsEl=document.getElementById('hrs-'+id), dEl=document.getElementById('inc-'+id);
  const rate=getHourlyRate(id);
  if(hrsEl && dEl && rate>0 && (dEl.value===''||dEl.getAttribute('data-autofilled')==='1')){
    const hrs=parseFloat(hrsEl.value);
    if(!isNaN(hrs)&&hrs>0){
      dEl.value=String(Math.round(hrs*rate*100)/100);
      dEl.setAttribute('data-autofilled','1');
    } else if(dEl.getAttribute('data-autofilled')==='1'){
      dEl.value=''; dEl.removeAttribute('data-autofilled');
    }
  }
  budRecalc(); budSaveDraft();
}
// Shared loader/saver lookup so add/delete/rename work for all three category types
const BUD_CAT_LOAD={fix:loadFixCats, var:loadVarCats, inc:loadIncCats};
const BUD_CAT_SAVE={fix:saveFixCats, var:saveVarCats, inc:saveIncCats};
function budRenameCat(type,id,val){
  const load=BUD_CAT_LOAD[type], save=BUD_CAT_SAVE[type];
  if(!load) return;
  const cats=load(); const c=cats.find(x=>x.id===id); if(!c) return;
  c.name=val; save(cats); // no re-render: keep input focus while typing
}
// One delegated listener for add / delete category buttons (survives re-renders)
document.addEventListener('click', function(e){
  // Per-card Edit/Done toggle: flush amounts, flip the card's mode, re-render. Names are
  // saved live (budRenameCat oninput) and amounts by budSaveDraft, so Done needs no extra save.
  const editBtn=e.target.closest('[data-action="bud-edit-toggle"]');
  if(editBtn){
    const type=editBtn.dataset.type;
    if(type in budEditMode){
      budSaveDraft();
      budEditMode[type]=!budEditMode[type];
      renderBudgetTab();
    }
    return;
  }
  // Unlock/lock a past week for backfill editing (e.g. fixing a previous week's income).
  const weekEdit=e.target.closest('[data-action="bud-week-edit"]');
  if(weekEdit){
    budSaveDraft();              // flush any edits to the viewed week before flipping the lock
    budPastEdit=!budPastEdit;
    renderBudgetTab();
    return;
  }
  const del=e.target.closest('.delete-cat-btn');
  if(del){
    budSaveDraft();   // flush the week's current input values before the DOM is rebuilt
    const type=del.dataset.type, id=del.dataset.id;
    const load=BUD_CAT_LOAD[type], save=BUD_CAT_SAVE[type];
    if(!load) return;
    save(load().filter(c=>c.id!==id));
    renderBudgetTab();
    return;
  }
  const add=e.target.closest('.add-cat-btn');
  if(add){
    budSaveDraft();   // flush the week's current input values before the DOM is rebuilt
    const type=add.dataset.type;
    const load=BUD_CAT_LOAD[type], save=BUD_CAT_SAVE[type];
    if(!load) return;
    const id=genCatId(type);
    const cats=load(); cats.push({id,name:'',budget:''}); save(cats);
    renderBudgetTab();
    setTimeout(()=>document.getElementById('catname-'+type+'-'+id)?.focus(),60);
    return;
  }
});

// Collapsible budget cards: one delegated listener; state persisted by card index
document.addEventListener('click', function(e){
  if(e.target.closest('[data-action="bud-edit-toggle"]')) return; // Edit button isn't a collapse tap
  const toggle=e.target.closest('.bud-toggle');
  if(!toggle) return;
  const card=toggle.closest('.card');
  if(!card) return;
  card.classList.toggle('bud-collapsed');
  saveBudgetCollapseState();
});
// Keyed by data-bud-key, not by position. The old index-based array silently mis-applied
// itself whenever the card count changed — the due banner and the previous-weeks list both
// render .card elements conditionally, so a collapsed card could reappear as a different one.
// Cards without a key (those two) simply aren't persisted, which is what we want anyway.
function saveBudgetCollapseState(){
  const states={};
  document.querySelectorAll('#budget-week-view .card[data-bud-key]').forEach(card=>{
    states[card.dataset.budKey]=card.classList.contains('bud-collapsed');
  });
  localStorage.setItem('daily_budget_collapse', JSON.stringify(states));
}
function restoreBudgetCollapseState(){
  try{
    const states=JSON.parse(localStorage.getItem('daily_budget_collapse')||'{}');
    if(!states||Array.isArray(states)||typeof states!=='object') return; // legacy array: ignore, re-saves on first toggle
    document.querySelectorAll('#budget-week-view .card[data-bud-key]').forEach(card=>{
      if(states[card.dataset.budKey]) card.classList.add('bud-collapsed');
    });
  }catch(e){}
}

function renderBudgetTab(){
  const monday=getMondayOf(currentWeekIdx);
  const key=weekKey(monday);
  const data=getBudWeekData(key);
  const isCur=currentWeekIdx===0;
  if(isCur) budPastEdit=false;          // current week is always editable; clear any past-edit state
  const editable = isCur || budPastEdit; // current week, or a past week the user unlocked

  document.getElementById('week-label-main').textContent=
    isCur?'This week':currentWeekIdx===-1?'Last week':Math.abs(currentWeekIdx)+' weeks ago';
  document.getElementById('week-label-sub').textContent=fmtWeekLabel(monday);
  document.getElementById('week-next-btn').style.opacity=currentWeekIdx>=0?'0.3':'1';
  // Same state, second surface: the landscape-only compact strip (see .bud-compact-nav).
  const cw=document.getElementById('bud-compact-week');
  if(cw) cw.textContent=(isCur?'This week':currentWeekIdx===-1?'Last week':Math.abs(currentWeekIdx)+' weeks ago')+' \u00b7 '+fmtWeekLabel(monday);
  const cn=document.getElementById('bud-compact-next');
  if(cn) cn.style.opacity=currentWeekIdx>=0?'0.3':'1';

  // Edit-week toggle: only on past weeks (current week is editable already).
  const weekEditBtn=document.getElementById('week-edit-btn');
  if(weekEditBtn){
    weekEditBtn.style.display = isCur ? 'none' : 'inline-block';
    weekEditBtn.textContent = budPastEdit ? '✓ Done editing' : '✎ Edit week';
  }

  // Savings: free per-week amount. New weeks store sav_amount; weeks saved under the old
  // "target + extra" model are shown at their historical total so nothing reads as $0.
  const savEl=document.getElementById('sav-amount');
  if(savEl){
    savEl.value=(data.sav_amount!==undefined&&data.sav_amount!=='')
      ? data.sav_amount
      : '';
    savEl.disabled=!editable; savEl.style.opacity=editable?'1':'0.7';
  }

  // Dynamic income + fixed + variable category cards
  const incWrap=document.getElementById('bud-income-card');
  if(incWrap) incWrap.innerHTML=renderIncomeCard(data,editable);
  const fixWrap=document.getElementById('bud-fixed-card');
  if(fixWrap) fixWrap.innerHTML=renderFixedCard(data,editable);
  const upWrap=document.getElementById('bud-upcoming-card');
  if(upWrap) upWrap.innerHTML=renderUpcomingCard();
  const goalWrap=document.getElementById('bud-vargoal-card');
  if(goalWrap) goalWrap.innerHTML=renderVarGoalCard(data,editable);
  const setupWrap=document.getElementById('bud-setup-card');
  if(setupWrap) setupWrap.innerHTML=renderBudgetSetupCard();
  const recWrap=document.getElementById('bud-record-card');
  if(recWrap) recWrap.innerHTML=renderRecordCard();
  const varWrap=document.getElementById('bud-variable-card');
  if(varWrap) varWrap.innerHTML=renderVariableCard(data,editable);
  // Empty string when nothing is stranded, so this slot collapses to nothing in normal use.
  const strandedWrap=document.getElementById('bud-stranded-card');
  if(strandedWrap) strandedWrap.innerHTML=renderStrandedCard();

  const notesEl=document.getElementById('week-notes');
  if(notesEl){ notesEl.value=data.notes||''; notesEl.disabled=!editable; }

  const saveBtn=document.getElementById('save-week-btn');
  const saveMsg=document.getElementById('save-week-msg');
  const saveHint=document.getElementById('save-week-hint');
  if(saveBtn){
    saveBtn.style.display=editable?'block':'none';
    // A week already marked reviewed says so, rather than offering the same button again as
    // though nothing had happened.
    const done=!!(data&&data.saved);
    saveBtn.textContent=done?'✓ Week finished — tap to update':'Finish week';
  }
  if(saveHint) saveHint.style.display=editable?'block':'none';
  if(saveMsg) saveMsg.style.display='none';

  budRecalc(true);
  renderPrevWeeks();
  renderBudgetConfig();
  loadCCInput();
  renderDueBanner(monday);
  // Before restoring collapse state, so the keyed lookup runs over the cards where they
  // finally sit. (It queries #budget-week-view, which both columns live inside, so the order
  // of these two is belt-and-braces rather than load-bearing.)
  budApplyLayout();
  restoreBudgetCollapseState();
}
// Visual reminder only (never touches the leftover calc): for the week being viewed, surface
// any debt account with statement tracking on whose due date falls Mon–Sun of that week.
// Supports several at once.
function renderDueBanner(monday){
  const el=document.getElementById('bud-due-banner'); if(!el) return;
  const mondayStr=weekKey(monday);
  const sun=new Date(monday.getFullYear(),monday.getMonth(),monday.getDate()+6);
  const sundayStr=weekKey(sun);
  const hits=accounts.filter(a=>a&&a.type==='debt'&&a.tracksStatement&&a.dueDate
    && String(a.dueDate).slice(0,10)>=mondayStr && String(a.dueDate).slice(0,10)<=sundayStr);
  if(!hits.length){ el.innerHTML=''; return; }
  el.innerHTML=hits.map(a=>{
    // Was a local date format; now the shared acctDueText so this banner and the Accounts
    // screen never disagree about the same due date. Inside this banner's own week window the
    // helper always returns the countdown form, which is the whole point of the banner.
    const dueTxt=acctDueText(a)||'';
    const amt=parseFloat(a.statementBalance)||0;
    return '<div class="card" style="background:var(--warn-bg);border:1px solid var(--warn-border);padding:12px 14px;margin-bottom:12px;display:flex;align-items:center;gap:8px">'+
      // Icon, not 💳: the stroke inherits the row's amber via currentColor. Same reasoning
      // (and the same glyph) as the Home statement row, which got this right first.
      '<span style="color:var(--warn-dark);display:flex">'+acctIcon('card',16)+'</span>'+
      '<span style="font-size:13px;font-weight:600;color:var(--warn-dark)">'+_catEscHtml(a.name)+': '+fmtMoney(amt)+(dueTxt?' · '+dueTxt:'')+'</span>'+
    '</div>';
  }).join('');
}

// ── Budget setup: pay days + weekly savings target ─────────────────
// These feed the Home tab (pay-day countdown + budget-left projection) and the
// legacy-week savings fallback. Stored in budDefaults alongside the fixed defaults.
const BUD_DAY_NAMES=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
function renderBudgetConfig(){
  const sg=document.getElementById('bud-cfg-savings-goal');
  if(sg) sg.value=budDefaults.savingsGoal??'';
  // One pay-day selector per actual income source (loadIncCats — the list used for weekly
  // entries), so adding/renaming/removing a source updates these automatically.
  const wrap=document.getElementById('bud-payday-rows');
  if(wrap){
    const dayOpts=(cur)=>BUD_DAY_NAMES.map((d,v)=>'<option value="'+v+'"'+(v===cur?' selected':'')+'>'+d+'</option>').join('');
    const cats=activeCats(loadIncCats());
    wrap.innerHTML = cats.length
      ? cats.map(c=>{
          const name=catIsUnnamed(c)?'Income source':c.name.trim();
          const rate=getHourlyRate(c.id);
          return '<div class="bud-row">'+
            '<div class="bud-row-left"><div class="bud-row-name">'+_catEscHtml(name)+' pay day</div></div>'+
            '<select class="bud-row-input" id="bud-payday-'+c.id+'" style="width:140px;text-align:left;padding:0 8px;-webkit-appearance:menulist;appearance:menulist" onchange="budSaveConfig()">'+dayOpts(getPayDay(c.id))+'</select>'+
          '</div>'+
          // Optional $/hr — lets the weekly Income card pre-fill hours × rate as a starting
          // estimate. Blank = off; actual pay entry stays manual either way.
          '<div class="bud-row">'+
            '<div class="bud-row-left"><div class="bud-row-name" style="font-weight:500;color:var(--muted)">'+_catEscHtml(name)+' hourly rate</div></div>'+
            '<input class="bud-row-input" type="number" inputmode="decimal" id="bud-rate-'+c.id+'" placeholder="$/hr" value="'+(rate||'')+'" onchange="budSaveConfig()">'+
          '</div>';
        }).join('')
      : '<div class="bud-row"><div class="bud-row-left"><div class="bud-row-budget">Add an income source above to set its pay day.</div></div></div>';
  }
}
function budSaveConfig(){
  const sg=document.getElementById('bud-cfg-savings-goal');
  if(sg){ const n=parseFloat(sg.value); budDefaults.savingsGoal = isNaN(n)?undefined:n; }
  // Read every generated pay-day selector back into budDefaults.payDays (keyed by source id).
  activeCats(loadIncCats()).forEach(c=>{
    const el=document.getElementById('bud-payday-'+c.id);
    if(el){ const v=parseInt(el.value); if(!isNaN(v)) setPayDay(c.id, v); }
    const rateEl=document.getElementById('bud-rate-'+c.id);
    if(rateEl) setHourlyRate(c.id, rateEl.value); // blank/0 clears the rate
  });
  localStorage.setItem('daily_budget_defaults', JSON.stringify(budDefaults));
  syncBudDefaultsToFirebase();
  // Repaint the savings card so a changed goal shows on its label (and recolours the figure)
  // straight away rather than waiting for the next Budget render.
  if(typeof budRecalc==='function') budRecalc();
}

// ── Budget calculator ──────────────────────────────────────────────
// Standalone on purpose. The previous attempt wired itself into the budget inputs, hijacking
// taps and pulling focus off the field, which let a sync refresh overwrite an in-progress
// entry — the "reverting values" bug that got it removed (05e1cd1). This one touches nothing
// but its own display.
// Sequential four-function behaviour, like a physical calculator: each new operator resolves
// the pending one. No eval() anywhere — the operation is applied by a switch.
let _bcalc={acc:null, op:null, entry:'0', fresh:true};
function bcalcRender(){
  const d=document.getElementById('bcalc-display'); if(d) d.textContent=_bcalc.entry;
  const e=document.getElementById('bcalc-expr');
  if(e){
    const sym={'+':'+','-':'−','*':'×','/':'÷'}[_bcalc.op]||'';
    e.innerHTML=_bcalc.op!=null ? (bcalcTrim(_bcalc.acc)+' '+sym) : '&nbsp;';
  }
}
function bcalcTrim(n){
  if(n==null||isNaN(n)) return '0';
  // Kill floating-point noise (0.1+0.2) without forcing decimals onto whole numbers.
  const r=Math.round(n*1e10)/1e10;
  return String(r);
}
function bcalcDigit(d){
  if(_bcalc.fresh){ _bcalc.entry=d; _bcalc.fresh=false; }
  else if(_bcalc.entry==='0') _bcalc.entry=d;
  else if(_bcalc.entry.replace(/[-.]/g,'').length<12) _bcalc.entry+=d;
  bcalcRender();
}
function bcalcDot(){
  if(_bcalc.fresh){ _bcalc.entry='0.'; _bcalc.fresh=false; }
  else if(!_bcalc.entry.includes('.')) _bcalc.entry+='.';
  bcalcRender();
}
function bcalcApply(a,b,op){
  switch(op){
    case '+': return a+b;
    case '-': return a-b;
    case '*': return a*b;
    case '/': return b===0?NaN:a/b;
    default:  return b;
  }
}
function bcalcOp(op){
  const cur=parseFloat(_bcalc.entry)||0;
  if(_bcalc.op!=null && !_bcalc.fresh){
    const r=bcalcApply(_bcalc.acc,cur,_bcalc.op);
    if(isNaN(r)){ bcalcClear(); _bcalc.entry='Can\'t divide by 0'; bcalcRender(); return; }
    _bcalc.acc=r; _bcalc.entry=bcalcTrim(r);
  } else {
    _bcalc.acc=cur;
  }
  _bcalc.op=op; _bcalc.fresh=true;
  bcalcRender();
}
function bcalcEquals(){
  if(_bcalc.op==null) return;
  const cur=parseFloat(_bcalc.entry)||0;
  const r=bcalcApply(_bcalc.acc,cur,_bcalc.op);
  if(isNaN(r)){ bcalcClear(); _bcalc.entry='Can\'t divide by 0'; bcalcRender(); return; }
  _bcalc.entry=bcalcTrim(r); _bcalc.acc=null; _bcalc.op=null; _bcalc.fresh=true;
  bcalcRender();
}
function bcalcClear(){ _bcalc={acc:null,op:null,entry:'0',fresh:true}; bcalcRender(); }
function bcalcSign(){
  if(_bcalc.entry==='0') return;
  _bcalc.entry=_bcalc.entry.startsWith('-')?_bcalc.entry.slice(1):'-'+_bcalc.entry;
  bcalcRender();
}
// Percent of the pending left-hand value where there is one (200 + 10% = 220), otherwise a
// plain division by 100 — matching what a phone calculator does.
function bcalcPercent(){
  const cur=parseFloat(_bcalc.entry)||0;
  _bcalc.entry=bcalcTrim(_bcalc.op!=null&&_bcalc.acc!=null ? _bcalc.acc*cur/100 : cur/100);
  _bcalc.fresh=false;
  bcalcRender();
}
function bcalcBack(){
  if(_bcalc.fresh) return;
  _bcalc.entry=_bcalc.entry.length>1?_bcalc.entry.slice(0,-1):'0';
  if(_bcalc.entry==='-') _bcalc.entry='0';
  bcalcRender();
}

// Savings is a free per-week input (no auto-calc / no lock). The savings goal is SUGGESTIVE
// only — it never fills in an amount, it just colours the savings figure once reached.
const SAVINGS_GOAL = 200; // default when the user hasn't set one
function getSavingsGoal(){ const g=parseFloat(budDefaults&&budDefaults.savingsGoal); return isNaN(g)?SAVINGS_GOAL:g; }
function savingsColor(amt){
  const goal=getSavingsGoal();
  if(amt>=goal) return 'var(--positive)';   // met the goal
  if(amt>0)            return 'var(--accent)';       // saved something, below goal
  return 'var(--muted)';                             // nothing saved
}
function countUp(el, target, duration){
  if(!el || isNaN(target)) return;
  duration = duration || 600;
  const start = performance.now();
  function step(now){
    const p = Math.min((now-start)/duration, 1);
    const ease = 1 - Math.pow(1-p, 3);
    el.textContent = '$' + Math.round(target * ease).toLocaleString();
    if(p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}
function budRecalc(animate){
  const v=id=>parseFloat(document.getElementById(id)?.value)||0;
  let totalIncome=0;
  // An archived category has no input, so fall back to whatever the week already holds —
  // otherwise the on-screen total would disagree with weekIncome(), which still counts it.
  const _wk=budgetData[weekKey(getMondayOf(currentWeekIdx))]||{};
  const liveOrSaved=(pre,c)=>{ const el=document.getElementById(pre+'-'+c.id);
    return el ? (parseFloat(el.value)||0) : (parseFloat(_wk[pre+'_'+c.id])||0); };
  loadIncCats().forEach(c=>{ totalIncome += liveOrSaved('inc',c); });

  // Fixed + variable totals are computed by the CANONICAL readers (weekFixedTotal /
  // weekVarTotal) against a copy of the week with the live input values merged over it, rather
  // than by re-implementing their rules here. This used to be a hand-rolled parallel
  // calculation and it had already drifted once (recurring categories have no input, so a
  // naive sum counted them as zero); with frozen fixRates and transaction-backed variable
  // spending there are now three separate precedence rules to keep in step, and duplicating
  // them is how the on-screen total ends up disagreeing with the saved week.
  const _wkKey=weekKey(getMondayOf(currentWeekIdx));
  const _live=Object.assign({}, _wk);
  // Only ACTIVE NON-RECURRING categories have inputs (renderFixedCard gives recurring charges
  // a read-only block instead), so merging the live values below stamps fix_ keys for just
  // those — and weekFixedTotal treats any week carrying fix_ fields as defining its own
  // category list. Recurring charges therefore dropped straight out of the total: a brand-new
  // week displayed "Recurring $69.08" directly above "Total fixed $67" until its fixRates were
  // frozen by the first save, at which point the figure jumped.
  // Seeding the full current set first makes the merge unable to shrink it, and matches
  // exactly what budEnsureFixRates writes on that first save — so the number no longer
  // changes between a new week's first paint and its first keystroke.
  // Guarded on the week having NEITHER frozen rates NOR explicit fix_ fields, which is
  // precisely the state where weekFixedTotal would have used the current category list
  // anyway. A frozen week and a pre-fixRates legacy week both keep their own set untouched.
  if(!_wk.fixRates && !Object.keys(_wk).some(k=>k.startsWith('fix_'))){
    loadFixCats().forEach(c=>{ _live['fix_'+c.id]=''; });
  }
  loadFixCats().forEach(c=>{ const el=document.getElementById('fix-'+c.id); if(el) _live['fix_'+c.id]=el.value||''; });
  loadVarCats().forEach(c=>{ const el=document.getElementById('var-'+c.id); if(el) _live['var_'+c.id]=el.value||''; });
  const totalFixed=weekFixedTotal(_live);
  const totalVar=weekVarTotal(_live,_wkKey);

  // Savings is a free per-week amount (no fixed target); the goal is display-only.
  const totalSaved  = parseFloat(document.getElementById('sav-amount')?.value)||0;
  const totalOut    = totalSaved+totalFixed+totalVar;
  const leftover    = totalIncome>0?totalIncome-totalOut:null;

  const $ = (id,t) => { const el=document.getElementById(id); if(el) el.textContent=t; };
  $('calc-income',  totalIncome>0?'$'+totalIncome.toFixed(0):'—');
  $('calc-saved',   '$'+totalSaved.toFixed(0));
  $('calc-fixed',   '$'+totalFixed.toFixed(0));
  // Exact, not rounded: the rows above it are per-cent transaction figures, so a toFixed(0)
  // total disagreed with its own visible arithmetic ($1,388.94 of rows summarised as $1,389).
  $('calc-variable',totalVar>0?fmtMoneyExact(totalVar):'—');
  $('calc-leftover',leftover!==null?(leftover>=0?'+$':'-$')+Math.abs(leftover).toFixed(0):'—');
  updateVarGoalCard(totalVar);

  // The goal label was hardcoded as "Goal: $200 minimum" in index.html, so it kept showing
  // $200 no matter what the user set in Pay days & savings goal. Drive it from the saved value.
  $('sav-goal-label','Goal: $'+getSavingsGoal().toLocaleString()+' minimum');
  // Header summary: this week's savings stays readable once the card is collapsed. The
  // generic rule keeps only the LAST .bud-row, which here is "Total saved" — not the figure
  // that matters week to week.
  $('sav-head-sum','$'+totalSaved.toFixed(0));
  // Collapsed-card totals, so minimising a card never hides its figure.
  $('sum-inc','$'+totalIncome.toFixed(0));
  $('sum-fix','$'+totalFixed.toFixed(0));
  $('sum-var',fmtMoneyExact(totalVar));
  const _vg=currentVarGoal&&currentVarGoal();
  $('sum-vargoal',_vg?(fmtMoneyExact(totalVar)+' / '+fmtMoney(_vg)):'—');
  const savSum=document.getElementById('sav-head-sum');
  if(savSum) savSum.style.color='var(--text)';

  // The savings goal IS a judgement, so it gets said in words. It used to be said by recolouring
  // the amount — blue when met, red when not — which meant the figure changed meaning with no
  // label attached to it, and red on a number that is simply "less than a target you set
  // yourself" reads as an error rather than as information.
  const calcSavedEl=document.getElementById('calc-saved');
  if(calcSavedEl) calcSavedEl.style.color='var(--text)';
  const savStatus=document.getElementById('sav-status');
  if(savStatus){
    const goal=getSavingsGoal();
    savStatus.innerHTML = (!goal || !(totalIncome>0 || totalSaved>0)) ? ''
      : totalSaved>=goal ? tstat('pos','Goal met','check',true)
      : totalSaved>=goal*0.6 ? tstat('warn','Under goal','flat',true)
      : tstat('neg','Well under','down',true);
  }

  // Was a coloured circle emoji plus a word. The emoji ignores currentColor, so the dot and the
  // pill it sat in could never be the same hue, and it rendered differently on every OS. The
  // tonal chip carries the tint, a stroke icon and the word together.
  const pill=document.getElementById('week-status-pill');
  if(pill){
    pill.className='';
    pill.innerHTML = leftover===null ? tstat('warn','Enter income','flat')
      : leftover>=50 ? tstat('pos','On track','check')
      : leftover>=0  ? tstat('warn','Tight week','flat')
      :                tstat('neg','Over budget','alert');
  }

  // ── Hero: SPENT vs COMMITTED vs AVAILABLE ──
  // "Spent" used to mean saved + fixed + variable all added together, with the fixed half
  // including the prorated share of bills that had not actually been charged yet. That made a
  // yearly rego bill look like money leaving the account every week, and blended four
  // different kinds of money under one word.
  //   spent      — money that has actually gone: variable spending (transactions or manual)
  //   committed  — the accrued share of recurring/fixed costs, reserved but not necessarily
  //                charged. Still deducted, because it is genuinely not available to spend.
  //   saved      — deliberately allocated
  //   available  — income minus all three; what is actually still spendable this week
  // Proration is kept, exactly as the review asked; only the LABEL changes, so the smoothing
  // stays useful without pretending an annual bill is charged weekly.
  const spentNow   = totalVar;
  const committed  = totalFixed;
  const available  = totalIncome>0 ? (totalIncome - spentNow - committed - totalSaved) : null;
  $('bud-hero-avail', available===null ? '$0' : (available>=0?'':'-')+'$'+Math.abs(available).toFixed(0));
  $('bud-hero-spent', '$'+spentNow.toFixed(0));
  $('bud-hero-committed', '$'+committed.toFixed(0));
  $('bud-hero-saved', '$'+totalSaved.toFixed(0));
  $('bud-hero-income-note', totalIncome>0?('of $'+totalIncome.toFixed(0)+' income'):'');
  // Safe daily pace — the figure that actually governs a decision at the counter. Only shown
  // for the CURRENT week: a past week has no "rest of the week" left to pace against.
  const paceEl=document.getElementById('bud-hero-pace');
  if(paceEl){
    const daysLeft=(currentWeekIdx===0&&typeof varGoalDaysLeft==='function')?varGoalDaysLeft():0;
    paceEl.textContent = (available!==null && available>0 && daysLeft>0)
      ? '$'+Math.floor(available/daysLeft)+'/day for the '+(daysLeft===1?'rest of today':daysLeft+' days left')
      : (available!==null && available<0 ? 'Over by $'+Math.abs(available).toFixed(0)+' this week' : '');
  }
  const availLbl=document.getElementById('bud-hero-avail-lbl');
  if(availLbl) availLbl.textContent = (available!==null&&available<0) ? 'Over budget' : 'Available to spend';
  // The forecast starts from this exact figure AND the exact object it was derived from, so
  // it can never disagree with the hero directly above it.
  if(typeof renderForecastCard==='function') renderForecastCard(available, _live);
  if(animate){
    const _el=id=>document.getElementById(id);
    if(available!==null&&available>0) countUp(_el('bud-hero-avail'), available);
    countUp(_el('bud-hero-spent'), spentNow);
    countUp(_el('bud-hero-committed'), committed);
    countUp(_el('bud-hero-saved'), totalSaved);
  }
  const heroPill=document.getElementById('week-status-pill-hero');
  if(heroPill){
    heroPill.textContent = leftover===null ? 'Enter income' : (leftover>=0 ? '✓ On track' : '⚠ Over budget');
    heroPill.style.background = (leftover!==null&&leftover<0) ? 'rgba(231,76,60,.5)' : 'rgba(255,255,255,.2)';
  }

  const barEl=document.getElementById('budget-bar');     // white fill on the hero gradient
  const barL=document.getElementById('budget-bar-label-l');
  const barR=document.getElementById('budget-bar-label-r');
  if(totalIncome>0){
    // "allocated", not "spent": totalOut is spent + committed + saved. Money put into savings
    // has not been spent, and an accrued share of a yearly bill has not been charged — which
    // is the conflation the hero above now separates into three named figures.
    const pct=Math.min(110,Math.round(totalOut/totalIncome*100));
    if(barEl){
      if(animate){
        barEl.classList.remove('budget-hero-bar-fill-animate');
        barEl.style.width='0%'; barEl.offsetWidth;
        barEl.classList.add('budget-hero-bar-fill-animate');
        const _tgt=Math.min(100,pct)+'%';
        requestAnimationFrame(()=>{ barEl.classList.remove('budget-hero-bar-fill-animate'); barEl.style.transition='width 0.65s cubic-bezier(0.22,0.61,0.36,1)'; barEl.style.width=_tgt; });
      } else { barEl.style.width=Math.min(100,pct)+'%'; }
    }
    if(barL) barL.textContent='$'+totalOut.toFixed(0)+' allocated';
    if(barR) barR.textContent=pct+'% of income';
  } else {
    if(barEl) barEl.style.width='0%';
    if(barL) barL.textContent='Enter income to see breakdown';
    if(barR) barR.textContent='';
  }
}

// Write the per-week editable fields from the DOM into a week record.
//
// CRITICAL: sav-amount and week-notes live in STATIC html — they're always in the DOM,
// even when the Budget tab isn't the active view. The inc/fix/var inputs, by contrast, are
// rendered dynamically and only exist while the tab is on screen (hence their `if(el)`
// guard). Without a matching guard, a save that fires while another tab is showing would
// read the STALE static input — e.g. an empty sav-amount left over from before a cloud sync
// updated budgetData in the background — and
// write that empty value back with a fresh updatedAt, which then wins every merge and wipes
// the real saved amount locally AND on every other device. This is why savings (and only
// savings) kept vanishing on refresh and refused to sync. So only capture the two static
// fields when the Budget tab is the live, rendered view; otherwise preserve budgetData's
// existing values. (renderBudgetTab keeps these inputs in sync with budgetData whenever the
// tab is active — including on incoming cloud echoes — so "budget is the view" == "fresh".)
function budWriteFields(d){
  const gv=id=>document.getElementById(id)?.value||'';
  if(S.view==='budget'){
    d.sav_amount = gv('sav-amount');
    // Only when the goal input is actually on screen (it's behind the card's Edit button) —
    // otherwise a routine draft flush would blank the week's saved goal.
    if(document.getElementById('vargoal-input')) d.var_goal = gv('vargoal-input');
    d.notes      = gv('week-notes');
  }
  loadIncCats().forEach(c=>{ const el=document.getElementById('inc-'+c.id); if(el) d['inc_'+c.id]=el.value||''; });
  // Optional hours-worked per source — stored independently of the dollar figure.
  loadIncCats().forEach(c=>{ const el=document.getElementById('hrs-'+c.id); if(el) d['hrs_'+c.id]=el.value||''; });
  loadFixCats().forEach(c=>{ const el=document.getElementById('fix-'+c.id); if(el) d['fix_'+c.id]=el.value||''; });
  loadVarCats().forEach(c=>{ const el=document.getElementById('var-'+c.id); if(el) d['var_'+c.id]=el.value||''; });
}
function budSaveDraft(){
  // Current week always auto-persists; a past week persists only while unlocked for editing.
  if(currentWeekIdx !== 0 && !budPastEdit) return;
  const key=weekKey(getMondayOf(currentWeekIdx)); // write to the VIEWED week, not always "this" week
  if(!budgetData[key]) budgetData[key]={};
  const d=budgetData[key];
  const before=JSON.stringify(d);
  budEnsureFixRates(d);   // freeze this week's recurring prices the first time it is written
  d.wk=key;               // so weekKeyOf can resolve transactions without a reverse lookup
  budWriteFields(d);
  budEnsureStatsSnapshot(d,key,false);
  if(!d.saved) d.draft=true;
  // Only a REAL change stamps and syncs. Draft flushes also fire on render/week-nav with
  // untouched inputs — stamping those would let a device with stale data pass it off as
  // the freshest copy just by being opened.
  if(JSON.stringify(d)===before) return;
  d.updatedAt=Date.now();
  budSaveData(key);
}

function budSaveCurrentWeek(){
  const monday=getMondayOf(currentWeekIdx);
  const key=weekKey(monday);
  if(!budgetData[key]) budgetData[key]={};
  const d=budgetData[key];
  budEnsureFixRates(d);   // freeze this week's recurring prices the first time it is written
  d.wk=key;               // so weekKeyOf can resolve transactions without a reverse lookup
  budWriteFields(d);
  budEnsureStatsSnapshot(d,key,true);
  d.saved=true; delete d.draft;
  d.updatedAt=Date.now(); // explicit user save — always stamp
  budSaveData(key); renderPrevWeeks(); updateNavBadges();
}

function budSaveWeekExplicit(){
  budSaveCurrentWeek();
  const btn=document.getElementById('save-week-btn');
  const msg=document.getElementById('save-week-msg');
  if(btn){btn.textContent='✓ Week finished';btn.style.background='var(--accent)';}
  if(msg) msg.style.display='block';
  setTimeout(()=>{
    if(btn){btn.textContent='Finish week';btn.style.background='';}
    if(msg) msg.style.display='none';
  },1800);
}


function _applyCardCollapse(id, collapse){
  const card=document.getElementById(id); if(!card) return;
  const body=document.getElementById(id+'-body');
  if(!body){ if(collapse) card.classList.add('collapsed'); else card.classList.remove('collapsed'); return; }
  if(collapse){
    card.classList.add('collapsed');
    body.style.height=body.scrollHeight+'px';
    body.style.overflow='hidden';
    setTimeout(()=>{
      body.style.transition='height 0.3s ease,opacity 0.25s ease';
      body.style.height='0';
      body.style.opacity='0';
    }, 16);
  } else {
    card.classList.remove('collapsed');
    body.style.transition='height 0.3s ease,opacity 0.25s ease';
    body.style.height=body.scrollHeight+'px';
    body.style.opacity='';
    body.addEventListener('transitionend',()=>{ body.style.height=''; body.style.transition=''; },{ once:true });
  }
}
function toggleCard(id){
  const card=document.getElementById(id); if(!card) return;
  const isCollapsed=!card.classList.contains('collapsed');
  _applyCardCollapse(id, isCollapsed);
  let collapsed; try{ collapsed=JSON.parse(localStorage.getItem('daily_collapsed')||'{}'); }catch(e){ collapsed={}; }
  if(isCollapsed) collapsed[id]=true; else delete collapsed[id];
  localStorage.setItem('daily_collapsed',JSON.stringify(collapsed));
}
function restoreCardCollapse(){
  let collapsed; try{ collapsed=JSON.parse(localStorage.getItem('daily_collapsed')||'{}'); }catch(e){ collapsed={}; }
  Object.keys(collapsed).forEach(id=>{
    const card=document.getElementById(id); if(!card) return;
    card.classList.add('collapsed');
    const body=document.getElementById(id+'-body');
    if(body){ body.style.height='0'; body.style.opacity='0'; body.style.overflow='hidden'; }
  });
}

function renderPrevWeeks(){
  const wrap=document.getElementById('prev-weeks-section'); if(!wrap) return;
  const curKey=weekKey(getMondayOf(currentWeekIdx));
  const keys=Object.keys(budgetData).filter(k=>k<curKey).sort((a,b)=>b.localeCompare(a)).slice(0,8);
  if(!keys.length){wrap.innerHTML=emptyState('📋','No previous weeks','Your saved weeks will appear here');return;}
  const chevron='<svg class="card-chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>';
  let html='<div class="card" id="bud-card-prev"><div class="card-collapse-header" onclick="toggleCard(\'bud-card-prev\')"><div class="sec-label" style="margin-bottom:0">Previous weeks</div><div class="card-collapse-right">'+chevron+'</div></div><div class="card-collapse-body" id="bud-card-prev-body" style="padding-top:6px">';
  keys.forEach(k=>{
    const d=budgetData[k];
    const inc=weekIncome(d);
    const saved=weekSavedAmt(d);
    const left=inc>0?weekLeftover(d):null;
    const mon=new Date(k+'T12:00:00');
    const fri=new Date(mon); fri.setDate(mon.getDate()+4);
    const lbl=mon.toLocaleDateString('en-AU',{day:'numeric',month:'short'})+' – '+fri.toLocaleDateString('en-AU',{day:'numeric',month:'short'});
    html+='<div class="prev-week-row"><div class="prev-week-date">'+lbl+'</div><div class="prev-week-pills">';
    if(inc>0) html+='<span class="prev-pill in">$'+inc.toFixed(0)+' in</span>';
    html+='<span class="prev-pill saved">$'+saved.toFixed(0)+' saved</span>';
    if(left!==null) html+='<span class="prev-pill '+(left>=0?'left':'over')+'">'+(left>=0?'+':'-')+'$'+Math.abs(left).toFixed(0)+'</span>';
    html+='</div></div>';
  });
  html+='</div></div></div>';
  wrap.innerHTML=html;
}

function renderMonth(){
  const monthDate=getMonthDate(currentMonthOffset);
  const isCur=currentMonthOffset>=0;
  document.getElementById('month-label-main').textContent=fmtMonthLabel(monthDate);
  document.getElementById('month-next-btn').style.opacity=isCur?'0.3':'1';
  const keys=getMondaysInMonth(monthDate);
  let totalIncome=0,totalSaved=0,totalSpending=0,weekCount=0;
  keys.forEach(k=>{
    const d=budgetData[k]; if(!d) return; weekCount++;
    totalIncome+=weekIncome(d);
    totalSaved+=weekSavedAmt(d);
    totalSpending+=weekSpending(d);
  });
  const totalOut=totalSaved+totalSpending;
  const leftover=totalIncome>0?totalIncome-totalOut:null;

  document.getElementById('month-label-sub').textContent=weekCount>0?weekCount+' week'+(weekCount>1?'s':'')+' recorded':'No data saved yet';

  const sg=document.getElementById('month-summary-grid');
  if(sg){
    // Income and Expenses rather than Saved and CC balance: the CC balance is a running debt
    // that has nothing to do with the month being viewed, and Saved was already implied by
    // the savings rate beside it. These three now describe the same month — what came in,
    // what went out (fixed + variable), and what proportion stuck.
    const savRate=totalIncome>0?(totalSaved/totalIncome*100).toFixed(0)+'%':'—';
    // Neutral figures. These used to be painted in their chart-series colours — income green,
    // expenses orange, rate green — which asserted that earning is good and spending is bad
    // before anything had actually been compared. The only judgement available here is the
    // savings rate against a target, and that now travels as a chip beside the number rather
    // than as the number's own colour.
    const rateChip = (weekCount>0 && totalIncome>0)
      ? (totalSaved/totalIncome>=0.2 ? tstat('pos','On track','check',true)
        : totalSaved>0 ? tstat('warn','Below 20%','flat',true)
        : tstat('neg','Nothing saved','down',true))
      : '';
    sg.innerHTML=[
      {val:savRate,lbl:'Savings rate',chip:rateChip},
      {val:weekCount>0?'$'+Math.round(totalIncome).toLocaleString():'—',lbl:'Income'},
      {val:weekCount>0?'$'+Math.round(totalSpending).toLocaleString():'—',lbl:'Expenses'},
    ].map(s=>'<div class="sum-card"><div class="sum-card-val">'+s.val+'</div><div class="sum-card-lbl">'+s.lbl+'</div>'+(s.chip?'<div class="sum-card-chip">'+s.chip+'</div>':'')+'</div>').join('');
  }

  const barEl=document.getElementById('month-bar');
  const barL=document.getElementById('month-bar-label-l');
  const barR=document.getElementById('month-bar-label-r');
  if(totalIncome>0){
    const pct=Math.min(110,Math.round(totalOut/totalIncome*100));
    const bc=pct>100?'var(--danger)':pct>85?'var(--warn)':'var(--success)';
    if(barEl){barEl.style.width=Math.min(100,pct)+'%';barEl.style.background=bc;}
    if(barL) barL.textContent='$'+totalOut.toFixed(0)+' allocated';
    if(barR) barR.textContent=pct+'% of income';
  } else {
    if(barEl) barEl.style.width='0%';
    if(barL) barL.textContent=weekCount>0?'Enter income to see breakdown':'No weeks saved for this month';
    if(barR) barR.textContent='';
  }

  const catEl=document.getElementById('month-categories');
  if(catEl){
    // varCatAmount, not a raw var_ read: a category backed by transactions has its total in
    // the ledger, and reading the manual field directly reported it as zero.
    // Every one of these is variable spending, so they are ONE family (the warm tone) stepped
    // down in opacity by rank — not eight unrelated hues. The bar LENGTH already says which is
    // biggest; the old rainbow was re-encoding the category name in colour and nothing else.
    const catTotals=activeCats(loadVarCats()).map(c=>({
      label:catLabel(c),
      val:keys.reduce((s,k)=>s+varCatAmount(budgetData[k],k,c.id),0)
    }));
    const catRank=catTotals.slice().sort((a,b)=>b.val-a.val);
    catTotals.forEach(c=>{
      const i=catRank.indexOf(c);
      c.color=budWarmRgba(Math.max(0.30, 0.92 - i*0.13).toFixed(2));
    });
    const maxVal=Math.max(1,...catTotals.map(c=>c.val));
    catEl.innerHTML=catTotals.length?catTotals.map(c=>{
      const pct=Math.round(c.val/maxVal*100);
      return '<div class="month-cat-row"><div class="month-cat-label">'+c.label+'</div>'
        +'<div class="month-cat-bar-wrap"><div class="month-cat-bar-fill" style="width:'+pct+'%;background:'+c.color+'"></div></div>'
        +'<div class="month-cat-amount">'+(c.val>0?'$'+c.val.toFixed(0):'—')+'</div></div>';
    }).join(''):'<div style="font-size:13px;color:var(--muted);text-align:center;padding:8px 0">No variable categories</div>';
  }

  const wl=document.getElementById('month-weeks-list');
  if(monthWeekChart){ monthWeekChart.destroy(); monthWeekChart=null; }
  if(wl){
    if(!keys.length){
      wl.innerHTML=emptyState('📅','No weeks in this month','Navigate to a month with budget data');
    } else {
      const labels=keys.map(k=>{
        const mon=new Date(k+'T12:00:00');
        return mon.toLocaleDateString('en-AU',{day:'numeric',month:'short'});
      });
      const data=keys.map(k=>budgetData[k]);
      // Income sits in its own stack; spent / committed / saved STACK together, because they
      // are components of one figure rather than four independent measures. The old chart drew
      // "Total expenses" as a fifth bar beside "CC / variable" and "Fixed" — its own two
      // components — so the same money was graphed twice at equal visual weight and the tallest
      // bar was always a duplicate. Stacked, the components sum to the total by construction
      // and the comparison that matters (income vs everything it has to cover) is left-to-right.
      const legend=budChartLegend([
        {c:BUD_CHART_COLORS.income,l:'Income'},
        {c:BUD_CHART_COLORS.variable,l:'Spent'},
        {c:BUD_CHART_COLORS.fixed,l:'Committed'},
        {c:BUD_CHART_COLORS.saved,l:'Saved'},
      ]);
      wl.innerHTML='<div class="chart-legend">'+legend+'</div><div id="month-weeks-chart-wrap" style="height:220px"><canvas id="month-weeks-chart"></canvas></div>';
      const ctx=document.getElementById('month-weeks-chart');
      const {gc,tc}=budChartGridColors();
      monthWeekChart=new Chart(ctx,{
        type:'bar',
        data:{
          labels,
          datasets:[
            {label:'Income',data:data.map(weekIncome),backgroundColor:BUD_CHART_COLORS.income,borderRadius:3,stack:'in',order:0},
            {label:'Spent',data:keys.map((k,i)=>weekVarTotal(data[i],k)),backgroundColor:BUD_CHART_COLORS.variable,borderRadius:3,stack:'out',order:1},
            {label:'Committed',data:data.map(weekFixed),backgroundColor:BUD_CHART_COLORS.fixed,borderRadius:3,stack:'out',order:2},
            {label:'Saved',data:data.map(weekSavedAmt),backgroundColor:BUD_CHART_COLORS.saved,borderRadius:3,stack:'out',order:3},
          ]
        },
        options:{
          responsive:true,maintainAspectRatio:false,
          plugins:{
            legend:{display:false},
            tooltip:{callbacks:{label:c=>c.dataset.label+': $'+c.parsed.y.toFixed(0)}}
          },
          scales:{
            // stacked:true on both axes is what makes the 'in' / 'out' stack groups above
            // render as two columns per week rather than seven separate bars.
            x:{stacked:true,grid:{display:false},ticks:{color:tc,font:{size:11}}},
            y:{stacked:true,grid:{color:gc},ticks:{color:tc,font:{size:11},callback:v=>'$'+v},beginAtZero:true}
          }
        }
      });
    }
  }

  // Biggest purchases this month — only possible now the ledger exists, and the fastest way to
  // answer "where did it actually go?" after a month reads worse than expected. A month total
  // and a category bar both stop one level short of the thing you actually recognise.
  const bigEl=document.getElementById('month-biggest');
  if(bigEl){
    const monthTxns=keys.flatMap(k=>txnsForWeek(k));
    const top=[...monthTxns].sort((a,b)=>(parseFloat(b.amount)||0)-(parseFloat(a.amount)||0)).slice(0,5);
    bigEl.innerHTML = top.length
      ? '<div class="card"><div class="sec-label">Biggest purchases</div>'+
          top.map(t=>{
            const cat=activeCats(loadVarCats()).find(c=>c.id===t.catId);
            return '<div class="up-row">'+
              '<span class="up-name">'+(t.merchant?_catEscHtml(t.merchant):'Expense')+
                (cat?'<span class="month-big-cat">'+_catEscHtml(catLabel(cat))+'</span>':'')+'</span>'+
              '<span class="up-when" style="flex:0 0 auto">'+fmtDate(t.date)+'</span>'+
              '<span class="up-amt">'+fmtMoneyExact(parseFloat(t.amount)||0)+'</span>'+
            '</div>';
          }).join('')+
        '</div>'
      : '';
  }
}

// ── Yearly budget view ────────────────────────────────────────────
// ── Yearly view ────────────────────────────────────────────────────
// This used to read a rolling 12 months for its charts while the "Saved this year" tile read
// the calendar year, so the headline figure and the chart described different spans. Now
// everything is one calendar year, which is also what makes the year nav meaningful.
let budgetYearOffset=0;   // 0 = this year, -1 = last year
function budViewedYear(){ return localMidnight(getLocalDate()).getFullYear()+budgetYearOffset; }
function changeBudgetYear(dir){
  if(dir>0&&budgetYearOffset>=0) return;   // never navigate into the future
  budgetYearOffset+=dir;
  renderYear();
}
// One entry per calendar month of the given year. Months are always returned in order with
// zeros for the empty ones, so a gap month reads as a gap on the chart rather than being
// silently dropped and shifting the axis.
function budYearMonths(year){
  const now=localMidnight(getLocalDate());
  const isCurrentYear=year===now.getFullYear();
  const lastMonth=isCurrentYear?now.getMonth():11;   // don't project into unlived months
  const months=[];
  for(let m=0;m<=lastMonth;m++){
    months.push({m, ym:year+'-'+String(m+1).padStart(2,'0'),
      label:new Date(year,m,1).toLocaleDateString('en-AU',{month:'short'}),
      // keys: the week keys that fed this month, so per-category figures can be recomputed
      // later (the rising-categories comparison) without re-scanning all of budgetData.
      income:0, fixed:0, variable:0, saved:0, weeks:0, keys:[]});
  }
  Object.keys(budgetData).forEach(k=>{
    if(k.substring(0,4)!==String(year)) return;
    const mi=parseInt(k.substring(5,7),10)-1;
    if(isNaN(mi)||mi<0||mi>lastMonth) return;
    const d=budgetData[k]; if(!d) return;
    const M=months[mi];
    M.income+=weekIncome(d); M.fixed+=weekFixed(d);
    M.variable+=weekVarTotal(d,k); M.saved+=weekSavedAmt(d); M.weeks++; M.keys.push(k);
  });
  return months;
}
function renderYear(){
  const year=budViewedYear();
  const months=budYearMonths(year);
  const withData=months.filter(m=>m.weeks>0);
  const points=months.map(m=>({label:m.label, income:m.income, saved:m.saved}));
  const fixedArr=months.map(m=>m.fixed);
  const varArr=months.map(m=>m.variable);
  const rateArr=months.map(m=>m.income>0?(m.saved/m.income*100):0);

  // ── Year label + nav ──
  const lm=document.getElementById('year-label-main');
  const ls=document.getElementById('year-label-sub');
  if(lm) lm.textContent=String(year);
  if(ls) ls.textContent=withData.length
    ? withData.length+' month'+(withData.length===1?'':'s')+' recorded'
    : 'No data yet';
  const nextBtn=document.getElementById('year-next-btn');
  if(nextBtn) nextBtn.style.opacity=budgetYearOffset>=0?'0.3':'1';

  // ── Stat tiles ──
  const sg=document.getElementById('year-summary-grid');
  if(sg){
    const totIncome=months.reduce((s,m)=>s+m.income,0);
    const totSaved=months.reduce((s,m)=>s+m.saved,0);
    const avgRate=totIncome>0?(totSaved/totIncome*100):0;
    // Best month by what was actually put away, which is the number worth chasing.
    const best=withData.slice().sort((a,b)=>b.saved-a.saved)[0];
    // Neutral, for the same reason as the Month tiles: none of these is a verdict. The one
    // genuine comparison on this screen — the year's average rate against a 20% target —
    // is carried by a chip, not by recolouring the percentage itself.
    const rateChip = withData.length
      ? (avgRate>=20 ? tstat('pos','On track','check',true)
        : avgRate>=10 ? tstat('warn','Below 20%','flat',true)
        : tstat('neg','Well below 20%','down',true))
      : '';
    sg.innerHTML=[
      {val:'$'+Math.round(totIncome).toLocaleString(),lbl:'Earned in '+year},
      {val:'$'+Math.round(totSaved).toLocaleString(),lbl:'Saved in '+year},
      {val:avgRate.toFixed(0)+'%',lbl:'Average savings rate',chip:rateChip},
      {val:best?best.label:'—',lbl:best?'Best month · $'+Math.round(best.saved).toLocaleString():'Best month'},
      // Annual cost of every recurring charge still running. Individually a subscription reads
      // as a few dollars a week and never looks worth cancelling; the yearly figure is the one
      // that makes the case either way, and it is the number nobody ever works out by hand.
      {val:'$'+Math.round(loadFixCats().filter(c=>catIsRecurring(c)&&catIsCharging(c))
            .reduce((s,c)=>s+((parseFloat(catAmount(c))||0)*({weekly:52,monthly:12,yearly:1}[catCycle(c)]||0)),0)).toLocaleString(),
       lbl:'Recurring, per year'},
    ].map(s=>'<div class="sum-card"><div class="sum-card-val">'+s.val+'</div><div class="sum-card-lbl">'+s.lbl+'</div>'+(s.chip?'<div class="sum-card-chip">'+s.chip+'</div>':'')+'</div>').join('');
  }

  // ── Month-by-month table ──
  // The arrays above already held all of this; the view just never showed it itemised.
  const ml=document.getElementById('year-months-list');
  if(ml){
    ml.innerHTML=withData.length
      ? '<div class="year-mo-row year-mo-head"><span>Month</span><span>In</span><span>Out</span><span>Saved</span><span>Rate</span></div>'+
        withData.map(m=>{
          const out=m.fixed+m.variable;
          const rate=m.income>0?(m.saved/m.income*100):0;
          // Flat and legible: a twelve-row table with a green/amber/grey column in it was
          // twelve verdicts stacked on top of each other. A month with nothing recorded is
          // still muted, because that is absence of data rather than a bad result.
          return '<div class="year-mo-row">'+
            '<span class="year-mo-name">'+m.label+'</span>'+
            '<span>'+fmtMoney(m.income)+'</span>'+
            '<span>'+fmtMoney(out)+'</span>'+
            '<span>'+fmtMoney(m.saved)+'</span>'+
            '<span'+(rate>0?'':' style="color:var(--muted)"')+'>'+rate.toFixed(0)+'%</span>'+
          '</div>';
        }).join('')
      : '<div style="text-align:center;color:var(--muted);font-size:13px;padding:18px 0">Nothing recorded in '+year+' yet.</div>';
  }

  // ── Which categories are rising ──
  // A yearly total says what you spent; it doesn't say what is getting worse. This compares the
  // last 3 months of data against the 3 before them, per variable category, so a habit that has
  // crept up is visible while it is still worth acting on. Needs 4+ months of data to mean
  // anything — below that the two windows overlap or one is empty, and the comparison would be
  // noise dressed up as a trend, so the card simply doesn't render.
  const trendsEl=document.getElementById('year-trends');
  if(trendsEl){
    trendsEl.innerHTML='';
    if(withData.length>=4){
      const recent=withData.slice(-3), prior=withData.slice(-6,-3);
      if(prior.length){
        const sumCat=(mons,catId)=>mons.reduce((s,m)=>
          s+(m.keys||[]).reduce((t,k)=>t+varCatAmount(budgetData[k],k,catId),0),0);
        const rows=activeCats(loadVarCats()).map(c=>{
          const now=sumCat(recent,c.id)/recent.length, was=sumCat(prior,c.id)/prior.length;
          return {label:catLabel(c), now, was, diff:now-was,
                  pct: was>0 ? ((now-was)/was*100) : (now>0?100:0)};
        }).filter(r=>r.diff>0 && r.now>0).sort((a,b)=>b.diff-a.diff).slice(0,4);
        if(rows.length){
          trendsEl.innerHTML='<div class="card"><div class="sec-label">Rising fastest</div>'+
            '<div class="up-hint" style="border:none;margin:0 0 8px;padding:0">Average per month, last 3 vs the 3 before</div>'+
            rows.map(r=>'<div class="up-row">'+
              '<span class="up-name">'+_catEscHtml(r.label)+'</span>'+
              // A real judgement — this category is getting worse — so it gets a tonal chip
              // with an arrow and a number, and the money beside it stays neutral.
              '<span class="up-when" style="flex:0 0 auto">'+tstat(r.pct>=25?'neg':'warn','+'+Math.round(r.pct)+'%','up',true)+'</span>'+
              '<span class="up-amt">'+fmtMoney(r.was)+' → '+fmtMoney(r.now)+'</span>'+
            '</div>').join('')+
          '</div>';
        }
      }
    }
  }

  // ── Stacked bar + savings-rate line ──
  if(yearStackChart){ yearStackChart.destroy(); yearStackChart=null; }
  const stackWrap=document.getElementById('year-stack-wrap');
  const stackLegend=document.getElementById('year-stack-legend');
  const {gc,tc}=budChartGridColors();
  if(stackWrap){
    if(withData.length<2){
      stackWrap.innerHTML='<div style="text-align:center;color:var(--muted);font-size:13px;padding:20px 0">Not enough data yet.</div>';
      if(stackLegend) stackLegend.innerHTML='';
    } else {
      if(stackLegend) stackLegend.innerHTML=budChartLegend([
        {c:BUD_CHART_COLORS.fixed,l:'Fixed'},
        {c:BUD_CHART_COLORS.variable,l:'CC / variable'},
        {c:BUD_CHART_COLORS.saved,l:'Saved'},
        {c:BUD_CHART_COLORS.rate,l:'Savings rate %',dash:true},
      ]);
      stackWrap.style.height='280px';
      stackWrap.innerHTML='<canvas id="year-stack-chart"></canvas>';
      yearStackChart=new Chart(document.getElementById('year-stack-chart'),{
        type:'bar',
        data:{
          labels:points.map(p=>p.label),
          datasets:[
            {label:'Fixed',data:fixedArr,backgroundColor:BUD_CHART_COLORS.fixed,stack:'s'},
            {label:'CC / variable',data:varArr,backgroundColor:BUD_CHART_COLORS.variable,stack:'s'},
            {label:'Saved',data:points.map(p=>p.saved),backgroundColor:BUD_CHART_COLORS.saved,stack:'s',borderRadius:{topLeft:4,topRight:4}},
            // Same accent as the Saved bars — they are the same story — separated by being a
            // dashed line with markers on a second axis rather than by a fifth unrelated hue.
            {label:'Savings rate',data:rateArr,type:'line',yAxisID:'y2',borderColor:BUD_CHART_COLORS.rate,backgroundColor:BUD_CHART_COLORS.rate,borderWidth:2,borderDash:[5,4],pointRadius:3,pointStyle:'rectRot',pointBackgroundColor:BUD_CHART_COLORS.rate,tension:0.3,fill:false}
          ]
        },
        options:{
          responsive:true,maintainAspectRatio:false,
          plugins:{
            legend:{display:false},
            tooltip:{callbacks:{label:c=>c.dataset.label==='Savings rate'?c.dataset.label+': '+c.parsed.y.toFixed(0)+'%':c.dataset.label+': $'+c.parsed.y.toFixed(0)}}
          },
          scales:{
            x:{stacked:true,grid:{display:false},ticks:{color:tc,font:{size:11},maxTicksLimit:12}},
            y:{stacked:true,grid:{color:gc},ticks:{color:tc,font:{size:11},callback:v=>'$'+v},beginAtZero:true},
            y2:{position:'right',min:0,max:50,grid:{display:false},ticks:{color:tc,font:{size:11},callback:v=>v+'%'}}
          }
        }
      });
    }
  }

  // ── Monthly CC / variable spending line ──
  if(yearCCChart){ yearCCChart.destroy(); yearCCChart=null; }
  const ccWrap=document.getElementById('year-cc-wrap');
  const ccLegend=document.getElementById('year-cc-legend');
  if(ccWrap){
    if(withData.length<2){
      ccWrap.innerHTML='<div style="text-align:center;color:var(--muted);font-size:13px;padding:20px 0">Not enough data yet.</div>';
      if(ccLegend) ccLegend.innerHTML='';
    } else {
      if(ccLegend) ccLegend.innerHTML=budChartLegend([{c:BUD_CHART_COLORS.variable,l:'CC / variable spending'}]);
      ccWrap.style.height='200px';
      ccWrap.innerHTML='<canvas id="year-cc-chart"></canvas>';
      yearCCChart=new Chart(document.getElementById('year-cc-chart'),{
        type:'line',
        data:{
          labels:points.map(p=>p.label),
          datasets:[
            {label:'CC / variable spending',data:varArr,borderColor:BUD_CHART_COLORS.variable,backgroundColor:budWarmRgba(0.14),borderWidth:2.5,pointRadius:3,pointBackgroundColor:BUD_CHART_COLORS.variable,fill:true,tension:0.3}
          ]
        },
        options:{
          responsive:true,maintainAspectRatio:false,
          plugins:{
            legend:{display:false},
            tooltip:{callbacks:{label:c=>'$'+c.parsed.y.toFixed(0)}}
          },
          scales:{
            x:{grid:{display:false},ticks:{color:tc,font:{size:11},maxTicksLimit:12}},
            y:{grid:{color:gc},ticks:{color:tc,font:{size:11},callback:v=>'$'+v},beginAtZero:true}
          }
        }
      });
    }
  }
}

// ── Budget trends ─────────────────────────────────────────────────
function getBudWeekTotals(d){
  return {income:weekIncome(d), spending:weekSpending(d), saved:weekSavedAmt(d)};
}
function getBudTrendPoints(range){
  const groups={};
  const allKeys=Object.keys(budgetData).sort();
  let filteredKeys=allKeys;
  if(range==='monthly'){
    const cutoff=localMidnight(getLocalDate());
    cutoff.setDate(1);
    cutoff.setMonth(cutoff.getMonth()-11);
    const cutoffYM=dateStr(cutoff).substring(0,7);
    filteredKeys=allKeys.filter(k=>k.substring(0,7)>=cutoffYM);
  }
  filteredKeys.forEach(k=>{
    const d=budgetData[k]; if(!d) return;
    const mon=new Date(k+'T12:00:00');
    const groupKey=range==='yearly'?String(mon.getFullYear()):k.substring(0,7);
    if(!groups[groupKey]) groups[groupKey]={income:0,spending:0,saved:0};
    const t=getBudWeekTotals(d);
    groups[groupKey].income+=t.income;
    groups[groupKey].spending+=t.spending;
    groups[groupKey].saved+=t.saved;
  });
  const sortedLog=[...savingsLog].sort((a,b)=>a.date<b.date?-1:1);
  return Object.keys(groups).sort().map(k=>{
    const label=range==='yearly'?k:(([y,m])=>
      new Date(parseInt(y),parseInt(m)-1,1).toLocaleDateString('en-AU',{month:'short',year:'2-digit'})
    )(k.split('-'));
    const relevant=sortedLog.filter(e=>(range==='yearly'?e.date.substring(0,4):e.date.substring(0,7))<=k);
    const balance=relevant.length?relevant[relevant.length-1].balance:null;
    return {label,...groups[k],balance};
  });
}
function setBudTrendRange(range){
  budTrendRange=range;
  ['monthly','yearly','alltime'].forEach(r=>{
    const btn=document.getElementById('btr-'+r); if(!btn) return;
    btn.style.background=r===range?'var(--header)':'transparent';
    btn.style.color=r===range?'#fff':'var(--muted)';
  });
  renderBudTrend();
}
function renderBudTrend(){
  const wrap=document.getElementById('bud-trend-wrap'); if(!wrap) return;
  if(budChart){budChart.destroy();budChart=null;}
  const points=getBudTrendPoints(budTrendRange);
  if(points.length<2){
    wrap.innerHTML='<div style="text-align:center;color:var(--muted);font-size:13px;padding:20px 0">Not enough data yet.</div>';
    return;
  }
  wrap.innerHTML='<canvas id="bud-trend-chart"></canvas>';
  const ctx=document.getElementById('bud-trend-chart'); if(!ctx) return;
  const {gc,tc}=budChartGridColors();
  budChart=new Chart(ctx,{
    type:'line',
    data:{
      labels:points.map(p=>p.label),
      datasets:[
        // Same mapping as Budget Month / Yearly: neutral income, warm spending, accent saved,
        // and the account balance as a dashed neutral reference.
        {label:'Income',data:points.map(p=>p.income),borderColor:BUD_CHART_COLORS.income,backgroundColor:'transparent',borderWidth:2,pointRadius:3,pointBackgroundColor:BUD_CHART_COLORS.income,fill:false,tension:0.3},
        {label:'Spending',data:points.map(p=>p.spending),borderColor:BUD_CHART_COLORS.spending,backgroundColor:budWarmRgba(0.10),borderWidth:2.5,pointRadius:4,pointBackgroundColor:BUD_CHART_COLORS.spending,fill:false,tension:0.3},
        {label:'Saved',data:points.map(p=>p.saved),borderColor:BUD_CHART_COLORS.saved,backgroundColor:budAccentRgba(0.10),borderWidth:2.5,pointRadius:4,pointBackgroundColor:BUD_CHART_COLORS.saved,fill:false,tension:0.3},
        {label:'Account',data:points.map(p=>p.balance),borderColor:BUD_CHART_COLORS.fixed,backgroundColor:'transparent',borderWidth:2,pointRadius:3,pointBackgroundColor:BUD_CHART_COLORS.fixed,fill:false,tension:0.3,spanGaps:false,borderDash:[5,4]}
      ]
    },
    options:{
      responsive:true,
      // The only chart in the app that keeps its aspect ratio. On a landscape phone that means
      // a ~780px-wide canvas computes a ~440px-tall one — taller than the whole viewport — so
      // the CSS max-height cap alone cannot save it (Chart.js would keep resizing back). Ratio
      // is dropped at that size only; every other viewport keeps the existing behaviour.
      maintainAspectRatio:(typeof isLandscapePhone==='function' && isLandscapePhone())?false:true,
      plugins:{
        legend:{display:true,labels:{color:tc,font:{size:12},usePointStyle:true,pointStyleWidth:10}},
        tooltip:{callbacks:{label:c=>c.dataset.label+': $'+c.parsed.y.toFixed(0)}}
      },
      scales:{
        x:{grid:{color:gc},ticks:{color:tc,font:{size:11},maxTicksLimit:8}},
        y:{grid:{color:gc},ticks:{color:tc,font:{size:11},callback:v=>'$'+v},beginAtZero:true}
      }
    }
  });
}

// ── Savings account card ──────────────────────────────────────────
function renderSavingsCard(){
  const wrap=document.getElementById('bud-savings-card-wrap'); if(!wrap) return;
  const today=getLocalDate();
  const sorted=[...savingsLog].sort((a,b)=>a.date<b.date?-1:1);
  const cur=sorted.length?sorted[sorted.length-1]:null;
  wrap.innerHTML=`<div class="card">
    <div class="sec-label bud-head-label" style="margin-bottom:12px">${cardIcon('bank')}<span>Savings account</span></div>
    <div style="display:flex;gap:8px;margin-bottom:12px;align-items:stretch">
      <div style="flex:1;display:flex;flex-direction:column;gap:6px">
        <input type="date" id="sav-log-date" value="${today}"
          style="width:100%;height:40px;border:1.5px solid var(--border);border-radius:8px;font-size:14px;padding:0 10px;background:var(--card);color:var(--text)">
        <input type="number" id="sav-log-bal" inputmode="decimal" min="0" step="0.01" placeholder="Balance ($)"
          style="width:100%;height:40px;border:1.5px solid var(--border);border-radius:8px;font-size:18px;font-weight:500;text-align:center;background:var(--card);color:var(--text)">
      </div>
      <button onclick="logSavingsBalance()"
        style="padding:0 18px;background:var(--header);color:#fff;border:none;border-radius:8px;font-size:14px;font-weight:600;cursor:pointer">Log</button>
    </div>
    ${cur?`<div style="margin-bottom:10px">
      <div style="font-size:28px;font-weight:800">$${cur.balance.toLocaleString()}</div>
      <div style="font-size:12px;color:var(--muted)">Logged ${cur.date}</div>
    </div>`:''}
    ${sorted.length?`<div style="max-height:160px;overflow-y:auto">
      ${[...sorted].reverse().map(e=>`
        <div style="display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:1px solid var(--border)">
          <span style="font-size:13px;color:var(--muted)">${e.date}</span>
          <span style="font-size:14px;font-weight:600">$${e.balance.toLocaleString()}</span>
          <button onclick="deleteSavingsEntry('${e.date}')" style="font-size:12px;color:var(--danger);background:none;border:none;cursor:pointer;padding:0 4px">✕</button>
        </div>`).join('')}
    </div>`:'<div style="text-align:center;color:var(--muted);font-size:13px;padding:8px 0">No entries yet — log your balance above</div>'}
  </div>`;
}
function logSavingsBalance(){
  const dateEl=document.getElementById('sav-log-date');
  const balEl=document.getElementById('sav-log-bal');
  const bal=parseFloat(balEl.value);
  const date=dateEl.value;
  if(!bal||!date) return;
  savingsLog=savingsLog.filter(e=>e.date!==date);
  savingsLog.push({date,balance:bal,t:Date.now()}); // t lets this win the newest-per-date merge
  savingsLog.sort((a,b)=>a.date<b.date?-1:1);
  saveSavingsLog();
  balEl.value='';
  renderSavingsCard();
  if(statsSubTab==='finance'){ renderBSBalance(); renderBSAccountGrowth(); renderBSTrend(); }
}
function deleteSavingsEntry(date){
  savingsLog=savingsLog.filter(e=>e.date!==date);
  saveSavingsLog();
  renderSavingsCard();
  if(statsSubTab==='finance'){ renderBSBalance(); renderBSAccountGrowth(); renderBSTrend(); }
}

// ── Savings goals card ────────────────────────────────────────────
function renderGoalsCard(){
  const wrap=document.getElementById('bud-goals-card-wrap'); if(!wrap) return;
  const goals=budDefaults.goals||[];
  const sortedLog=[...savingsLog].sort((a,b)=>a.date<b.date?-1:1);
  const curBal=sortedLog.length?sortedLog[sortedLog.length-1].balance:0;
  const goalsHTML=goals.map((g,i)=>{
    const pct=g.target>0?Math.min(100,Math.round(curBal/g.target*100)):0;
    const remaining=Math.max(0,g.target-curBal);
    const bc=pct>=100?'var(--success)':pct>=50?'var(--warn)':'#3b82f6';
    const weeksLeft=Math.max(0,(new Date(g.date+'T12:00:00')-new Date())/(7*864e5));
    const weeklyNeeded=weeksLeft>0&&remaining>0?'$'+Math.ceil(remaining/weeksLeft).toLocaleString()+'/wk needed':null;
    return `<div style="padding:12px 0;border-bottom:1px solid var(--border)">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px">
        <div style="font-size:15px;font-weight:700">${g.name}</div>
        <div style="display:flex;align-items:center;gap:8px">
          <span style="font-size:12px;color:var(--muted)">$${g.target.toLocaleString()} by ${g.date}</span>
          <button onclick="deleteGoal(${i})" style="font-size:12px;color:var(--danger);background:none;border:none;cursor:pointer;padding:0">✕</button>
        </div>
      </div>
      <div style="height:6px;background:var(--border);border-radius:3px;overflow:hidden;margin-bottom:6px">
        <div style="width:${pct}%;height:100%;background:${bc};border-radius:3px"></div>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:12px;color:var(--muted)">
        <span>${pct}%${curBal>0?' ($'+curBal.toLocaleString()+')':''}</span>
        <span>${pct>=100?'🎉 Reached!':(remaining>0?'$'+remaining.toLocaleString()+' to go':'')+(weeklyNeeded?' · '+weeklyNeeded:'')}</span>
      </div>
    </div>`;
  }).join('');
  wrap.innerHTML=`<div class="card">
    <div class="sec-label bud-head-label" style="margin-bottom:12px">${cardIcon('target')}<span>Savings goals</span></div>
    <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:${goals.length?'4px':'0'}">
      <input type="text" id="goal-name" placeholder="Goal name" style="flex:1 1 100px;min-width:0;max-width:100%;box-sizing:border-box;height:38px;border:1.5px solid var(--border);border-radius:8px;font-size:13px;padding:0 8px;background:var(--card);color:var(--text)">
      <input type="number" id="goal-target" inputmode="decimal" placeholder="$ Target" style="flex:1 1 70px;min-width:0;max-width:100%;box-sizing:border-box;height:38px;border:1.5px solid var(--border);border-radius:8px;font-size:13px;text-align:center;background:var(--card);color:var(--text)">
      <input type="date" id="goal-date" style="flex:1 1 110px;min-width:0;max-width:100%;box-sizing:border-box;height:38px;border:1.5px solid var(--border);border-radius:8px;font-size:13px;padding:0 6px;background:var(--card);color:var(--text)">
      <button onclick="addGoal()" style="flex-shrink:0;padding:0 14px;height:38px;background:var(--header);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer">Add</button>
    </div>
    ${goals.length?goalsHTML:'<div style="text-align:center;color:var(--muted);font-size:13px;padding:12px 0">Add a goal above</div>'}
  </div>`;
}
function addGoal(){
  const name=document.getElementById('goal-name')?.value.trim();
  const target=parseFloat(document.getElementById('goal-target')?.value);
  const date=document.getElementById('goal-date')?.value;
  if(!name||!target||!date) return;
  if(!budDefaults.goals) budDefaults.goals=[];
  budDefaults.goals.push({name,target,date});
  localStorage.setItem('daily_budget_defaults',JSON.stringify(budDefaults));
  syncBudDefaultsToFirebase();
  renderGoalsCard();
}
function deleteGoal(i){
  budDefaults.goals=(budDefaults.goals||[]).filter((_,idx)=>idx!==i);
  localStorage.setItem('daily_budget_defaults',JSON.stringify(budDefaults));
  syncBudDefaultsToFirebase();
  renderBSGoals();
}

// ── Budget Stats (Stats tab) ──────────────────────────────────────
// Account-derived cards lead: the Finance tab was almost entirely budget data with the net
// worth chart buried below four budget cards, so account history was effectively hidden.
const STATS_FIN_LAYOUT={
  mobile:[
    ['bs-finance-left',['bs-week-wrap','bs-balance-wrap','bs-acctgrowth-wrap','bs-trend-wrap-card']],
    ['bs-finance-right',[]]
  ],
  desktop:[
    ['bs-finance-left',['bs-week-wrap','bs-acctgrowth-wrap']],
    ['bs-finance-right',['bs-balance-wrap','bs-trend-wrap-card']]
  ]
};
let _statsFinanceLayoutMode=null;
function statsApplyFinanceLayout(force){
  const mode=window.innerWidth>=1024?'desktop':'mobile';
  if(mode===_statsFinanceLayoutMode&&!force) return;
  const plan=STATS_FIN_LAYOUT[mode];
  if(!plan.every(([colId])=>document.getElementById(colId))) return;
  plan.forEach(([colId,ids])=>{
    const col=document.getElementById(colId);
    const want=ids.map(id=>document.getElementById(id)).filter(Boolean);
    const have=Array.from(col.children);
    if(have.length===want.length&&want.every((el,i)=>have[i]===el)) return;
    want.forEach(el=>col.appendChild(el));
  });
  _statsFinanceLayoutMode=mode;
}
function renderBudgetStats(){
  statsApplyFinanceLayout();
  renderBSWeek();
  renderBSBalance();
  renderBSAccountGrowth();
  renderBSTrend();
  renderBSCatBreakdown();
}
// The latest CLOSED week, read against the plan that was saved for that week. This used to
// exist only as a Review card, which left the Finance tab opening on a net-worth chart with
// no weekly result anywhere on it.
function renderBSWeek(){
  const wrap=document.getElementById('bs-week-wrap'); if(!wrap) return;
  const weeks=statsCompletedWeeks();
  const head=cardHeader('wallet','Latest completed week');
  if(!weeks.length){
    wrap.innerHTML='<div class="card">'+head+'<div class="stats-note-panel">No completed budget week yet. The current week is still in progress and is never scored as a result.</div></div>';
    return;
  }
  const k=weeks[weeks.length-1], d=budgetData[k];
  const parts=statsWeekParts(d,k), q=statsWeekSpendQuality(d,k);
  const target=parseFloat(d.statsSnapshot&&d.statsSnapshot.totalTarget);
  const comparable=!q.ambiguousLegacyVariable&&!isNaN(target)&&target>0;
  const over=comparable&&parts.total>target;
  const pct=comparable?Math.min(100,Math.round(parts.total/target*100)):0;
  const saved=weekSavedAmt(d);
  wrap.innerHTML='<div class="card">'+
    cardHeader('wallet','Latest completed week',
      (comparable?statsChip(over?'warn':'good',(over?'Over':'Under')+' plan'):statsChip('neutral',q.ambiguousLegacyVariable?'Legacy week':'No saved plan'))+
      '<button class="card-hd-act" onclick="openBudgetWeekFromStats(\''+k+'\')">Open week &rarr;</button>')+
    statsFigure(fmtMoney(Math.round(parts.total)),'','Spent · week of '+fmtDate(k)+(comparable?' · saved plan '+fmtMoney(target):''))+
    (comparable?'<div class="card-bar"><div class="card-bar-fill" style="width:'+pct+'%;background:'+(over?'var(--danger)':'var(--positive)')+'"></div></div>':'')+
    statsSplit([
      ['Fixed',fmtMoney(Math.round(parts.fixed))],
      ['Variable',fmtMoney(Math.round(parts.variable))],
      ['Saved',fmtMoney(Math.round(saved))]
    ])+
    '<div class="stats-data-note">'+
      (q.ambiguousLegacyVariable
        ? 'This week stores only a legacy aggregate, and later transactions cannot be safely separated from it — the known figure is shown and no total is invented.'
        : comparable
          ? (over?'Over':'Under')+' by '+fmtMoney(Math.abs(parts.total-target))+'. The plan is the one saved with that week, not today’s budget settings.'
          : 'No plan snapshot was saved for this week, so today’s targets are deliberately not substituted for it.')+
      (parts.variableFromSnapshot?' Variable spend comes from the week’s stored aggregate; no per-category detail exists for it.':' Transactions override manual category figures wherever they exist.')+
    '</div></div>';
}

// ── Finance: which accounts actually moved ────────────────────────
// The net worth chart shows the total but not where it came from. This ranks each account by
// its effect on net worth over the period, so a rise driven by paying down debt reads
// differently from one driven by saving.
let bsGrowthRange='30';   // '30' | '90' | 'all'
function setBSGrowthRange(r){ bsGrowthRange=r; renderBSAccountGrowth(); }
function bsGrowthFromDate(a){
  if(bsGrowthRange==='all'){
    const h=(a&&a.history||[]).filter(e=>e&&e.date).slice().sort((x,y)=>x.date<y.date?-1:1);
    return h.length?h[0].date:getLocalDate();
  }
  const d=localMidnight(getLocalDate());
  d.setDate(d.getDate()-parseInt(bsGrowthRange,10));
  return dateStr(d);
}
function renderBSAccountGrowth(){
  const wrap=document.getElementById('bs-acctgrowth-wrap'); if(!wrap) return;
  const head=(body)=>'<div class="card" style="padding:0;overflow:hidden">'+
    '<div style="background:transparent;padding:16px 16px 0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;color:var(--muted);display:flex;justify-content:space-between;align-items:center;gap:8px">'+
      '<span class="bud-head-label">'+cardIcon('trend')+'<span>Account growth</span></span>'+
      '<div class="bs-growth-range">'+
        [['30','30d'],['90','90d'],['all','All']].map(([v,l])=>
          '<button onclick="setBSGrowthRange(\''+v+'\')" class="'+(bsGrowthRange===v?'on':'')+'">'+l+'</button>').join('')+
      '</div>'+
    '</div>'+body+'</div>';
  const tracked=accounts.filter(a=>a&&(a.history||[]).some(e=>e&&e.date));
  const completeDates=accountsHistoryDates().filter(d=>tracked.length===accounts.filter(Boolean).length&&tracked.every(a=>accountEntryAt(a,d)));
  if(completeDates.length<2){
    wrap.innerHTML=head('<div style="padding:14px 16px;text-align:center;color:var(--muted);font-size:13px">Record comparable dated balances for every account to identify what moved.</div>');
    return;
  }
  const boundary=bsGrowthRange==='all'?completeDates[0]:bsGrowthFromDate(tracked[0]);
  const from=completeDates.filter(d=>d<=boundary).pop()||completeDates[0];
  const to=completeDates[completeDates.length-1];
  const rows=tracked.map(a=>{
    const baseline=accountEntryAt(a,from), latest=accountEntryAt(a,to);
    const then=parseFloat(baseline.balance)||0;
    const now=parseFloat(latest.balance)||0;
    const delta=Math.round((now-then)*100)/100;
    // A debt shrinking RAISES net worth, so its contribution is the opposite of its delta.
    const nwEffect=(a.type==='debt')?-delta:delta;
    const pct=then?Math.round((delta/Math.abs(then))*1000)/10:null;
    return {a,from,to,delta,nwEffect,pct};
  }).sort((x,y)=>y.nwEffect-x.nwEffect);
  const netChange=rows.reduce((s,r)=>s+r.nwEffect,0);
  const body='<div style="padding:6px 16px 14px">'+
    rows.map(r=>{
      const evKey=statsRegisterAccountEvidence(r);
      const good=r.nwEffect>0, flat=r.nwEffect===0;
      const col=flat?'var(--muted)':(good?'var(--success)':'var(--danger)');
      const arrow=flat?'':(r.delta>0?'▲':'▼');
      return '<button type="button" class="bs-growth-row" onclick="openAccountGrowthEvidence(\''+evKey+'\')">'+
        '<div class="bs-growth-name">'+_catEscHtml(a_name(r.a))+
          '<span class="bs-growth-type">'+(r.a.type==='debt'?'Debt':'Asset')+'</span></div>'+
        '<div class="bs-growth-spark">'+(acctSparklineHtml(r.a,r.from,r.to)||'')+'</div>'+
        '<div class="bs-growth-delta" style="color:'+col+'">'+
          (flat?'—':arrow+' '+fmtMoney(Math.abs(r.delta)))+
          (r.pct!==null&&!flat?'<span class="bs-growth-pct">'+(r.pct>0?'+':'')+r.pct+'%</span>':'')+
        '</div>'+
      '</button>';
    }).join('')+
    '<div class="stats-data-note">Comparable account coverage · '+fmtDate(from)+' – '+fmtDate(to)+' · balances carry forward between updates.</div>'+
    '<div class="bs-growth-total">'+
      '<span>Net worth change</span>'+
      '<span style="color:'+(netChange>0?'var(--success)':netChange<0?'var(--danger)':'var(--muted)')+'">'+
        (netChange===0?'—':(netChange>0?'▲ ':'▼ ')+fmtMoney(Math.abs(netChange)))+'</span>'+
    '</div>'+
  '</div>';
  wrap.innerHTML=head(body);
}
function a_name(a){ return (a&&a.name)||'Account'; }

// ── Finance: spending category breakdown (fixed + variable, last 12 saved weeks) ─
function statsWeekCatDefs(d,key,kind){
  const snap=d&&d.statsSnapshot;
  const prefix=kind==='fixed'?'fix_':'var_';
  const snapDefs=snap&&Array.isArray(snap[kind])?snap[kind]:[];
  const byId={}; snapDefs.forEach(c=>{ if(c&&c.id) byId[c.id]=c.label||('Category '+c.id); });
  const ids=new Set(Object.keys(d||{}).filter(k=>k.startsWith(prefix)&&k!=='var_goal').map(k=>k.slice(prefix.length)));
  snapDefs.forEach(c=>{ if(c&&c.id) ids.add(c.id); });
  if(kind==='fixed'&&d&&d.fixRates) Object.keys(d.fixRates).forEach(id=>ids.add(id));
  if(kind==='variable') txnsForWeek(key).forEach(t=>{ if(t&&t.catId) ids.add(t.catId); });
  return [...ids].map(id=>({id,label:byId[id]||('Category '+id),snapshot:!!byId[id]}));
}
function statsFixedCatAmount(d,id){
  const v=d&&d['fix_'+id];
  if(v!==undefined&&v!=='') return parseFloat(v)||0;
  if(d&&d.fixRates&&Object.prototype.hasOwnProperty.call(d.fixRates,id)) return parseFloat(d.fixRates[id])||0;
  return 0;
}
function statsHasFixedDetail(d,defs){
  return (defs||[]).some(c=>{
    const v=d&&d['fix_'+c.id];
    return (v!==undefined&&v!==''&&v!==null)||!!(d&&d.fixRates&&Object.prototype.hasOwnProperty.call(d.fixRates,c.id));
  });
}
function statsHasVariableDetail(d,key,defs){
  return (defs||[]).some(c=>{
    const v=d&&d['var_'+c.id];
    return (v!==undefined&&v!==''&&v!==null)||txnsForWeekCat(key,c.id).length>0;
  });
}
// One definition of a week's spend, split into the two halves the Finance tab shows. Each
// half resolves independently: a transaction must override a manual variable figure without
// discarding a legacy snapshot's only surviving fixed aggregate.
function statsWeekParts(d,key){
  const fixed=statsWeekCatDefs(d,key,'fixed'), variable=statsWeekCatDefs(d,key,'variable');
  const fixedDetail=statsHasFixedDetail(d,fixed), variableDetail=statsHasVariableDetail(d,key,variable);
  const fixedTotal=fixedDetail
    ? fixed.reduce((sum,c)=>sum+statsFixedCatAmount(d,c.id),0)
    : (d&&d.snapshot?parseFloat(d.snapshot.fixed)||0:0);
  const variableTotal=variableDetail
    ? variable.reduce((sum,c)=>sum+varCatAmount(d,key,c.id),0)
    : (d&&d.snapshot?parseFloat(d.snapshot.variable)||0:0);
  return {fixed:fixedTotal,variable:variableTotal,total:fixedTotal+variableTotal,
    fixedFromSnapshot:!fixedDetail,variableFromSnapshot:!variableDetail};
}
function statsWeekSpending(d,key){ return statsWeekParts(d,key).total; }
function statsWeekSpendQuality(d,key){
  const hasRawVariable=Object.keys(d||{}).some(k=>k.startsWith('var_')&&k!=='var_goal'&&d[k]!==''&&d[k]!==null&&d[k]!==undefined);
  const legacyVariable=parseFloat(d&&d.snapshot&&d.snapshot.variable)||0;
  return {
    ambiguousLegacyVariable:!!(legacyVariable&&!hasRawVariable&&txnsForWeek(key).length)
  };
}
function renderBSCatBreakdown(){
  const wrap=document.getElementById('bs-catbreak-wrap'); if(!wrap) return;
  const keys=Object.keys(budgetData)
    .filter(k=>{const d=budgetData[k]; return d&&(d.saved||d.draft||d.snapshot);})
    .sort().slice(-12);
  if(!keys.length){ wrap.innerHTML=''; return; }
  // Same mapping as Budget Month/Yearly rather than a tenth of a rainbow: committed money is
  // neutral, discretionary money is the one warm tone, and rank inside each family is carried
  // by opacity. The bar LENGTH is what says which category is biggest.
  const catBarColor=(kind,rank)=>{
    const a=Math.max(0.28, 0.92 - rank*0.11).toFixed(2);
    if(kind==='Variable') return budWarmRgba(a);
    const dark=(typeof S==='object')?S.theme!=='light':true;
    return (dark?'rgba(255,255,255,':'rgba(28,28,30,')+(a*0.42).toFixed(3)+')';
  };
  const catMap={}; let legacyWeeks=0, ambiguousWeeks=0;
  const add=(kind,def,val,key)=>{
    if(!val) return;
    const mapKey=kind+'|'+def.id+'|'+def.label;
    if(!catMap[mapKey]) catMap[mapKey]={id:def.id,label:def.label,val:0,kind:kind==='fixed'?'Fixed':kind==='variable'?'Variable':'Legacy',weeks:[]};
    catMap[mapKey].val+=val;
    catMap[mapKey].weeks.push({key,val});
  };
  keys.forEach(k=>{
    const d=budgetData[k];
    if(!d.statsSnapshot) legacyWeeks++;
    if(statsWeekSpendQuality(d,k).ambiguousLegacyVariable) ambiguousWeeks++;
    const fixed=statsWeekCatDefs(d,k,'fixed'), variable=statsWeekCatDefs(d,k,'variable');
    const fixedDetailed=statsHasFixedDetail(d,fixed), variableDetailed=statsHasVariableDetail(d,k,variable);
    if(!fixedDetailed&&d.snapshot) add('legacy',{id:'fixed-aggregate',label:'Legacy fixed aggregate'},parseFloat(d.snapshot.fixed)||0,k);
    if(!variableDetailed&&d.snapshot) add('legacy',{id:'variable-aggregate',label:'Legacy variable aggregate'},parseFloat(d.snapshot.variable)||0,k);
    if(fixedDetailed) fixed.forEach(def=>add('fixed',def,statsFixedCatAmount(d,def.id),k));
    if(variableDetailed) variable.forEach(def=>add('variable',def,varCatAmount(d,k,def.id),k));
  });
  const cats=Object.values(catMap);
  cats.sort((a,b)=>b.val-a.val);
  const total=cats.reduce((s,c)=>s+c.val,0);
  if(total<=0){ wrap.innerHTML=''; return; }
  const max=Math.max(1,...cats.map(c=>c.val));
  const shownCats=cats.filter(c=>c.val>0);
  // Rank restarts per family, so the biggest variable category and the biggest fixed one are
  // each the strongest tone of their own tone rather than competing on one ramp.
  const seen={};
  shownCats.forEach(c=>{ c.barColor=catBarColor(c.kind, seen[c.kind]=(seen[c.kind]===undefined?0:seen[c.kind]+1)); });
  const rows=shownCats.map(c=>{
    const evidenceKey=statsRegisterFinanceEvidence(c);
    const pctOfTotal=Math.round(c.val/total*100);
    return '<button type="button" class="stats-muscle-row" onclick="openFinanceCategoryEvidence(\''+evidenceKey+'\')" aria-label="Open '+_catEsc(c.label)+' source records"><div class="muscle-bar-row">'+
      '<div class="muscle-bar-label" style="width:110px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="'+_catEsc(c.label)+'">'+_catEscHtml(c.label)+'</div>'+
      '<div class="muscle-bar-track"><div class="muscle-bar-fill" style="width:'+Math.round(c.val/max*100)+'%;background:'+c.barColor+'"></div></div>'+
      '<div class="muscle-bar-count" style="width:78px">$'+Math.round(c.val).toLocaleString()+' · '+pctOfTotal+'%</div>'+
    '</div></button>';
  }).join('');
  wrap.innerHTML='<div class="card" style="padding:0;overflow:hidden">'+
    cardHeader('receipt','Where the money goes · last '+keys.length+' week'+(keys.length>1?'s':''))+
    '<div style="padding:14px 16px">'+
      (legacyWeeks?'<div class="stats-data-note">'+legacyWeeks+' legacy week'+(legacyWeeks===1?' has':'s have')+' no saved category labels. Archived IDs are retained, but current labels are not presented as historical fact.</div>':'')+
      (ambiguousWeeks?'<div class="stats-data-note">'+ambiguousWeeks+' snapshot-only legacy week'+(ambiguousWeeks===1?' has':'s have')+' later transaction detail that cannot be safely reconciled with the old aggregate. Only known transaction detail is shown; no total is invented.</div>':'')+
      rows+
      '<div style="display:flex;justify-content:space-between;font-size:12px;color:var(--muted);border-top:1px solid var(--border);padding-top:10px;margin-top:4px"><span>'+(ambiguousWeeks?'Known categorised spend':'Total spent')+'</span><b style="color:var(--text)">$'+Math.round(total).toLocaleString()+'</b></div>'+
    '</div></div>';
}

function renderBSProgress(){
  const wrap=document.getElementById('bs-progress-wrap'); if(!wrap) return;
  const keys=Object.keys(budgetData).filter(k=>{const d=budgetData[k];return d&&(d.saved||d.draft||d.snapshot);}).sort();
  if(!keys.length){ wrap.innerHTML=''; return; }
  const weekCount=keys.length;
  const totalSaved=keys.reduce((s,k)=>s+weekSavedAmt(budgetData[k]),0);
  const goal=getSavingsGoal();
  const cumulativeGoal=goal*weekCount;
  const pct=cumulativeGoal>0?Math.min(100,Math.round(totalSaved/cumulativeGoal*100)):0;
  // The bar is the primary saved series, so it stays in the accent whatever the outcome; the
  // outcome itself is stated in words beside the percentage.
  const chip = !cumulativeGoal ? ''
    : totalSaved>=cumulativeGoal ? tstat('pos','At goal','check',true)
    : totalSaved>=cumulativeGoal*0.85 ? tstat('pos','On track','check',true)
    : totalSaved>=cumulativeGoal*0.6 ? tstat('warn','Behind','flat',true)
    : tstat('neg','Well behind','down',true);
  wrap.innerHTML='<div class="card bst-prog-card">'+
    '<div class="bst-prog-label">Total saved · '+weekCount+' week'+(weekCount>1?'s':'')+' tracked</div>'+
    '<div class="bst-prog-val">$'+Math.round(totalSaved).toLocaleString()+'</div>'+
    '<div class="bst-prog-goal">of $'+cumulativeGoal.toLocaleString()+' cumulative goal ($'+goal+'/wk)</div>'+
    '<div style="height:8px;background:var(--border);border-radius:4px;overflow:hidden;margin-top:12px">'+
      '<div style="width:'+pct+'%;height:100%;background:var(--accent);border-radius:4px;transition:width .4s ease"></div>'+
    '</div>'+
    '<div style="display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted);margin-top:8px">'+
      '<span>'+pct+'% of goal</span>'+chip+
    '</div>'+
  '</div>';
}

function renderBSBestWorst(){
  const wrap=document.getElementById('bs-bestworst-wrap'); if(!wrap) return;
  const keys=Object.keys(budgetData).filter(k=>budgetData[k]&&weekIncome(budgetData[k])>0);
  if(!keys.length){ wrap.innerHTML=''; return; }
  let bestKey=null,bestSav=-Infinity,worstKey=null,worstOver=-Infinity;
  keys.forEach(k=>{
    const d=budgetData[k];
    const sav=weekSavedAmt(d);
    const left=weekIncome(d)-weekSpending(d)-weekSavedAmt(d);
    if(sav>bestSav){bestSav=sav;bestKey=k;}
    if(left<0&&-left>worstOver){worstOver=-left;worstKey=k;}
  });
  const fmtWk=k=>k?new Date(k+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short'}):'—';
  wrap.innerHTML='<div class="bst-tiles">'+
    '<div class="bst-tile">'+
      '<div class="bst-tile-icon">'+cardIcon('trophy')+'</div>'+
      '<div class="bst-tile-lbl">Best week</div>'+
      '<div class="bst-tile-date">'+fmtWk(bestKey)+'</div>'+
      // The amount stays neutral; the verdict travels as a chip beside it.
      '<div class="bst-tile-val">'+(bestKey?'$'+Math.round(bestSav):'—')+'</div>'+
      (bestKey?'<div class="bst-tile-chip">'+tstat('pos','Most saved','check',true)+'</div>':'')+
    '</div>'+
    '<div class="bst-tile">'+
      '<div class="bst-tile-icon">'+cardIcon('alert')+'</div>'+
      '<div class="bst-tile-lbl">Worst week</div>'+
      '<div class="bst-tile-date">'+fmtWk(worstKey)+'</div>'+
      '<div class="bst-tile-val">'+(worstKey?'$'+Math.round(worstOver):'—')+'</div>'+
      '<div class="bst-tile-chip">'+(worstKey?tstat('neg','Over budget','alert',true):tstat('pos','No overspend','check',true))+'</div>'+
    '</div>'+
  '</div>';
}

// ── Stats: Nutrition sub-tab ──────────────────────────────────────
// Charts the archived daily calorie totals (daily_cal_history, written by
// recordCalorieHistory on every food log) plus today's live total.
let nutChart=null;
function renderNutrition(){
  const wrap=document.getElementById('nutrition-content'); if(!wrap) return;
  if(nutChart){ nutChart.destroy(); nutChart=null; }
  const today=getLocalDate();
  const todayTotal=S.dailyLog.date===today?S.dailyLog.entries.reduce((a,e)=>a+(e.kcal||0),0):0;
  const c=calcGoalCals();
  const goalCals=c?(c.goal==='cut'?c.cut:c.goal==='bulk'?c.bulk:c.maintain):null;
  const totals={...calorieHistory};
  if(todayTotal>0) totals[today]=todayTotal;
  const calendarDays=[]; const end=localMidnight(today);
  for(let i=29;i>=0;i--){ const d=new Date(end); d.setDate(d.getDate()-i); calendarDays.push(dateStr(d)); }
  const isLogged=d=>Object.prototype.hasOwnProperty.call(totals,d)&&totals[d]>0;
  const last7=calendarDays.slice(-8,-1);
  const logged7=last7.filter(isLogged);
  const vals7=logged7.map(d=>totals[d]);
  const avg7=vals7.length?Math.round(vals7.reduce((a,v)=>a+v,0)/vals7.length):null;
  const logged30=calendarDays.filter(isLogged);
  const relation=avg7!==null&&goalCals?Math.round(avg7-goalCals):null;
  // Seven-day coverage strip: a missing day is drawn as an outline, never as a zero bar.
  const max7=Math.max(1,...vals7);
  const strip=last7.map(d=>{
    const v=isLogged(d)?totals[d]:null;
    const h=v===null?0:Math.max(12,Math.round(v/max7*100));
    return '<button type="button" class="ov-day'+(v===null?' none':'')+'" onclick="openNutritionEvidence(\''+d+'\')" '+
      'aria-label="'+fmtDate(d)+(v===null?', not logged':', '+Math.round(v)+' kilocalories')+'">'+
      '<div class="ov-day-track"><div class="ov-day-fill" style="height:'+h+'%"></div></div>'+
      '<span>'+new Date(d+'T12:00:00').toLocaleDateString('en-AU',{weekday:'narrow'})+'</span></button>';
  }).join('');
  wrap.innerHTML='<div class="card">'+
    cardHeader('receipt','Calorie coverage',
      statsChip(logged7.length>=5?'good':'warn',logged7.length+' of 7 days')+
      '<button class="card-hd-act" onclick="openCalorieOverlay()">Food log &rarr;</button>')+
    statsFigure(avg7===null?'—':avg7.toLocaleString(),avg7===null?'':'kcal',
      avg7===null?'No completed day logged in the last 7'
        :'Logged-day average · '+fmtDate(last7[0])+' – '+fmtDate(last7[6]))+
    statsSplit([
      ['Today · in progress',todayTotal>0?todayTotal.toLocaleString()+' kcal':'Not logged'],
      ['Coverage · 30 days',logged30.length+' of 30'],
      ['Current reference',goalCals?goalCals.toLocaleString()+' kcal':'Not set']
    ])+
    '<div class="card-shape ov-days">'+strip+'</div>'+
    '<div class="stats-data-note">Hollow bars are days with no record — unknown, never zero, and excluded from the average. Today is counted separately because it is still in progress.'+
      (goalCals?' The '+(c.goal||'maintain')+' reference ('+goalCals.toLocaleString()+' kcal) is your CURRENT setting; historical goal changes were never stored, so it is not evidence of what a past day was aiming at.':' Set up Health to add a current calorie reference.')+
      (relation!==null?' The logged-day average sits '+(relation===0?'exactly on':Math.abs(relation)+' kcal '+(relation>0?'above':'below'))+' that reference.':'')+
    '</div>'+
    '<button class="stats-inline-link" style="margin-top:10px" onclick="openNutritionEvidence()">See dated coverage &rarr;</button>'+
  '</div>'+
  '<div class="card">'+cardHeader('trend','Logged calories · 30 calendar days')+
    (logged30.length>=2
      ? '<div class="card-cap">Gaps are unlogged days and are not joined across · tap a point for that day’s record</div>'+
        '<div class="stats-chart-box"><canvas id="nut-chart" aria-label="Daily calories over the last 30 calendar days"></canvas></div>'
      : '<div class="stats-note-panel">Log at least two days in this window to see a trend.</div>')+
    '<div class="stats-data-note">Protein, carbohydrate and fat were never stored per day, so no historical macro trend exists to show.</div>'+
  '</div>';
  if(logged30.length>=2){
    const ctx=document.getElementById('nut-chart'); if(!ctx) return;
    const {gc,tc}=budChartGridColors();
    const accent=(getComputedStyle(document.documentElement).getPropertyValue('--accent')||'#777').trim();
    const accentRgb=(getComputedStyle(document.documentElement).getPropertyValue('--accent-rgb')||'92,92,92').trim();
    const datasets=[{label:'Logged calories',data:calendarDays.map(d=>isLogged(d)?totals[d]:null),borderColor:accent,backgroundColor:'rgba('+accentRgb+',.08)',borderWidth:2.5,pointRadius:3,pointBackgroundColor:accent,fill:false,tension:0.25,spanGaps:false}];
    if(goalCals) datasets.push({label:'Current reference',data:calendarDays.map(()=>goalCals),borderColor:'rgba(150,150,150,0.7)',borderDash:[6,4],borderWidth:1.5,pointRadius:0,fill:false});
    nutChart=new Chart(ctx,{
      type:'line',
      data:{labels:calendarDays.map(d=>d===today?'Today · in progress':new Date(d+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short'})),datasets},
      options:{
        responsive:true,maintainAspectRatio:false,
        onClick:(event,elements)=>{if(elements.length&&elements[0].datasetIndex===0)openNutritionEvidence(calendarDays[elements[0].index]);},
        plugins:{legend:{display:false},tooltip:{callbacks:{label:cx=>cx.dataset.label+': '+cx.parsed.y+' kcal'}}},
        scales:{
          x:{grid:{color:gc},ticks:{color:tc,font:{size:10},maxTicksLimit:6,maxRotation:0,minRotation:0}},
          y:{grid:{color:gc},ticks:{color:tc,font:{size:10}},beginAtZero:false}
        }
      }
    });
  }
}

// ── Stats: Overview (orientation) ────────────────────────────────
// Overview answers "what does my system look like now, and what moved?". It is deliberately
// NOT Home (no inputs, no today-only widgets, no current-week remainder) and NOT Review (no
// interpretation) — every figure names an explicit completed window and its coverage.

// Best comparable value for one literal exercise inside a window. Warm-ups are excluded by
// setMetricValue; mixed-unit histories return nothing rather than a merged number.
function statsExerciseWindowBest(name,from,to){
  const info=exerciseMetricInfo(name);
  if(info.kind==='mixed') return null;
  let best=null,date='';
  (S.sessions||[]).forEach(s=>{
    if(s.date<from||s.date>to) return;
    const ex=(s.exercises||[]).find(e=>e.name===name); if(!ex) return;
    (ex.sets||[]).forEach(set=>{
      const v=setMetricValue(set,info);
      if(v!==null&&(best===null||v>best)){ best=v; date=s.date; }
    });
  });
  return best===null?null:{value:best,date,info};
}
// The exercise performed on the most distinct days inside a window — the one literal signal
// Overview shows, chosen by evidence volume rather than by anything the user configured.
function statsTopExercise(from,to){
  const days={};
  (S.sessions||[]).forEach(s=>{
    if(s.date<from||s.date>to) return;
    (s.exercises||[]).forEach(ex=>{
      if(!ex||!ex.name) return;
      const has=(ex.sets||[]).some(statsIsWorkingSet);
      if(!has) return;
      (days[ex.name]=days[ex.name]||new Set()).add(s.date);
    });
  });
  let best=null;
  Object.keys(days).forEach(n=>{ if(!best||days[n].size>days[best].size) best=n; });
  return best?{name:best,days:days[best].size}:null;
}
// Measured weight change strictly inside a window — no interpolation, no carry-forward.
function statsWeightWindow(sorted,fromDate){
  const inWin=sorted.filter(w=>w.date>=fromDate);
  if(inWin.length<2) return null;
  const a=parseFloat(inWin[0].weight), b=parseFloat(inWin[inWin.length-1].weight);
  return {delta:+(b-a).toFixed(1),from:inWin[0].date,to:inWin[inWin.length-1].date,n:inWin.length};
}
function statsCalorieCoverage(days){
  const today=getLocalDate();
  const live=S.dailyLog&&S.dailyLog.date===today?S.dailyLog.entries.reduce((a,e)=>a+(e.kcal||0),0):0;
  const end=new Date(localMidnight(today)); end.setDate(end.getDate()-1);
  const out=[];
  for(let i=days-1;i>=0;i--){
    const d=new Date(end); d.setDate(d.getDate()-i);
    const ds=dateStr(d);
    const v=parseFloat((calorieHistory||{})[ds])||0;
    out.push({date:ds,val:v>0?v:null});
  }
  const logged=out.filter(x=>x.val!==null);
  return {days:out,logged,live,
    avg:logged.length?Math.round(logged.reduce((a,x)=>a+x.val,0)/logged.length):null,
    from:out[0].date,to:out[out.length-1].date};
}
// Completed budget weeks only, newest last. The live week is never treated as a result.
function statsCompletedWeeks(){
  const cur=weekKey(getMondayOf(0));
  return Object.keys(budgetData||{})
    .filter(k=>k<cur&&budgetData[k]&&(budgetData[k].saved||budgetData[k].snapshot||budgetData[k].draft))
    .sort();
}
// Net worth movement, but only across dates where EVERY account has a recorded balance —
// otherwise the "change" would be an account appearing, not money moving.
function statsNetWorth(){
  const tracked=accounts.filter(a=>a);
  if(!tracked.length) return null;
  if(!tracked.every(a=>(a.history||[]).some(e=>e&&e.date))) return {covered:false,accounts:tracked.length,
    missing:tracked.filter(a=>!(a.history||[]).some(e=>e&&e.date)).length};
  const dates=accountsHistoryDates().filter(d=>tracked.every(a=>accountEntryAt(a,d)));
  if(dates.length<2) return {covered:false,accounts:tracked.length,missing:0,dates:dates.length};
  const latest=dates[dates.length-1];
  const cut=localMidnight(getLocalDate()); cut.setDate(cut.getDate()-30);
  const baseline=dates.filter(d=>d<=dateStr(cut)).pop()||dates[0];
  const stale=Math.max(...tracked.map(a=>{
    const e=accountEntryAt(a,latest);
    return e?Math.floor((localMidnight(getLocalDate())-localMidnight(e.date))/864e5):Infinity;
  }));
  return {covered:true,accounts:tracked.length,latest,baseline,
    now:netWorthAt(latest),then:netWorthAt(baseline),delta:netWorthAt(latest)-netWorthAt(baseline),stale};
}

function ovBlock(icon,title,tab,body,chip){
  return '<div class="card ov-block">'+
    cardHeader(icon,title,(chip||'')+'<button class="card-hd-act" onclick="setStatsTab(\''+tab+'\')">Open '+title+' &rarr;</button>')+
    body+'</div>';
}
function renderStatsOverview(){
  const wrap=document.getElementById('overview-content'); if(!wrap) return;
  const P=statsPeriod(4);
  const trained=trainedDaysIn(P.from,P.to), trainedPrev=trainedDaysIn(P.priorFrom,P.priorTo);
  const trainDelta=trained-trainedPrev;
  const sessions=sessionsIn(P.from,P.to);
  const wa=weightGoalAnalysis();
  const cal=statsCalorieCoverage(7);
  const weeks=statsCompletedWeeks();
  const lastWeek=weeks.length?weeks[weeks.length-1]:null;
  const lastSpend=lastWeek?statsWeekSpending(budgetData[lastWeek],lastWeek):null;
  const lastQuality=lastWeek?statsWeekSpendQuality(budgetData[lastWeek],lastWeek):null;
  const lastTarget=lastWeek?parseFloat(budgetData[lastWeek].statsSnapshot&&budgetData[lastWeek].statsSnapshot.totalTarget):NaN;
  const planComparable=!!lastWeek&&!lastQuality.ambiguousLegacyVariable&&!isNaN(lastTarget)&&lastTarget>0;
  const nw=statsNetWorth();

  // ── Hero summary: the four highest-order facts, each naming its own window ──
  const heroCells=[
    {tab:'training',l:'Trained days',v:S.sessions.length?trained:'—',u:S.sessions.length?'/ 4 wks':'',
     s:!S.sessions.length?'No saved sessions':(trainedPrev||trained?(trainDelta?(trainDelta>0?'+':'−')+Math.abs(trainDelta)+' vs prior 4 wks':'Same as prior 4 wks'):'No prior period'),
     cls:''},
    {tab:'body',l:'Weight',v:wa.cur?parseFloat(wa.cur.weight):'—',u:wa.cur?'kg':'',
     s:wa.cur?(wa.staleDays===0?'Measured today':'Measured '+wa.staleDays+'d ago'):'No check-ins',
     cls:wa.cur&&wa.staleDays>14?'stale':''},
    {tab:'nutrition',l:'Calories logged',v:cal.logged.length+' / 7',u:'days',
     s:cal.avg!==null?cal.avg.toLocaleString()+' kcal average':'Nothing logged in this window',cls:''},
    {tab:'finance',l:'Last week spend',v:lastSpend===null?'—':fmtMoney(Math.round(lastSpend)),u:'',
     s:lastWeek?(planComparable?(lastSpend<=lastTarget?'Under':'Over')+' plan by '+fmtMoney(Math.abs(lastSpend-lastTarget)):'No saved plan for that week'):'No completed week',
     cls:planComparable?(lastSpend<=lastTarget?'up':'down'):''}
  ].map(c=>'<button type="button" class="ov-hs" onclick="setStatsTab(\''+c.tab+'\')">'+
      '<span class="ov-hs-label">'+c.l+'</span>'+
      '<span class="ov-hs-val">'+c.v+(c.u?'<span class="ov-hs-unit">'+c.u+'</span>':'')+'</span>'+
      '<span class="ov-hs-sub'+(c.cls?' '+(c.cls==='up'?'ov-pos':'ov-neg'):'')+'">'+c.s+'</span></button>').join('');

  // ── Training block ──
  let trainBody;
  if(!S.sessions.length){
    trainBody='<div class="ov-empty">No saved sessions yet. Finish a workout in Log and this fills in.</div>';
  }else{
    const durs=(S.sessions||[]).filter(s=>s.date>=P.from&&s.date<=P.to&&s.duration>0).map(s=>s.duration);
    const avgDur=durs.length?Math.round(durs.reduce((a,b)=>a+b,0)/durs.length):null;
    const top=statsTopExercise(P.from,P.to);
    let signal='';
    if(top){
      const now=statsExerciseWindowBest(top.name,P.from,P.to);
      if(now){
        const before=statsExerciseWindowBest(top.name,P.priorFrom,P.priorTo);
        const info=now.info, unit=info.unit;
        const diff=before?+(now.value-before.value).toFixed(2):null;
        const cmp=diff===null?'no comparable prior period'
          :diff===0?'same as prior 4 weeks'
          :(diff>0?'+':'−')+Math.abs(diff)+unit+' vs prior 4 weeks';
        signal='<button type="button" class="ov-signal" onclick="openExerciseEvidence(this.dataset.ex,\''+P.from+'\',\''+P.to+'\',\''+_catEsc(P.label)+'\')" data-ex="'+_catEsc(top.name)+'">'+
          '<span class="ov-signal-t">'+_catEscHtml(top.name)+'</span>'+
          '<span class="ov-signal-v">'+info.label.toLowerCase()+' '+now.value+unit+'</span>'+
          '<span class="ov-signal-m">'+top.days+' day'+(top.days===1?'':'s')+' logged · '+cmp+'</span>'+
          '<span class="stats-review-link">See the sets &rarr;</span></button>';
      }else{
        const info=exerciseMetricInfo(top.name);
        signal='<div class="ov-signal-none">'+_catEscHtml(top.name)+' was logged most often, but '+(info.kind==='mixed'?'its saved sessions use different measurement units':'it has no comparable working-set value')+', so no single best value is calculated.</div>';
      }
    }
    trainBody=statsFigure(trained,'days','Distinct trained days · 4 completed weeks · '+P.label)+
      statsSplit([['Sessions saved',sessions],['Avg session',avgDur?avgDur+' min':'—'],['Prior 4 wks',trainedPrev+' days']])+
      signal;
  }

  // ── Body block ──
  let bodyBody, bodyChip='';
  if(!wa.cur){
    bodyBody='<div class="ov-empty">No weight check-ins recorded. Add one in Health to see measured change here.</div>';
  }else{
    const cut=new Date(localMidnight(getLocalDate())); cut.setDate(cut.getDate()-28);
    const win=statsWeightWindow(wa.sorted,dateStr(cut));
    if(wa.staleDays>14) bodyChip=statsChip('warn',wa.staleDays+'d old');
    const goalCells=[];
    goalCells.push(['Change · 28 days',win?(win.delta>0?'+':win.delta<0?'−':'')+Math.abs(win.delta)+' kg':'—']);
    goalCells.push(['Target',wa.hasGoal?wa.target+' kg':'None set']);
    goalCells.push(['Target date',wa.hasGoal&&weightGoal.date?fmtDate(String(weightGoal.date).slice(0,10)):'—']);
    let goalLine='';
    if(wa.hasGoal&&wa.legacy){
      goalLine='<div class="ov-note">This goal predates goal episodes, so it has no trusted baseline. Re-save it in Health to start pace tracking.</div>';
    }else if(wa.hasGoal){
      const modeWord=wa.mode==='cut'?'Cut':wa.mode==='bulk'?'Bulk':'Maintain';
      const paceTxt=wa.pace&&wa.rateReady?wa.pace.label:'Pace withheld';
      const rateTxt=wa.rateReady?(wa.rate>0?'+':'')+wa.rate.toFixed(2)+' kg/week measured'
        :wa.rateNoisy?wa.rateReason:'Rate withheld — needs 6+ readings over 21+ days and a check-in inside 14 days';
      goalLine='<div class="ov-goal">'+
        '<span class="ov-goal-mode">'+modeWord+' episode since '+(wa.startedAt?fmtDate(wa.startedAt):'—')+'</span>'+
        (wa.pace&&wa.rateReady?statsChip(wa.pace.onPace?'good':'warn',paceTxt):statsChip('neutral',wa.pace?'Pace withheld':'No target date'))+
        '</div><div class="ov-note">'+rateTxt+'</div>';
    }
    bodyBody=statsFigure(parseFloat(wa.cur.weight),'kg','Latest check-in · '+fmtDate(wa.cur.date)+' · '+(wa.staleDays===0?'today':wa.staleDays+' day'+(wa.staleDays===1?'':'s')+' ago'))+
      statsSplit(goalCells)+
      goalLine;
  }

  // ── Nutrition block ──
  let nutBody;
  if(!cal.logged.length&&!Object.keys(calorieHistory||{}).length){
    nutBody='<div class="ov-empty">No calorie days recorded yet. Log a day and the 7-day coverage appears here.</div>';
  }else{
    const max=Math.max(1,...cal.logged.map(x=>x.val));
    const strip=cal.days.map(d=>{
      const h=d.val===null?0:Math.max(12,Math.round(d.val/max*100));
      const lbl=new Date(d.date+'T12:00:00').toLocaleDateString('en-AU',{weekday:'narrow'});
      return '<div class="ov-day'+(d.val===null?' none':'')+'" title="'+fmtDate(d.date)+(d.val===null?' · not logged':' · '+Math.round(d.val)+' kcal')+'">'+
        '<div class="ov-day-track"><div class="ov-day-fill" style="height:'+h+'%"></div></div>'+
        '<span>'+lbl+'</span></div>';
    }).join('');
    nutBody=statsFigure(cal.avg===null?'—':cal.avg.toLocaleString(),cal.avg===null?'':'kcal',
        'Logged-day average · '+cal.logged.length+' of 7 completed days · '+fmtDate(cal.from)+' – '+fmtDate(cal.to))+
      '<div class="card-shape ov-days">'+strip+'</div>'+
      '<div class="ov-note">Hollow bars are days with no record — unknown, not zero.'+(cal.live>0?' Today is still in progress and is excluded.':'')+'</div>';
  }

  // ── Finance block ──
  let finBody;
  if(!lastWeek&&(!nw||!nw.covered)){
    finBody='<div class="ov-empty">No completed budget week and no comparable account balances yet.</div>';
  }else{
    let weekPart='';
    if(lastWeek){
      const over=planComparable&&lastSpend>lastTarget;
      const pct=planComparable?Math.min(100,Math.round(lastSpend/lastTarget*100)):0;
      weekPart=statsFigure(fmtMoney(Math.round(lastSpend)),'',
          'Week of '+fmtDate(lastWeek)+' · '+(lastQuality.ambiguousLegacyVariable?'known spend only; legacy total unavailable'
            :planComparable?'saved plan '+fmtMoney(lastTarget):'no saved plan for that week'))+
        (planComparable?'<div class="card-bar"><div class="card-bar-fill" style="width:'+pct+'%;background:'+(over?'var(--danger)':'var(--positive)')+'"></div></div>'+
          '<div class="ov-note">'+(over?'Over':'Under')+' that week’s saved plan by '+fmtMoney(Math.abs(lastSpend-lastTarget))+'.</div>':'');
    }
    let nwPart='';
    if(nw&&nw.covered){
      const d=nw.delta;
      nwPart=statsSplit([
        ['Net worth',fmtMoney(nw.now)],
        ['Change',(d===0?'—':(d>0?'+':'−')+fmtMoney(Math.abs(d)))],
        ['Since',fmtDate(nw.baseline)]
      ])+'<div class="ov-note">All '+nw.accounts+' account'+(nw.accounts===1?'':'s')+' had a recorded balance on both dates; balances carry forward between updates.'+
        (nw.stale>14?' Oldest balance is '+nw.stale+' days old.':'')+'</div>';
    }else if(nw){
      nwPart='<div class="ov-note">Net worth change is withheld: '+(nw.missing?nw.missing+' account'+(nw.missing===1?' has':'s have')+' no recorded starting balance.':'fewer than two dates have a balance for every account.')+'</div>';
    }
    finBody=weekPart+nwPart;
  }

  wrap.innerHTML=
    '<div class="ov-hero">'+
      '<div class="ov-hero-head"><span class="ov-hero-kicker">Look-back</span>'+
        '<span class="ov-hero-range">'+P.label+' · completed periods only</span></div>'+
      '<div class="ov-hero-grid">'+heroCells+'</div>'+
    '</div>'+
    '<div class="ov-grid">'+
      ovBlock('calendar','Training','training',trainBody)+
      ovBlock('scale','Body','body',bodyBody,bodyChip)+
      ovBlock('receipt','Nutrition','nutrition',nutBody)+
      ovBlock('wallet','Finance','finance',finBody)+
    '</div>';
}

// ── Stats: Review (a short ranked set of conclusions) ────────────
// Review is not a second Overview. It only holds items that cleared an evidence threshold,
// ranked by how much they could change a decision. Fewer, stronger cards — and a calm state
// when the data genuinely says nothing.
function statsReviewInsights(){
  const out=[], P=statsPeriod(4);

  // Training frequency — needs a real prior period and a shift worth naming.
  const now=trainedDaysIn(P.from,P.to), prev=trainedDaysIn(P.priorFrom,P.priorTo);
  if((now||prev)&&Math.abs(now-prev)>=2){
    const up=now>prev;
    out.push({score:Math.abs(now-prev)*9,icon:'calendar',label:'Training frequency',
      chip:statsChip('neutral',(up?'+':'−')+Math.abs(now-prev)+' days'),
      conclusion:'You trained on '+now+' day'+(now===1?'':'s')+' in the last 4 completed weeks, '+(up?'up':'down')+' from '+prev+'.',
      meta:P.label+' vs the 4 weeks before it · distinct calendar days · '+sessionsIn(P.from,P.to)+' saved sessions in the period',
      actions:[['setStatsTab(\'training\')','Open Training']]});
  }

  // Body — goal-aware, and only when the rate is actually eligible.
  const wa=weightGoalAnalysis();
  if(wa.hasGoal&&!wa.legacy&&wa.cur){
    if(wa.staleDays>21){
      out.push({score:48,icon:'scale',label:'Body goal',chip:statsChip('warn','Stale'),
        conclusion:'Goal pace cannot be assessed — the newest check-in is '+wa.staleDays+' days old.',
        meta:'Goal episode since '+fmtDate(wa.startedAt)+' · target '+wa.target+' kg · no forecast is made from stale readings',
        actions:[['openWeightEvidence(\''+wa.cur.date+'\')','See the check-in'],['setStatsTab(\'body\')','Open Body']]});
    }else if(wa.pace&&wa.rateReady){
      const cutting=wa.mode==='cut', maintaining=wa.mode==='maintain';
      const verb=maintaining?'holding':(cutting?'losing':'gaining');
      const rate=Math.abs(wa.rate).toFixed(2);
      const conclusion=maintaining
        ? (wa.pace.onPace?'Measured weight is inside the maintenance range.':'Measured weight has drifted outside the maintenance range.')
        : (wa.pace.onPace?'On track for the '+(cutting?'cut':'bulk')+' — '+verb+' '+rate+' kg/week measured.'
                         :'Behind the '+(cutting?'cut':'bulk')+' target — '+rate+' kg/week measured against the path this goal needs.');
      out.push({score:wa.pace.onPace?34:72,icon:'scale',label:'Body goal',
        chip:statsChip(wa.pace.onPace?'good':'warn',wa.pace.label),
        conclusion,
        meta:wa.goalReadings.length+' readings since '+fmtDate(wa.startedAt)+' · target '+wa.target+' kg'+(weightGoal.date?' by '+fmtDate(String(weightGoal.date).slice(0,10)):'')+' · rate is measured, not projected',
        actions:[['openWeightEvidence(\''+wa.cur.date+'\')','See the check-in'],['setStatsTab(\'body\')','Open Body']]});
    }
  }

  // Nutrition — only worth raising when the record is too thin to compare periods at all.
  const cal=statsCalorieCoverage(7);
  if(Object.keys(calorieHistory||{}).length&&cal.logged.length<4){
    out.push({score:40,icon:'receipt',label:'Calorie record',chip:statsChip('warn','Sparse'),
      conclusion:'Only '+cal.logged.length+' of the last 7 completed days has a calorie record, so period comparisons are not meaningful yet.',
      meta:fmtDate(cal.from)+' – '+fmtDate(cal.to)+' · unlogged days stay unknown and are never counted as zero',
      actions:[['openNutritionEvidence()','See dated coverage'],['setStatsTab(\'nutrition\')','Open Nutrition']]});
  }

  // Finance — latest completed week against its own saved plan.
  const weeks=statsCompletedWeeks();
  if(weeks.length){
    const k=weeks[weeks.length-1], d=budgetData[k];
    const spent=statsWeekSpending(d,k), q=statsWeekSpendQuality(d,k);
    const target=parseFloat(d.statsSnapshot&&d.statsSnapshot.totalTarget);
    if(!q.ambiguousLegacyVariable&&!isNaN(target)&&target>0){
      const diff=spent-target, pct=Math.round(Math.abs(diff)/target*100);
      if(Math.abs(diff)>=25&&pct>=10){
        const over=diff>0;
        out.push({score:Math.min(88,pct*2.5),icon:'wallet',label:'Weekly plan',
          chip:statsChip(over?'warn':'good',(over?'+':'−')+pct+'%'),
          conclusion:'The week of '+fmtDate(k)+' finished '+fmtMoney(Math.abs(diff))+' '+(over?'over':'under')+' the plan saved for that week.',
          meta:'Spent '+fmtMoney(Math.round(spent))+' against a saved plan of '+fmtMoney(target)+' · transactions override manual category figures',
          actions:[['closeStatsEvidence();openBudgetWeekFromStats(\''+k+'\')','Open that budget week'],['setStatsTab(\'finance\')','Open Finance']]});
      }
    }
    // A single variable category moving against its own recent baseline — the finance insight
    // Overview deliberately does not carry.
    const base=weeks.slice(-5,-1);
    if(base.length>=3){
      const defs=statsWeekCatDefs(d,k,'variable');
      let bestCat=null;
      defs.forEach(def=>{
        const nowVal=varCatAmount(d,k,def.id);
        const hist=base.map(wk=>varCatAmount(budgetData[wk],wk,def.id));
        const seen=hist.filter(v=>v>0);
        if(seen.length<3&&nowVal<=0) return;
        const avg=hist.reduce((a,v)=>a+v,0)/hist.length;
        if(avg<=0) return;
        const diff=nowVal-avg, pct=Math.round(Math.abs(diff)/avg*100);
        if(Math.abs(diff)<25||pct<40) return;
        if(!bestCat||Math.abs(diff)>Math.abs(bestCat.diff)) bestCat={def,nowVal,avg,diff,pct};
      });
      if(bestCat){
        const up=bestCat.diff>0;
        const compared=base.concat([k]).map(wk=>{
          const savedDef=statsWeekCatDefs(budgetData[wk],wk,'variable').find(x=>x.id===bestCat.def.id);
          return {key:wk,val:varCatAmount(budgetData[wk],wk,bestCat.def.id),label:savedDef&&savedDef.snapshot?savedDef.label:null};
        });
        const savedLabels=[...new Set(compared.map(w=>w.label).filter(Boolean))];
        const labelNote=savedLabels.length>1
          ? 'The saved label changed across these weeks; each source row keeps its historical name'
          : compared.every(w=>w.label)?'The category label was saved with every compared week'
          : 'Some weeks lack a saved label; the archived category ID is retained without borrowing today’s name';
        const evKey=statsRegisterFinanceEvidence({id:bestCat.def.id,label:bestCat.def.label,kind:'Variable',
          weeks:compared});
        out.push({score:Math.min(80,bestCat.pct),icon:'receipt',label:'Category shift',
          chip:statsChip(up?'warn':'good',(up?'+':'−')+bestCat.pct+'%'),
          conclusion:_catEscHtml(bestCat.def.label)+' was '+fmtMoney(Math.round(bestCat.nowVal))+' in the week of '+fmtDate(k)+', against a '+fmtMoney(Math.round(bestCat.avg))+' average over the '+base.length+' weeks before it.',
          meta:labelNote+' · transaction-backed where transactions exist',
          actions:[['openFinanceCategoryEvidence(\''+evKey+'\')','See the transactions'],['setStatsTab(\'finance\')','Open Finance']]});
      }
    }
  }

  // Balance-sheet trust: a net-worth figure resting on an old balance is a coverage problem,
  // not a money problem, and it is worth saying so once.
  const nw=statsNetWorth();
  if(nw&&nw.covered&&nw.stale>21){
    out.push({score:52,icon:'bank',label:'Account coverage',chip:statsChip('warn',nw.stale+'d stale'),
      conclusion:'Net worth is resting on a balance that has not been updated for '+nw.stale+' days.',
      meta:'Latest comparable date '+fmtDate(nw.latest)+' · balances carry forward between updates, so the figure is as old as its oldest input',
      actions:[['openNetWorthEvidence(\''+nw.latest+'\')','See each balance'],['setStatsTab(\'finance\')','Open Finance']]});
  }

  return out.sort((a,b)=>b.score-a.score).slice(0,3);
}
function renderStatsReview(){
  const wrap=document.getElementById('review-content'); if(!wrap) return;
  const items=statsReviewInsights();
  if(!items.length){
    wrap.innerHTML='<div class="card stats-calm">'+cardHeader('check','Review')+
      '<div class="stats-conclusion">Nothing needs attention from the available data.</div>'+
      '<div class="stats-data-note">No completed-period comparison cleared its evidence threshold. Overview has the current figures and their coverage.</div>'+
      '<button class="stats-inline-link" style="margin-top:12px" onclick="setStatsTab(\'overview\')">Back to Overview &rarr;</button></div>';
    return;
  }
  wrap.innerHTML='<div class="rev-list">'+items.map(it=>
    '<div class="card rev-card">'+
      cardHeader(it.icon,it.label,it.chip||'')+
      '<div class="rev-conclusion">'+it.conclusion+'</div>'+
      '<div class="rev-meta">'+it.meta+'</div>'+
      '<div class="rev-actions">'+it.actions.map((a,i)=>
        '<button type="button" class="'+(i?'rev-act':'rev-act primary')+'" onclick="'+a[0]+'">'+a[1]+' &rarr;</button>').join('')+
      '</div></div>').join('')+'</div>'+
    '<div class="stats-data-note rev-foot">Completed periods only. Missing data is unknown, never zero, and nothing here is reconstructed from today’s settings.</div>';
}
function setBSTrendRange(range){
  bsTrendRange=range;
  renderBSTrend();
}
function renderBSTrend(){
  const wrap=document.getElementById('bs-trend-wrap-card'); if(!wrap) return;
  // Always destroy a prior chart first so re-rendering can't conflict on the canvas
  if(bsChart){bsChart.destroy();bsChart=null;}
  const seg=statsSeg('bst',[['monthly','12W'],['yearly','52W'],['alltime','All']],bsTrendRange,'setBSTrendRange');
  const card=body=>'<div class="card">'+cardHeader('trend','Spending trend',seg)+body+'</div>';
  // Per-week spending: each saved week (daily_budget) is one bar. Grouping by month
  // previously hid everything until 2+ months existed; weeks within one month now show.
  const keys=Object.keys(budgetData)
    .filter(k=>{const d=budgetData[k]; return d && (d.saved || d.draft || d.snapshot);})
    .sort();
  // Range toggle controls how many recent weeks are shown
  const windowWeeks = bsTrendRange==='monthly' ? 12 : bsTrendRange==='yearly' ? 52 : keys.length;
  const shown = keys.slice(-windowWeeks);
  if(shown.length<1){
    wrap.innerHTML=card('<div class="stats-note-panel">No budget history yet. Save a week in Budget to begin this trend.</div>');
    return;
  }
  const spent  = shown.map(k=>statsWeekSpending(budgetData[k],k));
  const currentMonday=weekKey(getMondayOf(0));
  const labels = shown.map(k=>new Date(k+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short'})+(k===currentMonday?' · in progress':''));
  const goals=shown.map(k=>{
    const n=parseFloat(budgetData[k]?.statsSnapshot?.totalTarget);
    return !isNaN(n)&&n>0?n:null;
  });
  const goalCoverage=goals.filter(v=>v!==null).length;
  const ambiguousCoverage=shown.filter(k=>statsWeekSpendQuality(budgetData[k],k).ambiguousLegacyVariable).length;
  const completed=shown.filter(k=>k<currentMonday);
  const latestDone=completed.length?completed[completed.length-1]:null;
  const latestAmbiguous=latestDone&&statsWeekSpendQuality(budgetData[latestDone],latestDone).ambiguousLegacyVariable;
  const conclusion=latestDone
    ? 'Latest completed week: '+fmtMoney(Math.round(statsWeekSpending(budgetData[latestDone],latestDone)))+(latestAmbiguous?' known spend; full legacy total unavailable.':' spent.')
    : 'The current week is still in progress; no completed week is available in this range.';
  wrap.innerHTML=card('<div class="stats-chart-summary">'+conclusion+(latestDone?' <button class="stats-inline-link" onclick="openBudgetWeekFromStats(\''+latestDone+'\')">Open source week →</button>':'')+'</div>'+
    '<div class="stats-data-note">Saved plan available for '+goalCoverage+' of '+shown.length+' week'+(shown.length===1?'':'s')+'. Missing plans are not reconstructed from today’s defaults.'+(ambiguousCoverage?' '+ambiguousCoverage+' snapshot-only legacy week'+(ambiguousCoverage===1?' shows':'s show')+' known detail only.':'')+'</div>'+
    '<div class="stats-chart-box"><canvas id="bs-trend-chart" aria-label="Weekly spending and saved plans"></canvas></div>');
  const ctx=document.getElementById('bs-trend-chart'); if(!ctx) return;
  const {gc,tc}=budChartGridColors();
  const accent=budAccentHex();
  const datasets=[
    // Warm tone for spending, matching Budget Month/Yearly, so the same money is the same
    // colour wherever it is drawn.
    {type:'bar',label:'Spent',data:spent,backgroundColor:budWarmRgba(0.62),borderColor:BUD_CHART_COLORS.spending,borderWidth:1,borderRadius:6,maxBarThickness:48}
  ];
  if(goalCoverage){
    datasets.push({type:'line',label:'Saved plan',data:goals,borderColor:accent,borderWidth:2,borderDash:[6,4],pointRadius:0,fill:false,tension:0,spanGaps:false});
  }
  bsChart=new Chart(ctx,{
    data:{labels,datasets},
    options:{
      responsive:true,maintainAspectRatio:false,
      onClick:(event,elements)=>{ if(elements.length){ closeStatsEvidence(); openBudgetWeekFromStats(shown[elements[0].index]); } },
      plugins:{
        legend:{display:true,labels:{color:tc,font:{size:12},usePointStyle:true,pointStyleWidth:10}},
        tooltip:{callbacks:{label:c=>c.parsed.y==null?c.dataset.label+': unavailable':c.dataset.label+': $'+c.parsed.y.toFixed(0)}}
      },
      scales:{
        x:{grid:{color:gc},ticks:{color:tc,font:{size:11},maxTicksLimit:12,maxRotation:0,minRotation:0}},
        y:{grid:{color:gc},ticks:{color:tc,font:{size:11},callback:v=>'$'+v},beginAtZero:true}
      }
    }
  });
}
// Union of all dates across every account's history, ascending. Drives the trend chart's axis.
function accountsHistoryDates(){
  const set=new Set();
  accounts.forEach(a=>(a&&a.history||[]).forEach(e=>{ if(e&&e.date) set.add(e.date); }));
  return [...set].sort((x,y)=>x<y?-1:1);
}
// Rendered in two places — Stats → Finance and the Accounts page — so it's parametrised by
// container rather than hardcoded to one. One function means the two can't drift apart; the
// Chart instances are tracked per container so re-rendering one never destroys the other's.
const _nwCharts={};
let nwChartRange='3m';
const nwChartSeries={assets:false,debts:false};
function nwChartRefresh(){
  ['accounts-chart','bs-balance-wrap'].forEach(id=>{ if(document.getElementById(id)) renderNetWorthChartInto(id); });
}
function setNWChartRange(range){ nwChartRange=range; nwChartRefresh(); }
function toggleNWChartSeries(series){
  if(series==='assets'||series==='debts') nwChartSeries[series]=!nwChartSeries[series];
  nwChartRefresh();
}
function nwChartDates(allDates){
  if(nwChartRange==='all') return allDates.slice();
  const months={ '1m':1, '3m':3, '1y':12 }[nwChartRange]||3;
  const cut=localMidnight(getLocalDate()); cut.setMonth(cut.getMonth()-months);
  const cutStr=dateStr(cut);
  const shown=allDates.filter(d=>d>=cutStr);
  const prior=allDates.filter(d=>d<cutStr).pop();
  if(prior) shown.unshift(prior); // carry one anchor in so the period change has a real baseline
  return shown.length>=2?shown:allDates.slice(-2);
}
function nwCompactMoney(v){
  const n=Math.abs(v), sign=v<0?'−':'';
  if(n>=1000000) return sign+'$'+(n/1000000).toFixed(n>=10000000?0:1).replace('.0','')+'m';
  if(n>=1000) return sign+'$'+(n/1000).toFixed(n>=100000?0:1).replace('.0','')+'k';
  return sign+'$'+Math.round(n);
}
function renderBSBalance(){ renderNetWorthChartInto('bs-balance-wrap'); }
function renderNetWorthChartInto(wrapId){
  const wrap=document.getElementById(wrapId); if(!wrap) return;
  if(_nwCharts[wrapId]){ _nwCharts[wrapId].destroy(); _nwCharts[wrapId]=null; }
  const canvasId=wrapId+'-nwcanvas';
  const allDates=accountsHistoryDates();
  const chartAccounts=accounts.filter(a=>a);
  const unrecorded=chartAccounts.filter(a=>!(a.history||[]).some(e=>e&&e.date));
  const completeDates=unrecorded.length?[]:allDates.filter(d=>chartAccounts.every(a=>accountEntryAt(a,d)));
  if(completeDates.length<2){
    const why=unrecorded.length
      ? 'Log a starting balance for '+_catEscHtml(unrecorded.map(a=>a_name(a)).join(', '))+' before calculating net worth history.'
      : 'Record balances on at least 2 common dates in Accounts to see a comparable trend.';
    wrap.innerHTML='<div class="card" style="padding:0;overflow:hidden"><div style="background:transparent;padding:16px 16px 0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;color:var(--muted);display:flex;align-items:center;gap:6px">'+acctIcon('trend',13)+'Net worth over time</div><div style="padding:14px 16px;text-align:center;color:var(--muted);font-size:13px">'+why+'</div></div>';
    return;
  }
  const dates=nwChartDates(completeDates);
  // Assets, debts and net worth at each recorded date (each account carried forward from its
  // last known balance on/before that date — same convention as the old CC line).
  const assetAccts=accounts.filter(a=>a&&a.type==='asset'), debtAccts=accounts.filter(a=>a&&a.type==='debt');
  const assetsData=dates.map(d=>assetAccts.reduce((s,a)=>s+accountBalanceAt(a,d),0));
  const debtsData =dates.map(d=>debtAccts.reduce((s,a)=>s+accountBalanceAt(a,d),0));
  const netData   =dates.map((d,i)=>assetsData[i]-debtsData[i]);
  const curNet=netData[netData.length-1];
  const firstNet=netData[0], change=curNet-firstNet;
  const changePct=firstNet?change/Math.abs(firstNet)*100:null;
  const changeCol=change>0?'var(--success)':change<0?'var(--danger)':'var(--muted)';
  const changeText=(change>0?'+':change<0?'−':'')+fmtMoney(Math.abs(change))+
    (changePct===null?'':' · '+(changePct>0?'+':'')+changePct.toFixed(1)+'%');
  const accent=(getComputedStyle(document.documentElement).getPropertyValue('--accent')||'#FF6B35').trim();
  const stale=accounts.filter(a=>a&&(a.history||[]).length).map(a=>{
    const h=a.history.slice().filter(e=>e&&e.date).sort((x,y)=>x.date<y.date?-1:1);
    if(!h.length) return null;
    const days=Math.floor((localMidnight(getLocalDate())-localMidnight(h[h.length-1].date))/864e5);
    return days>14?{name:a_name(a),days}:null;
  }).filter(Boolean);
  const latest=completeDates[completeDates.length-1];
  const ranges=[['1m','1M'],['3m','3M'],['1y','1Y'],['all','ALL']];
  wrap.innerHTML='<div class="card nw-chart-card">'+
    '<div class="nw-chart-head">'+
      '<div><div class="nw-chart-kicker">'+acctIcon('trend',13)+'Net worth</div>'+
        '<div class="nw-chart-value">'+fmtMoney(curNet)+'</div>'+
        '<div class="nw-chart-change" style="color:'+changeCol+'">'+changeText+'</div></div>'+
      '<div class="nw-chart-ranges">'+ranges.map(r=>'<button onclick="setNWChartRange(\''+r[0]+'\')" class="'+(nwChartRange===r[0]?'on':'')+'">'+r[1]+'</button>').join('')+'</div>'+
    '</div>'+
    '<div class="nw-chart-canvas"><canvas id="'+canvasId+'"></canvas></div>'+
    '<div class="nw-chart-series">'+
      '<span class="on"><i style="background:'+accent+'"></i>Net worth</span>'+
      '<button onclick="toggleNWChartSeries(\'assets\')" class="'+(nwChartSeries.assets?'on':'')+'"><i></i>Assets</button>'+
      (debtAccts.length?'<button onclick="toggleNWChartSeries(\'debts\')" class="'+(nwChartSeries.debts?'on':'')+'"><i></i>Debts</button>':'')+
    '</div>'+
    '<div class="nw-chart-foot">Based on recorded balances carried forward between updates · Common coverage since '+fmtDate(completeDates[0])+' · Latest update '+fmtDate(latest)+
      (stale.length?'<span class="nw-chart-stale">'+_catEscHtml(stale.map(x=>x.name+' '+x.days+'d').join(' · '))+' old</span>':'')+
      (wrapId==='bs-balance-wrap'?'<button class="stats-inline-link" onclick="openAccounts()">Open account records →</button>':'')+
    '</div></div>';
  const ctx=document.getElementById(canvasId); if(!ctx) return;
  const {gc,tc}=budChartGridColors();
  const latestPoint=c=>c.dataIndex===dates.length-1?4:0;
  const datasets=[{label:'Net worth',data:netData,borderColor:accent,backgroundColor:'rgba('+hexToRgb(accent)+',.08)',borderWidth:3,pointRadius:latestPoint,pointHoverRadius:5,pointBackgroundColor:accent,pointBorderColor:S.theme==='dark'?'#171717':'#fff',pointBorderWidth:2,fill:true,stepped:'after',tension:0}];
  if(nwChartSeries.assets) datasets.push({label:'Assets',data:assetsData,borderColor:'#52B788',backgroundColor:'transparent',borderWidth:1.75,borderDash:[5,4],pointRadius:0,pointHoverRadius:4,fill:false,stepped:'after',tension:0});
  if(debtAccts.length&&nwChartSeries.debts) datasets.push({label:'Debts',data:debtsData,borderColor:'#E74C3C',backgroundColor:'transparent',borderWidth:1.75,borderDash:[5,4],pointRadius:0,pointHoverRadius:4,fill:false,stepped:'after',tension:0});
  _nwCharts[wrapId]=new Chart(ctx,{
    type:'line',
    data:{ labels:dates.map(e=>new Date(e+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short'})), datasets },
    options:{
      responsive:true,maintainAspectRatio:false,
      onClick:(event,elements)=>{ if(elements.length) openNetWorthEvidence(dates[elements[0].index]); },
      interaction:{mode:'index',intersect:false},
      plugins:{
        legend:{display:false},
        tooltip:{displayColors:true,backgroundColor:S.theme==='dark'?'#222':'#fff',titleColor:tc,bodyColor:tc,borderColor:gc,borderWidth:1,padding:12,callbacks:{label:c=>c.dataset.label+': '+fmtMoney(c.parsed.y)}}
      },
      scales:{
        x:{grid:{display:false},border:{display:false},ticks:{color:tc,font:{size:10,weight:'600'},maxTicksLimit:5,maxRotation:0}},
        y:{position:'right',grid:{color:gc,drawTicks:false},border:{display:false},ticks:{color:tc,font:{size:10,weight:'600'},padding:8,callback:nwCompactMoney},beginAtZero:false}
      }
    }
  });
}
function renderBSConsist(){
  const wrap=document.getElementById('bs-consist-wrap'); if(!wrap) return;
  const allKeys=Object.keys(budgetData).sort().reverse().slice(0,8).reverse();
  if(!allKeys.length){
    wrap.innerHTML='<div class="card" style="padding:0;overflow:hidden"><div style="background:transparent;padding:16px 16px 0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;color:var(--muted);display:flex;align-items:center;gap:6px">'+cardIcon('calendar')+'Budget consistency</div><div style="padding:14px 16px;text-align:center;color:var(--muted);font-size:13px">No weeks saved yet.</div></div>';
    return;
  }
  const cells=allKeys.map(k=>{
    const d=budgetData[k]; if(!d) return '';
    const inc=weekIncome(d);
    const leftover=inc>0?weekLeftover(d):null;
    const mon=new Date(k+'T12:00:00');
    const dayLbl=mon.toLocaleDateString('en-AU',{day:'numeric',month:'short'});
    const status=leftover===null?'grey':leftover>=50?'green':leftover>=0?'amber':'red';
    const bg={green:'#52B788',amber:'#f59e0b',red:'#E74C3C',grey:'var(--border)'};
    const fg={green:'#fff',amber:'#fff',red:'#fff',grey:'var(--muted)'};
    const valLbl=leftover!==null?(leftover>=0?'+$':'-$')+Math.abs(leftover).toFixed(0):'—';
    return '<div style="flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:3px">'
      +'<div style="width:100%;height:48px;background:'+bg[status]+';border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:'+fg[status]+'">'+valLbl+'</div>'
      +'<div style="font-size:9px;color:var(--muted);text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;width:100%;padding:0 1px">'+dayLbl+'</div>'
      +'</div>';
  }).join('');
  wrap.innerHTML='<div class="card" style="padding:0;overflow:hidden">'
    +'<div style="background:transparent;padding:16px 16px 0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;color:var(--muted);display:flex;align-items:center;gap:6px">'+cardIcon('calendar')+'Budget consistency</div>'
    +'<div style="padding:14px 16px">'
    +'<div style="display:flex;gap:5px;margin-bottom:10px">'+cells+'</div>'
    +'<div style="display:flex;gap:14px;font-size:11px;color:var(--muted)">'
    +'<span><span style="display:inline-block;width:10px;height:10px;background:#52B788;border-radius:2px;vertical-align:middle;margin-right:3px"></span>On track</span>'
    +'<span><span style="display:inline-block;width:10px;height:10px;background:#f59e0b;border-radius:2px;vertical-align:middle;margin-right:3px"></span>Tight</span>'
    +'<span><span style="display:inline-block;width:10px;height:10px;background:#E74C3C;border-radius:2px;vertical-align:middle;margin-right:3px"></span>Over</span>'
    +'</div></div></div>';
}
function renderBSRecords(){
  const wrap=document.getElementById('bs-records-wrap'); if(!wrap) return;
  const keys=Object.keys(budgetData);
  if(keys.length<2){
    wrap.innerHTML='<div class="card" style="padding:0;overflow:hidden"><div style="background:transparent;padding:16px 16px 0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;color:var(--muted);display:flex;align-items:center;gap:6px">'+cardIcon('trophy')+'Personal records</div><div style="padding:14px 16px;text-align:center;color:var(--muted);font-size:13px">Save at least 2 weeks to see records.</div></div>';
    return;
  }
  let bestInc={val:0,key:null},bestSav={val:0,key:null},loSpend={val:Infinity,key:null};
  keys.forEach(k=>{
    const d=budgetData[k]; if(!d) return;
    const inc=weekIncome(d);
    const spend=weekSpending(d);
    const sav=weekSavedAmt(d);
    if(inc>0&&inc>bestInc.val){bestInc={val:inc,key:k};}
    if(sav>bestSav.val){bestSav={val:sav,key:k};}
    if(inc>0&&spend<loSpend.val){loSpend={val:spend,key:k};}
  });
  const fmtWk=k=>{if(!k) return '—'; return new Date(k+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'2-digit'});};
  const rows=[
    {icon:cardIcon('wallet'),label:'Highest income',val:bestInc.key?'$'+bestInc.val.toFixed(0):'—',wk:fmtWk(bestInc.key)},
    {icon:cardIcon('down'),label:'Lowest spending',val:loSpend.key&&isFinite(loSpend.val)?'$'+loSpend.val.toFixed(0):'—',wk:fmtWk(loSpend.key)},
    {icon:cardIcon('medal'),label:'Most saved',val:bestSav.key?'$'+bestSav.val.toFixed(0):'—',wk:fmtWk(bestSav.key)},
  ];
  wrap.innerHTML='<div class="card" style="padding:0;overflow:hidden">'
    +'<div style="background:transparent;padding:16px 16px 0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;color:var(--muted);display:flex;align-items:center;gap:6px">'+cardIcon('trophy')+'Personal records</div>'
    +'<div style="padding:2px 16px">'
    +rows.map(r=>'<div style="display:flex;justify-content:space-between;align-items:center;padding:11px 0;border-bottom:1px solid var(--border)">'
      +'<div style="display:flex;align-items:center;gap:10px"><span style="font-size:20px">'+r.icon+'</span>'
      +'<div><div style="font-size:13px;font-weight:600">'+r.label+'</div><div style="font-size:11px;color:var(--muted)">Week of '+r.wk+'</div></div></div>'
      +'<div style="font-size:18px;font-weight:800;color:var(--success)">'+r.val+'</div>'
      +'</div>').join('')
    +'</div></div>';
}
function renderBSGoals(){
  const wrap=document.getElementById('bs-goals-wrap'); if(!wrap) return;
  const goals=budDefaults.goals||[];
  // Savings-goal progress tracks daily_accounts, not the retired savingsLog. It used to sum
  // EVERY asset, which counted the everyday spending account as progress toward a savings
  // goal and reported roughly double the real figure. The `saver` flag already draws exactly
  // the line this needs — money deliberately set aside vs. money that's going to get spent —
  // and accountsPayoffPosition() has always honoured it, so reading it here makes one
  // definition of "savings" hold across the app instead of two contradictory ones.
  // Falls back to all assets when nothing is flagged, so an install that never touched the
  // toggle behaves exactly as before.
  const saverTot=accountsSaverTotal();
  const usingSavers=accounts.some(acctIsSaver);
  const curBal=usingSavers?saverTot:accountsAssetsTotal();
  const balSrc=usingSavers?'savers accounts':'all assets';
  const goalsHTML=goals.map((g,i)=>{
    const pct=g.target>0?Math.min(100,Math.round(curBal/g.target*100)):0;
    const remaining=Math.max(0,g.target-curBal);
    const bc=pct>=100?'var(--success)':pct>=50?'var(--warn)':'#3b82f6';
    const weeksLeft=Math.max(0,(new Date(g.date+'T12:00:00')-new Date())/(7*864e5));
    const weeklyNeeded=weeksLeft>0&&remaining>0?'$'+Math.ceil(remaining/weeksLeft).toLocaleString()+'/wk needed':null;
    return `<div style="padding:12px 0;border-bottom:1px solid var(--border)">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px">
        <div style="font-size:15px;font-weight:700">${g.name}</div>
        <div style="display:flex;align-items:center;gap:8px">
          <span style="font-size:12px;color:var(--muted)">$${g.target.toLocaleString()} by ${g.date}</span>
          <button onclick="deleteGoal(${i})" style="font-size:12px;color:var(--danger);background:none;border:none;cursor:pointer;padding:0">✕</button>
        </div>
      </div>
      <div style="height:6px;background:var(--border);border-radius:3px;overflow:hidden;margin-bottom:6px">
        <div style="width:${pct}%;height:100%;background:${bc};border-radius:3px"></div>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:12px;color:var(--muted)">
        <span>${pct}%${curBal>0?' ($'+curBal.toLocaleString()+' in '+balSrc+')':''}</span>
        <span>${pct>=100?'🎉 Reached!':(remaining>0?'$'+remaining.toLocaleString()+' to go':'')+(weeklyNeeded?' · '+weeklyNeeded:'')}</span>
      </div>
    </div>`;
  }).join('');
  wrap.innerHTML=`<div class="card" style="padding:0;overflow:hidden">
    <div style="background:transparent;padding:16px 16px 0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;color:var(--muted);display:flex;align-items:center;gap:6px">${cardIcon('target')}Savings goals</div>
    <div style="padding:14px 16px">
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:${goals.length?'12px':'0'}">
        <input type="text" id="bs-goal-name" placeholder="Goal name" style="flex:1 1 100px;min-width:0;box-sizing:border-box;height:38px;border:1.5px solid var(--border);border-radius:8px;font-size:13px;padding:0 8px;background:var(--card);color:var(--text)">
        <input type="number" id="bs-goal-target" inputmode="decimal" placeholder="$ Target" style="flex:1 1 70px;min-width:0;box-sizing:border-box;height:38px;border:1.5px solid var(--border);border-radius:8px;font-size:13px;text-align:center;background:var(--card);color:var(--text)">
        <input type="date" id="bs-goal-date" style="flex:1 1 110px;min-width:0;box-sizing:border-box;height:38px;border:1.5px solid var(--border);border-radius:8px;font-size:13px;padding:0 6px;background:var(--card);color:var(--text)">
        <button onclick="addBSGoal()" style="flex-shrink:0;padding:0 14px;height:38px;background:var(--header);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer">Add</button>
      </div>
      ${goals.length?goalsHTML:'<div style="text-align:center;color:var(--muted);font-size:13px;padding:12px 0">No goals yet — add one above</div>'}
    </div>
  </div>`;
}
function addBSGoal(){
  const name=document.getElementById('bs-goal-name')?.value.trim();
  const target=parseFloat(document.getElementById('bs-goal-target')?.value);
  const date=document.getElementById('bs-goal-date')?.value;
  if(!name||!target||!date) return;
  if(!budDefaults.goals) budDefaults.goals=[];
  budDefaults.goals.push({name,target,date});
  localStorage.setItem('daily_budget_defaults',JSON.stringify(budDefaults));
  syncBudDefaultsToFirebase();
  renderBSGoals();
}

// ── Home tab ──────────────────────────────────────────────────────
// ── Habits ────────────────────────────────────────────────────────
function loadHabits(){
  return lsLoad('daily_habits',
    ['Morning workout','Hit calorie goal','Log budget','8h sleep','Drink 2L water'],
    d=>Array.isArray(d)&&d.length>0);
}
function loadHabitsLog(){ return lsLoad('daily_habits_log', {}); }
function saveHabitsLog(){ lsSave('daily_habits_log', habitsLog, 'habitsLog'); }
function toggleHabit(idx){
  const today=getLocalDate();
  if(!habitsLog[today]) habitsLog[today]=[];
  const arr=habitsLog[today];
  const pos=arr.indexOf(idx);
  if(pos>=0) arr.splice(pos,1); else arr.push(idx);
  saveHabitsLog();
  refreshHabitsUI();
}
// Delegated: a tap survives the list re-rendering between press and release. An inline
// onclick on a row that gets rebuilt mid-tap is swallowed → "nothing happens, tap again".
document.addEventListener('click',function(e){
  const el=e.target.closest('[data-habit-toggle]'); if(!el) return;
  const i=parseInt(el.getAttribute('data-habit-toggle'),10);
  if(!isNaN(i)) toggleHabit(i);
});
function getWeekDates(){
  const monday=getMondayOf(0);
  return Array.from({length:7},(_,i)=>{
    const d=new Date(monday); d.setDate(monday.getDate()+i);
    return dateStr(d);
  });
}
function buildHabitsWeekGrid(){
  const today=getLocalDate();
  const dates=getWeekDates();
  const n=habitsData.length||1;
  const labels=['M','T','W','T','F','S','S'];
  return dates.map((date,i)=>{
    const done=(habitsLog[date]||[]).length;
    const isFuture=date>today;
    let bg='var(--border)',tc='var(--muted)';
    if(!isFuture&&done>=n){bg='var(--success)';tc='#fff';}
    else if(!isFuture&&done>0){bg='#f59e0b';tc='#fff';}
    const border=date===today?'border:2px solid var(--text);':'border:2px solid transparent;';
    return '<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px">'
      +'<div style="width:30px;height:30px;border-radius:8px;background:'+bg+';'+border+'display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:'+tc+'">'
      +(!isFuture&&done>0?done:'')
      +'</div>'
      +'<div style="font-size:9px;color:var(--muted)">'+labels[i]+'</div>'
      +'</div>';
  }).join('');
}
// 30-day per-habit completion for the Stats tab (uses the existing index-based model:
// habit "done" on a date = its index is in habitsLog[date]).
function renderStatsHabits(){
  const el=document.getElementById('stats-habits-list');
  const section=document.getElementById('stats-habits-section');
  if(!el) return;
  if(!habitsData.length){ if(section) section.style.display='none'; return; }
  if(section) section.style.display='';
  const days=[]; const d0=localMidnight(getLocalDate());
  for(let i=0;i<30;i++){ const d=new Date(d0); d.setDate(d.getDate()-i); days.push(dateStr(d)); }
  el.innerHTML=habitsData.map((h,idx)=>{
    const completed=days.filter(day=>(habitsLog[day]||[]).indexOf(idx)>=0).length;
    const pct=Math.round(completed/30*100);
    const streak=calcHabitStreakIdx(idx);
    return '<div style="margin-bottom:18px">'+
      '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px">'+
        '<span style="font-size:14px;font-weight:600;color:var(--text)">'+String(h).replace(/</g,'&lt;')+'</span>'+
        '<span style="font-size:12px;color:var(--muted)">'+completed+'/30 · 🔥 '+streak+'</span>'+
      '</div>'+
      '<div style="height:8px;background:var(--border);border-radius:4px;overflow:hidden">'+
        '<div style="height:100%;width:'+pct+'%;background:var(--accent);border-radius:4px;transition:width .4s ease"></div>'+
      '</div>'+
      '<div style="font-size:11px;color:var(--muted);margin-top:4px">'+pct+'% this month</div>'+
    '</div>';
  }).join('');
}
function calcHabitStreakIdx(idx){
  let streak=0; const d=localMidnight(getLocalDate());
  while(true){ if((habitsLog[dateStr(d)]||[]).indexOf(idx)<0) break; streak++; d.setDate(d.getDate()-1); }
  return streak;
}
// Habits stats live in the Training sub-tab. Created dynamically and always
// re-appended to the end of #sub-training.
function ensureHabitsStatsInProgress(){
  const sub=document.getElementById('sub-training'); if(!sub) return;
  let sec=document.getElementById('stats-habits-section');
  if(!sec){
    sec=document.createElement('div');
    sec.id='stats-habits-section';
    sec.style.cssText='margin-top:24px;display:none';
    sec.innerHTML='<div class="sec-label" style="margin-bottom:12px">📋 Habit completion · last 30 days</div><div id="stats-habits-list"></div>';
  }
  sub.appendChild(sec); // move/keep at the end
  renderStatsHabits();
}
function buildHabitsWeekStats(){
  const today=getLocalDate();
  const dates=getWeekDates();
  const n=habitsData.length;
  let perfect=0,total=0,days=0;
  dates.forEach(d=>{
    if(d>today) return;
    days++;
    const done=(habitsLog[d]||[]).length;
    total+=done;
    if(done>=n) perfect++;
  });
  const avg=days>0?(total/days).toFixed(1):'0';
  return '<span style="font-size:12px;font-weight:600;color:var(--success)">'+perfect+' perfect day'+(perfect!==1?'s':'')+'</span>'
    +'<span style="font-size:12px;color:var(--muted);margin-left:8px">· avg '+avg+'/'+n+' per day</span>';
}
function buildTodayHabitsList(){
  const today=getLocalDate();
  const done=habitsLog[today]||[];
  return habitsData.map((h,i)=>{
    const checked=done.includes(i);
    const isLast=i===habitsData.length-1;
    return '<div data-habit-toggle="'+i+'" style="display:flex;align-items:center;gap:12px;padding:11px 0;'+(isLast?'':'border-bottom:1px solid var(--border);')+'cursor:pointer;-webkit-tap-highlight-color:transparent">'
      +'<div style="width:22px;height:22px;border-radius:6px;flex-shrink:0;display:flex;align-items:center;justify-content:center;'+(checked?'background:var(--accent);border:2px solid var(--accent);':'background:transparent;border:2px solid var(--border);')+'">'
      +(checked?'<svg viewBox="0 0 12 10" width="10" height="10" fill="none"><polyline points="1,5 4,8 11,1" stroke="#fff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>':'')
      +'</div>'
      +'<span style="font-size:14px;'+(checked?'color:var(--muted);text-decoration:line-through;':'color:var(--text);')+'">'+h+'</span>'
      +'</div>';
  }).join('');
}
function refreshHabitsUI(){
  const g=document.getElementById('habits-week-grid');
  if(g) g.innerHTML=buildHabitsWeekGrid();
  const s=document.getElementById('habits-week-stats');
  if(s) s.innerHTML=buildHabitsWeekStats();
  const l=document.getElementById('habits-today-list');
  if(l) l.innerHTML=buildTodayHabitsList();
  const c=document.getElementById('habits-today-count');
  if(c){
    const today=getLocalDate();
    const n=habitsData.length;
    const doneN=(habitsLog[today]||[]).length;
    c.textContent=doneN+'/'+n;
    c.style.color='#fff';
    c.style.opacity=(doneN===n&&n>0)?'1':'0.75';
  }
}
// ── Week in review ────────────────────────────────────────────────
// Rebuilt around DELTAS, because as a snapshot this card was almost entirely duplicate. Its
// 2×2 grid showed Workouts (the same distinct-session-dates count the streak card already
// computes), Budget (the same leftover as the budget card), Cals today (the same total as the
// calorie ring) and Weight Δ — and Weight Δ, its one unique cell, is now covered properly by
// the Weight & Goal card. Three of four cells were repeating a number from another card two
// rows away, which is why Home felt busy without feeling informative.
// A delta is not a duplicate: "4 workouts" is already on screen, "+1 vs last week" is not.
// The habits stats and 7-day grid moved to the habits card, where they describe the thing
// they belong to.
function buildWeekSummaryCard(){
  const {mondayStr,sundayStr}=getWeekBounds();
  const prevMon=getMondayOf(-1);
  const prevMonStr=weekKey(prevMon);
  const prevSun=new Date(prevMon); prevSun.setDate(prevMon.getDate()+6);
  const prevSunStr=dateStr(prevSun);
  const inRange=(d,a,b)=>d>=a&&d<=b;
  // Workouts: distinct days trained, this week vs last.
  const wNow=new Set(S.sessions.filter(s=>inRange(s.date,mondayStr,sundayStr)).map(s=>s.date)).size;
  const wPrev=new Set(S.sessions.filter(s=>inRange(s.date,prevMonStr,prevSunStr)).map(s=>s.date)).size;
  // Spending: total outgoings for each week, from the same accessor the Budget tab uses.
  const sNow=budgetData[mondayStr]?weekSpending(budgetData[mondayStr]):null;
  const sPrev=budgetData[prevMonStr]?weekSpending(budgetData[prevMonStr]):null;
  // Calories: daily average across the days actually logged in each week. calorieHistory is a
  // flat {date: total} map, so this is a read — no new tracking.
  const avgCals=(a,b)=>{
    const vals=Object.keys(calorieHistory||{}).filter(d=>inRange(d,a,b))
      .map(d=>parseFloat(calorieHistory[d])||0).filter(v=>v>0);
    return vals.length?Math.round(vals.reduce((x,y)=>x+y,0)/vals.length):null;
  };
  const cNow=avgCals(mondayStr,sundayStr), cPrev=avgCals(prevMonStr,prevSunStr);
  // A delta chip is only honest when there is a previous week to compare against — otherwise
  // it silently treats "no data last week" as zero and reports a fake improvement.
  const chip=(now,prev,opts)=>{
    const o=opts||{};
    if(now==null||prev==null) return '<span class="wr-chip wr-chip-none">no last week</span>';
    const d=+(now-prev).toFixed(o.dp||0);
    if(!d) return '<span class="wr-chip wr-chip-none">same</span>';
    // neutral: the direction has no good/bad reading, so the chip stays grey and just reports
    // the movement. lowerIsBetter otherwise flips which way is green — more workouts is good,
    // more spend is not.
    const cls=o.neutral?'wr-chip-flat':((o.lowerIsBetter?d<0:d>0)?'wr-chip-up':'wr-chip-down');
    return '<span class="wr-chip '+cls+'">'+
      (d>0?'+':'−')+(o.money?fmtMoney(Math.abs(d)):Math.abs(d))+'</span>';
  };
  const row=(label,valHtml,chipHtml)=>
    '<div class="wr-row"><span class="wr-row-l">'+label+'</span>'+
    '<span class="wr-row-v">'+valHtml+'</span>'+chipHtml+'</div>';
  const dash='<span class="wr-row-none">—</span>';
  return '<div class="card">'
    +cardHeader('calendar','Week in review',
       '<button class="card-hd-act" onclick="event.stopPropagation();openWeekReviewModal()">Full review →</button>')
    +row('Workouts', wNow+'<span class="wr-row-u">days</span>', chip(wNow,wPrev))
    +row('Spending', sNow==null?dash:fmtMoney(Math.round(sNow)), chip(sNow==null?null:Math.round(sNow), sPrev==null?null:Math.round(sPrev), {money:true,lowerIsBetter:true}))
    // Whether eating more is better depends entirely on the goal, so read it rather than
    // assuming: cutting wants the number down, bulking wants it up, and maintaining has no
    // preferred direction at all (grey chip, movement reported without a verdict). Painting
    // "+257 kcal" green for someone on a cut would be exactly backwards.
    +row('Avg calories', cNow==null?dash:cNow+'<span class="wr-row-u">kcal/day</span>',
        chip(cNow,cPrev,(()=>{ const g=(calcGoalCals()||{}).goal;
          return g==='cut'?{lowerIsBetter:true}:g==='bulk'?{}:{neutral:true}; })()))
    +'</div>';
}
// ── Weight & goal ─────────────────────────────────────────────────
// The app stored a weight goal that appeared nowhere on Home — a goal whose progress only
// exists on a settings screen is a goal you never see.
// The stored goal is {target, date}, and the DATE is what makes this more than a subtraction:
// with a start point, a target and a deadline you can say whether today's weight is ahead of
// or behind the straight line between them, which is the same "pace" idea the budget card
// uses. Without a target date it degrades to distance-to-go, which is still useful.
function buildWeightGoalCard(){
  const sorted=[...(S.weights||[])].sort((a,b)=>a.date<b.date?-1:1);
  const open='onclick="setView(\'stats\');setStatsTab(\'body\')"';
  if(!sorted.length){
    return '<div class="card" '+open+' style="cursor:pointer">'+
      cardHeader('scale','Weight')+
      '<div style="font-size:14px;color:var(--muted)">Log your weight to start tracking.</div>'+
    '</div>';
  }
  const cur=sorted[sorted.length-1];
  const target=parseFloat(weightGoal&&weightGoal.target);
  const hasGoal=!isNaN(target)&&target>0;
  // Last ~8 weeks of readings for the shape.
  const cutoff=dateStr(new Date(Date.now()-56*864e5));
  const recent=sorted.filter(w=>w.date>=cutoff);
  const series=(recent.length>=2?recent:sorted.slice(-8)).map(w=>parseFloat(w.weight)).filter(v=>isFinite(v));
  // Week-over-week delta from the readings inside the current week.
  const {mondayStr}=getWeekBounds();
  const wk=sorted.filter(w=>w.date>=mondayStr);
  const wkDelta=wk.length>=2?+(wk[wk.length-1].weight-wk[0].weight).toFixed(1):null;
  let capParts=[];
  if(wkDelta!==null) capParts.push((wkDelta>0?'+':'')+wkDelta+' kg this week');
  let pillHtml='';
  if(hasGoal){
    const toGo=+(target-cur.weight).toFixed(1);
    capParts.push(Math.abs(toGo)+' kg to go');
  // Pace uses the explicit goal episode baseline; a legacy goal without one never borrows the
  // first weigh-in and presents that guess as history.
    const gd=weightGoal.date?String(weightGoal.date).slice(0,10):'';
    const ga=weightGoalAnalysis();
    if(gd&&ga.startedAt&&ga.start!==null){
      const t0=localMidnight(ga.startedAt).getTime();
      const t1=localMidnight(gd).getTime();
      const now=localMidnight(getLocalDate()).getTime();
      if(t1>t0&&now>t0){
        const frac=Math.min(1,(now-t0)/(t1-t0));
        const expected=ga.start+(target-ga.start)*frac;
        const total=target-ga.start;
        // "Ahead" means further along the intended direction than the line expects.
        const ahead=total===0 ? true : ((cur.weight-expected)/total)>=-0.02;
        pillHtml='<span class="budget-snap-pill'+(ahead?'':' warn')+'">'+(ahead?'On pace':'Behind pace')+'</span>';
        capParts.push('target '+localMidnight(gd).toLocaleDateString('en-AU',{day:'numeric',month:'short'}));
      }
    }
  }
  return '<div class="card" '+open+' style="cursor:pointer">'+
    cardHeader('scale','Weight',pillHtml||(hasGoal?'':'<span class="card-hd-act">Set a goal →</span>'))+
    '<div><span class="card-fig">'+cur.weight+'</span><span class="card-fig-u">kg</span></div>'+
    (series.length>=2?'<div class="card-shape">'+sparkline(series,{target:hasGoal?target:null,height:40})+'</div>':'')+
    (capParts.length?'<div class="card-cap">'+capParts.join(' · ')+'</div>':'')+
  '</div>';
}
// ── Kitchen snapshot ──────────────────────────────────────────────
// Kitchen was an entire tab — recipes, shopping list, pantry — with no presence on Home at
// all, which is why Home read as a fitness-and-money app that happened to have a Kitchen tab.
// Everything here is a read of data already stored and synced: recipes carry `favourite` and a
// `lastCooked` timestamp (stored precisely so something could reason about rotation, and
// nothing did), kitShopComputeItems() already builds the shopping list, and kitPantryNeeds()
// already knows what is low or out.
// ── Personal records ──────────────────────────────────────────────
// Records use the same per-exercise metric resolver as Stats: seconds for timed movements,
// signed external load for loaded/assisted movements, and repetitions for bodyweight sets.
// Mixed saved units are deliberately omitted instead of being joined into a fake PR series.
function computePRHistory(){
  const best={}, events=[];
  const metrics={};
  [...(S.sessions||[])].sort((a,b)=>a.date<b.date?-1:1).forEach(s=>{
    (s.exercises||[]).forEach(ex=>{
      if(!ex||!ex.name) return;
      const metric=metrics[ex.name]||(metrics[ex.name]=exerciseMetricInfo(ex.name));
      if(metric.kind==='mixed') return;
      (ex.sets||[]).forEach(set=>{
        const val=setMetricValue(set,metric); if(val===null) return;
        const prev=best[ex.name];
        if(prev===undefined||val>prev){
          events.push({name:ex.name, val, reps:parseFloat(set.reps)||null,
                       date:s.date, prev:prev===undefined?null:prev, metric});
          best[ex.name]=val;
        }
      });
    });
  });
  return events;
}
// Every other training card on Home is about compliance — did you train, how many days, what
// percent done. None of them are about getting stronger, which is the reason to train at all.
function buildPRCard(){
  const ev=computePRHistory();
  const open='onclick="setView(\'stats\');setStatsTab(\'training\')"';
  if(!ev.length){
    return '<div class="card pr-card" '+open+' style="cursor:pointer">'+
      cardHeader('trophy','Personal records')+
      '<div style="font-size:14px;color:var(--muted)">Your first logged session sets them all.</div>'+
    '</div>';
  }
  // Most recent first, one row per exercise so a single lift that broke its record three weeks
  // running doesn't fill the card.
  const seen=new Set(), rows=[];
  for(let i=ev.length-1;i>=0&&rows.length<3;i--){
    const e=ev[i];
    if(seen.has(e.name)) continue;
    seen.add(e.name);
    const days=Math.floor((localMidnight(getLocalDate())-localMidnight(e.date))/864e5);
    const val=e.val+e.metric.unit+(e.metric.kind==='load'&&e.reps?' × '+e.reps:'');
    rows.push('<div class="pr-row">'+
      '<span class="pr-name">'+_catEscHtml(e.name)+'</span>'+
      (days<=14?'<span class="pr-new">NEW</span>':'')+
      '<span class="pr-val">'+val+'</span>'+
    '</div>');
  }
  return '<div class="card pr-card" '+open+' style="cursor:pointer">'+
    cardHeader('trophy','Personal records','<span class="card-hd-act">All →</span>')+
    rows.join('')+
  '</div>';
}
function buildKitchenCard(){
  const recipes=(typeof kitRecipes!=='undefined'&&Array.isArray(kitRecipes))?kitRecipes:[];
  const open='onclick="setView(\'kitchen\')"';
  if(!recipes.length){
    return '<div class="card" '+open+' style="cursor:pointer">'+
      cardHeader('pot','Kitchen')+
      '<div style="font-size:14px;color:var(--muted)">Add a recipe to get cook-again suggestions.</div>'+
    '</div>';
  }
  // Cook again: the favourite you have left longest. Favourites first because a suggestion you
  // have already said you like is worth more than one picked purely by staleness; never-cooked
  // recipes sort first inside each group (lastCooked 0), which is the right nudge for something
  // you saved and never made.
  const byStale=(a,b)=>(a.lastCooked||0)-(b.lastCooked||0);
  const favs=recipes.filter(r=>r.favourite).sort(byStale);
  const pick=(favs.length?favs:[...recipes].sort(byStale))[0];
  const days=pick.lastCooked?Math.floor((Date.now()-pick.lastCooked)/864e5):null;
  const ago=days===null?'never cooked':days===0?'cooked today':days===1?'cooked yesterday'
    :days<14?'cooked '+days+' days ago':'cooked '+Math.floor(days/7)+' weeks ago';
  const meta=[pick.category?pick.category[0].toUpperCase()+pick.category.slice(1):'',
              pick.servings?pick.servings+' servings':'', ago].filter(Boolean).join(' · ');
  // Shopping + pantry, as cells — omitted individually when there is nothing to say, so a
  // clear list doesn't render a "0 left" that looks like a failure.
  const cells=[];
  try{
    if(typeof kitShopComputePlan==='function'){
      const plan=kitShopComputePlan();
      const left=kitShopCountLeft(plan);
      if(Object.keys(plan.buy).length) cells.push({l:'Shopping',v:left?left+' left':'All done',
        c:left?'':'var(--positive)'});
    }
  }catch(e){}
  try{
    if(typeof kitPantryNeeds==='function'&&typeof kitPantryActive==='function'){
      const pantry=kitPantryActive();
      const n=kitPantryNeeds().length;
      const itemCount=pantry&&pantry.items?Object.keys(pantry.items).length:0;
      if(pantry) cells.push({l:pantry.name,v:n?(n+(n===1?' needs restocking':' need restocking')):(itemCount?'All stocked':'Empty pantry'),
        c:n?'#f59e0b':'var(--positive)'});
    }
  }catch(e){}
  const splitHtml=cells.map((c,i)=>
    (i?'<div class="card-split-div"></div>':'')+
    '<div><div class="card-split-l">'+c.l+'</div>'+
    '<div class="card-split-v"'+(c.c?' style="color:'+c.c+'"':'')+'>'+c.v+'</div></div>').join('');
  return '<div class="card" '+open+' style="cursor:pointer">'+
    cardHeader('pot','Kitchen','<span class="card-hd-act">Open →</span>')+
    '<div class="kit-suggest">'+_catEscHtml(pick.name||'Untitled')+'</div>'+
    '<div class="card-cap" style="margin-top:4px">'+meta+'</div>'+
    (splitHtml?'<div class="card-split">'+splitHtml+'</div>':'')+
  '</div>';
}
function buildTodayHabitsCard(){
  const today=getLocalDate();
  const doneCount=(habitsLog[today]||[]).length;
  const n=habitsData.length;
  const allDone=doneCount===n&&n>0;
  return '<div class="card" style="padding:0;overflow:hidden">'
    +'<div style="background:transparent;padding:16px 16px 0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;color:var(--muted);display:flex;justify-content:space-between;align-items:center">'
    +'<span>Daily habits</span>'
    +'<div style="display:flex;align-items:center;gap:10px">'
    +'<span id="habits-today-count" style="font-size:13px;font-weight:700;color:var(--text);opacity:'+(allDone?'1':'0.75')+'">'+doneCount+'/'+n+'</span>'
    +'<button onclick="openHabitsEditModal()" style="background:transparent;border:1px solid var(--border);border-radius:8px;padding:4px 11px;cursor:pointer;color:var(--muted);font-size:12px;font-weight:600;line-height:1;-webkit-tap-highlight-color:transparent" title="Edit habits">Edit</button>'
    +'</div>'
    +'</div>'
    +'<div style="padding:14px 16px">'
    +'<div id="habits-today-list">'+buildTodayHabitsList()+'</div>'
    // The week stats + 7-day grid moved here from the Week in Review card, where they were
    // the habits half of a card that also duplicated three other cards. A habits card showing
    // only today has no memory — the grid is what turns "3/5 today" into "and here's the week",
    // and it belongs with the habits it describes.
    +(habitsData.length
      ? '<div style="border-top:1px solid var(--border);margin-top:12px;padding-top:12px">'
        +'<div id="habits-week-stats" style="margin-bottom:8px">'+buildHabitsWeekStats()+'</div>'
        +'<div id="habits-week-grid" style="display:flex;gap:4px">'+buildHabitsWeekGrid()+'</div>'
      +'</div>'
      : '')
    +'</div>'
    +'</div>';
}
// Habits management is now a full-screen settings section (#settings-habits-section, rendered
// into #habits-edit-sheet). Kept as a named entry point for the Home habits card + menu.
function openHabitsEditModal(){ if(typeof openSettingsSection==='function') openSettingsSection('habits'); }
function renderHabitsEditModal(){
  const sheet=document.getElementById('habits-edit-sheet'); if(!sheet) return;
  const rows=habitsData.map((h,i)=>
    '<div class="habit-edit-row" data-idx="'+i+'">'
    +'<span class="habit-drag-handle" aria-label="Drag to reorder" title="Drag to reorder">⠿</span>'
    +'<span style="flex:1;font-size:14px;color:var(--text)">'+h.replace(/</g,'&lt;')+'</span>'
    +'<button onclick="deleteHabitItem('+i+')" style="background:none;border:none;color:var(--danger);font-size:16px;cursor:pointer;padding:0 4px;flex-shrink:0">✕</button>'
    +'</div>'
  ).join('') || '<div class="stg-help" style="margin:0 0 4px">No habits yet — add your first below.</div>';
  sheet.innerHTML=
    (habitsData.length>1?'<p class="stg-help" style="margin:0 0 12px">Drag the ⠿ handle to reorder · tap ✕ to remove</p>':'')
    +rows
    +'<div style="display:flex;gap:8px;margin-top:14px">'
    +'<input id="habit-new-input" type="text" placeholder="New habit…" style="flex:1;height:44px;border:1.5px solid var(--border);border-radius:10px;font-size:15px;padding:0 12px;background:transparent;color:var(--text)">'
    +'<button class="stg-btn primary" style="flex:0 0 auto" onclick="addHabitItem()">Add</button>'
    +'</div>';
}
// habitsRef is scoped to the auth callback, so it's not visible here — write to the cloud
// ref by uid directly. (Referencing habitsRef from these global fns threw a ReferenceError,
// which aborted them before the re-render — habits only appeared after close+reopen.)
function pushHabits(){
  try{ if(firebaseReady&&auth&&auth.currentUser&&db) db.ref('users/'+auth.currentUser.uid+'/habits').set(habitsData); }catch(e){}
}
function addHabitItem(){
  const inp=document.getElementById('habit-new-input'); if(!inp) return;
  const val=inp.value.trim(); if(!val) return;
  habitsData.push(val);
  localStorage.setItem('daily_habits',JSON.stringify(habitsData));
  pushHabits();
  inp.value='';
  renderHabitsEditModal();
  refreshTodayHabits();
}
function deleteHabitItem(i){
  habitsData.splice(i,1);
  // Keep completion history aligned: drop this index, shift higher indices down.
  Object.keys(habitsLog).forEach(date=>{
    habitsLog[date]=(habitsLog[date]||[]).filter(x=>x!==i).map(x=>x>i?x-1:x);
  });
  localStorage.setItem('daily_habits',JSON.stringify(habitsData));
  saveHabitsLog();
  pushHabits();
  renderHabitsEditModal();
  refreshTodayHabits();
}
// Apply the dragged habit order, remapping habitsLog indices so each habit's completion
// history follows it to the new position.
function applyHabitOrderFromDOM(){
  const rows=[...document.querySelectorAll('#habits-edit-sheet .habit-edit-row')];
  if(rows.length<2) return;
  const newOrder=rows.map(r=>parseInt(r.dataset.idx,10)); // old indices in their new order
  if(newOrder.some(isNaN)) return;
  const inv={}; newOrder.forEach((oldIdx,newPos)=>{ inv[oldIdx]=newPos; });
  habitsData=newOrder.map(oldIdx=>habitsData[oldIdx]);
  Object.keys(habitsLog).forEach(date=>{
    habitsLog[date]=(habitsLog[date]||[]).map(i=>inv[i]).filter(x=>x!==undefined).sort((a,b)=>a-b);
  });
  localStorage.setItem('daily_habits',JSON.stringify(habitsData));
  saveHabitsLog();
  pushHabits();
  renderHabitsEditModal();
  refreshTodayHabits();
}
// Pointer-based drag-to-reorder for the habits edit sheet (mouse + touch). Uses a floating
// clone that follows the pointer so it's obvious what you're holding and where it'll drop.
(function(){
  let row=null, clone=null, offY=0, parent=null;
  function onMove(e){
    if(!row) return;
    if(e.cancelable) e.preventDefault();
    clone.style.top=(e.clientY-offY)+'px';
    clone.style.display='none'; // hide clone so hit-test reads the row underneath
    const el=document.elementFromPoint(e.clientX,e.clientY);
    clone.style.display='';
    const over=(el&&el.closest)?el.closest('.habit-edit-row'):null;
    if(over&&over!==row&&over.parentElement===parent){
      const r=over.getBoundingClientRect();
      const after=e.clientY > r.top + r.height/2;
      parent.insertBefore(row, after?over.nextSibling:over);
    }
  }
  function onUp(){
    document.removeEventListener('pointermove',onMove);
    document.removeEventListener('pointerup',onUp);
    document.removeEventListener('pointercancel',onUp);
    if(!row) return;
    if(clone){ clone.remove(); clone=null; }
    row.style.opacity=''; row=null; parent=null;
    applyHabitOrderFromDOM();
  }
  document.addEventListener('pointerdown',function(e){
    const h=e.target.closest('.habit-drag-handle'); if(!h) return;
    row=h.closest('.habit-edit-row'); if(!row) return;
    parent=row.parentElement;
    const r=row.getBoundingClientRect();
    offY=e.clientY-r.top;
    clone=row.cloneNode(true);
    clone.classList.add('habit-dragging');
    clone.style.cssText='position:fixed;left:'+r.left+'px;top:'+r.top+'px;width:'+r.width+'px;height:'+r.height+'px;z-index:9999;pointer-events:none;margin:0';
    document.body.appendChild(clone);
    row.style.opacity='.25';
    try{ if(h.setPointerCapture&&e.pointerId!=null) h.setPointerCapture(e.pointerId); }catch(err){}
    e.preventDefault();
    document.addEventListener('pointermove',onMove,{passive:false});
    document.addEventListener('pointerup',onUp);
    document.addEventListener('pointercancel',onUp);
  });
})();
function closeHabitsEditModal(){ if(typeof closeSettingsSection==='function') closeSettingsSection(); }
function refreshTodayHabits(){
  const list=document.getElementById('habits-today-list');
  if(list) list.innerHTML=buildTodayHabitsList();
  const today=getLocalDate();
  const doneCount=(habitsLog[today]||[]).length;
  const n=habitsData.length;
  const counter=document.getElementById('habits-today-count');
  if(counter){ counter.textContent=doneCount+'/'+n; counter.style.opacity=(doneCount===n&&n>0)?'1':'0.75'; }
}

// Time-of-day greeting + saved profile name (source of truth: profileData.name).
function getGreeting(){
  const hour=new Date().getHours();
  const nm=(profileData.name||S.personalInfo?.name||'').trim();
  const timeGreet=hour<12?'Good morning':hour<17?'Good afternoon':'Good evening';
  return nm?timeGreet+', '+nm:timeGreet;
}

// ── Home weather card ──────────────────────────────────────────────
// Open-Meteo: free, no API key (nothing to hide in a static public repo), CORS-enabled.
// WMO weather codes → icon/label (https://open-meteo.com/en/docs — "WMO Weather interpretation codes").
const WEATHER_CODES={
  0:['☀️','Clear sky'],1:['🌤️','Mostly clear'],2:['⛅','Partly cloudy'],3:['☁️','Overcast'],
  45:['🌫️','Fog'],48:['🌫️','Fog'],
  51:['🌦️','Light drizzle'],53:['🌦️','Drizzle'],55:['🌦️','Heavy drizzle'],
  61:['🌧️','Light rain'],63:['🌧️','Rain'],65:['🌧️','Heavy rain'],
  71:['🌨️','Light snow'],73:['🌨️','Snow'],75:['🌨️','Heavy snow'],
  80:['🌦️','Rain showers'],81:['🌧️','Rain showers'],82:['⛈️','Violent showers'],
  95:['⛈️','Thunderstorm'],96:['⛈️','Thunderstorm'],99:['⛈️','Thunderstorm'],
};
// A dry sky — no precipitation, fog or storm — is the only case where cloud_cover should
// override the code (see cloudLook below).
function isDrySkyCode(code){ return code===0||code===1||code===2||code===3; }
// For a dry sky the WMO code is too coarse to trust: sampling live data, code 1 ("mainly
// clear") comes back at anything from 22% to 46% cloud cover, and code 0/1 both used to draw
// a cloudless sunny scene — so a half-grey sky rendered as brilliant sunshine. cloud_cover is
// the actual modelled percentage and tracks what you see out the window far better, so it
// drives the icon, the label and the scene whenever the sky is dry.
// Thresholds follow the usual met convention (roughly okta bands): few / scattered / broken / overcast.
const CLOUD_LOOKS=[
  {max:15,  base:'clear',  day:['☀️','Clear sky'],     night:['🌙','Clear night']},
  {max:40,  base:'clear',  day:['🌤️','Mostly sunny'],  night:['🌙','Mostly clear']},
  {max:70,  base:'partly', day:['⛅','Partly cloudy'],  night:['☁️','Partly cloudy']},
  {max:101, base:'cloudy', day:['☁️','Cloudy'],         night:['☁️','Cloudy']},
];
function cloudLook(cloud){
  for(const l of CLOUD_LOOKS){ if(cloud<l.max) return l; }
  return CLOUD_LOOKS[CLOUD_LOOKS.length-1];
}
// Icon + label for the card. Dry skies read from cloud_cover; anything with actual weather in
// it (rain/snow/fog/storm) still reads from the code, which is authoritative for those.
// Night matters here too: a clear sky at 9pm was previously drawing a ☀️.
function weatherLook(entry){
  if(entry&&isDrySkyCode(entry.code)&&entry.cloud!=null){
    const l=cloudLook(entry.cloud);
    return weatherPhase(entry)==='night'?l.night:l.day;
  }
  return WEATHER_CODES[entry&&entry.code]||['🌡️','—'];
}
// Condition → animated background "scene" (see .home-weather-card[data-scene] in
// kitchen-extras.css). Storm and fog skip the day/night split: a storm already reads as
// dark regardless of clock time, and fog's flat haze doesn't have a distinct night look in
// practice either — building separate art for those would just duplicate the day scene.
function weatherSceneBase(code,cloud){
  // Real weather first — these are what the code is actually good for.
  if(code===45||code===48) return 'fog';
  if(code===82||code>=95) return 'storm';
  if((code>=71&&code<=77)||(code>=85&&code<=86)) return 'snow';
  if((code>=51&&code<=67)||code===80||code===81) return 'rain';
  // Dry sky → let measured cloud cover decide how cloudy it looks.
  if(cloud!=null) return cloudLook(cloud).base;
  if(code===0||code===1) return 'clear';
  if(code===2) return 'partly';
  return 'cloudy';
}
// Time-of-day phase from the day's real sunrise/sunset rather than a fixed clock hour, so
// the card tracks the actual sky (an 8pm summer dusk vs an 8pm winter night). Computed at
// RENDER time, not fetch time, so a cached reading still advances dawn→noon→dusk on its own.
// Falls back to the API's is_day flag if the sun times are missing.
function weatherPhase(entry){
  const fallback=entry.isDay===0?'night':'day';
  if(!entry.sunrise||!entry.sunset) return fallback;
  const sr=new Date(entry.sunrise).getTime(), ss=new Date(entry.sunset).getTime();
  if(isNaN(sr)||isNaN(ss)) return fallback;
  const now=Date.now(), EDGE=45*60*1000;
  if(now<sr-EDGE||now>ss+EDGE) return 'night';
  if(Math.abs(now-sr)<=EDGE) return 'dawn';
  if(Math.abs(now-ss)<=EDGE) return 'dusk';
  if(Math.abs(now-(sr+ss)/2)<=2*60*60*1000) return 'noon';  // brightest, sun highest
  return 'day';
}
// The sun and moon travel a real arc between sunrise and sunset rather than sitting at one
// fixed spot per phase, and live wind angles the rain and drives the cloud speed. Everything
// is published as CSS custom properties so the animation layers stay pure CSS — this only
// decides where things sit, never how they move.
function applyWeatherMotion(card, entry){
  if(!card||!entry) return;
  const H=card.getBoundingClientRect().height||100;
  const now=Date.now(), DAY=86400000;
  const sr=entry.sunrise?new Date(entry.sunrise).getTime():NaN;
  const ss=entry.sunset?new Date(entry.sunset).getTime():NaN;
  let p=0.5, isNight=false;
  if(!isNaN(sr)&&!isNaN(ss)&&ss>sr){
    if(now>=sr&&now<=ss){
      p=(now-sr)/(ss-sr);                       // fraction of daylight elapsed
    } else {
      isNight=true;
      // Night spans sunset to the NEXT sunrise, so before dawn we look back to yesterday's
      // sunset and after dusk forward to tomorrow's sunrise.
      const start=now>ss?ss:ss-DAY;
      const end  =now>ss?sr+DAY:sr;
      p=(now-start)/(end-start);
    }
  } else {
    isNight=weatherPhase(entry)==='night';       // no sun times — fall back to the phase
  }
  p=Math.max(0,Math.min(1,isNaN(p)?0.5:p));
  const arc=Math.sin(Math.PI*p);                 // 0 at both horizons, 1 at the peak
  // How far above the card's top edge the disc rides at its peak. Expressed as a fraction of
  // the disc itself, not a fixed pixel value: it controls how much of the disc is cropped, so
  // hardcoding it would crop a smaller sun almost out of existence at midday.
  const disc=card.querySelector(isNight?'.wfx-moon':'.wfx-sun');
  const discSize=(disc&&disc.getBoundingClientRect().width)||62;
  const lowTop=H*0.55, peakTop=-Math.round(discSize*0.42);
  const set=(k,v)=>card.style.setProperty(k,v);
  set(isNight?'--wfx-moon-x':'--wfx-sun-x',(p*100).toFixed(1)+'%');
  set(isNight?'--wfx-moon-y':'--wfx-sun-y',Math.round(lowTop+(peakTop-lowTop)*arc)+'px');

  // Wind direction is the compass bearing the wind blows FROM, so a westerly (270) pushes
  // rain to the right: -sin(270) = +1.
  const spd=Math.max(0,Math.min(60,parseFloat(entry.wind)||0));
  const dir=parseFloat(entry.windDir);
  const across=isNaN(dir)?-1:-Math.sin(dir*Math.PI/180);
  set('--wfx-rain-x',(across*(6+spd*0.7)).toFixed(0)+'px');
  // Divides the cloud drift durations, so 0.6 is a slow still day and ~2.2 a gale.
  set('--wfx-wind',(0.6+Math.min(spd,40)/25).toFixed(2));
}
// Phase from the local clock alone, for the states where there is no reading to read sun
// times from: location not yet granted, first launch, or a failed fetch. Rough hour bands are
// the best available without a location, but enough that a 9pm card looks like night.
function weatherClockPhase(){
  const h=new Date().getHours();
  if(h<5)  return 'night';
  if(h<7)  return 'dawn';
  if(h<11) return 'day';
  if(h<15) return 'noon';
  if(h<18) return 'day';
  if(h<20) return 'dusk';
  return 'night';
}
// Placeholder sky for the no-data states. Deliberately a "clear" scene: it implies no
// precipitation we haven't measured, while still tracking time of day. Previously these
// states left data-scene="neutral", which has no CSS of its own and so fell through to the
// base blue-grey gradient — a daytime sky shown at every hour, including midnight.
function weatherPlaceholderScene(){ return 'clear-'+weatherClockPhase(); }
// Only clear/partly skies get the full dawn/noon/dusk treatment — under heavy cloud, rain or
// snow the sun's height barely changes how the sky reads, so those stay day/night.
function weatherScene(code,entry){
  const base=weatherSceneBase(code,entry&&entry.cloud);
  if(base==='storm'||base==='fog') return base;
  const phase=weatherPhase(entry);
  if(base==='clear'||base==='partly') return base+'-'+phase;
  return base+'-'+(phase==='night'?'night':'day');
}
// "Australia/Sydney" → "Sydney". Uses the timezone the forecast call already returns, so
// there's no second request and no extra service to depend on. It's the timezone's city, not
// a precise suburb — accurate enough for a glanceable card.
function weatherCityFromTz(tz){
  if(!tz) return '';
  const part=String(tz).split('/').pop();
  return part?part.replace(/_/g,' '):'';
}
function loadWeatherCache(){ return lsLoad('daily_weather_cache', null); }
// DEVICE-LOCAL, deliberately. This used to be written with a 'weatherCache' sync path, which
// uploaded precise latitude/longitude to Firebase on every refresh — while no listener and no
// restore entry ever read it back. It is a transient cache describing where this handset is
// standing right now, not a durable cross-device setting, so it stays on the device. The
// obsolete cloud node is removed only when the user explicitly clears their saved location
// (weatherClearSaved) — never silently at boot, which would be an unrequested delete.
function saveWeatherCache(c){ lsSave('daily_weather_cache', c); }
// ONE freshness threshold, so "fresh" cannot come to mean two different things in two places.
// Older than this and the reading is no longer the sky you are standing in: the Home card
// still shows it (marked stale, better than blanking), but the app's APPEARANCE must stop
// following it, and any refresh opportunity refetches.
const WEATHER_FRESH_MS=60*60*1000; // 60 minutes
// Shown before the user grants location, so the card reads as finished rather than an empty
// grey box. It's a real live reading for this city, clearly labelled "sample", not fake data —
// and, because it is not this user's sky, it is never allowed to drive the app's appearance.
const WEATHER_SAMPLE_LOC={lat:-33.8688, lon:151.2093, city:'Sydney'};
function weatherIsFresh(c){ return !!(c && c.fetchedAt && (Date.now()-c.fetchedAt) < WEATHER_FRESH_MS); }
function weatherIsReal(c){ return !!(c && !c.placeholder && c.lat!=null); }
// The only reading the global accent is allowed to follow: a real location, still fresh.
function weatherAppearanceEntry(){
  const c=loadWeatherCache();
  return (weatherIsReal(c) && weatherIsFresh(c)) ? c : null;
}
// Why the appearance is or isn't following the sky — shown in both Appearance and Weather
// settings so a neutral accent is never an unexplained one.
function weatherAppearanceStatus(){
  const c=loadWeatherCache();
  if(!c) return {ok:false, reason:'No weather reading yet, so the app colour is using its resting colour.'};
  if(c.placeholder) return {ok:false, reason:'Showing the Sydney sample. A sample sky never drives the app colour \u2014 use your own location in Settings \u2192 Weather.'};
  if(!weatherIsReal(c)) return {ok:false, reason:'No real location reading, so the app colour is using its resting colour.'};
  if(!weatherIsFresh(c)) return {ok:false, reason:'The last reading is over an hour old, so the app colour is using its resting colour until it refreshes.'};
  return {ok:true, reason:'Following your current sky.'};
}
// Transient per-session state for the Weather settings screen. The last FAILURE is persisted
// onto the cache instead (lastError/lastErrorAt) so it survives a reload — a network error
// that disappears when you navigate away is one the user can never act on.
let _weatherStatus={state:'idle', message:''};
function weatherSetStatus(state,message){
  _weatherStatus={state:state, message:message||''};
  if(typeof renderWeatherSection==='function') renderWeatherSection();
}
function weatherRecordFailure(msg){
  const c=loadWeatherCache();
  if(c){ c.lastError=msg; c.lastErrorAt=Date.now(); saveWeatherCache(c); }
  weatherSetStatus('error',msg);
}
function weatherRecordSuccess(entry){
  delete entry.lastError; delete entry.lastErrorAt;
  saveWeatherCache(entry);
  weatherSetStatus('ok','');
}
// Progressive enhancement only. Safari/iOS support for the Permissions API is inconsistent,
// and an absent answer means we do not know — never that permission was refused.
function weatherPermissionState(cb){
  try{
    if(!navigator.permissions||!navigator.permissions.query){ cb('unknown'); return; }
    const p=navigator.permissions.query({name:'geolocation'});
    if(!p||!p.then){ cb('unknown'); return; }
    p.then(function(r){ cb((r&&r.state)||'unknown'); }).catch(function(){ cb('unknown'); });
  }catch(e){ cb('unknown'); }
}
let _weatherLoading=false;
function renderWeatherInto(entry){
  // The accent is repainted FIRST and unconditionally: weather appearance must not depend on
  // the Home weather card being enabled. It used to sit after the early return below, so
  // hiding the card left the whole app following whatever sky was last cached.
  if(accentMode()==='weather' && typeof applyDayColour==='function') applyDayColour();
  if(typeof renderWeatherSection==='function') renderWeatherSection();
  const tempEl=document.getElementById('home-weather-temp');
  if(!tempEl) return; // card isn't in the current layout — nothing else to patch
  tempEl.textContent=Math.round(entry.tempC)+'°';
  const look=weatherLook(entry);
  document.getElementById('home-weather-icon').textContent=look[0];
  // On the sample reading the tappable label states what tapping does, rather than the
  // condition — the icon already carries that, and an unexplained city is the confusing part.
  const labelEl=document.getElementById('home-weather-label');
  labelEl.textContent=entry.placeholder?'Tap for your weather':look[1];
  labelEl.classList.toggle('weather-cta',!!entry.placeholder);
  const cityEl=document.getElementById('home-weather-city');
  if(cityEl) cityEl.textContent=entry.placeholder?(entry.city||'Sydney')+' · sample':(entry.city||'');
  // Feels-like is only worth showing when it actually differs from the real temperature —
  // repeating the same number twice reads as a bug, not a detail.
  const metaEl=document.getElementById('home-weather-meta');
  if(metaEl){
    const bits=[];
    if(entry.feelsC!=null&&Math.round(entry.feelsC)!==Math.round(entry.tempC)) bits.push('Feels '+Math.round(entry.feelsC)+'°');
    if(entry.tmax!=null&&entry.tmin!=null) bits.push('H '+Math.round(entry.tmax)+'°  L '+Math.round(entry.tmin)+'°');
    metaEl.textContent=bits.join('   ·   ');
  }
  const card=document.querySelector('.home-weather-card');
  if(card){
    card.dataset.scene=weatherScene(entry.code,entry);
    applyWeatherMotion(card,entry);
  }
}
// First-ever load (no cache yet): show an explicit "tap for weather" invite instead of
// popping the OS location prompt unasked — Home is where most sessions land first, and an
// unprompted permission dialog there is a bad first impression. Once granted, the browser
// won't re-prompt, so every later call is a silent refresh via loadWeatherWidget(true)
// (the label's own tap) or the auto-refresh at the bottom of renderHome().
function renderWeatherPrompt(){
  const labelEl=document.getElementById('home-weather-label'); if(!labelEl) return;
  document.getElementById('home-weather-temp').textContent='';
  document.getElementById('home-weather-icon').textContent='📍';
  labelEl.textContent='Tap for weather';
  setWeatherPlaceholderScene();
}
function renderWeatherError(denied){
  const labelEl=document.getElementById('home-weather-label'); if(!labelEl) return;
  document.getElementById('home-weather-temp').textContent='';
  document.getElementById('home-weather-icon').textContent='📍';
  labelEl.textContent=denied?'Enable location for weather':'Couldn\'t load weather — tap to retry';
  setWeatherPlaceholderScene();
}
// Both no-data states share the clock-based sky; without this they kept whatever scene was
// already on the card, which on a cold start is the daytime placeholder gradient.
function setWeatherPlaceholderScene(){
  const card=document.querySelector('.home-weather-card');
  if(card) card.dataset.scene=weatherPlaceholderScene();
}
// One place that turns coordinates into a reading, so the sample city, the saved-coordinate
// refresh and the real geolocation path all build an identical entry.
function fetchWeatherAt(lat,lon){
  return fetch('https://api.open-meteo.com/v1/forecast?latitude='+lat+'&longitude='+lon+
        '&current=temperature_2m,apparent_temperature,weather_code,is_day,cloud_cover,wind_speed_10m,wind_direction_10m'+
        '&daily=temperature_2m_max,temperature_2m_min,sunrise,sunset&forecast_days=1&timezone=auto')
    .then(r=>r.json())
    .then(data=>{
      const c=data&&data.current;
      if(!c||c.temperature_2m==null) throw new Error('no current-weather block');
      const d=(data&&data.daily)||{};
      const first=a=>Array.isArray(a)&&a.length?a[0]:null;
      return {lat,lon,tempC:c.temperature_2m,feelsC:c.apparent_temperature,
        code:c.weather_code,isDay:c.is_day,cloud:c.cloud_cover,
        wind:c.wind_speed_10m,windDir:c.wind_direction_10m,
        tmax:first(d.temperature_2m_max),tmin:first(d.temperature_2m_min),
        sunrise:first(d.sunrise),sunset:first(d.sunset),
        city:weatherCityFromTz(data&&data.timezone),
        fetchedAt:Date.now()};
    });
}
// Routine refresh. Runs whether or not the Home weather card is in the layout, because
// weather-driven appearance needs current data of its own accord. Reuses stored coordinates
// while permission-compatible — getCurrentPosition() is never called here, and a browser can
// only prompt when we actually ask where we are, which is what stops iOS asking every launch.
function loadWeatherWidget(userInitiated){
  const cache=loadWeatherCache();
  if(cache) renderWeatherInto(cache);
  if(_weatherLoading) return;
  const haveRealLocation=weatherIsReal(cache);

  // Tapping the card while it's showing the sample means "use my location" — one of only two
  // paths that touch geolocation, so the OS dialog only ever appears after a direct gesture.
  if(userInitiated && !haveRealLocation){ weatherUseCurrentLocation(); return; }
  if(weatherIsFresh(cache) && !userInitiated) return;

  if(haveRealLocation){ weatherRefreshStored(); return; }

  // No location yet: show a real reading for the sample city so the card looks finished
  // instead of empty, with the label inviting them to switch to their own. Explicitly
  // flagged placeholder:true, which is what keeps it out of the appearance system.
  _weatherLoading=true;
  weatherSetStatus('loading','');
  fetchWeatherAt(WEATHER_SAMPLE_LOC.lat,WEATHER_SAMPLE_LOC.lon)
    .then(e=>{ e.city=WEATHER_SAMPLE_LOC.city; e.placeholder=true; weatherRecordSuccess(e); renderWeatherInto(e); })
    .catch(()=>{ weatherRecordFailure('Could not reach the weather service.'); renderWeatherError(false); })
    .finally(()=>{ _weatherLoading=false; });
}
// Refetch at the coordinates already stored. Keeps the last good reading on any failure —
// but records the failure rather than swallowing it, so Weather settings can say so.
function weatherRefreshStored(){
  const cache=loadWeatherCache();
  if(!cache || cache.lat==null){ weatherSetStatus('error','No saved location to refresh.'); return; }
  if(_weatherLoading) return;
  _weatherLoading=true;
  weatherSetStatus('loading','');
  fetchWeatherAt(cache.lat,cache.lon)
    .then(e=>{ if(cache.placeholder){ e.placeholder=true; e.city=cache.city; } weatherRecordSuccess(e); renderWeatherInto(e); })
    .catch(()=>{ weatherRecordFailure('Could not reach the weather service \u2014 showing the last reading.'); })
    .finally(()=>{ _weatherLoading=false; });
}
// A direct user gesture: ALWAYS reacquire coordinates. maximumAge:0 is the point of it —
// "Update current location" that answers from a six-hour-old cached fix has not updated
// anything, which is exactly what made a stale suburb impossible to correct.
function weatherUseCurrentLocation(){
  if(!navigator.geolocation){
    weatherRecordFailure('This browser cannot provide a location.');
    renderWeatherError(false); return;
  }
  _weatherLoading=true;
  weatherSetStatus('loading','');
  navigator.geolocation.getCurrentPosition(
    pos=>{
      const lat=pos.coords.latitude, lon=pos.coords.longitude;
      fetchWeatherAt(lat,lon)
        .then(e=>{ weatherRecordSuccess(e); renderWeatherInto(e); if(typeof showToast==='function') showToast('Weather updated'); })
        .catch(()=>{ weatherRecordFailure('Found your location, but the weather service did not answer.'); renderWeatherError(false); })
        .finally(()=>{ _weatherLoading=false; });
    },
    err=>{
      _weatherLoading=false;
      const denied=!!(err&&err.code===1);
      weatherRecordFailure(denied
        ? 'Location permission was refused. Your browser or iOS Settings controls this \u2014 Daily cannot grant it.'
        : 'Could not get a location fix. Try again somewhere with a clearer signal.');
      const c=loadWeatherCache();
      if(c) renderWeatherInto(c); else renderWeatherError(denied);
    },
    {maximumAge:0, enableHighAccuracy:false, timeout:15000}
  );
}
// Clears the device cache, and — because the user asked for exactly that — also removes the
// obsolete users/<uid>/weatherCache node that older builds uploaded coordinates to. Nothing
// else reads that node; this is the only place it is ever deleted.
function weatherClearSaved(){
  try{
    localStorage.removeItem('daily_weather_cache');
    localStorage.removeItem('daily_weather_cache_ts');
  }catch(e){}
  let cloud=false;
  try{
    const ref=(typeof fbRef==='function')?fbRef('weatherCache'):null;
    if(ref){ cloud=true; ref.remove().catch(function(){}); }
  }catch(e){}
  weatherSetStatus('idle','');
  if(accentMode()==='weather' && typeof applyDayColour==='function') applyDayColour();
  setWeatherPlaceholderScene();
  renderWeatherPrompt();
  if(typeof renderWeatherSection==='function') renderWeatherSection();
  if(typeof showToast==='function') showToast(cloud?'Saved location cleared (device and cloud)':'Saved location cleared');
}
// ── Settings → Weather ────────────────────────────────────────────
// Appearance could already be set to follow the sky, but nothing anywhere said WHICH sky —
// which location, from what source, how old, or why the colour had gone neutral. This is that
// screen: every input to the weather system, stated plainly, with the four actions that can
// change it. Re-rendered from renderWeatherInto and weatherSetStatus, so it is always live.
let _weatherPerm='unknown';
const WEATHER_PERM_LABEL={granted:'Allowed',denied:'Blocked',prompt:'Will ask when you tap Update',unknown:'Unknown on this browser'};
function weatherAgeLabel(ts){
  if(!ts) return 'never';
  const mins=Math.floor((Date.now()-ts)/60000);
  if(mins<1) return 'just now';
  if(mins<60) return mins+' minute'+(mins===1?'':'s')+' ago';
  const hrs=Math.floor(mins/60);
  if(hrs<24) return hrs+' hour'+(hrs===1?'':'s')+' ago';
  const days=Math.floor(hrs/24);
  return days+' day'+(days===1?'':'s')+' ago';
}
function weatherSourceLabel(c){
  if(!c) return {t:'Unavailable', d:'No reading has been taken on this device yet.'};
  if(c.placeholder) return {t:'Sydney sample', d:'A real live reading for a sample city, shown so the card is not empty. It never drives the app colour.'};
  if(weatherIsFresh(c)) return {t:'Your current location', d:'A live reading for the coordinates saved on this device.'};
  return {t:'Cached real location', d:'Your location, but the reading is older than an hour and is treated as stale.'};
}
function renderWeatherSection(){
  const wrap=document.getElementById('settings-weather-section'); if(!wrap) return;
  const c=loadWeatherCache();
  const src=weatherSourceLabel(c);
  const app=weatherAppearanceStatus();
  const stale=c&&!weatherIsFresh(c);
  const look=c?weatherLook(c):null;
  const scene=c?weatherScene(c.code,c):weatherPlaceholderScene();
  const busy=_weatherStatus.state==='loading';
  // .stg-row, not the weather-only .wx-row it used to have: a label-left/value-right row is
  // the same thing here as it is on every other settings screen.
  const row=(k,v)=>'<div class="stg-row"><span class="stg-row-label">'+k+'</span><span class="stg-row-val">'+v+'</span></div>';
  const err=(c&&c.lastError)?c.lastError:'';
  const liveMsg=_weatherStatus.state==='error'?_weatherStatus.message:'';
  wrap.innerHTML=
    '<div class="stg-card" id="stg-card-wx-now">'+
      stgCardHead('cloud','Right now', escText(src.d))+
      '<div class="stg-status'+(app.ok?' ok':'')+'">'+escText(app.reason)+'</div>'+
      row('Source','<strong>'+escText(src.t)+'</strong>')+
      row('Condition', c?escText((look&&look[1])||'—'):'—')+
      row('Scene Daily reads', '<code>'+escText(scene)+'</code>')+
      row('Temperature', (c&&c.tempC!=null)?(Math.round(c.tempC)+'°C'):'—')+
      row('Last updated', (c?escText(weatherAgeLabel(c.fetchedAt)):'never')+(stale?' · stale':''))+
      (navigator.onLine===false?'<div class="stg-status" style="margin:12px 0 0">You are offline — showing the last reading.</div>':'')+
      ((err||liveMsg)?'<div class="stg-status err" style="margin:12px 0 0" role="alert">'+escText(liveMsg||err)+'</div>':'')+
    '</div>'+
    '<div class="stg-card" id="stg-card-wx-location">'+
      // Deliberately not called a suburb: this is the city of the forecast TIMEZONE, which is
      // all the forecast API returns. There is no reverse-geocode here, so claiming more
      // precision than that would be inventing it.
      stgCardHead('pin','Location','Taken from the forecast timezone, not a street address — it names the region the forecast is for, not your suburb.')+
      row('Forecast region', c?escText(c.city||'—'):'—')+
      row('Location permission', escText(WEATHER_PERM_LABEL[_weatherPerm]||WEATHER_PERM_LABEL.unknown))+
      (c&&c.lat!=null
        ? '<details class="wx-details"><summary>Stored coordinates</summary>'+
          '<div class="wx-coords">'+escText(Number(c.lat).toFixed(4))+', '+escText(Number(c.lon).toFixed(4))+
          '<br><span class="stg-help">Kept on this device only. Never uploaded, never included in a backup file.</span></div></details>'
        : '')+
      '<div class="stg-actions stack">'+
        '<button type="button" class="stg-btn primary"'+(busy?' disabled':'')+' onclick="weatherUseCurrentLocation()">'+
          (weatherIsReal(c)?'Update current location':'Use current location')+'</button>'+
        '<button type="button" class="stg-btn"'+((busy||!c||c.lat==null)?' disabled':'')+' onclick="weatherRefreshStored()">Refresh at the saved location</button>'+
      '</div>'+
      '<p class="stg-help">"Use current location" asks your device for a fresh position every time, even when coordinates are already saved.</p>'+
      '<p class="stg-help">Your browser and your phone’s settings control the permission, not Daily. If it is blocked, allow location for this site there and come back. Some browsers (including Safari) never report the status, which shows as Unknown — that does not mean blocked.</p>'+
      '<button type="button" class="stg-link" onclick="openSettingsSection(\'appearance\',\'stg-card-theme\')">Choose or turn off weather-driven colour →</button>'+
    '</div>'+
    // Destructive action, so it gets its own labelled card rather than sitting third in a
    // list of ordinary buttons.
    '<div class="stg-card stg-danger-zone" id="stg-card-wx-danger">'+
      stgCardHead('alert','Danger zone','Removes the cached reading and coordinates from this device, so old coordinates stop being reused. If you are signed in it also deletes the obsolete copy an earlier version of Daily uploaded.')+
      '<div class="stg-actions stack">'+
        '<button type="button" class="stg-btn danger"'+((busy||!c)?' disabled':'')+' onclick="weatherClearSaved()">Clear saved weather &amp; location</button>'+
      '</div>'+
    '</div>';
}
// Called from app launch, tab returns and appearance changes. Throttled so a burst of
// visibility/pageshow events cannot turn into a burst of requests.
let _weatherLastCheck=0;
function weatherEnsureFresh(){
  const now=Date.now();
  if(now-_weatherLastCheck < 60*1000) return;
  _weatherLastCheck=now;
  const cache=loadWeatherCache();
  // Nothing saved and no reason to need it yet: don't fetch a sample the user hasn't asked for.
  if(!cache && accentMode()!=='weather' && !(typeof _homeIds!=='undefined' && _homeIds.includes && _homeIds.includes('weather'))) return;
  if(weatherIsFresh(cache)) return;
  if(weatherIsReal(cache)){ weatherRefreshStored(); return; }
  loadWeatherWidget();
}
// Fixed set of decorative layers for every possible scene, shown/hidden per
// .home-weather-card[data-scene] in CSS — cheaper and simpler than swapping markup per
// condition, since it's just one attribute write in renderWeatherInto(). Stars/snow use a
// handful of individually-delayed elements rather than a repeating background pattern so
// they read as scattered/organic instead of a visible grid.
function buildWeatherCard(){
  const d=localMidnight(getLocalDate());
  const dayLabel=d.toLocaleDateString('en-AU',{weekday:'long'});
  const dateLabel=d.toLocaleDateString('en-AU',{day:'numeric',month:'long'});
  const stars=Array.from({length:5},(_,i)=>'<div class="wfx-star wfx-star-'+(i+1)+'"></div>').join('');
  const flakes=Array.from({length:6},(_,i)=>'<div class="wfx-flake wfx-flake-'+(i+1)+'"></div>').join('');
  const drops=Array.from({length:6},(_,i)=>'<div class="wfx-drop wfx-drop-'+(i+1)+'"></div>').join('');
  // Built with the clock-based sky already applied so a cold start paints the right time of
  // day immediately, instead of flashing the daytime placeholder before any render runs.
  return '<div class="card home-weather-card" data-scene="'+weatherPlaceholderScene()+'">'+
    '<div class="weather-fx" aria-hidden="true">'+
      '<div class="wfx-sun"></div>'+
      '<div class="wfx-moon"></div>'+
      '<div class="wfx-stars">'+stars+'</div>'+
      '<div class="wfx-cloud wfx-cloud-1"></div>'+
      '<div class="wfx-cloud wfx-cloud-2"></div>'+
      '<div class="wfx-cloud wfx-cloud-3"></div>'+
      '<div class="wfx-fog wfx-fog-1"></div>'+
      '<div class="wfx-fog wfx-fog-2"></div>'+
      '<div class="wfx-rain">'+drops+'</div>'+
      '<div class="wfx-snow">'+flakes+'</div>'+
      '<div class="wfx-flash"></div>'+
    '</div>'+
    '<div class="weather-content">'+
      '<div class="weather-left">'+
        '<div class="weather-city" id="home-weather-city"></div>'+
        '<div class="weather-day">'+dayLabel+'</div>'+
        '<div class="weather-date">'+dateLabel+'</div>'+
      '</div>'+
      '<div class="weather-right">'+
        '<div class="weather-temp-row">'+
          '<span class="weather-icon" id="home-weather-icon"></span>'+
          '<span class="weather-temp" id="home-weather-temp"></span>'+
        '</div>'+
        '<div class="weather-condition" id="home-weather-label" onclick="loadWeatherWidget(true)">Loading…</div>'+
        '<div class="weather-meta" id="home-weather-meta"></div>'+
      '</div>'+
    '</div>'+
  '</div>';
}
// ── Credit card tracker (Home card + Budget input) ───────────────
function loadCCData(){ return lsLoad('daily_cc', {}); }
function saveCCData(d){ lsSave('daily_cc', d, 'creditCard'); }
function renderCCCard(){
  const d=loadCCData();
  const balance=parseFloat(d.balance)||0;
  const balEl=document.getElementById('home-cc-balance');
  if(balEl) balEl.textContent='$'+balance.toFixed(0);

  // Due date — exactly the date the user set (YYYY-MM-DD), or legacy ISO. No auto-guessing.
  let due=null;
  if(d.dueDate){ const s=String(d.dueDate); due=new Date(s.length<=10?s+'T12:00:00':s); if(isNaN(due.getTime())) due=null; }
  const dueEl=document.getElementById('home-cc-due');
  if(dueEl){
    if(due){
      const overdue = due < new Date(getLocalDate()+'T12:00:00');
      dueEl.textContent=(overdue?'Overdue · ':'Due ')+due.toLocaleDateString('en-AU',{day:'numeric',month:'short'});
      dueEl.style.color = overdue ? 'var(--danger)' : '';
    } else {
      dueEl.textContent='Set due date in Budget';
      dueEl.style.color='';
    }
  }

  // Covered if the current savings balance covers what's owed on the card
  const savings=savingsLog.length?(parseFloat(savingsLog[savingsLog.length-1].balance)||0):0;
  const statusEl=document.getElementById('home-cc-status');
  if(statusEl){
    if(balance>0){
      const covered=savings>=balance;
      statusEl.textContent=covered?'✓ Covered':'⚠ Check funds';
      statusEl.className='home-cc-status '+(covered?'covered':'at-risk');
      statusEl.style.display='inline-block';
    } else {
      statusEl.textContent=''; statusEl.className='home-cc-status'; statusEl.style.display='none';
    }
  }
}
function updateCCBalance(){
  const val=parseFloat(document.getElementById('cc-balance-input')?.value)||0;
  const d=loadCCData();
  d.balance=val;            // due date is set explicitly via the date field — never auto-guessed
  saveCCData(d);
  recordCCHistory(val);     // dated history feeds the Finance net-worth trend
  renderCCCard();
}
function updateCCDue(){
  const v=document.getElementById('cc-due-input')?.value||'';
  const d=loadCCData();
  if(v) d.dueDate=v; else delete d.dueDate;
  saveCCData(d);
  renderCCCard();
}
// ── Budget tab: credit-card row (tap to expand → edit balance + repayment due) ──
let ccEditing=false;
function ccDueText(d){
  if(!d||!d.dueDate) return 'Set repayment date';
  const s=String(d.dueDate); const due=new Date(s.length<=10?s+'T12:00:00':s);
  if(isNaN(due.getTime())) return 'Set repayment date';
  const overdue = due < new Date(getLocalDate()+'T12:00:00');
  return (overdue?'Overdue · ':'Due ')+due.toLocaleDateString('en-AU',{day:'numeric',month:'short'});
}
function ccToggleEdit(){
  ccEditing=!ccEditing;
  renderCCRow();
  if(ccEditing) setTimeout(()=>document.getElementById('cc-balance-input')?.focus(),60);
}
function renderCCRow(){
  const block=document.getElementById('cc-card-block'); if(!block) return;
  const d=loadCCData();
  const balance=parseFloat(d.balance)||0;
  const dueTxt=ccDueText(d);
  const overdue=dueTxt.indexOf('Overdue')===0;
  if(!ccEditing){
    block.innerHTML=
      '<div class="bud-row cc-row" onclick="ccToggleEdit()" style="cursor:pointer">'+
        '<div class="bud-row-left">'+
          '<div class="bud-row-name">💳 Card balance owed</div>'+
          '<div class="bud-row-budget"'+(overdue?' style="color:var(--danger)"':'')+'>'+dueTxt+'</div>'+
        '</div>'+
        '<div class="bud-row-calc" style="color:var(--text)">$'+balance.toFixed(0)+'</div>'+
      '</div>';
  } else {
    const dueVal = d.dueDate ? String(d.dueDate).slice(0,10) : '';
    block.innerHTML=
      '<div class="bud-row cc-row">'+
        '<div class="bud-row-name" onclick="ccToggleEdit()" style="cursor:pointer">💳 Card balance owed</div>'+
        '<input class="bud-row-input" type="number" inputmode="decimal" placeholder="$0" id="cc-balance-input" value="'+(d.balance!==undefined&&d.balance!==''?d.balance:'')+'" oninput="updateCCBalance()">'+
      '</div>'+
      '<div class="bud-row cc-row">'+
        '<div class="bud-row-name" style="font-weight:500;color:var(--muted)">Repayment due</div>'+
        '<input class="bud-row-input" type="date" id="cc-due-input" value="'+dueVal+'" onchange="updateCCDue()" style="width:150px">'+
      '</div>'+
      '<p style="font-size:12px;color:var(--muted);line-height:1.45;margin:8px 0 2px">'+
        'This is how much is currently owed on the card. Purchases made on the card still go '+
        'into the Variable categories above, same as cash — this balance is a separate running '+
        'debt total and isn’t counted again in the weekly leftover.</p>';
  }
}
// Card balance + other debts now live in the Accounts page (the single source of truth for
// net worth). Replace the old inline CC editor with a link there so there's no parallel store.
function loadCCInput(){
  const block=document.getElementById('cc-card-block'); if(!block) return;
  const debts=accountsDebtsTotal();
  block.innerHTML=
    '<div class="bud-row cc-row" onclick="openAccounts()" style="cursor:pointer">'+
      '<div class="bud-row-left">'+
        '<div class="bud-row-name bud-row-name-ico">'+cardIcon('wallet')+'<span>Cards &amp; debts</span></div>'+
        '<div class="bud-row-budget">Managed in Accounts →</div>'+
      '</div>'+
      '<div class="bud-row-calc" style="color:var(--text)">'+(accounts.length?fmtMoney(debts):'—')+'</div>'+
    '</div>';
}

function daysUntil(targetDay,today){
  const nowDay=new Date(today+'T12:00:00').getDay();
  let diff=(targetDay-nowDay+7)%7;
  return diff===0?'Today! 🎉':'in '+diff+' day'+(diff===1?'':'s');
}
// ── Card chrome ───────────────────────────────────────────────────
// A small line-icon set for card headers, in one visual family with the sidebar's icons
// (24px grid, currentColor stroke, round caps) — so a card header stops being an emoji sitting
// a few hundred pixels from a clean icon set. Emoji ignore currentColor, so they can never
// follow the theme or the accent, and they render as a different picture per OS.
// Chrome only. Emoji the USER typed (note titles, recipe names, the per-subscription emoji
// field) are content and are left alone.
const CARD_ICONS={
  wallet:'<path d="M17 8V6a2 2 0 0 0-2-2H5a2 2 0 0 0 0 4h14a2 2 0 0 1 2 2v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6"/><circle cx="16.5" cy="13.5" r="1.1"/>',
  bank:'<path d="M3 21h18M5 10v11M19 10v11M9.5 10v11M14.5 10v11M4 10h16L12 4z"/>',
  scale:'<path d="M12 4v16M7 20h10M4 7h16M7 7l-3 6a3 3 0 0 0 6 0zM17 7l-3 6a3 3 0 0 0 6 0z"/>',
  trophy:'<path d="M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0zM7 6H5a2 2 0 0 0 0 4h2M17 6h2a2 2 0 0 1 0 4h-2"/>',
  check:'<path d="M9 12l2 2 4-4M5 4h14a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1z"/>',
  note:'<path d="M14 3v5h5M15 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7z"/>',
  pot:'<path d="M5 10h14v6a4 4 0 0 1-4 4H9a4 4 0 0 1-4-4zM3 10h18M8 10V7a4 4 0 0 1 8 0v3"/>',
  calendar:'<path d="M8 3v3M16 3v3M4 9h16M5 5h14a1 1 0 0 1 1 1v13a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1z"/>',
  cloud:'<path d="M7 18h10a4 4 0 0 0 .7-7.94A6 6 0 0 0 6.3 8.7 4.6 4.6 0 0 0 7 18z"/><path d="M9 14l2 2 4-4"/>',
  flame:'<path d="M12 3c3 4 6 5.5 6 9a6 6 0 0 1-12 0c0-2 1-3.5 2.5-5 .3 1.2 1 2 2 2.2C10 7 11 4.6 12 3z"/>',
  receipt:'<path d="M6 3h12v18l-2-1.4-2 1.4-2-1.4-2 1.4-2-1.4L6 21zM9.5 8h5M9.5 12h5"/>',
  trend:'<path d="M3 17l6-6 4 4 7-7"/><path d="M20 8v5h-5"/>',
  target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3"/>',
  /* Added for the Budget chrome pass — these replace 📌 🛒 💵 🎯 📅 🏆 ⚠️ 🔁 in card
     headings. An emoji ignores currentColor, so it could not follow the theme or the accent
     and rendered differently on every OS; these inherit like any other stroke icon. */
  cart:'<path d="M3 4h2l2.4 10.2a2 2 0 0 0 2 1.55h7.3a2 2 0 0 0 1.95-1.55L20.5 8H6"/><circle cx="10" cy="19.5" r="1.3"/><circle cx="17.5" cy="19.5" r="1.3"/>',
  pin:'<path d="M9 3h6M12 3v6M8.5 9h7l1.5 5H7zM12 14v7"/>',
  alert:'<path d="M12 9v5M12 17.5v.01M10.3 3.9 2.6 17.4A2 2 0 0 0 4.3 20.4h15.4a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/>',
  repeat:'<path d="M17 2l3 3-3 3"/><path d="M4 11.5V11a4 4 0 0 1 4-4h12"/><path d="M7 22l-3-3 3-3"/><path d="M20 12.5v.5a4 4 0 0 1-4 4H4"/>',
  down:'<path d="M12 4v14M6 12l6 6 6-6"/>',
  medal:'<circle cx="12" cy="15" r="5.5"/><path d="M12 12.8l.9 1.9 2 .3-1.5 1.4.4 2-1.8-1-1.8 1 .4-2-1.5-1.4 2-.3zM8 3l1.8 5.2M16 3l-1.8 5.2M7 3h10"/>'
};
function cardIcon(name){
  const d=CARD_ICONS[name];
  return d ? '<svg class="card-hd-ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>' : '';
}
// One header for every rebuilt card: icon + label on the left, an optional pill or action on
// the right. rightHtml is raw so a card can pass either.
function cardHeader(icon,label,rightHtml){
  return '<div class="card-hd"><div class="card-hd-l">'+cardIcon(icon)+
    '<span class="card-label">'+label+'</span></div>'+(rightHtml||'')+'</div>';
}
// Inline SVG sparkline — one path, no axes, no labels, no library. Chart.js is loaded but a
// 40px trend line inside a card wants a shape, not a chart: axes and tooltips at this size are
// noise, and a hand-rolled path costs nothing and scales with the card.
// preserveAspectRatio="none" so the path stretches to whatever width the card gives it while
// keeping its stroke crisp (vector-effect), which is what lets it act as a .card-shape stretch
// zone on desktop.
function sparkline(vals,opts){
  const o=opts||{};
  const h=o.height||40, col=o.color||'var(--accent-text)', W=100;
  const pts=(vals||[]).filter(v=>typeof v==='number'&&isFinite(v));
  if(pts.length<2) return '';
  let min=Math.min(...pts), max=Math.max(...pts);
  if(o.target!=null){ min=Math.min(min,o.target); max=Math.max(max,o.target); }
  const pad=(max-min)*0.12||1;
  min-=pad; max+=pad;
  const x=i=>(i/(pts.length-1)*W).toFixed(2);
  const y=v=>(h-((v-min)/(max-min))*h).toFixed(2);
  const d=pts.map((v,i)=>(i?'L':'M')+x(i)+' '+y(v)).join(' ');
  const tgt=o.target!=null
    ? '<line x1="0" y1="'+y(o.target)+'" x2="'+W+'" y2="'+y(o.target)+'" stroke="var(--text-3)" stroke-width="1" stroke-dasharray="3 3" vector-effect="non-scaling-stroke"/>'
    : '';
  // Last point marked so "where am I now" is findable without reading the whole line.
  const last='<circle cx="'+x(pts.length-1)+'" cy="'+y(pts[pts.length-1])+'" r="2.5" fill="'+col+'" vector-effect="non-scaling-stroke"/>';
  return '<svg class="card-spark" viewBox="0 0 '+W+' '+h+'" preserveAspectRatio="none" aria-hidden="true">'+
    tgt+'<path d="'+d+'" fill="none" stroke="'+col+'" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>'+
    last+'</svg>';
}
// Seven-day calorie strip for the overview card. daily_cal_history is a flat {date: total}
// map that was stored, synced, and never shown on Home — the card only ever knew about today,
// so "0 / 3,062" on a Sunday evening read as failure rather than as a Sunday.
// Folded into the existing card rather than shipped as a separate widget: one card showing
// today AND the week beats two cards each showing half of it.
function calorieWeekStrip(goalCals,todayTotal){
  const today=getLocalDate(), t0=localMidnight(today).getTime();
  const days=[];
  for(let i=6;i>=0;i--){
    const d=dateStr(new Date(t0-i*864e5));
    days.push({d, v: d===today ? todayTotal : (parseFloat((calorieHistory||{})[d])||0)});
  }
  const logged=days.filter(x=>x.v>0);
  // Under three logged days the chart is mostly gaps, which reads as broken rather than as
  // "not much history yet" — better to show nothing at all.
  if(logged.length<3) return '';
  const avg=Math.round(logged.reduce((a,b)=>a+b.v,0)/logged.length);
  const max=Math.max(goalCals||0, ...days.map(x=>x.v))*1.08||1;
  const bars=days.map(x=>
    '<div class="cw-col"><div class="cw-bar'+(x.d===today?' cw-today':'')+(x.v?'':' cw-empty')+
    '" style="height:'+Math.min(100,x.v/max*100).toFixed(1)+'%"></div></div>').join('');
  return '<div class="cal-week">'+
      (goalCals?'<div class="cw-target" style="bottom:'+(goalCals/max*100).toFixed(1)+'%"></div>':'')+
      bars+
    '</div>'+
    '<div class="card-cap">7-day avg '+avg.toLocaleString()+(goalCals?' · target '+goalCals.toLocaleString():'')+'</div>';
}
function homeHeroContent(goalCals,kcalTotal,budLeft,budPillCls,budPillTxt){
  if(goalCals){
    const pct=Math.min(100,Math.round(kcalTotal/goalCals*100));
    const rem=goalCals-kcalTotal;
    const ringCol=rem<0?'var(--danger)':pct>80?'var(--warn)':'var(--success)';
    const R=44,circ=+(2*Math.PI*R).toFixed(1),offset=+(circ*(1-pct/100)).toFixed(1);
    // Breakfast / lunch / dinner totals, replacing the greeting that used to sit above the
    // ring. The per-meal category is already recorded on every entry (MEAL_CATS), it just
    // was never surfaced here — so this is a read, not new tracking.
    const byMeal={breakfast:0,lunch:0,dinner:0};
    ((S.dailyLog&&S.dailyLog.entries)||[]).forEach(e=>{
      if(byMeal[e.category]!==undefined) byMeal[e.category]+=parseFloat(e.kcal)||0;
    });
    const mealRows=[['B','breakfast'],['L','lunch'],['D','dinner']].map(([initial,id])=>{
      const v=Math.round(byMeal[id]);
      return '<div class="hh-meal">'+
        '<span class="hh-meal-key">'+initial+'</span>'+
        '<span class="hh-meal-val'+(v?'':' hh-meal-empty')+'">'+(v?v:'—')+'</span>'+
      '</div>';
    }).join('');
    return (
      '<div class="hh-row">'+
      '<div class="hh-meals">'+mealRows+'</div>'+
      '<svg width="110" height="110" viewBox="0 0 110 110" style="flex-shrink:0">'+
        '<circle cx="55" cy="55" r="'+R+'" fill="none" stroke="var(--border)" stroke-width="9"/>'+
        '<circle cx="55" cy="55" r="'+R+'" fill="none" stroke="'+ringCol+'" stroke-width="9"'+
        ' stroke-dasharray="'+circ+'" stroke-dashoffset="'+offset+'"'+
        ' stroke-linecap="round" transform="rotate(-90 55 55)"/>'+
        '<text x="55" y="52" text-anchor="middle" dominant-baseline="middle" font-size="19" font-weight="800" fill="var(--text)">'+kcalTotal+'</text>'+
        '<text x="55" y="67" text-anchor="middle" font-size="10" fill="var(--muted)">eaten</text>'+
      '</svg>'+
      '<div class="hh-remain">'+
        '<div style="font-size:30px;font-weight:700;letter-spacing:-1px;color:'+ringCol+';line-height:1">'+(rem>=0?rem:Math.abs(rem))+'</div>'+
        '<div style="font-size:12px;color:var(--muted);margin-bottom:6px">'+(rem>=0?'kcal remaining':'kcal over target')+'</div>'+
        '<div style="font-size:11px;font-weight:600;color:var(--muted)">Goal: '+goalCals+' kcal</div>'+
      '</div>'+
      '</div>'+
      calorieWeekStrip(goalCals,kcalTotal));
  } else if(budLeft!==null){
    // Neutral figure, verdict in the chip — the same rule as everywhere else money is shown.
    const kind = budPillCls==='good'?'pos':budPillCls==='warn'?'warn':'neg';
    const ico  = kind==='pos'?'check':kind==='warn'?'flat':'alert';
    return (
      '<div style="text-align:center;padding:14px 0">'+
        '<div style="font-size:30px;font-weight:700;letter-spacing:-1px;color:var(--text);line-height:1;margin-bottom:6px">'+(budLeft>=0?'+$':'-$')+Math.abs(budLeft).toFixed(0)+'</div>'+
        '<div style="font-size:13px;color:var(--muted);margin-bottom:10px">This week\'s leftover</div>'+
        tstat(kind,budPillTxt,ico)+
      '</div>');
  } else {
    return '<div style="text-align:center;padding:14px 0;font-size:13px;color:var(--muted)">Set up your profile to see calorie targets</div>';
  }
}
function homeSavingsInner(){
  const last8=savingsLog.slice(-8);
  if(last8.length){
    const latest=last8[last8.length-1];
    const diffDays=Math.floor((new Date()-new Date(latest.date))/(864e5));
    const ago=diffDays===0?'today':diffDays===1?'yesterday':diffDays+' days ago';
    const vals=last8.map(e=>e.balance);
    const maxV=Math.max(...vals),minV=Math.min(...vals),range=maxV-minV||maxV||1;
    const bars=last8.map((e,i)=>{
      const prev=i>0?last8[i-1].balance:e.balance;
      const col=e.balance<prev?'var(--danger)':'var(--success)';
      const h=Math.max(8,Math.round(((e.balance-minV)/range)*36+8));
      return '<div style="flex:1;display:flex;align-items:flex-end;padding:0 1px"><div style="width:100%;height:'+h+'px;background:'+col+';border-radius:2px 2px 0 0;opacity:0.85"></div></div>';
    }).join('');
    return (
      '<div style="display:flex;justify-content:space-between;align-items:flex-end">'+
        '<div>'+
          '<div style="font-size:22px;font-weight:800">$'+latest.balance.toLocaleString()+'</div>'+
          '<div style="font-size:11px;color:var(--muted)">Updated '+ago+'</div>'+
        '</div>'+
        '<button class="sav-update-btn" onclick="event.stopPropagation();updateSavingsBalance()">Update</button>'+
      '</div>'+
      '<div style="display:flex;align-items:flex-end;height:40px;gap:2px;margin-top:8px">'+bars+'</div>');
  } else {
    return (
      '<div style="display:flex;justify-content:space-between;align-items:center">'+
        '<div style="font-size:22px;font-weight:800;color:var(--muted)">$—</div>'+
        '<button class="sav-update-btn" onclick="event.stopPropagation();updateSavingsBalance()">Update</button>'+
      '</div>'+
      '<div style="font-size:11px;color:var(--muted);margin-top:4px">No balance logged</div>');
  }
}

function renderHome(){
  const wrap=document.getElementById('home-content'); if(!wrap) return;
  const name=profileData.name||S.personalInfo.name||'';

  // Calories
  const today=getLocalDate();
  if(S.dailyLog.date!==today){ S.dailyLog={date:today,entries:[]}; persistDailyLog(); }
  const c=calcGoalCals();
  const goalCals=c?(c.goal==='cut'?c.cut:c.goal==='bulk'?c.bulk:c.maintain):null;
  const kcalTotal=S.dailyLog.entries.reduce((a,e)=>a+e.kcal,0);

  // Budget leftover — from the CURRENT WEEK's saved data (same accessors as the Budget
  // tab: weekIncome / weekLeftover) so Home always matches what the Budget tab shows.
  let budLeft=null,budPillCls='good',budPillTxt='';
  const curWk=budgetData[weekKey(getMondayOf(0))];
  const incTot=curWk?weekIncome(curWk):0;
  if(incTot>0){
    budLeft=weekLeftover(curWk);
    budPillCls=budLeft>=50?'good':budLeft>=0?'warn':'over';
    // Words only — the tonal chip these feed (tstat) supplies the tint and the icon, and an
    // emoji here would have restated the state a third time in a colour that cannot follow
    // the theme.
    budPillTxt=budLeft>=50?'On track':budLeft>=0?'Tight':'Over';
  }

  const heroContent=homeHeroContent(goalCals,kcalTotal,budLeft,budPillCls,budPillTxt);

  // Workout streak (consecutive days with logged sessions)
  const sessDates=[...new Set(S.sessions.map(s=>s.date))].sort();
  let wStreak=0;
  const dw=localMidnight(getLocalDate());
  while(true){ const ds=dateStr(dw); if(sessDates.includes(ds)){wStreak++;dw.setDate(dw.getDate()-1);}else break; }

  // Check-in streak
  const {current:ciStreak}=calcStreak();

  // This week's saved amount (the weekly-savings target was removed) + next workout
  const thisWeekSaved=Math.round(weekSavedAmt(budgetData[weekKey(getMondayOf(0))]||{}));
  const nextIdx=suggestDay();
  const nextType=type(nextIdx);
  const dayNum=nextIdx+1;

  // Pay day countdown tiles — one per named income source (loadIncCats), no hardcoded names.
  // Cells of the money card (see quickTiles) rather than free-floating mini-cards.
  const payDayTiles=loadIncCats()
    .filter(c=>(c.name||'').trim())
    .map(c=>{
      const str=daysUntil(getPayDay(c.id),today);
      const nm=_catEscHtml(c.name.trim());
      const soon=str==='Today! 🎉';
      return '<div class="mt-cell"><div class="mt-val'+(soon?' mt-val-sm':' mt-val-sm')+'" style="color:'+
        (soon?'var(--accent-text)':'var(--text)')+'">'+str+'</div>'+
        '<div class="mt-lbl">'+nm+' pay</div></div>';
    }).join('');

  // Last week's total pay (sum of income sources recorded for the previous budget week)
  const lastWk=budgetData[weekKey(getMondayOf(-1))];
  const lastWeekPay=lastWk?weekIncome(lastWk):0;

  const heroHdrCol=goalCals?'#52B788':budLeft!==null?'#FF6B35':'#64748b';
  const heroHdrTxt=goalCals?'Calorie progress':budLeft!==null?'Budget summary':'Overview';
  const heroHdrIcon=goalCals?'flame':budLeft!==null?'wallet':'check';

  // ── Momentum redesign: top-of-Home cards (display only; reuse existing data) ──
  const mCurType=type(S.dayIdx);
  const mExCount=mCurType.exercises.length;
  const mDone=S.checked.size;
  const mPct=mExCount?Math.round(mDone/mExCount*100):0;
  const mGoal=6;
  const mMon=getMondayOf(0);
  const mSessions=[...new Set(S.sessions.filter(s=>localMidnight(s.date)>=mMon).map(s=>s.date))].length;
  let mSegs=''; for(let i=0;i<mGoal;i++){ mSegs+='<div class="session-seg'+(i<mSessions?' done':'')+'"></div>'; }
  const mBudIncome=incTot>0?incTot:0;
  const mBudRem=incTot>0?budLeft:0;
  const mBudSpent=incTot>0?(incTot-budLeft):0;
  const mBudPct=mBudIncome>0?Math.min(mBudSpent/mBudIncome*100,100):0;
  const mBudOver=mBudRem<0;
  const mBudCol=mBudOver?'var(--danger)':'var(--positive)';
  const heroDateLabel=localMidnight(today).toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short'});
  const heroCard=
    '<div class="hero-workout-card">'+
      '<div class="hero-top">'+
        '<span class="hero-label">TODAY\'S SESSION · '+heroDateLabel+'</span>'+
        '<button class="hero-play-btn" aria-label="Go to workout" onclick="setView(\'log\')">'+
          '<svg width="18" height="18" viewBox="0 0 18 18" fill="none"><path d="M5 3.5l10 5.5-10 5.5V3.5z" fill="currentColor"/></svg>'+
        '</button>'+
      '</div>'+
      '<p class="hero-workout-title" id="hero-day-name">'+mCurType.name+'</p>'+
      '<p class="hero-meta" id="hero-meta">'+mExCount+' exercise'+(mExCount!==1?'s':'')+'</p>'+
      '<div class="hero-progress-row">'+
        '<span class="hero-progress-text" id="hero-progress-text">'+mDone+' of '+mExCount+' done</span>'+
        '<span class="hero-progress-pct" id="hero-progress-pct">'+mPct+'%</span>'+
      '</div>'+
      '<div class="hero-progress-track"><div class="hero-progress-fill" id="hero-progress-fill" style="width:'+mPct+'%;"></div></div>'+
    '</div>';
  const statsSplit=
    '<div class="card stats-split-card">'+
      '<div class="stats-left">'+
        '<p class="card-label">Streak</p>'+
        '<p class="metric-num" id="home-streak">'+wStreak+'</p>'+
        '<p class="metric-unit">days</p>'+
      '</div>'+
      '<div class="stats-divider"></div>'+
      '<div class="stats-right">'+
        '<p class="card-label">This week</p>'+
        '<p class="metric-num" id="home-sessions">'+mSessions+' <span class="metric-unit">of '+mGoal+'</span></p>'+
        '<div class="sessions-bar-row" id="home-sessions-bar">'+mSegs+'</div>'+
      '</div>'+
    '</div>';
  // ── Weekly budget ──
  // No longer an accent-gradient hero. It used the same 90%→35% accent gradient, white text and
  // glow as the session hero, so the two were indistinguishable in peripheral vision — and a
  // budget readout is not an action the way "start today's session" is. Full accent now means
  // "press this", and only the session card gets it.
  // Its colour is SEMANTIC instead: --positive / --warn / --danger on the pill and the bar fill.
  // That survives the accent being any hue (grey, indigo or bright blue depending on
  // weather/settings), and green-vs-red answers the question before you read the number.
  const budGoal=getWeekVarGoal(curWk);
  const budVarSpent=curWk?weekVarTotal(curWk):0;
  // The bar tracks VARIABLE spending against the weekly goal, not total spend against income,
  // because variable spend is the half that accrues day by day and the half still in your
  // control. Total spend can't be paced — a fixed cost lands in one lump, so a pace marker
  // against income would read "behind" every week the rent came out.
  const budHasGoal=budGoal!==null&&budGoal>0;
  const budVarPct=budHasGoal?budVarSpent/budGoal*100:0;
  const budBarPct=budHasGoal?Math.min(budVarPct,100):mBudPct;
  // Days elapsed this week including today (Mon=1 … Sun=7). varGoalDaysLeft() counts days
  // REMAINING, so elapsed is 8 minus that.
  const budPacePct=budHasGoal?Math.round((8-varGoalDaysLeft())/7*100):null;
  const budBehind=budHasGoal&&budVarPct>budPacePct+2;
  const budOverGoal=budHasGoal&&budVarSpent>budGoal;
  const budBarCol=(budHasGoal?budOverGoal:mBudOver)?'var(--danger)':budBehind?'#f59e0b':'var(--positive)';
  const budPillTxt2=mBudOver?'Over budget':budBehind?'Spending fast':'On track';
  const budPillCls2=mBudOver?' over':budBehind?' warn':'';
  const budCaption=budHasGoal
    ? fmtMoney(budVarSpent)+' of '+fmtMoney(budGoal)+' spending goal · '+(budBehind?'ahead of pace':'on pace')
    : (mBudIncome>0?'Set a weekly spending goal to track pace':'');
  const budgetSnapshot=
    '<div class="card budget-snapshot-card" onclick="setView(\'budget\')" style="cursor:pointer">'+
      cardHeader('wallet','Weekly budget',
        '<span class="budget-snap-pill'+budPillCls2+'" id="home-bud-status">'+budPillTxt2+'</span>')+
      '<div><span class="card-fig" id="home-bud-remaining" style="color:'+(mBudOver?'var(--danger)':'var(--text)')+'">'+
        (mBudRem>=0?'':'-')+fmtMoney(Math.abs(Math.round(mBudRem)))+'</span>'+
        '<span class="card-fig-u" id="home-bud-label">left of '+fmtMoney(Math.round(mBudIncome))+'</span></div>'+
      '<div class="card-bar">'+
        '<div class="card-bar-fill" id="home-bud-bar" style="width:'+budBarPct+'%;background:'+budBarCol+'"></div>'+
        (budPacePct!==null?'<div class="card-bar-pace" style="left:calc('+budPacePct+'% - 1px)" title="Where you should be today"></div>':'')+
      '</div>'+
      (budCaption?'<div class="card-cap">'+budCaption+'</div>':'')+
      // Capture from Home as well as Budget. A spending tracker is only as good as how fast a
      // purchase can be logged, and Home is the screen that is actually open when you walk out
      // of a shop. stopPropagation because the card itself navigates to the Budget tab.
      '<button class="txn-quick" onclick="event.stopPropagation();openTxnModal()">+ Add expense</button>'+
    '</div>';

  // Calorie / overview card
  const overviewCard=
    '<div class="card hero-card"'+(goalCals?' onclick="openCalorieOverlay()"':'')+' style="margin-bottom:12px;padding:0;overflow:hidden'+(goalCals?';cursor:pointer':'')+'">'+
      // Shared header, replacing another inline copy of the 11px/600/uppercase declaration.
      '<div style="padding:16px 16px 0">'+cardHeader(heroHdrIcon,heroHdrTxt)+'</div>'+
      // Greeting removed: it repeated the time of day the app already shows and pushed the
      // figures down. The meal totals now occupy that side of the card instead.
      '<div class="overview-content" style="padding:14px 16px">'+
        heroContent+
      '</div>'+
    '</div>';

  // Net Worth & Accounts widget (daily_accounts): total balance, per-account list
  // (tap to expand/collapse), net worth, and any tracked statement debt + due date.
  const _nw=accountsNetWorth(), _assets=accountsAssetsTotal(), _debts=accountsDebtsTotal();
  const _acctRows=accounts.map(a=>{
    const isD=a&&a.type==='debt';
    const util=(typeof acctUtilisation==='function')?acctUtilisation(a):null;
    const cat=(typeof acctCategoryLabel==='function')?acctCategoryLabel(a):null;
    // Sub-line only when there is something to say — a category, a utilisation figure, or both.
    const sub=[cat, util!==null?util.toFixed(0)+'% of limit':null].filter(Boolean).join(' · ');
    return '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:6px 0;border-bottom:1px solid var(--border);font-size:13px">'+
      '<span style="min-width:0"><span style="font-weight:600">'+_catEscHtml(a.name||'')+'</span>'+
        (sub?'<span style="display:block;font-size:11px;font-weight:600;color:'+
          (util!==null?acctUtilColour(util):'var(--muted)')+'">'+sub+'</span>':'')+'</span>'+
      '<span style="font-weight:700;font-family:var(--font-num);flex-shrink:0;color:'+(isD?'var(--danger)':'var(--text)')+'">'+(isD?'−':'')+fmtMoney(parseFloat(a.current)||0)+'</span>'+
    '</div>';
  }).join('');
  const _stmtRows=accounts
    .filter(a=>a&&a.type==='debt'&&a.tracksStatement&&((parseFloat(a.statementBalance)||0)>0||a.dueDate))
    .map(a=>{
      const dueTxt=acctDueText(a);
      return '<div style="font-size:12px;font-weight:600;color:var(--amber-dark);background:var(--amber-bg);border:1px solid var(--amber-border);border-radius:8px;padding:7px 10px;margin-top:8px">'+
        // Icon rather than 💳: inside an amber alert the stroke inherits the row's amber via
        // currentColor, which an emoji cannot do.
        '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;vertical-align:-2px;margin-right:6px" aria-hidden="true">'+
          '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18"/></svg>'+
        _catEscHtml(a.name||'')+': '+fmtMoney(parseFloat(a.statementBalance)||0)+' this statement'+(dueTxt?' · '+dueTxt:'')+'</div>';
    }).join('');
  // ── Net worth & accounts ──
  // Rebuilt on the shared card anatomy. It was the only Home card with no CSS identity at all —
  // assembled entirely from inline styles, so it had drifted furthest from everything else and
  // drifted further with each edit.
  // Hierarchy is inverted: NET WORTH is the primary figure, not total assets. Assets is the
  // bigger number but not the true one — $2,991 of assets against $2,812 of debts is a $179
  // position, and leading with the flattering figure told you the wrong thing at a glance.
  // The split below it is three-way when a Savers account exists, because "savers" money is
  // ringfenced and is deliberately excluded from the debt-payoff position (see
  // accountsPayoffPosition) — so folding it into one Assets number hides the distinction the
  // account flag exists to make. With no savers account it collapses to two cells rather than
  // rendering a dead $0 column.
  const _savers=accountsSaverTotal();
  const _spendable=_assets-_savers;
  const _splitCell=(label,val,col)=>'<div><div class="card-split-l">'+label+'</div>'+
    '<div class="card-split-v"'+(col?' style="color:'+col+'"':'')+'>'+fmtMoney(val)+'</div></div>';
  const _div='<div class="card-split-div"></div>';
  const _splitHtml=_savers>0
    ? _splitCell('Spendable',_spendable)+_div+_splitCell('Savers',_savers)+_div+_splitCell('Debts',_debts,'var(--danger)')
    : _splitCell('Assets',_assets)+_div+_splitCell('Debts',_debts,'var(--danger)');
  const balanceRow=
    '<div class="card home-networth-card">'+
      cardHeader('bank','Accounts',
        '<span class="card-hd-act" onclick="event.stopPropagation();openAccounts()">Manage →</span>')+
      (accounts.length
        ? '<div><span class="card-fig"'+(_nw<0?' style="color:var(--danger)"':'')+'>'+
            (_nw<0?'-':'')+fmtMoney(Math.abs(_nw))+'</span>'+
            '<span class="card-fig-u">net worth</span></div>'+
          '<div class="card-split">'+_splitHtml+'</div>'+
          // The statement alert moved ABOVE the account list: it is the actionable part of the
          // card and it was sitting below a collapsed section, i.e. last.
          _stmtRows+
          // Expand/collapse the per-account list — same inline toggle idiom as the
          // Recent-workout card; no re-render, so it can't lose scroll position.
          '<div onclick="event.stopPropagation();var d=this.nextElementSibling;var open=d.style.display===\'block\';d.style.display=open?\'none\':\'block\';this.querySelector(\'span\').textContent=open?\'▾\':\'▴\'" '+
            'style="cursor:pointer;font-size:12px;font-weight:700;color:var(--muted);margin-top:12px;display:flex;justify-content:space-between;align-items:center">'+
            accounts.length+' account'+(accounts.length===1?'':'s')+' <span>▾</span></div>'+
          '<div class="home-accts-list" style="display:none;margin-top:4px">'+_acctRows+'</div>'
        : '<div onclick="openAccounts()" style="cursor:pointer;font-size:14px;color:var(--muted)">Tap to add your savings, credit card, or any balance to track net worth.</div>')+
    '</div>';

  // Quick-info tiles (de-duplicated: no streak/next-workout — those live in the cards above)
  // ── Money at a glance ──
  // Was a bare 2-column grid of small .cards with no container of its own — a loose cluster
  // rather than a widget, so it broke the page's vertical rhythm every time you scrolled past
  // it, and its tiles carried their own padding and radius matching nothing else.
  // One card now, with the tiles as cells inside it sharing the card's padding. Emoji dropped:
  // the header icon says "money" once, so repeating 💰/💵/📅 on every cell was decoration that
  // also could not follow the theme.
  const quickTiles=
    '<div class="card" onclick="setView(\'budget\')" style="cursor:pointer">'+
      cardHeader('wallet','This week\'s money')+
      '<div class="mt-grid">'+
        '<div class="mt-cell"><div class="mt-val" style="color:var(--positive)">'+fmtMoney(thisWeekSaved)+'</div>'+
          '<div class="mt-lbl">Saved this week</div></div>'+
        '<div class="mt-cell"><div class="mt-val">'+fmtMoney(Math.round(lastWeekPay))+'</div>'+
          '<div class="mt-lbl">Last week\'s pay</div></div>'+
        payDayTiles+
      '</div>'+
    '</div>';

  // Each card is a draggable unit (data-card-id); assembled in the user's saved order
  // so a reorder survives the next renderHome. (Recent workout + Stats render separately.)
  const homeCards={
    session: heroCard,
    weather: buildWeatherCard(),
    streak: statsSplit,
    calories: overviewCard,
    review: buildWeekSummaryCard(),
    habits: buildTodayHabitsCard(),
    budget: budgetSnapshot,
    finance: buildFinanceCheckinCard(),
    balance: balanceRow,
    tiles: quickTiles,
    weight: buildWeightGoalCard(),
    prs: buildPRCard(),
    kitchen: buildKitchenCard(),
    notes: buildHomeNotesCard(),
    recent: buildHomeRecentCard()
  };
  // Ordered + visibility-filtered widget list; skip widgets whose HTML is empty right now
  // (e.g. Recent Workout before any session exists) so edit mode has no invisible boxes.
  const _homeIds=effectiveHomeWidgetIds(homeCards).filter(k=>homeCards[k]);
  // Cards that span both desktop columns are a saved per-card preference now, not a hardcoded
  // list. The class is emitted on every layout but only means anything inside the desktop
  // media query, where the grid lives.
  const _wide=new Set(homeLayout().wide);
  const _cardHtml=k=>'<div class="home-card'+(_wide.has(k)?' home-card-wide':'')+'" data-card-id="'+k+'">'+homeCards[k]+'</div>';
  if(window.innerWidth>=1024 || isLandscapePhone()){
    // Desktop AND landscape phone: ONE grid holding every card in saved order, so visual order
    // == DOM order. This replaced a column-major layout (cards dealt alternately into two flex
    // columns) that packed more tightly but made the visual order unreadable from the DOM —
    // which is why saveHomeOrder() used to refuse to run on desktop and drag-to-reorder was
    // mobile-only. Ordering has to win over packing for reordering to work at all: in a
    // packed/masonry layout a dragged card can't land where it was dropped. The cost is that a
    // short card beside a tall one leaves a gap rather than the columns finishing flush.
    // Weather is no longer pulled out and pinned last — it's an ordinary ordered card.
    // Landscape uses the SAME wrapper and the same two-column rule rather than a parallel
    // layout: a phone on its side has desktop's problem (width to spend, order to preserve)
    // at phone scale, and .home-card-wide has to keep spanning both columns in both.
    wrap.innerHTML='<div class="home-grid-cols">'+_homeIds.map(_cardHtml).join('')+'</div>';
  } else {
    wrap.innerHTML=_homeIds.map(_cardHtml).join('');
  }
  const _oldRecent=document.getElementById('home-recent-card'); if(_oldRecent) _oldRecent.innerHTML='';
  document.querySelectorAll('#view-home .card').forEach((card, i) => {
    card.style.animationDelay = (i * 45) + 'ms';
    card.classList.add('home-card-enter');
    setTimeout(() => card.classList.remove('home-card-enter'), 600 + i * 45);
  });
  if(homeEditMode) applyHomeEditMode();
  applyHomeCardCaps();   // assigns grid spans too

  applyDayColour();
  // Only touch geolocation/network if the widget is actually visible — a hidden card has no
  // #home-weather-temp for the result to land in anyway.
  // Not gated on the card being present: weather appearance needs fresh data whether or not
  // the widget is on Home. weatherEnsureFresh throttles, so this stays cheap on every render.
  if(_homeIds.includes('weather')) loadWeatherWidget(); else weatherEnsureFresh();
}

// ── Home widget system ────────────────────────────────────────────
// Every Home card is a "widget": it can be toggled off and back on (never deleted — the
// underlying data is untouched) and reordered. The registry tags each widget with its
// related tab for the Settings → Home Layout grouping. `fixed` widgets can't be hidden:
// the Overview card doubles as the app's greeting, so Home is never a fully blank page.
// Settings → Home Layout preview thumbnails. Miniature mock-ups of the real cards (same
