    '<div id="se-wrap"></div>'+
    '<div class="ob-btn-row" style="margin-top:14px">'+
      '<button class="ob-btn-skip" onclick="obSkipSplit()">Skip</button>'+
      '<button class="ob-btn-primary ob-btn-inline" onclick="obNext()">Continue →</button>'+
    '</div>';
