function kitLoadRecipes(){
  try{
    const raw=localStorage.getItem('kitchen_recipes');
    if(raw){ const arr=JSON.parse(raw); if(Array.isArray(arr)) return arr; }
  }catch(e){}
  const seeded=kitSeedRecipes();
  localStorage.setItem('kitchen_recipes',JSON.stringify(seeded));
  return seeded;
}
let kitRecipes=kitLoadRecipes();
function kitSaveRecipes(){ lsSave('kitchen_recipes', kitRecipes, 'kitRecipes'); }
const kitState={tab:'recipes',cat:'all',search:'',filter:'all',filtersOpen:false,selectedId:null,scaleServings:null};
const KIT_CATS=[['all','All'],['breakfast','Breakfast'],['lunch','Lunch'],['dinner','Dinner'],['dessert','Dessert']];

function kitEsc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function kitTrim(n){ let s=(Math.round(n*10)/10).toFixed(1); return s.endsWith('.0')?s.slice(0,-2):s; }
function kitScaledAmount(amount,baseServings,curServings){
  const n=parseFloat(amount);
  if(isNaN(n)||!baseServings) return amount===0?'':String(amount||'');
  return kitTrim((n/baseServings)*curServings);
}

function kitRender(){ kitSetTab(kitState.tab); }
function kitSetTab(tab){
  kitState.tab=tab;
  ['recipes','shopping','pantry'].forEach(t=>{
    const pane=document.getElementById('kit-'+t); if(pane) pane.classList.toggle('hidden',t!==tab);
    const btn=document.getElementById('kit-tab-'+t); if(btn) btn.classList.toggle('active',t===tab);
  });
  if(tab==='recipes') kitRenderList();
  if(tab==='shopping') kitShopRender();
  else if(typeof kitShopRenderAddBar==='function') kitShopRenderAddBar(false);
  if(tab==='pantry') kitPantryRender();
  updateKitFab();
}
// The "+" is only meaningful on the Recipes sub-tab of the Kitchen view. It used to be a child
// of #kit-recipes, so the pane's own .hidden did this; now that it has to live outside the
// swipe deck (see index.html) its visibility is explicit.
function updateKitFab(){
  const fab=document.getElementById('kit-fab'); if(!fab) return;
  const show = S.view==='kitchen' && (kitState&&kitState.tab==='recipes');
  fab.style.display = show ? 'flex' : 'none';
}
function kitOnSearch(v){ kitState.search=v||''; kitRenderList(); }
function kitSetCat(c){ kitState.cat=c; kitRenderList(); }
function kitToggleFilters(){
  kitState.filtersOpen=!kitState.filtersOpen;
  kitRenderFilterButton();
}
function kitResetFilters(){
  kitState.cat='all';
  kitState.filter='all';
  kitRenderList();
}
function kitRenderFilterButton(){
  const panel=document.getElementById('kit-filter-controls');
  const toggle=document.getElementById('kit-filter-toggle');
  const reset=document.getElementById('kit-filter-reset');
  const count=document.getElementById('kit-filter-count');
  const active=(kitState.cat!=='all'?1:0)+(kitState.filter!=='all'?1:0);
  if(panel) panel.classList.toggle('open',kitState.filtersOpen);
  if(toggle){
    toggle.classList.toggle('active',active>0);
    toggle.setAttribute('aria-expanded',kitState.filtersOpen?'true':'false');
  }
  if(reset) reset.classList.toggle('active',active===0);
  if(count){
    count.textContent=active||'';
    count.classList.toggle('hidden',active===0);
  }
}

function kitRenderCatPills(){
  const wrap=document.getElementById('kit-cat-pills'); if(!wrap) return;
  wrap.innerHTML=KIT_CATS.map(([v,l])=>
    '<button class="kit-cat-pill'+(kitState.cat===v?' active':'')+'" onclick="kitSetCat(\''+v+'\')">'+l+'</button>'
  ).join('');
}
// step normalisation helpers — seeded recipes have string steps, new ones use {text,timerMinutes}
function kitStepText(s){ return (s&&typeof s==='object') ? (s.text||'') : (s||''); }
function kitStepTimer(s){ return (s&&typeof s==='object'&&s.timerMinutes>0) ? s.timerMinutes : null; }

function kitFilteredRecipes(){
  const q=kitState.search.trim().toLowerCase();
  const f=kitState.filter;
  return kitRecipes.filter(r=>{
    if(kitState.cat!=='all' && r.category!==kitState.cat) return false;
    if(f==='favourites' && !r.favourite) return false;
    if(f==='recent' && !r.lastCooked) return false;
    if(!q) return true;
    if((r.name||'').toLowerCase().includes(q)) return true;
    return (r.ingredients||[]).some(i=>(i.name||'').toLowerCase().includes(q));
  });
}
function kitSetFilter(f){
  kitState.filter=f;
  kitRenderList();
}
function kitRenderFilterChips(){
  const wrap=document.getElementById('kit-filter-chips'); if(!wrap) return;
  const chips=[['all','All'],['favourites','Favourites ♥'],['recent','Recently Cooked 🕐']];
  wrap.innerHTML=chips.map(([v,l])=>
    '<button class="kit-fchip'+(kitState.filter===v?' active':'')+'" onclick="kitSetFilter(\''+v+'\')">'+l+'</button>'
  ).join('');
}

// ── Cooking mode ──────────────────────────────────────────────────
// Which of the recipe's ingredients this step's text actually names — deliberately simple
// word-boundary matching, not NLP. Tries the ingredient's full name first (how AI-authored
// steps already reference them, e.g. "800 g baby potatoes"); if that isn't found, falls back
// to just the last word of the name (e.g. "potatoes" alone) so a looser phrasing still
// counts. A miss here just means that ingredient sits in the full list instead of also being
// called out — never a correctness problem, so there's no need for anything heavier.
function kitStepIngredients(text, ingredients){
  const t=' '+String(text||'').toLowerCase()+' ';
  const esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const hasWord=phrase=>{
    const p=phrase.toLowerCase().trim(); if(!p) return false;
    return new RegExp('(^|[^a-z0-9])'+esc(p)+'s?([^a-z0-9]|$)','i').test(t);
  };
  return (ingredients||[]).filter(i=>{
    const name=(i&&i.name||'').trim(); if(!name) return false;
    if(hasWord(name)) return true;
    const words=name.split(/\s+/);
    const last=words[words.length-1];
    return last.length>=4 && hasWord(last);
  });
}
const kitCookState={recipeId:null,step:0,timerTotal:0,timerRemaining:0,timerStart:null,timerRunning:false,wakeLock:null,tickId:null};
function kitStartCooking(id){
  const r=kitRecipes.find(x=>x.id===id); if(!r) return;
  kitCookState.recipeId=id;
  kitCookState.step=0;
  kitCookState.timerRunning=false;
  kitCookState.timerStart=null;
  kitCookState.timerTotal=0;
  kitCookState.timerRemaining=0;
  if(kitCookState.tickId){ clearInterval(kitCookState.tickId); kitCookState.tickId=null; }
  const ov=document.getElementById('kit-cook-overlay'); if(!ov) return;
  // Opaque status bar already reserves its height (see #app-header) — fixed top padding, no
  // env(safe-area-inset-top) which double-counts it. Bottom inset kept.
  ov.style.cssText='display:flex;flex-direction:column;position:fixed;inset:0;background:var(--bg);z-index:200;overflow:hidden;padding:16px 0 env(safe-area-inset-bottom,16px)';
  kitCookRender();
  // wake lock
  if(navigator.wakeLock) navigator.wakeLock.request('screen').then(wl=>{ kitCookState.wakeLock=wl; }).catch(()=>{});
}
function kitExitCooking(){
  if(kitCookState.tickId){ clearInterval(kitCookState.tickId); kitCookState.tickId=null; }
  if(kitCookState.wakeLock){ kitCookState.wakeLock.release().catch(()=>{}); kitCookState.wakeLock=null; }
  const ov=document.getElementById('kit-cook-overlay');
  if(ov) ov.style.display='none';
  kitCookState.recipeId=null;
}
function kitCookFinish(){
  const r=kitRecipes.find(x=>x.id===kitCookState.recipeId);
  if(r){ r.lastCooked=Date.now(); kitSaveRecipes(); }
  kitExitCooking();
  kitShowToast('Well done! 🎉');
  kitRenderList();
  if(kitCookState.recipeId && window.innerWidth>=1024) kitRefreshOpenDetail();
}
function kitCookGo(dir){
  const r=kitRecipes.find(x=>x.id===kitCookState.recipeId); if(!r) return;
  const steps=r.steps||[];
  const next=kitCookState.step+dir;
  if(next<0||next>=steps.length) return;
  kitCookState.step=next;
  if(kitCookState.tickId){ clearInterval(kitCookState.tickId); kitCookState.tickId=null; }
  kitCookState.timerRunning=false;
  kitCookState.timerStart=null;
  kitCookRender();
}
function kitCookTimerToggle(){
  const r=kitRecipes.find(x=>x.id===kitCookState.recipeId); if(!r) return;
  const s=r.steps[kitCookState.step];
  const mins=kitStepTimer(s)||0; if(!mins) return;
  if(kitCookState.timerRunning){
    // pause: store remaining
    kitCookState.timerRemaining=Math.max(0,kitCookState.timerRemaining-Math.floor((Date.now()-kitCookState.timerStart)/1000));
    kitCookState.timerRunning=false;
    kitCookState.timerStart=null;
    if(kitCookState.tickId){ clearInterval(kitCookState.tickId); kitCookState.tickId=null; }
    kitCookRenderTimer();
  } else {
    // start / resume
    if(kitCookState.timerTotal!==mins*60||kitCookState.timerRemaining<=0){
      kitCookState.timerTotal=mins*60;
      kitCookState.timerRemaining=mins*60;
    }
    kitCookState.timerStart=Date.now();
    kitCookState.timerRunning=true;
    kitCookState.tickId=setInterval(kitCookTick,500);
    kitCookRenderTimer();
  }
}
function kitCookTimerReset(){
  const r=kitRecipes.find(x=>x.id===kitCookState.recipeId); if(!r) return;
  const s=r.steps[kitCookState.step];
  const mins=kitStepTimer(s)||0;
  if(kitCookState.tickId){ clearInterval(kitCookState.tickId); kitCookState.tickId=null; }
  kitCookState.timerRunning=false;
  kitCookState.timerStart=null;
  kitCookState.timerTotal=mins*60;
  kitCookState.timerRemaining=mins*60;
  kitCookRenderTimer();
}
function kitCookTick(){
  if(!kitCookState.timerRunning) return;
  const elapsed=Math.floor((Date.now()-kitCookState.timerStart)/1000);
  const rem=Math.max(0,kitCookState.timerRemaining-elapsed);
  if(rem===0){
    clearInterval(kitCookState.tickId); kitCookState.tickId=null;
    kitCookState.timerRunning=false;
    kitCookState.timerRemaining=0;
    kitCookRenderTimer();
    if(navigator.vibrate) navigator.vibrate([300,100,300]);
    kitShowToast('Timer done! ⏰');
  } else {
    kitCookRenderTimer();
  }
}
function kitCookTimerSec(){
  if(!kitCookState.timerRunning) return kitCookState.timerRemaining;
  return Math.max(0,kitCookState.timerRemaining-Math.floor((Date.now()-kitCookState.timerStart)/1000));
}
function kitCookRenderTimer(){
  const r=kitRecipes.find(x=>x.id===kitCookState.recipeId); if(!r) return;
  const s=r.steps[kitCookState.step];
  const mins=kitStepTimer(s)||0;
  const tWrap=document.getElementById('kit-cook-timer'); if(!tWrap) return;
  if(!mins){ tWrap.innerHTML=''; return; }
  const sec=kitCookTimerSec();
  const mm=String(Math.floor(sec/60)).padStart(2,'0');
  const ss=String(sec%60).padStart(2,'0');
  const done=sec===0;
  const total=kitCookState.timerTotal||mins*60;
  const pct=total>0?Math.round((1-sec/total)*100):0;
  tWrap.innerHTML=
    '<div class="kit-cook-timer-ring" style="--pct:'+pct+'%">'+
      '<svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="34" stroke="var(--border)" stroke-width="6" fill="none"/><circle cx="40" cy="40" r="34" stroke="'+(done?'var(--danger)':'var(--accent)')+'" stroke-width="6" fill="none" stroke-dasharray="213.6" stroke-dashoffset="'+Math.round((1-pct/100)*213.6)+'" stroke-linecap="round" transform="rotate(-90 40 40)"/></svg>'+
      '<div class="kit-cook-timer-time'+(done?' done':'')+'">'+mm+':'+ss+'</div>'+
    '</div>'+
    '<div class="kit-cook-timer-btns">'+
      '<button class="kit-cook-tbtn" onclick="kitCookTimerToggle()">'+(kitCookState.timerRunning?'⏸ Pause':'▶ Start')+'</button>'+
      '<button class="kit-cook-tbtn secondary" onclick="kitCookTimerReset()">↺ Reset</button>'+
    '</div>';
}
function kitCookRender(){
  const r=kitRecipes.find(x=>x.id===kitCookState.recipeId); if(!r) return;
  const ov=document.getElementById('kit-cook-overlay'); if(!ov) return;
  const steps=r.steps||[];
  const idx=kitCookState.step;
  const total=steps.length;
  const s=steps[idx];
  const text=kitStepText(s);
  const hasPrev=idx>0;
  const hasNext=idx<total-1;
  const pct=total>1?Math.round(((idx+1)/total)*100):100;
  // reset timer state when step changes
  const mins=kitStepTimer(s)||0;
  if(kitCookState.timerTotal!==mins*60){
    kitCookState.timerTotal=mins*60;
    kitCookState.timerRemaining=mins*60;
    kitCookState.timerRunning=false;
    kitCookState.timerStart=null;
    if(kitCookState.tickId){ clearInterval(kitCookState.tickId); kitCookState.tickId=null; }
  }
  // Honour whatever serving scale is set on the detail view (kitState.scaleServings) — same
  // convention kitRenderDetail uses, so a batch cook scaled up before hitting "Start cooking"
  // shows the same scaled amounts here rather than reverting to the recipe's base servings.
  const cur=kitState.scaleServings||r.servings;
  const ingRowHTML=i=>{
    const amt=kitScaledAmount(i.amount,r.servings,cur);
    const right=[amt,i.unit].filter(x=>x!=='' && x!=null).join(' ');
    return '<div class="kit-cook-ing-row"><span>'+kitEsc(i.name)+'</span><span class="kit-cook-ing-amt">'+kitEsc(right)+'</span></div>';
  };
  const allIngs=(r.ingredients||[]).filter(i=>i&&i.name);
  const stepIngs=kitStepIngredients(text, allIngs);
  const allIngHTML=allIngs.map(ingRowHTML).join('');
  const stepIngHTML=stepIngs.length ? stepIngs.map(ingRowHTML).join('')
    : '<div class="kit-cook-ing-empty">No ingredients from the list are named in this step.</div>';
  // Real cards (cardHeader + CARD_ICONS, the shared vocabulary in css/kitchen-extras.css —
  // see the CLAUDE.md note on using it for new cards) rather than a hand-rolled header on a
  // flush hairline-bordered strip. Header stays put; only the row list scrolls, via the inner
  // .kit-cook-ing-rows — that's what keeps a capped-height card from clipping its own title
  // when the ingredient list is long.
  const servingsNote=cur!==r.servings?'<span class="kit-cook-ing-servings">'+cur+' serving'+(cur===1?'':'s')+'</span>':'';
  ov.innerHTML=
    '<div class="kit-cook-topbar">'+
      '<button class="kit-cook-exit" onclick="kitExitCooking()">✕ Exit</button>'+
      '<div class="kit-cook-recipe-name">'+kitEsc(r.emoji||'🍽️')+' '+kitEsc(r.name)+'</div>'+
      '<div></div>'+
    '</div>'+
    '<div class="kit-cook-progress-bar"><div class="kit-cook-progress-fill" style="width:'+pct+'%"></div></div>'+
    '<div class="kit-cook-step-label">Step '+( idx+1)+' of '+total+'</div>'+
    '<div class="kit-cook-content">'+
      // Kept on screen through every step rather than tucked behind a toggle — the point
      // raised was that switching to the ingredients list mid-step (e.g. the detail view)
      // loses your place in the method. Split in two: the full list is a fixed reference,
      // "For this step" re-filters on every kitCookRender() call so it tracks whichever step
      // you're on. Each panel scopes its own scroll so a long list can't push Prev/Next off
      // screen — see kitStepIngredients for how the step text is matched to ingredient names.
      (allIngHTML?'<div class="kit-cook-ing-panel kit-cook-ing-all card">'+
        cardHeader('pot','Ingredients',servingsNote)+
        '<div class="kit-cook-ing-rows">'+allIngHTML+'</div>'+
      '</div>':'')+
      '<div class="kit-cook-body">'+
        '<div class="kit-cook-step-text">'+kitEsc(text)+'</div>'+
        '<div id="kit-cook-timer"></div>'+
      '</div>'+
      (allIngHTML?'<div class="kit-cook-ing-panel kit-cook-ing-step card">'+
        cardHeader('check','For this step')+
        '<div class="kit-cook-ing-rows">'+stepIngHTML+'</div>'+
      '</div>':'')+
    '</div>'+
    '<div class="kit-cook-nav">'+
      '<button class="kit-cook-nav-btn" onclick="kitCookGo(-1)"'+(hasPrev?'':' disabled')+'>← Prev</button>'+
      (hasNext
        ? '<button class="kit-cook-nav-btn primary" onclick="kitCookGo(1)">Next →</button>'
        : '<button class="kit-cook-nav-btn finish" onclick="kitCookFinish()">🎉 Finish Cooking</button>')+
    '</div>';
  kitCookRenderTimer();
}

// toast helper
let kitToastTimer=null;
function kitShowToast(msg){
  const el=document.getElementById('kit-toast'); if(!el) return;
  el.textContent=msg;
  el.style.display='block';
  el.classList.add('visible');
  if(kitToastTimer) clearTimeout(kitToastTimer);
  kitToastTimer=setTimeout(()=>{ el.classList.remove('visible'); setTimeout(()=>{ el.style.display='none'; },300); },2500);
}
function kitRenderFeatured(){
  const wrap=document.getElementById('kitchen-featured'); if(!wrap) return;
  if(!kitRecipes.length){ wrap.innerHTML=''; return; }
  // Featured = most recently cooked, else most recently added
  const byRecent=[...kitRecipes].sort((a,b)=>(b.lastCooked||0)-(a.lastCooked||0)||(b.createdAt||0)-(a.createdAt||0));
  const r=byRecent[0]; if(!r){ wrap.innerHTML=''; return; }
  const label=r.lastCooked?'Last cooked':'Latest recipe';
  const cal=r.calories!=null?'<span class="kitchen-hero-cal">'+r.calories+' cal</span>':'';
  const time=r.cookTime?'<span class="kitchen-hero-time">'+(cal?'· ':'')+r.cookTime+' min</span>':'';
  wrap.innerHTML=
    '<div class="kitchen-hero-card">'+
      '<p class="card-label">'+label+'</p>'+
      '<p class="kitchen-hero-name">'+(r.emoji?r.emoji+' ':'')+kitEsc(r.name)+'</p>'+
      ((cal||time)?'<div style="display:flex;gap:8px;align-items:center;margin-top:8px">'+cal+time+'</div>':'')+
      '<button class="kitchen-hero-btn" onclick="kitOpenDetail(\''+r.id+'\')">View Recipe →</button>'+
    '</div>';
}
function kitRenderList(){
  kitRenderFeatured();
  kitRenderFilterChips();
  kitRenderCatPills();
  kitRenderFilterButton();
  const list=document.getElementById('kit-list'); if(!list) return;
  const items=kitFilteredRecipes();
  // Favourites first, then by name
  items.sort((a,b)=>(b.favourite?1:0)-(a.favourite?1:0)||(a.name||'').localeCompare(b.name||''));
  if(!items.length){
    list.innerHTML='<div class="empty" style="padding:48px 16px"><div style="font-size:40px">🍽️</div><div style="font-size:15px;font-weight:600;margin-top:10px">No recipes found</div><div style="font-size:13px;color:var(--muted);margin-top:4px">Try a different search or add a new recipe.</div></div>';
  } else {
    list.innerHTML=items.map(r=>{
      const sel=r.id===kitState.selectedId?' kit-card-active':'';
      const cal=r.calories!=null?'<span class="kit-cal-badge">'+r.calories+' cal</span>':'';
      const batch=r.batchPrep?'<span class="kit-batch-badge">🍱 Batch</span>':'';
      const cookTime=r.cookTime?'<span class="kit-cal-badge">⏱ '+r.cookTime+'m</span>':'';
      let cookedLabel='';
      if(r.lastCooked){
        const days=Math.floor((Date.now()-r.lastCooked)/86400000);
        cookedLabel='<div class="kit-cooked-ago">'+(days===0?'Cooked today':days===1?'Cooked yesterday':'Cooked '+days+' days ago')+'</div>';
      }
      return '<div class="kit-card kit-c-'+(r.category||'dinner')+sel+'" onclick="kitOpenDetail(\''+r.id+'\')">'+
        '<div class="kit-card-top">'+
          '<div class="kit-cat-tile" aria-hidden="true">'+kitCardEmoji(r)+'</div>'+
          '<div class="kit-card-name">'+kitEsc(r.name)+'</div>'+
          '<div class="kit-card-actions" onclick="event.stopPropagation()">'+
            '<button class="kit-fav'+(r.favourite?' on':'')+'" onclick="kitToggleFav(\''+r.id+'\')" aria-label="Favourite">'+(r.favourite?'⭐':'☆')+'</button>'+
            '<button class="kit-menu-btn" onclick="kitToggleMenu(\''+r.id+'\',event)">⋯</button>'+
          '</div>'+
        '</div>'+
        '<div class="kit-card-meta"><span class="kit-cat-tag kit-cat-'+r.category+'">'+r.category+'</span>'+cal+cookTime+batch+'</div>'+
        (r.description?'<div class="kit-card-desc">'+kitEsc(r.description)+'</div>':'')+
        '<div class="kit-card-serv">🍽️ '+r.servings+' serving'+(r.servings!=1?'s':'')+'</div>'+
        cookedLabel+
        (kitMenuOpenId===r.id?
          '<div class="kit-menu-dropdown" onclick="event.stopPropagation()">'+
            '<button onclick="kitMenuOpenId=null;kitOpenForm(\''+r.id+'\')">✏️ Edit</button>'+
            '<button onclick="kitMenuOpenId=null;kitCopyRecipe(\''+r.id+'\')">🤖 Copy for AI</button>'+
            '<button class="danger" onclick="kitMenuOpenId=null;kitDeleteRecipe(\''+r.id+'\')">🗑️ Delete</button>'+
          '</div>':'')+
      '</div>';
    }).join('');
  }
  // Desktop: keep the persistent detail column in sync
  if(kitUsesSplitPane()){
    const col=document.getElementById('kit-detail-col');
    if(col){
      if(kitState.selectedId && kitRecipes.some(r=>r.id===kitState.selectedId)) kitRenderDetail(kitState.selectedId,col);
      else col.innerHTML='<div class="empty" style="padding-top:80px"><div style="font-size:48px">🍳</div><div style="font-size:16px;font-weight:600;margin-top:12px">Select a recipe</div><div style="font-size:13px;color:var(--muted);margin-top:6px">Pick one from the list to see the full method.</div></div>';
    }
  }
}
let kitMenuOpenId=null;
function kitToggleMenu(id,e){
  if(e) e.stopPropagation();
  kitMenuOpenId=(kitMenuOpenId===id)?null:id;
  kitRenderList();
}
// close menu on outside tap
document.addEventListener('click',()=>{ if(kitMenuOpenId){ kitMenuOpenId=null; kitRenderList(); } });
function kitToggleFav(id){
  const r=kitRecipes.find(x=>x.id===id); if(!r) return;
  r.favourite=!r.favourite;
  kitSaveRecipes();
  kitRenderList();
  if(kitState.selectedId===id) kitRefreshOpenDetail();
}

function kitOpenDetail(id){
  kitState.selectedId=id;
  const r=kitRecipes.find(x=>x.id===id); if(!r) return;
  kitState.scaleServings=r.servings;
  if(kitUsesSplitPane()){
    kitRenderList(); // re-render list (highlight) + detail column
  } else {
    const ov=document.getElementById('kit-detail-overlay');
    kitRenderDetail(id,document.getElementById('kit-detail-overlay-inner'));
    if(ov) ov.style.display='flex';
  }
}
function kitCloseDetail(){
  const ov=document.getElementById('kit-detail-overlay');
  if(ov) ov.style.display='none';
  kitState.selectedId=null;
  if(kitUsesSplitPane()) kitRenderList();
}
function kitRefreshOpenDetail(){
  if(kitUsesSplitPane()){
    const col=document.getElementById('kit-detail-col');
    if(col&&kitState.selectedId) kitRenderDetail(kitState.selectedId,col);
  } else {
    const inner=document.getElementById('kit-detail-overlay-inner');
    if(inner&&kitState.selectedId) kitRenderDetail(kitState.selectedId,inner);
  }
}
function kitScale(delta){
  const r=kitRecipes.find(x=>x.id===kitState.selectedId); if(!r) return;
  const next=(kitState.scaleServings||r.servings)+delta;
  if(next<1) return;
  kitState.scaleServings=next;
  kitRefreshOpenDetail();
}
function kitRenderDetail(id,target){
  if(!target) return;
  const r=kitRecipes.find(x=>x.id===id);
  if(!r){ target.innerHTML=''; return; }
  const cur=kitState.scaleServings||r.servings;
  const ingRows=(r.ingredients||[]).map(i=>{
    const amt=kitScaledAmount(i.amount,r.servings,cur);
    const right=[amt,i.unit].filter(x=>x!=='' && x!=null).join(' ');
    return '<div class="kit-ing-row"><span>'+kitEsc(i.name)+'</span><span class="kit-ing-amt">'+kitEsc(right)+'</span></div>';
  }).join('');
  const stepRows=(r.steps||[]).map((s,i)=>{
    const text=kitStepText(s);
    const timer=kitStepTimer(s);
    return '<div class="kit-step-row"><span class="kit-step-n">'+(i+1)+'</span><div class="kit-step-body"><span>'+kitEsc(text)+'</span>'+(timer?'<span class="kit-step-timer-badge">⏱ '+timer+' min</span>':'')+'</div></div>';
  }).join('');
  const tags=(r.tags||[]).map(t=>'<span class="kit-tag">'+kitEsc(t)+'</span>').join('');
  let macros='';
  if(r.calories!=null||r.protein!=null||r.carbs!=null||r.fat!=null){
    const scl=v=>v==null?'—':Math.round(v*cur/r.servings);
    macros='<div class="kit-macros">'+
      '<div class="kit-macro"><div class="kit-macro-v">'+scl(r.calories)+'</div><div class="kit-macro-l">cal</div></div>'+
      '<div class="kit-macro"><div class="kit-macro-v">'+scl(r.protein)+'</div><div class="kit-macro-l">protein</div></div>'+
      '<div class="kit-macro"><div class="kit-macro-v">'+scl(r.carbs)+'</div><div class="kit-macro-l">carbs</div></div>'+
      '<div class="kit-macro"><div class="kit-macro-v">'+scl(r.fat)+'</div><div class="kit-macro-l">fat</div></div>'+
    '</div>';
  }
  const cookInfo=(r.cookTime?'<span class="kit-cal-badge">⏱ '+r.cookTime+' min</span>':'');
  const backBtn=kitUsesSplitPane()?'':'<button class="back-btn" data-back="kitCloseDetail" aria-label="Back">'+BACK_CHEVRON+'</button>';
  target.innerHTML=
    '<div class="kit-detail-head">'+backBtn+
      '<button class="kit-fav'+(r.favourite?' on':'')+'" onclick="kitToggleFav(\''+r.id+'\')" style="margin-left:auto" aria-label="Favourite">'+(r.favourite?'⭐':'☆')+'</button>'+
    '</div>'+
    (r.emoji?'<div class="kit-detail-emoji">'+r.emoji+'</div>':'')+
    '<div class="kit-detail-name">'+kitEsc(r.name)+'</div>'+
    '<div class="kit-card-meta" style="margin-bottom:14px"><span class="kit-cat-tag kit-cat-'+r.category+'">'+r.category+'</span>'+(r.batchPrep?'<span class="kit-batch-badge">🍱 Batch</span>':'')+cookInfo+tags+'</div>'+
    (r.description?'<div class="kit-card-desc" style="margin-bottom:16px">'+kitEsc(r.description)+'</div>':'')+
    '<button class="kit-start-cooking-btn" onclick="kitStartCooking(\''+r.id+'\')">▶ Start Cooking</button>'+
    '<div class="kit-scaler">'+
      '<button class="kit-scale-btn" onclick="kitScale(-1)" aria-label="Fewer servings">−</button>'+
      '<div class="kit-scale-val"><div class="kit-scale-num">'+cur+'</div><div class="kit-scale-lbl">servings</div></div>'+
      '<button class="kit-scale-btn" onclick="kitScale(1)" aria-label="More servings">+</button>'+
    '</div>'+
    macros+
    '<div class="kit-sec-label">Ingredients</div><div class="kit-ing-list">'+ingRows+'</div>'+
    '<div class="kit-sec-label">Method</div><div class="kit-step-list">'+stepRows+'</div>'+
    '<div class="kit-detail-actions">'+
      '<button class="kit-act kit-act-primary" onclick="kitLogMeal(\''+r.id+'\')">🍴 Log this meal</button>'+
      '<button class="kit-act" onclick="kitOpenForm(\''+r.id+'\')">✏️ Edit</button>'+
      '<button class="kit-act kit-act-danger" onclick="kitDeleteRecipe(\''+r.id+'\')">🗑️ Delete</button>'+
    '</div>';
}
function kitLogMeal(id){
  const r=kitRecipes.find(x=>x.id===id); if(!r) return;
  const cur=kitState.scaleServings||r.servings;
  const kcal=r.calories!=null?Math.round(r.calories*cur/r.servings):0;
  const today=getLocalDate();
  if(S.dailyLog.date!==today){ S.dailyLog={date:today,entries:[]}; }
  S.dailyLog.entries.push({name:r.name,kcal,category:'other'});
  persistDailyLog();
  if(typeof renderCalorieLog==='function') renderCalorieLog();
  // Dismiss the mobile recipe overlay so the calorie overlay isn't hidden behind it
  const dov=document.getElementById('kit-detail-overlay');
  if(dov) dov.style.display='none';
  openCalorieOverlay();
}
function kitDeleteRecipe(id){
  const r=kitRecipes.find(x=>x.id===id); if(!r) return;
  if(!confirm('Delete "'+r.name+'"?')) return;
  kitRecipes=kitRecipes.filter(x=>x.id!==id);
  kitSaveRecipes();
  if(!kitUsesSplitPane()) kitCloseDetail();
  else { kitState.selectedId=null; }
  kitRenderList();
}

// ── Add / edit form ───────────────────────────────────────────────
const KIT_STANDARD_TAGS=[
  {val:'high-protein',label:'High Protein'},
  {val:'low-carb',label:'Low Carb'},
  {val:'quick',label:'Quick'},
  {val:'vegetarian',label:'Vegetarian'},
  {val:'bulk-cook',label:'Bulk Cook'},
];
const KIT_UNITS=['g','kg','ml','L','cup','tbsp','tsp','piece','oz','lb'];
// The tile always shows something, so cards line up whether or not a recipe carries an emoji
// — several seeded ones (Butter Garlic Prawns) have none and previously rendered no glyph at
// all, leaving their titles hanging where every other card had one.
const KIT_CAT_EMOJI={breakfast:'🍳',lunch:'🥪',dinner:'🍽️',dessert:'🍰'};
function kitCardEmoji(r){
  const e=(r&&r.emoji||'').trim();
  return e || KIT_CAT_EMOJI[(r&&r.category)||'dinner'] || '🍽️';
}
// ── Import recipes from Claude ─────────────────────────────────────
// Daily is a static site with no backend, and the Firebase rules only accept writes from the
// signed-in user's own uid, so nothing can push data in from outside. The transfer is
// therefore a paste: Claude emits JSON in the schema below and this validates it.
// Strict on purpose — a bad paste is reported precisely rather than half-imported, since a
// silently mangled recipe is worse than a rejected one.
const KIT_IMPORT_CATS=['breakfast','lunch','dinner','dessert'];
// Returns {recipes:[...]} or {error:'...'} — never throws, never partially applies.
function kitParseImport(text){
  const raw=String(text||'').trim();
  if(!raw) return {error:'Nothing pasted yet.'};
  // Tolerate a ```json fence, since that is how chat tools usually present a code block.
  const unfenced=raw.replace(/^```(?:json)?\s*/i,'').replace(/```$/,'').trim();
  let data;
  try{ data=JSON.parse(unfenced); }
  catch(e){ return {error:"That isn't valid JSON. Copy the whole code block, including the outer { } or [ ]."}; }
  // Accept a single recipe, a bare array, or {recipes:[...]}.
  let list=Array.isArray(data)?data:(data&&Array.isArray(data.recipes)?data.recipes:[data]);
  if(!list.length) return {error:'No recipes found in that JSON.'};
  const out=[];
  for(let i=0;i<list.length;i++){
    const r=list[i], where=list.length>1?(' (recipe '+(i+1)+')'):'';
    if(!r||typeof r!=='object') return {error:'Each recipe must be an object'+where+'.'};
    const name=String(r.name||'').trim();
    if(!name) return {error:'A recipe is missing "name"'+where+'.'};
    if(!Array.isArray(r.ingredients)||!r.ingredients.length) return {error:'"'+name+'" needs a non-empty "ingredients" array.'};
    const ingredients=[];
    for(const ing of r.ingredients){
      if(!ing||typeof ing!=='object') return {error:'"'+name+'": each ingredient must be an object with a "name".'};
      const iname=String(ing.name||'').trim();
      if(!iname) return {error:'"'+name+'": an ingredient is missing "name".'};
      const amt=ing.amount===''||ing.amount==null?'':(isNaN(parseFloat(ing.amount))?String(ing.amount):parseFloat(ing.amount));
      ingredients.push({name:iname, amount:amt, unit:String(ing.unit||'').trim()});
    }
    // Steps may be plain strings or {text,timerMinutes}; the cook mode reads both.
    const steps=(Array.isArray(r.steps)?r.steps:[]).map(s=>{
      if(typeof s==='string') return s;
      if(s&&typeof s==='object'&&s.text) return {text:String(s.text), timerMinutes:(s.timerMinutes==null?null:parseInt(s.timerMinutes)||null)};
      return null;
    }).filter(Boolean);
    const cat=String(r.category||'').toLowerCase();
    const num=v=>{ const n=parseFloat(v); return isNaN(n)?null:n; };
    const tags=Array.isArray(r.tags)?r.tags.map(t=>String(t).trim()).filter(Boolean):[];
    out.push({
      name, emoji:String(r.emoji||'🍽️').trim()||'🍽️',
      category:KIT_IMPORT_CATS.indexOf(cat)>=0?cat:'dinner',
      description:String(r.description||'').trim(),
      servings:Math.max(1,parseInt(r.servings)||2),
      cookTime:num(r.cookTime), ingredients, steps, tags,
      calories:num(r.calories), protein:num(r.protein), carbs:num(r.carbs), fat:num(r.fat),
      batchPrep:tags.includes('batch-prep')||tags.includes('bulk-cook')
    });
  }
  return {recipes:out};
}
// ── Export recipes for AI ──────────────────────────────────────────
// Emits the SAME schema kitParseImport accepts, so the round trip closes: copy a recipe out,
// ask an assistant to change it, paste the result straight back into Import. Anything that
// only produced prose would have to be retyped by hand.
function kitRecipeToExport(r){
  const num=v=>{ const n=parseFloat(v); return isNaN(n)?null:n; };
  return {
    name:r.name||'',
    emoji:r.emoji||'🍽️',
    category:KIT_IMPORT_CATS.indexOf(r.category)>=0?r.category:'dinner',
    servings:Math.max(1,parseInt(r.servings)||1),
    description:r.description||'',
    cookTime:num(r.cookTime),
    ingredients:(r.ingredients||[]).map(i=>({
      name:i.name||'',
      amount:(i.amount===''||i.amount==null)?'':(num(i.amount)!=null?num(i.amount):i.amount),
      unit:i.unit||''
    })),
    // Steps keep whichever shape they were stored in; both import cleanly.
    steps:(r.steps||[]).map(s=>(s&&typeof s==='object'&&s.text)
      ? {text:s.text, timerMinutes:(s.timerMinutes==null?null:parseInt(s.timerMinutes)||null)}
      : String(s)),
    tags:Array.isArray(r.tags)?r.tags.slice():[],
    calories:num(r.calories), protein:num(r.protein), carbs:num(r.carbs), fat:num(r.fat)
  };
}
// The wrapper explains the format to an assistant that has never seen this app, so the pasted
// block is useful on its own rather than needing the separate briefing prompt every time.
function kitBuildExportText(recipes,intro){
  const payload={recipes:recipes.map(kitRecipeToExport)};
  return [
    intro,
    '',
    'Rules for any version you give back:',
    '- Reply with ONE ```json code block in exactly this shape and nothing else inside the fences.',
    '- category must be one of: '+KIT_IMPORT_CATS.join(', ')+'.',
    '- tags must come from: '+KIT_STANDARD_TAGS.map(t=>t.val).join(', ')+'.',
    '- amount is a number and the unit goes in "unit" (one of: '+KIT_UNITS.join(', ')+', or "" for countable things).',
    '- Name ingredients as they would be BOUGHT ("Onion", not "finely diced onion") — my shopping list merges identical names.',
    '- calories/protein/carbs/fat are PER SERVING, numbers only. Use null rather than guessing.',
    '- steps are plain strings, or {"text": "...", "timerMinutes": N} for a timed step.',
    '',
    '```json',
    JSON.stringify(payload,null,2),
    '```'
  ].join('\n');
}
function kitCopyText(text,msg){
  const done=()=>{ if(typeof showToast==='function') showToast(msg); };
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(done).catch(()=>fallbackCopy(text,done));
  } else fallbackCopy(text,done);
}
function kitCopyRecipe(id){
  const r=kitRecipes.find(x=>x.id===id); if(!r) return;
  kitCopyText(kitBuildExportText([r],
    'Here is one recipe from my recipe app. Suggest improvements, adapt it, or scale it as I ask — '+
    'then give it back in the same format so I can import it straight back.'),
    'Recipe copied — paste it into your AI chat');
}
function kitCopyAllRecipes(){
  if(!kitRecipes.length){ if(typeof showToast==='function') showToast('No recipes to copy'); return; }
  kitCopyText(kitBuildExportText(kitRecipes,
    'Here is my whole recipe book ('+kitRecipes.length+' recipes). Use it to understand what I actually cook '+
    'when suggesting meal plans or new recipes. Give anything new back in the same format so I can import it.'),
    kitRecipes.length+' recipes copied');
}
function kitOpenImport(){
  const box=document.getElementById('kit-import-box'); if(!box) return;
  box.innerHTML=
    // Same topbar as the recipe form, so it joins the app's unified back navigation
    // (the delegated [data-back] handler) rather than inventing its own close control.
    '<div class="kit-form-topbar">'+
      '<button class="back-btn" data-back="kitCloseImport" aria-label="Back">'+BACK_CHEVRON+'</button>'+
      '<div class="modal-title">Import recipes</div>'+
      '<div style="width:36px"></div>'+
    '</div>'+
    '<div style="padding:4px 2px 0">'+
      '<p style="font-size:13px;color:var(--muted);line-height:1.5;margin:0 0 10px">'+
        'Paste the JSON your assistant produced. Ask it for recipes “in Daily import format”, '+
        'or give it the format below once and it will remember for that chat.</p>'+
      '<textarea id="kit-import-text" rows="8" placeholder=\'{"recipes":[{"name":"…","ingredients":[…]}]}\' '+
        'style="width:100%;box-sizing:border-box;font-family:ui-monospace,monospace;font-size:12px;line-height:1.45;'+
        'padding:10px;border-radius:10px;border:1px solid var(--border);background:var(--bg);color:var(--text);resize:vertical"></textarea>'+
      '<div id="kit-import-msg" style="font-size:12.5px;font-weight:600;margin-top:8px;min-height:17px"></div>'+
      '<details style="margin-top:6px"><summary style="font-size:12px;color:var(--muted);cursor:pointer">Show the format</summary>'+
        '<pre style="font-size:11px;line-height:1.45;overflow-x:auto;background:var(--bg);border:1px solid var(--border);border-radius:10px;padding:10px;margin-top:8px">'+
_catEscHtml(KIT_IMPORT_EXAMPLE)+'</pre></details>'+
      // Export lives beside import: the two halves of the same round trip.
      '<button class="modal-btn secondary" style="width:100%;margin-top:12px" onclick="kitCopyAllRecipes()">🤖 Copy my whole recipe book for AI</button>'+
      '<div style="display:flex;gap:10px;margin-top:14px">'+
        '<button class="modal-btn secondary" onclick="kitCloseImport()">Cancel</button>'+
        '<button class="modal-btn primary" onclick="kitDoImport()">Import</button>'+
      '</div>'+
    '</div>';
  document.getElementById('kit-import-overlay').classList.remove('hidden');
}
function kitCloseImport(){ const o=document.getElementById('kit-import-overlay'); if(o) o.classList.add('hidden'); }
const KIT_IMPORT_EXAMPLE=
'{\n  "recipes": [\n    {\n      "name": "Lemon Garlic Chicken",\n      "emoji": "🍗",\n      "category": "dinner",\n      "servings": 2,\n      "description": "One-pan roast chicken thighs.",\n      "cookTime": 35,\n      "ingredients": [\n        { "name": "Chicken thighs", "amount": 4, "unit": "" },\n        { "name": "Lemon", "amount": 1, "unit": "" },\n        { "name": "Olive oil", "amount": 2, "unit": "tbsp" }\n      ],\n      "steps": [\n        "Heat oven to 200C.",\n        { "text": "Roast until cooked through.", "timerMinutes": 30 }\n      ],\n      "tags": ["quick"],\n      "calories": 520, "protein": 42, "carbs": 6, "fat": 34\n    }\n  ]\n}';
function kitDoImport(){
  const msg=document.getElementById('kit-import-msg');
  const res=kitParseImport(document.getElementById('kit-import-text')?.value);
  if(res.error){ if(msg){ msg.textContent=res.error; msg.style.color='var(--danger)'; } return; }
  // Same shape kitSaveForm builds, so imported recipes are ordinary recipes from here on.
  res.recipes.forEach(d=>kitRecipes.push(Object.assign({id:kitUUID(),favourite:false,lastCooked:null,createdAt:Date.now()},d)));
  kitSaveRecipes();
  kitCloseImport();
  kitSetTab('recipes');
  showToast('Imported '+res.recipes.length+' recipe'+(res.recipes.length>1?'s':''));
}
function kitOpenForm(id){
  const editing=id?kitRecipes.find(x=>x.id===id):null;
  const r=editing||{name:'',emoji:'🍽️',category:'dinner',description:'',servings:2,cookTime:null,
    ingredients:[{name:'',amount:'',unit:'g'}],steps:[{text:'',timerMinutes:null}],
    tags:[],calories:null,protein:null,carbs:null,fat:null};
  const box=document.getElementById('kit-form-box'); if(!box) return;
  const catOpts=['breakfast','lunch','dinner','dessert'].map(c=>'<option value="'+c+'"'+(r.category===c?' selected':'')+'>'+c.charAt(0).toUpperCase()+c.slice(1)+'</option>').join('');
  const tagChips=KIT_STANDARD_TAGS.map(t=>{
    const on=(r.tags||[]).includes(t.val)||(t.val==='bulk-cook'&&r.batchPrep);
    return '<button type="button" class="kit-tag-chip'+(on?' active':'')+'" data-tag="'+t.val+'" onclick="this.classList.toggle(\'active\')">'+t.label+'</button>';
  }).join('');
  box.innerHTML=
    '<div class="kit-form-topbar">'+
      '<button class="back-btn" data-back="kitCloseForm" aria-label="Back">'+BACK_CHEVRON+'</button>'+
      '<div class="modal-title">'+(editing?'Edit Recipe':'New Recipe')+'</div>'+
      '<div style="width:36px"></div>'+
    '</div>'+
    '<input type="hidden" id="kit-f-id" value="'+(editing?editing.id:'')+'">'+
    '<div class="kit-f-emoji-row">'+
      '<input id="kit-f-emoji" class="kit-f-emoji-input" type="text" value="'+(r.emoji||'🍽️')+'" maxlength="4" placeholder="🍽️">'+
      '<input id="kit-f-name" class="kit-f-name-input" type="text" value="'+kitEsc(r.name||'')+'" placeholder="Recipe name" autocomplete="off">'+
    '</div>'+
    '<div class="settings-2col">'+
      '<div class="settings-field"><label>Category</label><select id="kit-f-cat">'+catOpts+'</select></div>'+
      '<div class="settings-field"><label>Servings</label><input id="kit-f-serv" type="number" min="1" inputmode="numeric" value="'+(r.servings||2)+'"></div>'+
    '</div>'+
    '<div class="settings-field"><label>Cook time (min)</label><input id="kit-f-time" type="number" min="0" inputmode="numeric" value="'+(r.cookTime||'')+'" placeholder="e.g. 25"></div>'+
    '<div class="settings-field"><label>Description</label><input id="kit-f-desc" type="text" value="'+kitEsc(r.description||'')+'" placeholder="Short description"></div>'+
    '<div class="settings-field"><label>Macros (per recipe)</label><div class="kit-macro-grid">'+
      '<input id="kit-f-cal" type="number" inputmode="numeric" placeholder="cal" value="'+(r.calories??'')+'">'+
      '<input id="kit-f-pro" type="number" inputmode="numeric" placeholder="protein" value="'+(r.protein??'')+'">'+
      '<input id="kit-f-carb" type="number" inputmode="numeric" placeholder="carbs" value="'+(r.carbs??'')+'">'+
      '<input id="kit-f-fat" type="number" inputmode="numeric" placeholder="fat" value="'+(r.fat??'')+'">'+
    '</div></div>'+
    '<div class="settings-field"><label>Ingredients</label><div id="kit-f-ings"></div>'+
      '<button class="kit-add-row" onclick="kitFormAddIng()">+ Add ingredient</button></div>'+
    '<div class="settings-field"><label>Steps <span style="font-size:11px;font-weight:400;color:var(--muted)">(add a timer if the step needs one)</span></label>'+
      '<div id="kit-f-steps"></div>'+
      '<button class="kit-add-row" onclick="kitFormAddStep()">+ Add step</button></div>'+
    '<div class="settings-field"><label>Tags</label><div class="kit-tag-chips-wrap" id="kit-f-tag-chips">'+tagChips+'</div></div>'+
    '<button class="kit-f-save-btn" onclick="kitSaveForm()">Save Recipe</button>'+
    '<div style="height:24px"></div>';
  document.getElementById('kit-f-ings').innerHTML='';
  (r.ingredients&&r.ingredients.length?r.ingredients:[{name:'',amount:'',unit:'g'}]).forEach(i=>kitFormAddIng(i));
  document.getElementById('kit-f-steps').innerHTML='';
  (r.steps&&r.steps.length?r.steps:[{text:'',timerMinutes:null}]).forEach(s=>kitFormAddStep(s));
  const ov=document.getElementById('kit-form-overlay');
  ov.classList.remove('hidden');
  // full-screen on mobile
  if(window.innerWidth<1024){
    // Fixed top padding — opaque status bar reserves its height; no env(safe-area-inset-top)
    // double-count (see #app-header). Bottom inset kept.
    ov.style.cssText='position:fixed;inset:0;background:var(--bg);z-index:180;display:flex;flex-direction:column;overflow-y:auto;padding:16px 0 env(safe-area-inset-bottom,24px);align-items:stretch;justify-content:flex-start';
    const mb=document.getElementById('kit-form-box');
    if(mb) mb.style.cssText='width:100%;max-width:none;border-radius:0;box-shadow:none;max-height:none;margin:0;flex:1';
  } else {
    ov.style.cssText='';
    const mb=document.getElementById('kit-form-box');
    if(mb) mb.style.cssText='';
  }
}
function kitFormAddIng(data){
  const wrap=document.getElementById('kit-f-ings'); if(!wrap) return;
  const d=(data&&typeof data==='object')?data:{name:'',amount:'',unit:'g'};
  // '' is a real, deliberate unit (see kitParseImport/KIT_IMPORT_CATS) — it means "countable",
  // e.g. "4 salmon fillets". Recipes can also carry a unit KIT_UNITS never listed (kg, L — both
  // appear in the preloaded recipes). Either way, without a matching <option> no choice is
  // actually selected and the browser defaults to whichever renders first — so editing the
  // recipe and saving without touching that dropdown silently rewrote the ingredient's real
  // unit to whatever that first option happened to be. Always include the ingredient's own
  // current unit as an option, even if it isn't one KIT_UNITS knows about, so nothing already
  // saved can be swapped out from under it just by opening the editor.
  const unitVal=(d.unit===undefined||d.unit===null)?'g':d.unit;
  const knownUnits=unitVal!==''&&KIT_UNITS.indexOf(unitVal)<0 ? [unitVal,...KIT_UNITS] : KIT_UNITS;
  const unitSel='<option value=""'+(unitVal===''?' selected':'')+'>Count / pieces</option>'+
    knownUnits.map(u=>'<option value="'+u+'"'+(unitVal===u?' selected':'')+'>'+u+'</option>').join('');
  const row=document.createElement('div');
  row.className='kit-f-ing-row';
  row.innerHTML=
    '<input class="kit-fi-amt" type="text" inputmode="decimal" placeholder="Qty" value="'+kitEsc(String(d.amount||''))+'">'+
    '<select class="kit-fi-unit-sel">'+unitSel+'</select>'+
    '<input class="kit-fi-name" type="text" placeholder="Ingredient" value="'+kitEsc(d.name||'')+'">'+
    '<button class="kit-f-del" onclick="this.parentElement.remove()" aria-label="Remove">✕</button>';
  wrap.appendChild(row);
}
function kitFormAddStep(data){
  const wrap=document.getElementById('kit-f-steps'); if(!wrap) return;
  const text=kitStepText(data);
  const timer=kitStepTimer(data);
  const row=document.createElement('div');
  row.className='kit-f-step-row';
  row.innerHTML=
    '<textarea class="kit-fs-text" rows="2" placeholder="Describe this step">'+kitEsc(text)+'</textarea>'+
    '<input class="kit-fs-timer" type="number" inputmode="numeric" min="0" placeholder="⏱ min" value="'+(timer||'')+'" title="Timer (minutes)">'+
    '<button class="kit-f-del" onclick="this.parentElement.remove()" aria-label="Remove">✕</button>';
  wrap.appendChild(row);
}
function kitCloseForm(){
  const ov=document.getElementById('kit-form-overlay');
  if(ov){ ov.classList.add('hidden'); ov.style.cssText=''; }
  const mb=document.getElementById('kit-form-box');
  if(mb) mb.style.cssText='';
}
function kitSaveForm(){
  const num=v=>{ const n=parseFloat(v); return isNaN(n)?null:n; };
  const name=(document.getElementById('kit-f-name')?.value||'').trim();
  if(!name){ alert('Please enter a recipe name.'); return; }
  const ings=[...document.querySelectorAll('#kit-f-ings .kit-f-ing-row')].map(row=>({
    name:(row.querySelector('.kit-fi-name')?.value||'').trim(),
    amount:(()=>{ const v=(row.querySelector('.kit-fi-amt')?.value||'').trim(); const n=parseFloat(v); return (v!==''&&!isNaN(n))?n:v; })(),
    unit:(row.querySelector('.kit-fi-unit-sel')?.value||row.querySelector('.kit-fi-unit')?.value||'').trim(),
  })).filter(i=>i.name);
  const steps=[...document.querySelectorAll('#kit-f-steps .kit-f-step-row')].map(row=>{
    const t=(row.querySelector('.kit-fs-text')?.value||'').trim();
    const m=parseInt(row.querySelector('.kit-fs-timer')?.value||'');
    return {text:t,timerMinutes:(!isNaN(m)&&m>0)?m:null};
  }).filter(s=>s.text);
  const tags=[...document.querySelectorAll('#kit-f-tag-chips .kit-tag-chip.active')].map(b=>b.dataset.tag);
  const id=document.getElementById('kit-f-id')?.value||'';
  const data={
    name,
    emoji:(document.getElementById('kit-f-emoji')?.value||'🍽️').trim()||'🍽️',
    category:document.getElementById('kit-f-cat')?.value||'dinner',
    description:(document.getElementById('kit-f-desc')?.value||'').trim(),
    servings:Math.max(1,parseInt(document.getElementById('kit-f-serv')?.value)||1),
    cookTime:num(document.getElementById('kit-f-time')?.value),
    ingredients:ings,
    steps,
    tags,
    calories:num(document.getElementById('kit-f-cal')?.value),
    protein:num(document.getElementById('kit-f-pro')?.value),
    carbs:num(document.getElementById('kit-f-carb')?.value),
    fat:num(document.getElementById('kit-f-fat')?.value),
    batchPrep:tags.includes('batch-prep')||tags.includes('bulk-cook'),
  };
  if(id){
    const r=kitRecipes.find(x=>x.id===id);
    if(r) Object.assign(r,data);
  } else {
    kitRecipes.push(Object.assign({id:kitUUID(),favourite:false,lastCooked:null,createdAt:Date.now()},data));
    kitState.selectedId=null;
  }
  kitSaveRecipes();
  kitCloseForm();
  kitRenderList();
  if(id&&kitState.selectedId===id) kitRefreshOpenDetail();
}

// ══ KITCHEN: Shopping List ════════════════════════════════════════
function kitGetIngredientCategory(name){
  const n=name.toLowerCase();
  if(/prawn|beef|chicken|lamb|steak|mince|patty|patties|pork|fish|tuna|salmon|egg/.test(n)) return 'Protein';
  if(/milk|cheese|butter|yoghurt|cream|feta/.test(n)) return 'Dairy';
  if(/lettuce|rocket|spinach|tomato|carrot|potato|onion|lemon|lime|berry|berries|apple|banana|capsicum|zucchini|mushroom|spring onion|basil|coriander leaf/.test(n)) return 'Produce';
  if(/bread|bun|noodle|rice|flour|pasta|oat|cereal|cracker|wrap|tortilla/.test(n)) return 'Bakery & Grains';
  return 'Other';
}
const KITSHOP_CAT_ORDER=['Produce','Protein','Dairy','Bakery & Grains','Other'];

function kitShopLoadSelected(){ return lsLoad('kitchen_shopping_selected', [], Array.isArray); }
function kitShopSaveSelected(){ lsSave('kitchen_shopping_selected', kitShopSelected, 'kitShopSelected'); }
function kitShopLoadChecked(){ return lsLoad('kitchen_shopping_checked', {}); }
function kitShopSaveChecked(){ lsSave('kitchen_shopping_checked', kitShopChecked, 'kitShopChecked'); }
function kitShopLoadManual(){ return lsLoad('kitchen_shopping_manual', [], Array.isArray); }
function kitShopSaveManual(){ lsSave('kitchen_shopping_manual', kitShopManual, 'kitShopManual'); }
let kitShopSelected = kitShopLoadSelected();
let kitShopChecked  = kitShopLoadChecked();
let kitShopManual   = kitShopLoadManual();
// If a list was already built (selections exist), reopen on the list view
let kitShopView = kitShopSelected.length ? 'list' : 'selector';

function kitShopRender(){
  const sel=document.getElementById('kitshop-selector');
  const list=document.getElementById('kitshop-list');
  if(!sel||!list) return;
  const onList=kitShopView==='list' && kitShopSelected.length>0;
  sel.classList.toggle('hidden',onList);
  list.classList.toggle('hidden',!onList);
  if(onList) kitShopRenderList(); else kitShopRenderSelector();
}

// ── State 1: recipe selector ──
function kitShopSelEntry(id){ return kitShopSelected.find(s=>s.recipeId===id); }
function kitShopToggleRecipe(id){
  const r=kitRecipes.find(x=>x.id===id); if(!r) return;
  const i=kitShopSelected.findIndex(s=>s.recipeId===id);
  if(i>=0) kitShopSelected.splice(i,1);
  else kitShopSelected.push({recipeId:id,servings:r.servings});
  kitShopSaveSelected();
  kitShopRenderSelector();
}
function kitShopAdjustServings(id,delta){
  const e=kitShopSelEntry(id); if(!e) return;
  const next=e.servings+delta;
  if(next<1) return;
  e.servings=next;
  kitShopSaveSelected();
  kitShopRenderSelector();
}
function kitShopRenderSelector(){
  const wrap=document.getElementById('kitshop-selector'); if(!wrap) return;
  const location=(typeof kitPantryLocationControlHTML==='function')?kitPantryLocationControlHTML('shopping',false):'';
  if(!kitRecipes.length){
    wrap.innerHTML=location+'<div class="empty" style="padding-top:64px"><div style="font-size:48px">🛒</div><div style="font-size:16px;font-weight:600;margin-top:12px">No recipes yet</div><div style="font-size:13px;color:var(--muted);margin-top:6px">Add recipes first, then build a list.</div></div>';
    return;
  }
  const recs=[...kitRecipes].sort((a,b)=>(a.name||'').localeCompare(b.name||''));
  let html=location+'<div class="kitshop-heading">What are you cooking this week?</div>';
  html+='<div class="kitshop-sel-list">';
  recs.forEach(r=>{
    const e=kitShopSelEntry(r.id);
    const on=!!e;
    const servings=e?e.servings:r.servings;
    html+='<div class="kitshop-sel-card'+(on?' selected':'')+'" onclick="kitShopToggleRecipe(\''+r.id+'\')">'+
      '<div class="kitshop-sel-check">'+(on?'✓':'')+'</div>'+
      '<div class="kitshop-sel-body">'+
        '<div class="kitshop-sel-name">'+kitEsc(r.name)+'</div>'+
        '<div class="kit-card-meta"><span class="kit-cat-tag kit-cat-'+r.category+'">'+r.category+'</span></div>'+
      '</div>'+
      (on?
        '<div class="kitshop-serv" onclick="event.stopPropagation()">'+
          '<button class="kitshop-serv-btn" onclick="kitShopAdjustServings(\''+r.id+'\',-1)" aria-label="Fewer">−</button>'+
          '<div class="kitshop-serv-num">'+servings+'</div>'+
          '<button class="kitshop-serv-btn" onclick="kitShopAdjustServings(\''+r.id+'\',1)" aria-label="More">+</button>'+
        '</div>'
        :'<div class="kitshop-serv-hint">'+r.servings+' serv</div>')+
    '</div>';
  });
  html+='</div>';
  const n=kitShopSelected.length;
  html+='<button class="kitshop-build-btn" onclick="kitShopBuild()"'+(n?'':' disabled')+'>Build shopping list →</button>';
  wrap.innerHTML=html;
}
function kitShopBuild(){
  if(!kitShopSelected.length) return;
  kitShopView='list';
  kitShopRender();
}

// ── Quantity combining ──
function kitShopNorm(name){ return (name||'').toLowerCase().trim(); }
function kitShopItemKey(name,unit){ return kitShopNorm(name)+'-'+(unit||'').toLowerCase().trim(); }
const KITSHOP_CHECKED_SCHEMA=2;
function kitShopNormaliseChecked(raw){
  const activeId=(typeof kitPantryActiveId==='function')?kitPantryActiveId():'pantry_home';
  const legacyId=(typeof kitPantryGet==='function'&&kitPantryGet('pantry_home'))?'pantry_home':activeId;
  let out;
  if(raw&&raw.schemaVersion===KITSHOP_CHECKED_SCHEMA&&raw.pantries&&typeof raw.pantries==='object'){
    out={schemaVersion:KITSHOP_CHECKED_SCHEMA,pantries:{}};
    Object.keys(raw.pantries).forEach(pid=>{
      const src=raw.pantries[pid]; if(!src||typeof src!=='object') return;
      const rows={}; Object.keys(src).forEach(k=>{ if(src[k]) rows[k]=true; });
      out.pantries[pid]=rows;
    });
  } else {
    const rows={};
    if(raw&&typeof raw==='object') Object.keys(raw).forEach(k=>{ if(raw[k]) rows[k]=true; });
    out={schemaVersion:KITSHOP_CHECKED_SCHEMA,pantries:{}};
    out.pantries[legacyId]=rows;
  }
  if(!out.pantries[activeId]) out.pantries[activeId]={};
  if(JSON.stringify(raw||{})!==JSON.stringify(out)){
    lsSave('kitchen_shopping_checked',out,_bootPhase?null:'kitShopChecked');
  }
  return out;
}
function kitShopCheckedMap(pantryId){
  const pid=pantryId||((typeof kitPantryActiveId==='function')?kitPantryActiveId():'pantry_home');
  if(!kitShopChecked||kitShopChecked.schemaVersion!==KITSHOP_CHECKED_SCHEMA){
    kitShopChecked=kitShopNormaliseChecked(kitShopChecked);
  }
  return (kitShopChecked.pantries&&kitShopChecked.pantries[pid])||{};
}
function kitShopRowChecked(it,pantryId){
  const rows=kitShopCheckedMap(pantryId);
  return !!(rows[it.key]||(it.legacyKey&&rows[it.legacyKey]));
}
function kitShopRemoveCheckedKeyEverywhere(key){
  if(!kitShopChecked||!kitShopChecked.pantries) return;
  Object.keys(kitShopChecked.pantries).forEach(pid=>{ delete kitShopChecked.pantries[pid][key]; });
}
function kitShopComputeRecipeItems(){
  const map={};
  kitShopSelected.forEach(sel=>{
    const r=kitRecipes.find(x=>x.id===sel.recipeId); if(!r) return;
    const factor=(sel.servings||r.servings)/(r.servings||1);
    (r.ingredients||[]).forEach(ing=>{
      const nm=ing.name||'';
      if(!nm) return;
      const unit=(ing.unit||'').trim();
      const key=kitShopItemKey(nm,unit);
      const n=parseFloat(ing.amount);
      if(!map[key]){
        map[key]={name:nm,unit,amount:isNaN(n)?null:0,hasNumeric:!isNaN(n),category:kitGetIngredientCategory(nm)};
      }
      if(!isNaN(n)){
        map[key].amount=(map[key].amount||0)+n*factor;
        map[key].hasNumeric=true;
      }
    });
  });
  return map;
}
function kitShopAddRequirement(target,it){
  if(!target.requirements) target.requirements=[];
  target.requirements.push({name:it.name,unit:it.unit,amount:it.amount,hasNumeric:it.hasNumeric});
}
function kitShopComputePlan(pantryId){
  const pantry=(typeof kitPantryGet==='function')?kitPantryGet(pantryId):null;
  const pid=pantry?pantry.id:(pantryId||'pantry_home');
  const pantryName=pantry?pantry.name:'Home';
  const index=(typeof kitPantryIngredientIndex==='function')?kitPantryIngredientIndex(pid):null;
  const recipe=kitShopComputeRecipeItems();
  const normal={}, needMap={}, stockedMap={};
  Object.keys(recipe).forEach(key=>{
    const it=Object.assign({key,source:'recipe'},recipe[key]);
    const match=(typeof kitPantryMatchIngredient==='function')?kitPantryMatchIngredient(it.name,index):null;
    if(!match){ normal[key]=it; return; }
    const status=kitPantryStatusOf(match);
    const targetMap=status==='in'?stockedMap:needMap;
    let target=targetMap[match.id];
    if(!target){
      target=targetMap[match.id]={key:'pantry:'+pid+':'+match.id,source:status==='in'?'stocked':'pantry',
        pantryId:pid,pantryName,itemId:match.id,name:match.name,category:'Pantry needs',status,
        inStock:match.inStock!==false,runningLow:!!match.runningLow,requirements:[]};
    }
    kitShopAddRequirement(target,it);
  });
  if(typeof kitPantryNeeds==='function') kitPantryNeeds(pid).forEach(it=>{
    if(needMap[it.id]) return;
    needMap[it.id]={key:'pantry:'+pid+':'+it.id,source:'pantry',pantryId:pid,pantryName,
      itemId:it.id,name:it.name,category:'Pantry needs',status:it.status,
      inStock:it.inStock!==false,runningLow:!!it.runningLow,requirements:[]};
  });
  // Manual rows are deliberate user entries. Their source-specific key keeps them visible
  // even when a recipe or pantry item has the same name.
  kitShopManual.forEach(m=>{
    const key='manual:'+m.id;
    normal[key]={key,name:m.name,unit:'',amount:null,hasNumeric:false,category:m.category||'Other',
      source:'manual',manual:true,manualId:m.id,legacyKey:kitShopItemKey(m.name,'')};
  });
  const pantryNeeds=Object.keys(needMap).map(k=>needMap[k]).sort((a,b)=>a.name.localeCompare(b.name));
  const stocked=Object.keys(stockedMap).map(k=>stockedMap[k]).sort((a,b)=>a.name.localeCompare(b.name));
  const buy={};
  Object.keys(normal).forEach(k=>{ buy[k]=normal[k]; });
  pantryNeeds.forEach(it=>{ buy[it.key]=it; });
  return {pantryId:pid,pantryName,normal,pantryNeeds,stocked,buy};
}
function kitShopComputeItems(pantryId){ return kitShopComputePlan(pantryId).buy; }
function kitShopCountLeft(plan,pantryId){
  const p=plan||kitShopComputePlan(pantryId);
  let n=p.pantryNeeds.length;
  Object.keys(p.normal).forEach(k=>{ if(!kitShopRowChecked(p.normal[k],p.pantryId)) n++; });
  return n;
}
function kitShopRequirementText(reqs){
  return (reqs||[]).map(r=>{
    if(r.hasNumeric&&r.amount!=null) return kitTrim(r.amount)+(r.unit?' '+r.unit:'');
    return r.unit||'';
  }).filter(Boolean).join(' · ');
}
function kitShopRenderList(){
  const wrap=document.getElementById('kitshop-list'); if(!wrap) return;
  const plan=kitShopComputePlan();
  const keys=Object.keys(plan.normal);
  // group by category
  const groups={};
  keys.forEach(k=>{ const it=plan.normal[k]; (groups[it.category]=groups[it.category]||[]).push(it); });
  const totalItems=keys.length+plan.pantryNeeds.length;
  const left=kitShopCountLeft(plan);
  let html=(typeof kitPantryLocationControlHTML==='function')?kitPantryLocationControlHTML('shopping',false):'';
  html+='<div class="kitshop-list-head">'+
    '<button class="back-btn" data-back="kitShopBackToSelector" aria-label="Back">'+BACK_CHEVRON+'</button>'+
    '<div class="kitshop-list-title">Shopping list<span class="kitshop-count">'+left+'</span></div>'+
    '<button class="kitshop-clear-checked" onclick="kitShopClearChecked(decodeURIComponent(\''+kitPantryArg(plan.pantryId)+'\'))">Clear checked</button>'+
  '</div>';
  if(!totalItems){
    if(plan.stocked.length){
      html+='<div class="kitshop-empty"><div style="font-size:40px">✅</div><div class="kitshop-empty-t">Everything needed is already in '+kitEsc(plan.pantryName)+'</div><div class="kitshop-empty-d">Expand the stocked section below to review what Daily set aside.</div></div>';
    } else {
      html+='<div class="kitshop-empty"><div style="font-size:40px">✅</div><div class="kitshop-empty-t">Nothing to buy</div><div class="kitshop-empty-d">Choose recipes or add an item below when you are ready.</div></div>';
    }
  }
  if(plan.pantryNeeds.length){
    html+='<div class="kitshop-cat-head kitshop-pantry-head">🥫 Pantry needs</div>';
    plan.pantryNeeds.forEach(it=>{
      const qty=kitShopRequirementText(it.requirements);
      html+='<label class="kitshop-item">'+
        '<input type="checkbox" class="kitshop-cb" onchange="kitPantryRestock(decodeURIComponent(\''+kitPantryArg(it.pantryId)+'\'),decodeURIComponent(\''+kitPantryArg(it.itemId)+'\'))">'+
        '<span class="kitshop-item-name">'+kitEsc(it.name)+'</span>'+
        (qty?'<span class="kitshop-item-qty">'+kitEsc(qty)+'</span>':'')+
        '<span class="kitshop-need-tag '+(it.status==='low'?'low':'out')+'">'+(it.status==='low'?'⚠ Low':'Out')+'</span>'+
      '</label>';
    });
  }
  KITSHOP_CAT_ORDER.forEach(cat=>{
    const items=groups[cat]; if(!items||!items.length) return;
    items.sort((a,b)=>a.name.localeCompare(b.name));
    html+='<div class="kitshop-cat-head">'+cat+'</div>';
    items.forEach(it=>{
      const checked=kitShopRowChecked(it,plan.pantryId);
      let qty='';
      if(it.hasNumeric&&it.amount!=null){ qty=kitTrim(it.amount)+(it.unit?' '+it.unit:''); }
      else if(it.unit){ qty=it.unit; }
      html+='<label class="kitshop-item'+(checked?' checked':'')+'">'+
        '<input type="checkbox" class="kitshop-cb"'+(checked?' checked':'')+' onchange="kitShopToggleCheck(decodeURIComponent(\''+kitPantryArg(it.key)+'\'),this.checked,decodeURIComponent(\''+kitPantryArg(plan.pantryId)+'\'))">'+
        '<span class="kitshop-item-name">'+kitEsc(it.name)+'</span>'+
        (qty?'<span class="kitshop-item-qty">'+kitEsc(qty)+'</span>':'')+
        (it.manual?'<button class="kitshop-item-del" onclick="event.preventDefault();kitShopDeleteManual(\''+it.manualId+'\')" aria-label="Remove">✕</button>':'')+
      '</label>';
    });
  });
  if(plan.stocked.length){
    const ui=(typeof kitPantryUI==='function')?kitPantryUI():{};
    const open=!!(ui.stockedOpen&&ui.stockedOpen[plan.pantryId]);
    html+='<section class="kitshop-stocked'+(open?' open':'')+'">'+
      '<button type="button" class="kitshop-stocked-toggle" aria-expanded="'+(open?'true':'false')+'" onclick="kitPantryToggleStockedSection(decodeURIComponent(\''+kitPantryArg(plan.pantryId)+'\'))">'+
        '<span class="kitshop-stocked-chev" aria-hidden="true">›</span>'+
        '<span>Already in '+kitEsc(plan.pantryName)+'</span><span class="kitshop-stocked-count">'+plan.stocked.length+'</span>'+
      '</button>'+
      (open?'<div class="kitshop-stocked-rows">'+plan.stocked.map(it=>{
        const qty=kitShopRequirementText(it.requirements);
        return '<div class="kitshop-item kitshop-stocked-item"><span class="kitshop-stocked-mark" aria-hidden="true">✓</span>'+
          '<span class="kitshop-item-name">'+kitEsc(it.name)+'</span>'+
          (qty?'<span class="kitshop-item-qty">'+kitEsc(qty)+'</span>':'')+
          '<span class="kitshop-stocked-tag">In stock</span></div>';
      }).join('')+'</div>':'')+
    '</section>';
  }
  html+='<button class="kitshop-clear-all" onclick="kitShopClearAll()">Clear all & start over</button>';
  wrap.innerHTML=html;
  // Manual-add bar (fixed) lives outside the scroll list
  kitShopRenderAddBar(true);
}
function kitShopRenderAddBar(show){
  let bar=document.getElementById('kitshop-addbar');
  if(!show){ if(bar) bar.remove(); return; }
  if(!bar){
    bar=document.createElement('div');
    bar.id='kitshop-addbar';
    bar.className='kitshop-addbar';
    bar.innerHTML='<input id="kitshop-add-input" type="text" placeholder="Add an item…" onkeydown="if(event.key===\'Enter\')kitShopAddManual()"><button onclick="kitShopAddManual()">Add</button>';
    document.body.appendChild(bar);
  }
  bar.style.display='flex';
}
function kitShopBackToSelector(){
  kitShopView='selector';
  kitShopRenderAddBar(false);
  kitShopRender();
}
function kitShopToggleCheck(key,checked,pantryId){
  const pid=pantryId||kitPantryActiveId();
  if(!kitShopChecked.pantries[pid]) kitShopChecked.pantries[pid]={};
  if(checked) kitShopChecked.pantries[pid][key]=true; else delete kitShopChecked.pantries[pid][key];
  kitShopSaveChecked();
  kitShopRenderList();
}
function kitShopClearChecked(pantryId){
  const pid=pantryId||kitPantryActiveId();
  kitShopChecked.pantries[pid]={};
  kitShopSaveChecked();
  kitShopRenderList();
}
function kitShopAddManual(){
  const inp=document.getElementById('kitshop-add-input'); if(!inp) return;
  const name=inp.value.trim(); if(!name) return;
  kitShopManual.push({id:kitUUID(),name,category:'Other'});
  kitShopSaveManual();
  inp.value='';
  kitShopRenderList();
}
function kitShopDeleteManual(id){
  const m=kitShopManual.find(x=>x.id===id);
  kitShopManual=kitShopManual.filter(x=>x.id!==id);
  if(m){
    kitShopRemoveCheckedKeyEverywhere('manual:'+m.id);
    kitShopRemoveCheckedKeyEverywhere(kitShopItemKey(m.name,''));
  }
  kitShopSaveManual(); kitShopSaveChecked();
  kitShopRenderList();
}
function kitShopClearAll(){
  if(!confirm('Clear the whole list and start over?')) return;
  kitShopSelected=[]; kitShopChecked={schemaVersion:KITSHOP_CHECKED_SCHEMA,pantries:{}}; kitShopManual=[];
  kitShopChecked.pantries[kitPantryActiveId()]={};
  kitShopSaveSelected(); kitShopSaveChecked(); kitShopSaveManual();
  kitShopView='selector';
  kitShopRenderAddBar(false);
  kitShopRender();
}

// ══ KITCHEN: Spice & Pantry Tracker ═══════════════════════════════
const KITPANTRY_CATS=[
  ['spices','Spices',['Smoked paprika','Paprika (ground)','Coriander (ground)','Cumin (ground)','Chilli flakes','Garam masala','Garlic powder','Garlic salt','Onion powder','Allspice (ground)','Roast chicken seasoning','Cayenne pepper','Ginger powder']],
  ['herbs','Dried Herbs',['Parsley (dried)','Rosemary leaves','Oregano leaves','Italian herbs','Bay leaves','Cloves (whole)']],
  ['dry','Dry Goods',['Salt','Black pepper','Curry powder','Cinnamon','Sugar','Brown sugar','Plain flour','Vanilla extract']],
  ['oils','Oils & Fats',['Extra virgin olive oil','Canola oil','Salted butter','Sesame oil']],
  ['sauces','Sauces & Condiments',['Soy sauce','Worcestershire sauce','Balsamic vinegar','White vinegar','BBQ sauce','Teriyaki sauce','Mayonnaise','Chipotle in adobo','Tomato ketchup','Dijon mustard']],
];
function kitPantryId(name){ return name.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,''); }
function kitPantryArg(value){ return encodeURIComponent(String(value)).replace(/'/g,'%27'); }
const KITPANTRY_SEED_META={};
KITPANTRY_CATS.forEach(([cat,,items])=>items.forEach(nm=>{ KITPANTRY_SEED_META[kitPantryId(nm)]={name:nm,cat}; }));
const KITPANTRY_SCHEMA_VERSION=2;
const KITPANTRY_HOME_ID='pantry_home';
const KITPANTRY_CAT_KEYS=new Set(KITPANTRY_CATS.map(c=>c[0]));
function kitPantryHumanName(id){
  const s=String(id||'item').replace(/^custom[_-]?/,'').replace(/[_-]+/g,' ').trim()||'Pantry item';
  return s.charAt(0).toUpperCase()+s.slice(1);
}
function kitPantryNormaliseItem(id,value){
  const v=(value&&typeof value==='object')?value:{};
  const meta=KITPANTRY_SEED_META[id];
  const name=String(v.name||(meta&&meta.name)||kitPantryHumanName(id)).trim()||kitPantryHumanName(id);
  const cat=KITPANTRY_CAT_KEYS.has(v.cat)?v.cat:((meta&&meta.cat)||'dry');
  return {name,cat,inStock:v.inStock!==false,runningLow:!!v.runningLow,
    custom:typeof v.custom==='boolean'?v.custom:!meta};
}
function kitPantrySeedItems(){
  const items={};
  KITPANTRY_CATS.forEach(([cat,,names])=>names.forEach(name=>{
    items[kitPantryId(name)]={name,cat,inStock:true,runningLow:false,custom:false};
  }));
  return items;
}
function kitPantryUniqueName(name,used){
  const base=String(name||'Pantry').trim()||'Pantry';
  let out=base,n=2;
  while(used.has(out.toLocaleLowerCase())) out=base+' '+n++;
  used.add(out.toLocaleLowerCase());
  return out;
}
function kitPantryNormaliseData(raw,fresh){
  if(!(raw&&raw.schemaVersion===KITPANTRY_SCHEMA_VERSION&&raw.pantries&&typeof raw.pantries==='object')){
    const items={};
    if(raw&&typeof raw==='object') Object.keys(raw).forEach(id=>{ items[id]=kitPantryNormaliseItem(id,raw[id]); });
    else if(fresh) Object.assign(items,kitPantrySeedItems());
    return {schemaVersion:KITPANTRY_SCHEMA_VERSION,activePantryId:KITPANTRY_HOME_ID,
      order:[KITPANTRY_HOME_ID],pantries:{[KITPANTRY_HOME_ID]:{id:KITPANTRY_HOME_ID,name:'Home',items}}};
  }
  const pantries={}, usedNames=new Set();
  Object.keys(raw.pantries).forEach((key,i)=>{
    const src=raw.pantries[key]; if(!src||typeof src!=='object') return;
    let id=String(key||src.id||'').trim();
    if(!id||pantries[id]) id='pantry_'+kitUUID();
    const items={};
    const srcItems=src.items&&typeof src.items==='object'?src.items:{};
    Object.keys(srcItems).forEach(itemId=>{ items[itemId]=kitPantryNormaliseItem(itemId,srcItems[itemId]); });
    pantries[id]={id,name:kitPantryUniqueName(src.name||('Pantry '+(i+1)),usedNames),items};
  });
  let order=Array.isArray(raw.order)?raw.order.map(String).filter((id,i,a)=>pantries[id]&&a.indexOf(id)===i):[];
  Object.keys(pantries).forEach(id=>{ if(order.indexOf(id)<0) order.push(id); });
  if(!order.length){
    pantries[KITPANTRY_HOME_ID]={id:KITPANTRY_HOME_ID,name:'Home',items:{}};
    order=[KITPANTRY_HOME_ID];
  }
  const activePantryId=pantries[raw.activePantryId]?raw.activePantryId:order[0];
  return {schemaVersion:KITPANTRY_SCHEMA_VERSION,activePantryId,order,pantries};
}
function kitPantryLoad(){
  let parsed=null,rawText=null;
  try{ rawText=localStorage.getItem('kitchen_pantry'); if(rawText) parsed=JSON.parse(rawText); }catch(e){ parsed=null; }
  const data=kitPantryNormaliseData(parsed,!parsed);
  // Boot seeding and legacy migration use the timestamp-aware writer. A fresh device keeps
  // timestamp 0, while legacy data arriving later from Firebase is migrated and written back
  // with a real edit timestamp without creating a second sync path.
  if(!rawText||JSON.stringify(parsed)!==JSON.stringify(data)) lsSave('kitchen_pantry',data,_bootPhase?null:'kitPantry');
  return data;
}
let kitPantryData=kitPantryLoad();
kitShopChecked=kitShopNormaliseChecked(kitShopChecked);
function kitPantrySave(){ lsSave('kitchen_pantry', kitPantryData, 'kitPantry'); }
function kitPantryActiveId(){
  if(kitPantryData&&kitPantryData.pantries&&kitPantryData.pantries[kitPantryData.activePantryId]) return kitPantryData.activePantryId;
  return kitPantryData&&kitPantryData.order&&kitPantryData.order[0]||KITPANTRY_HOME_ID;
}
function kitPantryGet(id){
  const pid=id||kitPantryActiveId();
  return kitPantryData&&kitPantryData.pantries?kitPantryData.pantries[pid]||null:null;
}
function kitPantryActive(){ return kitPantryGet(kitPantryActiveId()); }
function kitPantryItemsByCat(pantryId){
  const groups={}; KITPANTRY_CATS.forEach(([cat])=>groups[cat]=[]);
  const pantry=kitPantryGet(pantryId); if(!pantry) return groups;
  const rank={}; let n=0;
  KITPANTRY_CATS.forEach(([, ,names])=>names.forEach(name=>{ rank[kitPantryId(name)]=n++; }));
  Object.keys(pantry.items||{}).forEach(id=>{
    const v=kitPantryNormaliseItem(id,pantry.items[id]);
    groups[v.cat].push(Object.assign({id,pantryId:pantry.id},v));
  });
  Object.keys(groups).forEach(cat=>groups[cat].sort((a,b)=>{
    const ar=rank[a.id],br=rank[b.id];
    if(ar!=null||br!=null) return (ar==null?9999:ar)-(br==null?9999:br);
    return a.name.localeCompare(b.name);
  }));
  return groups;
}
function kitPantryNeeds(pantryId){
  const pantry=kitPantryGet(pantryId); if(!pantry) return [];
  const out=[];
  Object.keys(pantry.items||{}).forEach(id=>{
    const v=kitPantryNormaliseItem(id,pantry.items[id]);
    const status=kitPantryStatusOf(v);
    if(status!=='in') out.push(Object.assign({id,pantryId:pantry.id,status},v));
  });
  out.sort((a,b)=>a.name.localeCompare(b.name));
  return out;
}
const KITPANTRY_STATUS=[
  {id:'in',  label:'In stock',   short:'In stock', icon:'\u2713'},
  {id:'low', label:'Running low',short:'Low',      icon:'\u26a0'},
  {id:'out', label:'Out',        short:'Out',      icon:'\u2715'}
];
function kitPantryStatusOf(it){
  if(!it) return 'in';
  if(it.inStock===false) return 'out';
  return it.runningLow?'low':'in';
}
function kitPantrySetStatus(id,status,pantryId){
  const pantry=kitPantryGet(pantryId); if(!pantry||!pantry.items[id]) return;
  const v=pantry.items[id];
  if(status==='out'){ v.inStock=false; v.runningLow=false; }
  else if(status==='low'){ v.inStock=true; v.runningLow=true; }
  else { v.inStock=true; v.runningLow=false; }
  kitPantrySave();
  kitPantryRefreshViews();
}
function kitPantryCycle(id){
  const order=['in','low','out'];
  const pantry=kitPantryActive(); if(!pantry) return;
  const it=pantry.items[id]||{};
  const cur=kitPantryStatusOf({inStock:it.inStock,runningLow:it.runningLow});
  kitPantrySetStatus(id, order[(order.indexOf(cur)+1)%order.length],pantry.id);
}

function kitPantryExactName(name){
  let s=String(name||'');
  try{ s=s.normalize('NFKD'); }catch(e){}
  return s.replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ')
    .replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ');
}
const KITPANTRY_ALIASES={
  'pepper':'black pepper','black pepper':'black pepper',
  'vanilla':'vanilla extract','vanilla extract':'vanilla extract',
  'worcestershire':'worcestershire sauce','worcestershire sauce':'worcestershire sauce',
  'balsamic':'balsamic vinegar','balsamic vinegar':'balsamic vinegar',
  'mayo':'mayonnaise','mayonnaise':'mayonnaise',
  'ketchup':'tomato ketchup','tomato ketchup':'tomato ketchup',
  'dijon':'dijon mustard','dijon mustard':'dijon mustard',
  'olive oil':'extra virgin olive oil','extra virgin olive oil':'extra virgin olive oil',
  'butter':'salted butter','salted butter':'salted butter',
  'rosemary':'rosemary leaves','rosemary leaves':'rosemary leaves',
  'oregano':'oregano leaves','oregano leaves':'oregano leaves'
};
function kitPantryCanonicalName(name){
  const stripped=String(name||'').replace(/\s*\((?:ground|dried|whole)\)\s*/gi,' ');
  const exact=kitPantryExactName(stripped);
  return KITPANTRY_ALIASES[exact]||exact;
}
function kitPantryIngredientIndex(pantryId){
  const groups=kitPantryItemsByCat(pantryId), exact={}, canonical={};
  KITPANTRY_CATS.forEach(([cat])=>(groups[cat]||[]).forEach(it=>{
    const e=kitPantryExactName(it.name),c=kitPantryCanonicalName(it.name);
    if(e&&!exact[e]) exact[e]=it;
    if(c&&!canonical[c]) canonical[c]=it;
  }));
  return {exact,canonical};
}
function kitPantryMatchIngredient(name,index){
  const idx=index||kitPantryIngredientIndex();
  return idx.exact[kitPantryExactName(name)]||idx.canonical[kitPantryCanonicalName(name)]||null;
}
function kitPantryHasDuplicateItem(name,pantryId){
  const key=kitPantryCanonicalName(name); if(!key) return false;
  const pantry=kitPantryGet(pantryId); if(!pantry) return false;
  return Object.keys(pantry.items||{}).some(id=>kitPantryCanonicalName(pantry.items[id].name)===key);
}

// ── View state: DEVICE-LOCAL ──
// Which filter is showing and which categories are collapsed are presentation preferences,
// not pantry data. Saved without a sync path and never registered in SYNC_BLOB_REG, so this
// cannot travel between devices or reach a backup — a phone collapsing Spices must not
// collapse it on a laptop.
function kitPantryUI(){
  const o=lsLoad('daily_pantry_ui', null);
  const ui=(o&&typeof o==='object')?o:{};
  if(['attention','stocked','all'].indexOf(ui.filter)<0) ui.filter='attention';
  if(!ui.collapsed||typeof ui.collapsed!=='object') ui.collapsed={};
  if(!ui.stockedOpen||typeof ui.stockedOpen!=='object') ui.stockedOpen={};
  if(typeof ui.cat!=='string') ui.cat='';
  return ui;
}
function kitPantryUISave(ui){ lsSave('daily_pantry_ui', ui); }
let kitPantryQuery='';    // transient: search is not a saved preference
function kitPantrySetFilter(f){ const ui=kitPantryUI(); ui.filter=f; kitPantryUISave(ui); kitPantryRender(); }
function kitPantrySetCat(c){ const ui=kitPantryUI(); ui.cat=c||''; kitPantryUISave(ui); kitPantryRender(); }
function kitPantrySearch(v){ kitPantryQuery=String(v||''); kitPantryRender(); }
function kitPantryClearSearch(){ kitPantryQuery=''; kitPantryRender(); }
function kitPantryToggleCat(cat){
  const ui=kitPantryUI();
  if(ui.collapsed[cat]) delete ui.collapsed[cat]; else ui.collapsed[cat]=true;
  kitPantryUISave(ui); kitPantryRender();
}
function kitPantryCollapseAll(collapse){
  const ui=kitPantryUI();
  ui.collapsed={};
  if(collapse) KITPANTRY_CATS.forEach(([cat])=>{ ui.collapsed[cat]=true; });
  kitPantryUISave(ui); kitPantryRender();
}
function kitPantryToggleStockedSection(pantryId){
  const ui=kitPantryUI();
  if(ui.stockedOpen[pantryId]) delete ui.stockedOpen[pantryId]; else ui.stockedOpen[pantryId]=true;
  kitPantryUISave(ui);
  if(kitState.tab==='shopping') kitShopRenderList();
}
function kitPantryRestock(pantryId,id){
  if(id==null){ id=pantryId; pantryId=kitPantryActiveId(); }
  const pantry=kitPantryGet(pantryId); if(!pantry||!pantry.items[id]) return;
  const v=pantry.items[id];
  v.inStock=true; v.runningLow=false;
  kitPantrySave();
  kitPantryRefreshViews();
}
let kitPantryAddOpen=false, kitPantryAddCat='spices';
function kitPantryOpenAdd(cat){
  kitPantryAddOpen=true;
  if(cat) kitPantryAddCat=cat;
  kitPantryRender();
  setTimeout(()=>{ const el=document.getElementById('kitpantry-new-name'); if(el) el.focus(); },40);
}
function kitPantryCloseAdd(){ kitPantryAddOpen=false; kitPantryRender(); }
function kitPantrySubmitAdd(){
  const nameEl=document.getElementById('kitpantry-new-name');
  const catEl=document.getElementById('kitpantry-new-cat');
  const stEl=document.getElementById('kitpantry-new-status');
  if(!nameEl) return;
  const name=nameEl.value.trim();
  const err=document.getElementById('kitpantry-new-err');
  if(!name){ if(err) err.textContent='Give the item a name.'; nameEl.focus(); return; }
  const cat=(catEl&&catEl.value)||kitPantryAddCat;
  const st=(stEl&&stEl.value)||'in';
  kitPantryAddCat=cat;
  const pantry=kitPantryActive(); if(!pantry) return;
  if(kitPantryHasDuplicateItem(name,pantry.id)){
    if(err) err.textContent='That item, or a matching pantry alias, is already in '+pantry.name+'.';
    nameEl.focus(); return;
  }
  const id='custom_'+Date.now();
  pantry.items[id]={inStock:st!=='out', runningLow:st==='low', custom:true, name:name, cat:cat};
  kitPantrySave();
  // Stay open for the next one — adding pantry items is something people do in a burst.
  kitPantryRender();
  setTimeout(()=>{
    const el=document.getElementById('kitpantry-new-name');
    if(el){ el.value=''; el.focus(); }
  },20);
}
// One row. Name on the left, one status control on the right — no checkbox, and no
// permanently-inactive Low button reserving space on all 41 items. Custom-item deletion is
// configuration, so its destructive control only exists while Pantry Edit mode is deliberate.
function kitPantryRowHTML(it){
  const st=kitPantryStatusOf(it);
  const meta=KITPANTRY_STATUS.find(s=>s.id===st)||KITPANTRY_STATUS[0];
  const next=KITPANTRY_STATUS[(KITPANTRY_STATUS.indexOf(meta)+1)%KITPANTRY_STATUS.length];
  const arg=kitPantryArg(it.id);
  return '<div class="kitpantry-item s-'+st+'">'+
    '<span class="kitpantry-name">'+kitEsc(it.name)+'</span>'+
    // Status is carried by an icon AND a word, never colour alone.
    '<button type="button" class="kitpantry-status s-'+st+'" onclick="kitPantryCycle(decodeURIComponent(\''+arg+'\'))" '+
      'aria-label="'+escAttr(it.name+': '+meta.label+'. Change to '+next.label+'.')+'">'+
      '<span class="kitpantry-status-ic" aria-hidden="true">'+meta.icon+'</span>'+meta.short+'</button>'+
    (it.custom&&kitPantryEditMode?'<button class="kitpantry-del" onclick="kitPantryDeleteCustom(decodeURIComponent(\''+arg+'\'))" aria-label="Remove '+escAttr(it.name)+'">\u2715</button>':'')+
  '</div>';
}

let kitPantryEditMode=false,kitPantryManageMode='',kitPantryManageError='';
function kitPantryToggleEdit(){
  kitPantryEditMode=!kitPantryEditMode;
  // New/rename forms belong to edit mode. Closing it must also clear a half-finished form so
  // reopening Edit always starts from the compact management choices, not stale input.
  if(!kitPantryEditMode){ kitPantryManageMode=''; kitPantryManageError=''; }
  kitPantryRender();
}
function kitPantryNameTaken(name,exceptId){
  const key=String(name||'').trim().toLocaleLowerCase();
  return kitPantryData.order.some(id=>id!==exceptId&&kitPantryData.pantries[id].name.toLocaleLowerCase()===key);
}
function kitPantryOpenManage(mode){
  kitPantryManageMode=mode; kitPantryManageError=''; kitPantryRender();
  setTimeout(()=>{
    const id=mode==='rename'?'kitpantry-rename-name':'kitpantry-location-name';
    const el=document.getElementById(id); if(el){ el.focus(); if(mode==='rename') el.select(); }
  },30);
}
function kitPantryCloseManage(){ kitPantryManageMode=''; kitPantryManageError=''; kitPantryRender(); }
function kitPantryNewId(){
  let id; do{ id='pantry_'+kitUUID(); }while(kitPantryData.pantries[id]); return id;
}
function kitPantrySubmitNew(){
  const input=document.getElementById('kitpantry-location-name'); if(!input) return;
  const name=input.value.trim();
  if(!name){ kitPantryManageError='Give the pantry a name.'; kitPantryRender(); return; }
  if(kitPantryNameTaken(name,'')){ kitPantryManageError='A pantry with that name already exists.'; kitPantryRender(); return; }
  const copy=(document.querySelector('input[name="kitpantry-start"]:checked')||{}).value==='copy';
  const current=kitPantryActive(),id=kitPantryNewId();
  const items=copy&&current?JSON.parse(JSON.stringify(current.items||{})):{};
  kitPantryData.pantries[id]={id,name,items};
  kitPantryData.order.push(id); kitPantryData.activePantryId=id;
  kitPantryManageMode=''; kitPantryManageError=''; kitPantryAddOpen=false; kitPantryQuery='';
  kitPantrySave(); kitPantryRefreshViews();
}
function kitPantrySubmitRename(){
  const pantry=kitPantryActive(),input=document.getElementById('kitpantry-rename-name'); if(!pantry||!input) return;
  const name=input.value.trim();
  if(!name){ kitPantryManageError='Give the pantry a name.'; kitPantryRender(); return; }
  if(kitPantryNameTaken(name,pantry.id)){ kitPantryManageError='A pantry with that name already exists.'; kitPantryRender(); return; }
  pantry.name=name; kitPantryManageMode=''; kitPantryManageError='';
  kitPantrySave(); kitPantryRefreshViews();
}
function kitPantryDeleteActive(){
  const pantry=kitPantryActive(); if(!pantry) return;
  if(kitPantryData.order.length<=1){
    kitPantryManageError='Daily needs at least one pantry, so '+pantry.name+' cannot be deleted.';
    kitPantryRender(); return;
  }
  if(!confirm('Delete "'+pantry.name+'" and all items tracked there? Other pantries, recipes and shopping items will stay unchanged.')) return;
  const oldIndex=kitPantryData.order.indexOf(pantry.id);
  kitPantryData.order=kitPantryData.order.filter(id=>id!==pantry.id);
  delete kitPantryData.pantries[pantry.id];
  kitPantryData.activePantryId=kitPantryData.order[Math.min(Math.max(oldIndex,0),kitPantryData.order.length-1)];
  if(kitShopChecked.pantries) delete kitShopChecked.pantries[pantry.id];
  kitPantryManageMode=''; kitPantryManageError=''; kitPantryAddOpen=false; kitPantryQuery='';
  kitPantrySave(); kitShopSaveChecked(); kitPantryRefreshViews();
}
function kitPantrySwitch(id){
  if(!kitPantryData.pantries[id]||id===kitPantryData.activePantryId) return;
  kitPantryData.activePantryId=id; kitPantryManageMode=''; kitPantryManageError='';
  kitPantryAddOpen=false; kitPantryQuery=''; kitPantrySave(); kitPantryRefreshViews();
}
function kitPantryLocationControlHTML(context,manage){
  const pantry=kitPantryActive(); if(!pantry) return '';
  const opts=kitPantryData.order.map(id=>{
    const p=kitPantryData.pantries[id];
    return '<option value="'+escAttr(id)+'"'+(id===pantry.id?' selected':'')+'>'+escText(p.name)+'</option>';
  }).join('');
  const title=context==='shopping'?'Shopping for':'Pantry location';
  const editing=manage&&kitPantryEditMode;
  let html='<section class="kitpantry-location" aria-label="'+escAttr(title)+'">'+
    '<div class="kitpantry-location-main"><div class="kitpantry-location-copy"><span class="kitpantry-location-kicker">'+title+'</span><strong>'+escText(pantry.name)+'</strong></div>'+
      '<div class="kitpantry-location-controls"><label class="kitpantry-location-select"><span>Switch</span><select aria-label="Switch pantry" onchange="kitPantrySwitch(this.value)">'+opts+'</select></label>'+
      (manage?'<button type="button" class="bud-edit-btn kitpantry-location-edit'+(editing?' active':'')+'" onclick="kitPantryToggleEdit()" aria-expanded="'+(editing?'true':'false')+'">'+(editing?'Done':'Edit')+'</button>':'')+'</div></div>';
  if(editing){
    const only=kitPantryData.order.length<=1;
    html+='<div class="kitpantry-location-management"><div class="kitpantry-location-actions">'+
      '<button type="button" onclick="kitPantryOpenManage(\'new\')">+ New</button>'+
      '<button type="button" onclick="kitPantryOpenManage(\'rename\')">Rename</button>'+
      '<button type="button" class="danger" onclick="kitPantryDeleteActive()"'+(only?' disabled':'')+'>Delete</button></div>'+
      (only?'<div class="kitpantry-location-note">Create another pantry before deleting '+escText(pantry.name)+'.</div>':'');
    if(kitPantryManageMode==='new'){
      html+='<div class="kitpantry-manage-form"><label>Pantry name<input id="kitpantry-location-name" type="text" autocomplete="off" placeholder="e.g. Mum\'s house" onkeydown="if(event.key===\'Enter\'){event.preventDefault();kitPantrySubmitNew();}"></label>'+
        '<fieldset><legend>Starting inventory</legend><label><input type="radio" name="kitpantry-start" value="empty" checked> Start empty</label><label><input type="radio" name="kitpantry-start" value="copy"> Copy '+escText(pantry.name)+'</label></fieldset>'+
        '<div class="kitpantry-manage-error" role="alert">'+escText(kitPantryManageError)+'</div><div class="kitpantry-manage-buttons"><button type="button" onclick="kitPantryCloseManage()">Cancel</button><button type="button" class="primary" onclick="kitPantrySubmitNew()">Create pantry</button></div></div>';
    } else if(kitPantryManageMode==='rename'){
      html+='<div class="kitpantry-manage-form"><label>Pantry name<input id="kitpantry-rename-name" type="text" autocomplete="off" value="'+escAttr(pantry.name)+'" onkeydown="if(event.key===\'Enter\'){event.preventDefault();kitPantrySubmitRename();}"></label>'+
        '<div class="kitpantry-manage-error" role="alert">'+escText(kitPantryManageError)+'</div><div class="kitpantry-manage-buttons"><button type="button" onclick="kitPantryCloseManage()">Cancel</button><button type="button" class="primary" onclick="kitPantrySubmitRename()">Save name</button></div></div>';
    } else if(kitPantryManageError){
      html+='<div class="kitpantry-manage-error" role="alert">'+escText(kitPantryManageError)+'</div>';
    }
    html+='</div>';
  }
  return html+'</section>';
}
function kitPantryRefreshViews(){
  if(typeof S!=='undefined'&&S.view==='kitchen'){
    if(kitState.tab==='pantry') kitPantryRender();
    else if(kitState.tab==='shopping') kitShopRender();
  }
  if(typeof S!=='undefined'&&S.view==='home'&&typeof renderHome==='function') renderHome();
}
function kitPantryRender(){
  const wrap=document.getElementById('kitpantry'); if(!wrap) return;
  // Keep the caret where it is: this re-renders on every keystroke.
  const active=document.activeElement;
  const searchFocused=!!(active&&active.id==='kitpantry-search');
  const caret=searchFocused?active.selectionStart:null;

  const pantry=kitPantryActive(); if(!pantry) return;
  const groups=kitPantryItemsByCat(pantry.id);
  const ui=kitPantryUI();
  const q=kitPantryQuery.trim().toLowerCase();

  let stocked=0,low=0,out=0;
  const all=[];
  KITPANTRY_CATS.forEach(([cat])=>(groups[cat]||[]).forEach(it=>{
    const st=kitPantryStatusOf(it);
    if(st==='out') out++; else if(st==='low') low++; else stocked++;
    all.push(Object.assign({},it,{status:st}));
  }));

  const matches=it=>{
    if(q && it.name.toLowerCase().indexOf(q)<0) return false;
    if(ui.cat && it.cat!==ui.cat) return false;
    if(ui.filter==='attention') return it.status!=='in';
    if(ui.filter==='stocked')   return it.status==='in';
    return true;
  };
  const visible=all.filter(matches);

  let html=kitPantryLocationControlHTML('pantry',true)+'<div class="kitpantry-search">'+
    '<svg class="kitpantry-search-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>'+
    '<input id="kitpantry-search" type="search" autocomplete="off" placeholder="Search pantry\u2026" '+
      'value="'+escAttr(kitPantryQuery)+'" oninput="kitPantrySearch(this.value)" aria-label="Search pantry">'+
    (kitPantryQuery?'<button type="button" class="kitpantry-search-x" onclick="kitPantryClearSearch()" aria-label="Clear search">\u2715</button>':'')+
  '</div>';

  // ── The old summary badges, now the primary filter ──
  const pill=(id,label,cls)=>'<button type="button" class="kitpantry-badge '+cls+(ui.filter===id?' on':'')+'" '+
    'aria-pressed="'+(ui.filter===id?'true':'false')+'" onclick="kitPantrySetFilter(\''+id+'\')">'+label+'</button>';
  html+='<div class="kitpantry-summary" role="group" aria-label="Filter pantry">'+
    pill('attention',(low+out)+' need attention','bad')+
    pill('stocked',stocked+' stocked','good')+
    pill('all','All '+all.length,'neutral')+
  '</div>';

  // ── Category chips: filter, not jump — jumping leaves you deep in a long document ──
  const chip=(c,label)=>'<button type="button" class="kitpantry-chip'+(ui.cat===c?' on':'')+'" '+
    'aria-pressed="'+(ui.cat===c?'true':'false')+'" onclick="kitPantrySetCat(\''+c+'\')">'+escText(label)+'</button>';
  html+='<div class="kitpantry-chips">'+chip('','All')+
    KITPANTRY_CATS.map(([c,label])=>chip(c,label)).join('')+'</div>';

  if(!all.length){
    html+='<div class="kitpantry-empty"><div class="kitpantry-empty-t">'+escText(pantry.name)+' is empty</div>'+
      '<div class="kitpantry-empty-d">Untracked recipe ingredients stay on the shopping list. Add the things kept here and Daily will set stocked items aside.</div></div>';
  } else if(ui.filter==='attention' && !(low+out) && !q){
    // The good case gets a real answer instead of a blank list.
    html+='<div class="kitpantry-empty"><div class="kitpantry-empty-t">\u2713 Everything is stocked</div>'+
      '<div class="kitpantry-empty-d">Nothing is running low or out.</div>'+
      '<button type="button" class="kitpantry-empty-btn" onclick="kitPantrySetFilter(\'all\')">View all '+all.length+' items</button></div>';
  } else if(!visible.length){
    html+='<div class="kitpantry-empty"><div class="kitpantry-empty-t">Nothing matches</div>'+
      '<div class="kitpantry-empty-d">'+(q?('No pantry item matches \u201c'+escText(kitPantryQuery)+'\u201d.'):'No items in this view.')+'</div></div>';
  } else if(ui.filter==='attention' || q){
    // A short, flat list — grouping two rows under five headings would be the same problem
    // in miniature. Searching behaves the same way: you want the hit, not its neighbourhood.
    html+='<div class="kitpantry-cat-head">'+(q?'Results':'Needs attention')+'</div>'+
      '<div class="kitpantry-cat-items kitpantry-group">'+visible.map(kitPantryRowHTML).join('')+'</div>';
  } else {
    // ── Grouped, collapsible ──
    html+='<div class="kitpantry-bulk">'+
      '<button type="button" onclick="kitPantryCollapseAll(true)">Collapse all</button>'+
      '<button type="button" onclick="kitPantryCollapseAll(false)">Expand all</button>'+
    '</div>';
    KITPANTRY_CATS.forEach(([cat,label])=>{
      const items=visible.filter(it=>it.cat===cat);
      if(!items.length) return;
      const cLow=items.filter(i=>i.status==='low').length;
      const cOut=items.filter(i=>i.status==='out').length;
      const cIn =items.filter(i=>i.status==='in').length;
      // Collapse is always honoured — forcing a category open because it holds a warning
      // meant "Collapse all" silently did not, which is worse than the problem it solved.
      // Nothing is hidden by collapsing: the warning counts stay in the heading, and the
      // Needs-attention filter above lists every one of them regardless of category state.
      // Categories start expanded, so a new warning is visible by default either way.
      // Choosing a category from the chips is itself an "open this" intent — otherwise
      // filtering to a category you had previously collapsed shows an empty screen.
      const open=!ui.collapsed[cat] || ui.cat===cat;
      const counts=[];
      if(cOut) counts.push('<span class="kitpantry-c bad">'+cOut+' out</span>');
      if(cLow) counts.push('<span class="kitpantry-c warn">'+cLow+' low</span>');
      counts.push('<span class="kitpantry-c">'+cIn+' stocked</span>');
      html+='<div class="kitpantry-cat-head">'+
        '<button type="button" class="kitpantry-cat-btn'+(open?' open':'')+'"'+
          ' aria-expanded="'+(open?'true':'false')+'" onclick="kitPantryToggleCat(\''+cat+'\')">'+
          '<span class="kitpantry-cat-chev" aria-hidden="true">\u203a</span>'+
          '<span class="kitpantry-cat-label">'+escText(label)+'</span>'+
          '<span class="kitpantry-counts">'+counts.join('')+'</span>'+
        '</button>'+
        '<button type="button" class="kitpantry-cat-add" onclick="kitPantryOpenAdd(\''+cat+'\')" aria-label="Add an item to '+escAttr(label)+'">+</button>'+
      '</div>';
      if(open) html+='<div class="kitpantry-cat-items kitpantry-group">'+items.map(kitPantryRowHTML).join('')+'</div>';
    });
  }

  // ── One add control for the whole pantry ──
  if(kitPantryAddOpen){
    const catOpts=KITPANTRY_CATS.map(([c,label])=>'<option value="'+escAttr(c)+'"'+(c===kitPantryAddCat?' selected':'')+'>'+escText(label)+'</option>').join('');
    const stOpts=KITPANTRY_STATUS.map(s=>'<option value="'+s.id+'">'+escText(s.label)+'</option>').join('');
    html+='<div class="kitpantry-newform">'+
      '<div class="kitpantry-newform-t">Add a pantry item</div>'+
      '<input id="kitpantry-new-name" type="text" placeholder="Item name" autocomplete="off" '+
        'onkeydown="if(event.key===\'Enter\'){event.preventDefault();kitPantrySubmitAdd();}">'+
      '<div class="kitpantry-newform-row">'+
        '<label>Category<select id="kitpantry-new-cat">'+catOpts+'</select></label>'+
        '<label>Status<select id="kitpantry-new-status">'+stOpts+'</select></label>'+
      '</div>'+
      '<div id="kitpantry-new-err" class="kitpantry-newform-err" role="alert"></div>'+
      '<div class="kitpantry-newform-btns">'+
        '<button type="button" class="kitpantry-newform-done" onclick="kitPantryCloseAdd()">Done</button>'+
        '<button type="button" class="kitpantry-newform-add" onclick="kitPantrySubmitAdd()">Add item</button>'+
      '</div>'+
    '</div>';
  } else {
    html+='<button type="button" class="kitpantry-addbtn" onclick="kitPantryOpenAdd()">+ Add pantry item</button>';
  }

  wrap.innerHTML=html;
  if(searchFocused){
    const el=document.getElementById('kitpantry-search');
    if(el){ el.focus(); try{ el.setSelectionRange(caret,caret); }catch(e){} }
  }
}
function kitPantryDeleteCustom(id){
  const pantry=kitPantryActive(); if(!pantry) return;
  delete pantry.items[id];
  kitPantrySave();
  kitPantryRefreshViews();
}

// ── Portrait lock ─────────────────────────────────────────────────
// iOS Safari ignores the JS screen-orientation lock API, so the manifest's
// "orientation":"portrait" only covers Android/installed PWAs. This overlay is the real
// enforcement. Width-guarded to 1024 so the desktop layout (always landscape on a monitor)
// is never blocked — only phone-width viewports rotated to landscape get the prompt.


// ── Boot ──────────────────────────────────────────────────────────
// Wrapped so a single render/init error surfaces a visible message instead of
// leaving a blank black screen — and so later steps (like the SW registration
// that ships fresh code) still run even if an earlier step throws.
try {
  migrateLegsGroupOnce(); // one-time: 'legs' → quads/hamstrings/calves/glutes/lower back
  recoverBudgetData(); // one-time: normalise legacy budget weeks, strip shadowing snapshots
  migrateCatBudgetsOnce(); // one-time: lift budgetConfig weekly amounts onto the categories
  migrateSubscriptionsToFixedOnce(); // one-time: fold subscriptions into fixed categories
  migrateDropSubsAggregateOnce(); // one-time: drop the leftover aggregate 'subs' category
  migrateRetiredAccentOnce(); // one-time: retired orange default → neutral grey
  budFreezeLegacyRatesOnce(); // one-time: pin pre-existing weeks so recurring prices stop floating
  migrateDefaultWideOnce();   // one-time: three full-width Home cards → just the session hero
  budCleanupUnnamedCatsOnce(); // one-time: clear machine-id rows left by unnamed categories
  // Warm the timed-exercise cache at boot: getPR/getPoints read it, and Stats can render
  // before renderLog has ever run.
  refreshSecsNames();
  // Weight-log consolidation: fold any legacy daily_weight_log entries into wt_weight.
  // The local key is only removed by the signed-in path (after the merged copy is safely
  // in the cloud), so a signed-out merge can never lose data to the next cloud pull.
  if(mergeLegacyWeightEntries()) persistWeights();
  // Seed the CC balance history from the current balance so the net-worth line has a start.
  if(!ccLog.length){
    const _ccBal=parseFloat(loadCCData().balance);
    if(_ccBal>0) recordCCHistory(_ccBal);
  }
  applyTheme();
  applyLogoDayColour();
  buildSideMenu();
  restoreQuickSettings();
  applyDayColour();
  logCheckin();
  // Restore an in-progress workout from earlier today (survives refresh); else fresh day.
  if(!restoreSetData()) initDay(suggestDay());
  renderHome();
  updateNavPill(S.view||'home'); // seed the nav underline before the first tab switch
  updateHeaderAvatar();
  updateDesktopSidebar();
  // Event delegation on the stable sidebar parent — one listener, never double-binds
  const _dsSidebar=document.getElementById('desktop-sidebar');
  if(_dsSidebar) _dsSidebar.addEventListener('click',e=>{
    const item=e.target.closest('.ds-item');
    if(item&&item.dataset.tab) setView(item.dataset.tab);
  });
  document.querySelectorAll('.ds-item').forEach(b=>b.classList.toggle('active',b.dataset.tab==='home'));
  updateNavPill('home');
  updateStatsPill('home');
  updateNavBadges();
  (function(){
    const _bn=document.getElementById('bottom-nav');
    if(!_bn) return;
    _bn.addEventListener('click', function(e){
      const btn=e.target.closest('.nav-btn');
      if(!btn) return;
      const icon=btn.querySelector('svg');
      if(!icon) return;
      icon.classList.remove('nav-icon-bounce');
      void icon.offsetWidth;
      icon.classList.add('nav-icon-bounce');
      icon.addEventListener('animationend', ()=>icon.classList.remove('nav-icon-bounce'), {once:true});
    });
  })();
  checkOnboarding();
  checkWhatsNew();
  checkReminders();
  // Boot is over: from here every save is a real edit and stamps the current time.
  _bootPhase = false;
} catch(e) {
  // Cleared in the failure path too — otherwise an init error would leave every later save
  // unstamped, and this device could never win a sync conflict again.
  _bootPhase = false;
  console.error('App init failed:', e);
  const main=document.getElementById('app-main');
  if(main) main.innerHTML='<div style="padding:24px;color:var(--text);font-size:14px;line-height:1.6">'+
    '<div style="font-size:32px;margin-bottom:8px">⚠️</div>'+
    '<div style="font-weight:700;margin-bottom:6px">Something went wrong loading the app</div>'+
    '<div style="color:var(--muted);font-size:13px;margin-bottom:12px">'+(e&&e.message?String(e.message).replace(/</g,'&lt;'):'Unknown error')+'</div>'+
    '<button onclick="try{if(typeof budSaveCurrentWeek===\'function\')budSaveCurrentWeek()}catch(e){};location.reload(true)" style="padding:10px 20px;border:none;border-radius:10px;background:var(--accent);color:#fff;font-size:14px;font-weight:600;cursor:pointer">Reload</button>'+
    '</div>';
}

// Always register the (network-first) service worker so fresh code reaches the
// device even if boot above threw — this is what replaces stale cached code.
if('serviceWorker' in navigator){
  // When a new SW (skipWaiting + clients.claim) takes control, the page is still
  // running the OLD cached JS/CSS until it reloads. Reload once automatically so
  // updates apply on the very next launch instead of needing a manual second relaunch.
  // Guarded against loops: only fires after an existing controller is replaced.
  let _swRefreshing=false;
  if(navigator.serviceWorker.controller){
    navigator.serviceWorker.addEventListener('controllerchange', function(){
      if(_swRefreshing) return;
      _swRefreshing=true;
      location.reload();
    });
  }
  // Relative, not hardcoded to a repo name — an absolute /workout-tracker/ path here
  // broke outright when the repo was renamed to daily-app (404, registration failed
  // silently), which also broke "Add to Home Screen" via manifest.json's start_url
  // pointing at the same dead path.
  navigator.serviceWorker.register('service-worker.js');
}

// ── Keep #app-main bottom padding in sync with the real bottom-nav height ──
// The nav height varies with the device safe-area inset, so measure it rather than
// hardcoding. Floored + small gap so a mistimed measurement can never clip content;
// falls back to the stylesheet value on desktop (nav hidden) or if measuring fails.
function syncNavPadding(){
  var nav=document.getElementById('bottom-nav');
  var main=document.getElementById('app-main');
  if(!nav||!main) return;
  // In landscape the nav is a full-height rail down the LEFT side, so its height is the whole
  // viewport and there is nothing along the bottom edge to clear. Measuring it here wrote the
  // rail's ~390px as bottom padding, which pushed #app-main past its parent, made its height
  // indefinite, and collapsed #swipe-deck (height:100%) to zero — every panel lost its height
  // and the Log columns measured 0 tall. The rail's WIDTH is handled in CSS by #app's
  // padding-left; nothing is needed here.
  if(typeof isLandscapePhone==='function' && isLandscapePhone()){
    main.style.paddingBottom='';
    document.documentElement.style.removeProperty('--nav-height');
    return;
  }
  var h=Math.round(nav.getBoundingClientRect().height);
  if(h>0){
    main.style.paddingBottom=Math.max(h+12, 88)+'px';
    document.documentElement.style.setProperty('--nav-height', h+'px');
  } else {
    main.style.paddingBottom='';
    document.documentElement.style.removeProperty('--nav-height');
  }
}
window.addEventListener('load', syncNavPadding);
window.addEventListener('resize', syncNavPadding);
window.addEventListener('orientationchange', function(){ setTimeout(syncNavPadding,150); });
setTimeout(syncNavPadding, 0);

// ── iOS standalone PWA cold-launch layout fix ──
// On a fresh launch from the Home Screen, iOS can render before env(safe-area-inset-*)
// resolve (they come back 0) and with a mis-measured viewport — the app "fixes itself"
// only after the user rotates. Force the same reflow a few times after launch / on
// resume so the safe-area insets + nav padding settle without needing a rotation.
// (Scroll position is preserved; the display toggle is synchronous so it never paints.)
function pinAppHeight(){
  // #app fills the viewport via CSS (position:fixed; inset:0), which iOS resolves correctly
  // at launch — so never set an explicit JS height here. Only clear a stale inline height
  // left by an earlier app version, and never the deliberate correction vpSyncApp applies
  // when WebKit hands back a keyboard-reduced box (checking _vpAppPinned, not the style,
  // because clearing it here would undo the fix on the very next resize).
  var app=document.getElementById('app');
  if(app && app.style.height && !_vpAppPinned) app.style.height='';
}
function nudgeLayout(){
  // Note: the old viewport-fit (cover→auto→cover) toggle was REMOVED — it raced with how
  // iOS resolves env(safe-area-inset-top) and intermittently double-counted it, dragging
  // the header down on some launches. With #app on position:fixed (stable dvh) the toggle
  // is unnecessary; we only keep the nav-padding sync here.
  pinAppHeight();
  if(typeof syncNavPadding==='function') syncNavPadding();
}
// ── Journal ────────────────────────────────────────────────────────
// One destination holding two structurally different jobs, separated by POSITION rather than
// by a mode switch: journal entries are the timeline, and the old reminder/expiry/reference
// notes sit above it as Open Loops. A diary entry is about the past and is permanent; a
// reminder is about the future and exists in order to stop existing. Interleaving them is what
// buries a passport expiry under three weeks of prose.
// There is no Journal/Notes toggle anywhere: the AFFORDANCE encodes the kind. The composer
// makes an entry, the + in the Open Loops header makes a note.
// Ids stay "notes" throughout (view id, nav data-tab, Home widget id) because they are
// persisted in the saved Home layout; only labels changed.
const JRN_MOODS=[{v:1,label:'Rough'},{v:2,label:'Low'},{v:3,label:'OK'},{v:4,label:'Good'},{v:5,label:'Great'}];
function jrnMoodLabel(m){ const x=JRN_MOODS.find(o=>o.v===m); return x?x.label:''; }

// Whole days between two YYYY-MM-DD strings. Both sides parse as UTC midnight on purpose: the
// difference is then an exact multiple of 24h with no DST hour to round past. localMidnight()
// looks like the right helper here and is subtly wrong — across a DST boundary two LOCAL
// midnights are 23 or 25 hours apart, and the rounding would report a day too many.
function notesDayDiff(dateA, dateB){
  const a=Date.parse(dateA+'T00:00:00Z'), b=Date.parse(dateB+'T00:00:00Z');
  if(isNaN(a)||isNaN(b)) return NaN;
  return Math.round((a-b)/86400000);
}
// Built through jrnNormalise so a new record is a v2 record from the first keystroke — nothing
// in the app constructs the legacy shape any more.
function jrnNewRecord(kind){
  const now=Date.now();
  return jrnNormalise({id:(kind==='entry'?'jrn_':'note_')+now, schemaVersion:JRN_SCHEMA,
    kind:kind||'note', createdAt:now, updatedAt:now, tags:kind==='entry'?[]:['personal']});
}

let jrnQuery='';
let jrnTab='timeline';      // timeline | notes | trash
let jrnSearchOpen=false;
let jrnSelId=null;          // desktop detail selection
let jrnListsDirty=false;

// Journal's two-pane split point, NOT the app's 1024px desktop line — the same reasoning as
// STG_SPLIT_MIN in Settings, and for the same reason it is a different number.
// At 1024 the 260px sidebar plus the section's 32px padding leave ~700px of content; a 400px
// navigation list would take most of it and hand the writing surface about 225px. A 225px
// editor is worse than no editor: the point of the desktop layout is that writing gets the
// space. Below this the phone's list-first flow is used instead — a clean full-screen editor
// beats a cramped pane.
// THIS NUMBER IS DUPLICATED in the @media query in css/journal.css and the two must agree:
// this function decides whether the editor mounts inline or as an overlay, and the CSS decides
// whether the pane it would mount into exists at all.
const JRN_SPLIT_MIN=1240;
function jrnIsDesktop(){ return window.innerWidth>=JRN_SPLIT_MIN; }
function jrnEntries(){ return jrnLive().filter(r=>r.kind==='entry'); }
function jrnNotesAll(){ return jrnLive().filter(r=>r.kind!=='entry'); }
// An entry always carries dateAbout, but fall back to its creation day rather than dropping a
// record out of the timeline if one ever arrives without it.
function jrnEntryDay(r){
  const d=String((r&&r.dateAbout)||'');
  if(/^\d{4}-\d{2}-\d{2}$/.test(d)) return d;
  return dateStr(new Date(Number((r&&r.createdAt))||Date.now()));
}
function jrnMatch(r,q){
  if(!q) return true;
  const hay=(String(r.title||'')+'\n'+String(r.body||'')+'\n'+(Array.isArray(r.tags)?r.tags.join(' '):'')).toLowerCase();
  return hay.indexOf(q)>=0;
}
function jrnQ(){ return jrnQuery.trim().toLowerCase(); }
function jrnTimeOf(r){
  const ms=Number(r&&r.createdAt)||0;
  if(!ms) return '';
  try{ return new Date(ms).toLocaleTimeString('en-AU',{hour:'numeric',minute:'2-digit'}); }catch(e){ return ''; }
}
function jrnLongDay(d){
  try{ return localMidnight(d).toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short'}); }
  catch(e){ return d; }
}
function jrnMonthLabel(d){
  try{ return localMidnight(d).toLocaleDateString('en-AU',{month:'long',year:'numeric'}); }
  catch(e){ return d.slice(0,7); }
}
// Newest day first; within a day, newest moment first. Days with no entries are simply not
// produced — an unwritten day is not rendered as a gap to feel bad about.
function jrnGroupByDay(entries){
  const map={};
  entries.forEach(r=>{ const d=jrnEntryDay(r); (map[d]=map[d]||[]).push(r); });
  return Object.keys(map).sort().reverse().map(d=>({
    date:d, items:map[d].sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0))
  }));
}
function jrnOpenLoops(){
  const today=getLocalDate();
  const in7=localMidnight(today); in7.setDate(in7.getDate()+7);
  const in7Str=dateStr(in7);
  const all=jrnNotesAll();
  const dated=n=>n.dueDate&&n.dateType!=='none';
  return {
    all,
    pinned : all.filter(n=>n.pinned),
    due    : all.filter(n=>!n.pinned&&dated(n)&&n.dueDate<=in7Str).sort((a,b)=>a.dueDate<b.dueDate?-1:1),
    later  : all.filter(n=>!n.pinned&&dated(n)&&n.dueDate>in7Str).sort((a,b)=>a.dueDate<b.dueDate?-1:1),
    undated: all.filter(n=>!n.pinned&&!dated(n)).sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0))
  };
}
// Semantic, never the accent: the runtime accent can be any hue, so a colour pairing that
// reads as "urgent" for one accent reads as decoration for another.
function jrnDueColour(diff){
  if(isNaN(diff)) return 'var(--muted)';
  return diff<=7?'var(--danger)':diff<=30?'#f59e0b':'var(--success)';
}
function jrnDueText(diff, dueDate){
  if(isNaN(diff)) return String(dueDate||'');
  if(diff<0) return Math.abs(diff)+'d overdue';
  if(diff===0) return 'Today';
  if(diff===1) return 'Tomorrow';
  if(diff<=30) return 'In '+diff+' days';
  return String(dueDate||'');
}

// Read-only cross-domain context. These values are resolved live from the canonical stores;
// they never become fields on a Journal record, so editing a workout or transaction cannot
// leave a stale copy behind in prose metadata.
function jrnWeekKeyForDate(ds){
  const d=localMidnight(ds), dow=d.getDay();
  d.setDate(d.getDate()-(dow===0?6:dow-1));
  return dateStr(d);
}
function jrnCalorieTotalForDate(ds){
  const today=getLocalDate();
  if(ds===today&&S.dailyLog&&S.dailyLog.date===today){
    const n=(S.dailyLog.entries||[]).reduce((sum,e)=>sum+(parseFloat(e.kcal)||0),0);
    if(n>0) return n;
  }
  if(Object.prototype.hasOwnProperty.call(calorieHistory||{},ds)){
    const n=parseFloat(calorieHistory[ds]);
    if(!isNaN(n)&&n>0) return n;
  }
  return null;
}
function jrnVariableWeekFact(ds){
  const key=jrnWeekKeyForDate(ds), d=budgetData&&budgetData[key];
  const txns=txnsForWeek(key);
  const hasRaw=Object.keys(d||{}).some(k=>k.startsWith('var_')&&k!=='var_goal'&&d[k]!==''&&d[k]!==null&&d[k]!==undefined);
  if(txns.length||hasRaw) return {key, amount:weekVarTotal(d||{},key), source:txns.length?'transactions':'weekly fields'};
  const legacy=parseFloat(d&&d.snapshot&&d.snapshot.variable);
  if(!isNaN(legacy)) return {key, amount:legacy, source:'legacy weekly total'};
  return null;
}
function jrnDayContext(ds){
  if(!aiIsDate(ds)) return [];
  const facts=[];
  const sessions=(S.sessions||[]).filter(s=>s&&s.date===ds);
  if(sessions.length){
    const labels=[...new Set(sessions.map(s=>String(s.sessionType||'Session')))];
    facts.push({kind:'workout',label:sessions.length===1?labels[0]:sessions.length+' sessions',detail:'Workout'});
  }
  const hlog=(typeof habitsLog==='object'&&habitsLog)?habitsLog:loadHabitsLog();
  if(Object.prototype.hasOwnProperty.call(hlog||{},ds)){
    const done=Array.isArray(hlog[ds])?hlog[ds].length:0;
    facts.push({kind:'habits',label:done+' habit'+(done===1?'':'s')+' completed',detail:'Habits'});
  }
  const kcal=jrnCalorieTotalForDate(ds);
  if(kcal!==null) facts.push({kind:'calories',label:Math.round(kcal).toLocaleString()+' kcal',detail:ds===getLocalDate()?'Food log · in progress':'Archived calorie total'});
  const weight=(S.weights||[]).find(w=>w&&w.date===ds&&parseFloat(w.weight)>0);
  if(weight) facts.push({kind:'weight',label:parseFloat(weight.weight)+' kg',detail:'Weight check-in'});
  const dayTxns=(txnData||[]).filter(t=>t&&t.date===ds);
  if(dayTxns.length){
    const amount=dayTxns.reduce((sum,t)=>sum+(parseFloat(t.amount)||0),0);
    facts.push({kind:'spending',label:fmtMoneyExact(amount),detail:dayTxns.length+' transaction'+(dayTxns.length===1?'':'s')+' that day'});
  } else {
    const wk=jrnVariableWeekFact(ds);
    if(wk) facts.push({kind:'spending',label:fmtMoneyExact(wk.amount),detail:'Variable spend · week of '+fmtDate(wk.key)});
  }
  return facts;
}
function jrnDayContextHtml(ds){
  const facts=jrnDayContext(ds);
  if(!facts.length) return '';
  return '<section class="jrn-context" aria-label="That day in Daily">'+
    '<div class="jrn-context-head"><span>That day in Daily</span><span>'+escText(jrnLongDay(ds))+'</span></div>'+
    '<div class="jrn-context-chips">'+facts.map(f=>
      '<button class="jrn-context-chip" data-jrn="day-source" data-source="'+f.kind+'" data-date="'+ds+'" aria-label="Open '+escAttr(f.detail)+' source">'+
        '<span class="jrn-context-value">'+escText(f.label)+'</span><span class="jrn-context-detail">'+escText(f.detail)+'</span><span aria-hidden="true">›</span>'+
      '</button>').join('')+'</div>'+
    '<div class="jrn-context-note">Recorded facts only. Missing areas are unknown, not zero.</div>'+
  '</section>';
}
function jrnRenderDayContext(){
  const el=document.getElementById('jrn-ed-context'); if(!el) return;
  const r=jrnEdRec();
  el.innerHTML=r&&r.kind==='entry'?jrnDayContextHtml(r.dateAbout||getLocalDate()):'';
}
function jrnOpenDaySource(kind,ds){
  jrnCloseEditor();
  if(kind==='workout'){
    setView('log'); openWorkoutHistory();
    setTimeout(()=>{ const row=document.querySelector('.session-card[data-session-date="'+ds+'"]'); if(row) row.scrollIntoView({block:'center'}); },40);
    return;
  }
  if(kind==='habits'){
    const log=(typeof habitsLog==='object'&&habitsLog)?habitsLog:loadHabitsLog();
    const done=Array.isArray(log[ds])?log[ds]:[];
    const rows=done.map(i=>'<div class="stats-source-row"><div class="stats-source-top"><span>'+escText(String(habitsData[i]||('Habit '+(i+1))))+'</span><span>Completed</span></div></div>').join('');
    openStatsEvidence('Habit log · '+fmtDate(ds),'<div class="stats-data-note">This date has a saved habit-log record. Only completed habit indices are stored; unticked habits are not interpreted as failures.</div><div class="stats-source-list">'+(rows||'<div class="stats-source-row">No completions are present in the saved record.</div>')+'</div>'+statsSourceActions(['<button onclick="closeStatsEvidence();setView(\'home\')">Open Habits on Home →</button>']));
    return;
  }
  if(kind==='calories'){
    if(ds===getLocalDate()){ setView('home'); openCalorieOverlay(); }
    else { setView('stats'); setStatsTab('nutrition',true); openNutritionEvidence(ds); }
    return;
  }
  if(kind==='weight'){ setView('stats'); setStatsTab('body',true); openWeightEvidence(ds); return; }
  if(kind==='spending'){ openBudgetWeekFromStats(jrnWeekKeyForDate(ds)); }
}

// Current-week reflection is deliberately ephemeral until Write is pressed and meaningful
// content is entered. It summarises only recorded facts, including partial-week coverage.
function jrnWeekReflection(){
  const today=getLocalDate(), monday=weekKey(getMondayOf(0));
  const days=[]; for(let d=localMidnight(monday),end=localMidnight(today);d<=end;d.setDate(d.getDate()+1)) days.push(dateStr(d));
  const facts=[];
  const sessions=(S.sessions||[]).filter(s=>s&&s.date>=monday&&s.date<=today);
  if(sessions.length){
    const trained=new Set(sessions.map(s=>s.date)).size;
    facts.push({label:'Training',value:sessions.length+' session'+(sessions.length===1?'':'s'),detail:trained+' distinct trained day'+(trained===1?'':'s')});
  }
  const hlog=(typeof habitsLog==='object'&&habitsLog)?habitsLog:loadHabitsLog();
  const habitDays=days.filter(d=>Object.prototype.hasOwnProperty.call(hlog||{},d));
  if(habitDays.length){
    const completed=habitDays.reduce((sum,d)=>sum+(Array.isArray(hlog[d])?hlog[d].length:0),0);
    facts.push({label:'Habits',value:completed+' completion'+(completed===1?'':'s'),detail:habitDays.length+' day'+(habitDays.length===1?'':'s')+' with a habit log'});
  }
  const spend=jrnVariableWeekFact(today);
  if(spend) facts.push({label:'Spending',value:fmtMoneyExact(spend.amount),detail:'Variable spend recorded · '+spend.source});
  const calDays=days.map(d=>({d,n:jrnCalorieTotalForDate(d)})).filter(x=>x.n!==null);
  if(calDays.length){
    const avg=Math.round(calDays.reduce((sum,x)=>sum+x.n,0)/calDays.length);
    facts.push({label:'Calories',value:avg.toLocaleString()+' kcal average',detail:calDays.length+' logged day'+(calDays.length===1?'':'s')+' · unlogged days excluded'});
  }
  const weights=(S.weights||[]).filter(w=>w&&w.date>=monday&&w.date<=today&&parseFloat(w.weight)>0).sort((a,b)=>a.date<b.date?-1:1);
  if(weights.length){
    const first=parseFloat(weights[0].weight), last=parseFloat(weights[weights.length-1].weight);
    const change=weights.length>1?Math.round((last-first)*10)/10:null;
    facts.push({label:'Weight',value:last+' kg',detail:change===null?'One check-in':weights.length+' check-ins · '+(change>0?'+':'')+change+' kg measured change'});
  }
  return {today,monday,days,facts,complete:localMidnight(today).getDay()===0};
}
function jrnReflectionHtml(compact){
  const w=jrnWeekReflection();
  if(compact){
    return '<button class="jrn-reflect-card" data-jrn="reflect">'+
      '<span><strong>Weekly reflection</strong><small>'+w.facts.length+' recorded area'+(w.facts.length===1?'':'s')+' ready to review</small></span><span aria-hidden="true">›</span>'+
    '</button>';
  }
  const rows=w.facts.length?w.facts.map(f=>
    '<div class="jrn-reflect-row"><span><strong>'+escText(f.label)+'</strong><small>'+escText(f.detail)+'</small></span><b>'+escText(f.value)+'</b></div>').join(''):
    '<div class="jrn-reflect-empty">There are no recorded workout, habit, spending, calorie or weight facts for this week yet.</div>';
  return '<div class="jrn-reflect">'+
    '<div class="jrn-reflect-period">'+(w.complete?'This week':'This week so far')+' · '+escText(fmtDate(w.monday))+'–'+escText(fmtDate(w.today))+'</div>'+
    '<div class="jrn-reflect-note">Only recorded facts are shown. This is a writing aid, not a score.</div>'+rows+
    '<div class="jrn-reflect-question"><span>Optional question</span><strong>What felt most important this week?</strong></div>'+
    '<button class="jrn-reflect-write" data-jrn="reflect-write">Write a reflection</button>'+
  '</div>';
}
function jrnSundayReflectHtml(){ return localMidnight(getLocalDate()).getDay()===0?jrnReflectionHtml(true):''; }
function jrnOpenReflection(){
  jrnEdFlush();
  const box=document.getElementById('paste-restore-box'), ov=document.getElementById('paste-restore-overlay');
  if(!box||!ov) return;
  // #bottom-nav is a body child while #app is its own fixed stacking context. A modal left
  // inside #app can look visible yet lose hit-testing to the nav; park the shared sheet on
  // body before opening it, just as the Journal editor is detached for phone use.
  if(ov.parentElement!==document.body) document.body.appendChild(ov);
  ov.classList.add('jrn-sheet');
  box.innerHTML='<div class="modal-header"><button class="back-btn" data-back="jrnCloseReflection" aria-label="Back to Journal">'+
    (typeof BACK_CHEVRON!=='undefined'?BACK_CHEVRON:'&#8249;')+'</button><div class="modal-title">Weekly reflection</div></div>'+
    '<div class="modal-body">'+jrnReflectionHtml(false)+'</div>';
  ov.classList.remove('hidden');
}
function jrnCloseReflection(){ const o=document.getElementById('paste-restore-overlay'); if(o){ o.classList.add('hidden'); o.classList.remove('jrn-sheet'); } }
function jrnStartReflection(){
  jrnCloseReflection();
  jrnOpenEditor(null,'entry');
  const b=document.getElementById('jrn-ed-body');
  if(b) b.placeholder='What felt most important this week?';
}

// ── Screen ──
// The editor element is moved between <body> (phone overlay) and the detail column (desktop),
// so it must be parked on <body> before #notes-content is rewritten or the re-render would
// destroy it along with its in-progress text.
function jrnDetachEditor(){
  const ed=document.getElementById('jrn-editor');
  if(ed && ed.parentElement!==document.body) document.body.appendChild(ed);
  return ed;
}
function renderNotes(){ renderJournal(); }
// Two layouts over ONE set of data, not one layout squeezed into two widths.
//   · Phone   — list-first. The tinted composer card is the primary affordance, entries are
//               cards, and opening one pushes the fullscreen editor. Unchanged.
//   · Desktop — editor-first. The left column is a NAVIGATION list (flat rows, quiet dividers,
//               one selected state) at a fixed reading width, and the writing surface owns the
//               rest of the screen. Before this it was the phone column stretched beside a
//               mostly empty "Nothing open" region, so the widest screen showed the least
//               writing.
function renderJournal(){
  const wrap=document.getElementById('notes-content'); if(!wrap) return;
  jrnDetachEditor();
  const desktop=jrnIsDesktop();
  // Pick the selection BEFORE the pane is built, so the list can mark the selected row and the
  // detail column has something to mount. Never re-enters renderJournal.
  if(desktop) jrnEnsureDesktopSelection();
  // While a search is running the screen is a results view: the composer previews today's entry,
  // which is not a result, and showing it at the top of a search for something else reads as a
  // false match. It comes straight back when the query is cleared.
  const rail = desktop
    ? jrnHeadHtml()+jrnNavHtml()
    : jrnHeadHtml()+(jrnQ()?'':jrnComposerHtml()+jrnSundayReflectHtml())+jrnLoopsHtml()+jrnBodyHtml();
  wrap.innerHTML = desktop
    ? '<div id="journal-root"><div class="jrn-rail">'+rail+'</div><div class="jrn-detail" id="jrn-detail"></div></div>'
    : '<div id="journal-root">'+rail+'</div>';
  if(desktop) jrnMountDetail();
  const s=document.getElementById('jrn-search');
  if(s && jrnSearchOpen && document.activeElement!==s){ s.value=jrnQuery; }
}
// The desktop left column. Sections, not cards: a heading, flat rows, quiet dividers.
function jrnNavHtml(){
  let h='<div class="jrn-nav">';
  if(!jrnQ() && jrnTab==='timeline') h+=jrnTodaySectionHtml()+jrnSundayReflectHtml();
  // The All notes tab IS the list of loops, grouped; showing the Open Loops section above it
  // printed the pinned rows twice, a few lines apart.
  if(jrnTab!=='notes') h+=jrnLoopsHtml();
  h+=jrnBodyHtml();
  return h+'</div>';
}
// Today is a ROW in the navigation list rather than the phone's tinted composer card — a card
// here would be the one elevated object in a column of flat rows, which is exactly the
// "rounded black boxes on a black page" effect the rest of this pass removes.
// It always offers a way in: "Start writing" when nothing has been written yet.
function jrnTodaySectionHtml(){
  const today=getLocalDate();
  const mine=jrnEntries().filter(r=>jrnEntryDay(r)===today)
    .sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0));
  // The unsaved "today" editor the desktop opens by default has no stored record to match on,
  // so the placeholder row carries the selected state on its behalf.
  const pendingToday = !!(jrnEdPending && jrnEdPending.id===jrnSelId);
  const rows = mine.length
    ? mine.map(r=>jrnEntryRow(r, jrnLongDay(today))).join('')
    : '<button class="jrn-row jrn-row-start'+(pendingToday?' sel':'')+'" data-jrn="new-entry">'+
        '<span class="jrn-row-top"><span class="jrn-row-date">'+escText(jrnLongDay(today))+'</span></span>'+
        '<span class="jrn-row-ttl">Start writing</span>'+
        '<span class="jrn-row-prev">How was today?</span>'+
      '</button>';
  return '<section class="jrn-sec">'+
    '<div class="jrn-sec-hd"><span class="jrn-sec-ttl">Today</span>'+
      '<button class="jrn-sec-act" data-jrn="new-entry">+ New entry</button></div>'+
    rows+
  '</section>';
}
// One flat row: date, title, a line of preview, quiet metadata. No shadow and no card edge —
// the divider and the selected state do all the work.
function jrnEntryRow(r, dateLabel){
  const title=String(r.title||'').trim();
  const body=String(r.body||'').replace(/\s+/g,' ').trim();
  const meta=[];
  if(r.mood) meta.push(jrnMoodLabel(r.mood));
  (Array.isArray(r.tags)?r.tags:[]).forEach(t=>meta.push(t));
  const t=jrnTimeOf(r);
  return '<button class="jrn-row'+(jrnSelId===r.id?' sel':'')+'" data-jrn="open" data-id="'+escAttr(r.id)+'">'+
    '<span class="jrn-row-top">'+
      (dateLabel?'<span class="jrn-row-date">'+escText(dateLabel)+'</span>':'')+
      (t?'<span class="jrn-row-time">'+escText(t)+'</span>':'')+
    '</span>'+
    '<span class="jrn-row-ttl">'+escText(title||body.slice(0,64)||'Untitled')+'</span>'+
    (body&&title?'<span class="jrn-row-prev">'+escText(body)+'</span>':'')+
    (meta.length?'<span class="jrn-row-meta">'+escText(meta.join(' · '))+'</span>':'')+
  '</button>';
}
// Re-render deferred while the editor holds a TEXT field — on desktop the editor is MOVED into
// the detail column on every render, and moving an element blurs whatever inside it had focus,
// which mid-sentence is unforgivable.
// It used to defer for any focus inside the editor at all, including a mood pill or a tag
// chip. Those are discrete presses, not typing: deferring them left the list showing "Start
// writing" after a mood had already created the entry, and nothing ever flushed the deferral,
// so the stale list survived until some unrelated render happened to come along.
function jrnEdHoldsText(){
  const a=document.activeElement; if(!a) return false;
  const ed=document.getElementById('jrn-editor');
  if(!ed || !ed.contains(a)) return false;
  const tag=(a.tagName||'').toLowerCase();
  if(tag==='textarea') return true;
  if(tag!=='input') return false;
  // A date input is a picker, not a text field being typed into.
  return (a.type||'text')!=='date';
}
function jrnRefreshLists(){
  if(jrnEdHoldsText()){ jrnListsDirty=true; return; }
  jrnListsDirty=false;
  renderJournal();
  if(typeof renderHomeNotesBubble==='function') renderHomeNotesBubble();
}
// The deferral above is now actually settled: when the field being typed into gives up focus,
// any render it postponed runs.
document.addEventListener('focusout',function(e){
  if(!jrnListsDirty) return;
  const ed=document.getElementById('jrn-editor');
  if(!ed || !e.target || !ed.contains(e.target)) return;
  setTimeout(function(){ if(jrnListsDirty && !jrnEdHoldsText()) jrnRefreshLists(); }, 0);
});
function jrnMountDetail(){
  const detail=document.getElementById('jrn-detail'); if(!detail) return;
  const ed=jrnDetachEditor();
  const stored = jrnSelId ? loadNotes().find(r=>r.id===jrnSelId&&!r.deletedAt) : null;
  // A new record is intentionally not stored until it has meaningful content. It still needs
  // to mount in the desktop detail pane; requiring a stored match here made every New action
  // flash and disappear before the first keystroke.
  const sel = stored || (jrnEdPending&&jrnEdPending.id===jrnSelId?jrnEdPending:null);
  if(sel && ed){
    detail.innerHTML='';
    ed.classList.add('inline','open');
    detail.appendChild(ed);
  } else {
    jrnSelId=null;
    if(ed) ed.classList.remove('inline','open');
    // Reached only if the editor element is missing or a selection was dropped mid-render —
    // jrnEnsureDesktopSelection() means the ordinary path always has today open. It is styled
    // to be READ rather than to fill space: a legible heading, not a faint grey block.
    detail.innerHTML='<div class="jrn-detail-empty">'+
      '<div class="jrn-empty-ttl">Nothing open</div>'+
      '<div class="jrn-empty-sub">Pick an entry from the list, or write about today.</div>'+
      '<button class="jrn-detail-empty-btn" data-jrn="new-entry">Write about today</button>'+
    '</div>';
  }
}
function jrnHeadHtml(){
  const searchIco='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>';
  const calIco='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>';
  const reflectIco='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 5h16M4 12h10M4 19h7"/><path d="m17 16 2 2 4-5"/></svg>';
  let h='<div class="jrn-head">'+
    '<div class="jrn-head-title">Journal</div>'+
    '<button class="jrn-head-btn" data-jrn="reflect" aria-label="Weekly reflection" title="Weekly reflection">'+reflectIco+'</button>'+
    '<button class="jrn-head-btn'+(jrnSearchOpen?' on':'')+'" data-jrn="search-toggle" aria-label="Search Journal" aria-pressed="'+(jrnSearchOpen?'true':'false')+'">'+searchIco+'</button>'+
    '<button class="jrn-head-btn" data-jrn="cal" aria-label="Jump to a date">'+calIco+'</button>'+
  '</div>';
  if(jrnSearchOpen){
    const q=jrnQ();
    const n = q ? jrnEntries().filter(r=>jrnMatch(r,q)).length + jrnNotesAll().filter(r=>jrnMatch(r,q)).length : 0;
    h+='<div class="jrn-search-wrap">'+
      '<input id="jrn-search" class="jrn-search" type="search" placeholder="Search entries, notes and tags" value="'+escAttr(jrnQuery)+'" autocomplete="off">'+
      (jrnQuery?'<button class="jrn-search-clear" data-jrn="search-clear">Clear</button>':'')+
    '</div>';
    if(q) h+='<div class="jrn-search-count">'+n+' match'+(n===1?'':'es')+'</div>';
  }
  return h;
}
// Permanently present and always first. Shows today's entry when one exists, so returning to an
// unfinished write is the same one tap as starting it.
function jrnComposerHtml(){
  const today=getLocalDate();
  const mine=jrnEntries().filter(r=>jrnEntryDay(r)===today)
    .sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0));
  const latest=mine[0];
  const firstLine=latest ? (String(latest.title||'').trim() || String(latest.body||'').trim().split('\n')[0] || 'Untitled') : '';
  let meta='';
  if(latest){
    const bits=[];
    if(mine.length>1) bits.push(mine.length+' entries today');
    if(latest.mood) bits.push(jrnMoodLabel(latest.mood));
    if(bits.length) meta='<div class="jrn-comp-meta">'+escText(bits.join(' · '))+'</div>';
  }
  return '<button class="jrn-composer" data-jrn="'+(latest?'open':'new-entry')+'"'+(latest?' data-id="'+escAttr(latest.id)+'"':'')+'>'+
    '<div class="jrn-comp-top">'+
      '<span class="jrn-comp-eyebrow">'+(latest?"Today's entry":'Today')+'</span>'+
      '<span class="jrn-comp-date">'+escText(jrnLongDay(today))+'</span>'+
    '</div>'+
    '<div class="jrn-comp-line'+(latest?'':' is-empty')+'">'+(latest?escText(firstLine):'How was today?')+'</div>'+
    meta+
  '</button>'+
  (latest?'<button class="jrn-loops-btn" data-jrn="new-entry" style="align-self:flex-start;margin:-6px 0 0 2px">+ Add another moment today</button>':'');
}
function jrnLoopRow(n, today){
  const diff=notesDayDiff(String(n.dueDate||''), today);
  const dated=n.dueDate&&n.dateType!=='none';
  const dot = n.pinned ? 'var(--accent)' : (dated ? jrnDueColour(diff) : 'var(--muted)');
  const right = n.pinned
    ? '<span class="jrn-loop-when" style="color:var(--accent-text)">Pinned</span>'
    : (dated ? '<span class="jrn-loop-when" style="color:'+jrnDueColour(diff)+'">'+escText(jrnDueText(diff,n.dueDate))+'</span>' : '');
  return '<button class="jrn-loop" data-jrn="open" data-id="'+escAttr(n.id)+'">'+
    '<span class="jrn-loop-dot" style="background:'+dot+'"></span>'+
    '<span class="jrn-loop-ttl">'+escText(String(n.title||'').trim()||'Untitled note')+'</span>'+
    right+
  '</button>';
}
// Above the timeline, permanently. This is the whole reason a reminder does not need its own
// destination: you pass it every night on the way to writing.
function jrnLoopsHtml(){
  const q=jrnQ();
  const L=jrnOpenLoops();
  const today=getLocalDate();
  let rows=L.pinned.concat(L.due);
  if(q) rows=rows.filter(r=>jrnMatch(r,q));
  const shown=rows.slice(0,5);
  const total=L.all.length;
  // On desktop this is a compact SECTION of the navigation list, matching Today and the month
  // groups; on the phone it stays the standalone card it has always been. Same markup, and the
  // desktop rules in css/journal.css strip the card surface — one code path, two treatments.
  const dk=jrnIsDesktop();
  let h='<div class="jrn-loops'+(dk?' jrn-sec':'')+'">'+
    '<div class="jrn-loops-hd'+(dk?' jrn-sec-hd':'')+'">'+
      '<span class="jrn-loops-ttl'+(dk?' jrn-sec-ttl':'')+'">Open loops'+(dk&&rows.length?' · '+rows.length:'')+'</span>'+
      (rows.length&&!dk?'<span class="jrn-loops-n">'+rows.length+'</span>':'')+
      '<span class="jrn-loops-act">'+
        (total?'<button class="jrn-loops-btn" data-jrn="tab" data-tab-id="notes">All notes</button>':'')+
        '<button class="jrn-loops-btn" data-jrn="new-note" aria-label="New note">+</button>'+
      '</span>'+
    '</div>';
  if(!shown.length){
    h+='<div class="jrn-loops-empty">'+(total?'Nothing pinned or due.':'Nothing due. Add a reminder with +')+'</div>';
  } else {
    shown.forEach(n=>{ h+=jrnLoopRow(n, today); });
    if(rows.length>shown.length) h+='<button class="jrn-loops-btn" data-jrn="tab" data-tab-id="notes" style="padding-left:2px">'+(rows.length-shown.length)+' more →</button>';
  }
  return h+'</div>';
}
function jrnEntryCard(r, today){
  const title=String(r.title||'').trim();
  const body=String(r.body||'');
  const chips=[];
  if(r.mood) chips.push('<span class="jrn-chip mood">'+escText(jrnMoodLabel(r.mood))+'</span>');
  (Array.isArray(r.tags)?r.tags:[]).forEach(t=>chips.push('<span class="jrn-chip">'+escText(t)+'</span>'));
  const t=jrnTimeOf(r);
  return '<button class="jrn-entry'+(jrnSelId===r.id?' sel':'')+'" data-jrn="open" data-id="'+escAttr(r.id)+'">'+
    (title?'<div class="jrn-entry-ttl">'+escText(title)+'</div>':'')+
    (body?'<div class="jrn-entry-body">'+escText(body)+'</div>':(title?'':'<div class="jrn-entry-body" style="color:var(--muted)">Empty entry</div>'))+
    ((chips.length||t)?'<div class="jrn-entry-foot">'+chips.join('')+(t?'<span class="jrn-time" style="margin-left:auto">'+escText(t)+'</span>':'')+'</div>':'')+
  '</button>';
}
function jrnTimelineHtml(){
  const q=jrnQ();
  const today=getLocalDate();
  let list=jrnEntries();
  if(q) list=list.filter(r=>jrnMatch(r,q));
  if(!list.length){
    return '<div class="jrn-empty">'+
      '<div class="jrn-empty-ttl">'+(q?'No entries match':'No entries yet')+'</div>'+
      '<div class="jrn-empty-sub">'+(q?'Try a different word, or check All notes.':'Tap the card above to write about today. Entries are grouped by the day they are about.')+'</div>'+
    '</div>';
  }
  // Desktop groups by MONTH and renders flat rows carrying their own date, because a per-day
  // sub-heading above every one-entry day turns a navigation list into a stack of headings.
  // The phone keeps its day headings above entry cards.
  if(jrnIsDesktop()){
    let h='', lastMonth='', open=false;
    // Today already has its own section at the top of the list; leaving it in the month groups
    // as well listed the same entry twice, three rows apart. While a search is running there
    // is no Today section, so nothing is withheld.
    const groups=jrnGroupByDay(list).filter(g=>q||jrnTab!=='timeline'||g.date!==today);
    groups.forEach(g=>{
      const mon=g.date.slice(0,7);
      if(mon!==lastMonth){
        if(open) h+='</section>';
        h+='<section class="jrn-sec"><div class="jrn-sec-hd"><span class="jrn-sec-ttl">'+escText(jrnMonthLabel(g.date))+'</span></div>';
        lastMonth=mon; open=true;
      }
      const diff=notesDayDiff(g.date, today);
      const label = diff===0?'Today' : diff===-1?'Yesterday' : jrnLongDay(g.date);
      g.items.forEach(r=>{ h+=jrnEntryRow(r, label); });
    });
    return h+(open?'</section>':'');
  }
  let h='', lastMonth='';
  jrnGroupByDay(list).forEach(g=>{
    const mon=g.date.slice(0,7);
    if(mon!==lastMonth){ h+='<div class="jrn-month">'+escText(jrnMonthLabel(g.date))+'</div>'; lastMonth=mon; }
    const diff=notesDayDiff(g.date, today);
    const name = diff===0?'Today' : diff===-1?'Yesterday' : '';
    h+='<div class="jrn-day">'+
      (name?'<span class="jrn-day-name">'+name+'</span>':'')+
      '<span class="jrn-day-date">'+escText(jrnLongDay(g.date))+'</span>'+
      (g.items.length>1?'<span class="jrn-day-n">'+g.items.length+' entries</span>':'')+
    '</div>';
    g.items.forEach(r=>{ h+=jrnEntryCard(r, today); });
  });
  return h;
}
function jrnNotesListHtml(){
  const q=jrnQ();
  const L=jrnOpenLoops();
  const today=getLocalDate();
  const sec=(label, arr)=>{
    let a = q ? arr.filter(r=>jrnMatch(r,q)) : arr;
    if(!a.length) return '';
    return '<div class="jrn-month">'+escText(label)+'</div><div class="jrn-loops">'+a.map(n=>jrnLoopRow(n,today)).join('')+'</div>';
  };
  const h = sec('Pinned', L.pinned)+sec('Due soon', L.due)+sec('Later', L.later)+sec('No date', L.undated);
  if(h) return h;
  return '<div class="jrn-empty">'+
    '<div class="jrn-empty-ttl">'+(q?'No notes match':'No notes yet')+'</div>'+
    '<div class="jrn-empty-sub">'+(q?'Try a different word.':'Notes are reminders, expiry dates and reference material — the things you need to see again, not the things you did.')+'</div>'+
  '</div>';
}
function jrnTrashHtml(){
  const t=jrnTrash();
  if(!t.length){
    return '<div class="jrn-empty"><div class="jrn-empty-ttl">Trash is empty</div>'+
      '<div class="jrn-empty-sub">Deleted entries and notes stay here for 30 days.</div></div>';
  }
  const now=Date.now();
  return '<div class="jrn-loops">'+t.map(r=>{
    const days=Math.max(0, 30-Math.floor((now-r.deletedAt)/86400000));
    return '<div class="jrn-trash-row">'+
      '<span class="jrn-trash-ttl">'+escText(String(r.title||'').trim()||String(r.body||'').trim().split('\n')[0]||'Untitled')+'</span>'+
      '<span class="jrn-trash-when">'+days+'d left</span>'+
      '<button class="jrn-trash-btn" data-jrn="restore" data-id="'+escAttr(r.id)+'">Restore</button>'+
    '</div>';
  }).join('')+'</div>';
}
function jrnBodyHtml(){
  const tab=(id,label)=>'<button class="jrn-pill'+(jrnTab===id?' on':'')+'" data-jrn="tab" data-tab-id="'+id+'">'+label+'</button>';
  const trashN=jrnTrash().length;
  const nav = (jrnTab==='timeline')
    ? ''
    : '<div class="jrn-ed-row" style="margin:2px 0 4px">'+tab('timeline','Timeline')+tab('notes','All notes')+tab('trash','Trash'+(trashN?' ('+trashN+')':''))+'</div>';
  let body;
  if(jrnTab==='notes') body=jrnNotesListHtml();
  else if(jrnTab==='trash') body=jrnTrashHtml();
  else body=jrnTimelineHtml();
  const footer = (jrnTab==='timeline' && trashN)
    ? '<button class="jrn-loops-btn" data-jrn="tab" data-tab-id="trash" style="align-self:flex-start">Trash ('+trashN+')</button>'
    : '';
  return '<div>'+nav+body+footer+'</div>';
}

// ── Jump to a date ──
// Deliberately not the primary browse surface: a calendar optimises for "what happened on the
// 14th", which is the rare question, and it renders every unwritten day as a visible hole.
// Days WITH entries carry a dot; days without are simply undotted, never marked as missed.
let jrnCalMonth=null;
function jrnOpenCal(){
  jrnCalMonth=jrnCalMonth||getLocalDate().slice(0,7);
  const box=document.getElementById('paste-restore-box');
  const ov=document.getElementById('paste-restore-overlay');
  if(!box||!ov) return;
  if(ov.parentElement!==document.body) document.body.appendChild(ov);
  ov.classList.add('jrn-sheet');
  box.innerHTML=
    '<div class="modal-header">'+
      '<button class="back-btn" data-back="jrnCloseCal" aria-label="Back">'+(typeof BACK_CHEVRON!=='undefined'?BACK_CHEVRON:'&#8249;')+'</button>'+
      '<div class="modal-title">Jump to a date</div>'+
    '</div>'+
    '<div class="modal-body"><div id="jrn-cal-body"></div></div>';
  ov.classList.remove('hidden');
  jrnRenderCal();
}
function jrnCloseCal(){ const o=document.getElementById('paste-restore-overlay'); if(o){ o.classList.add('hidden'); o.classList.remove('jrn-sheet'); } }
function jrnCalShift(n){
  const [y,m]=jrnCalMonth.split('-').map(Number);
  const d=new Date(y, m-1+n, 1);
  jrnCalMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
  jrnRenderCal();
}
function jrnRenderCal(){
  const el=document.getElementById('jrn-cal-body'); if(!el) return;
  const [y,m]=jrnCalMonth.split('-').map(Number);
  const first=new Date(y, m-1, 1);
  const days=new Date(y, m, 0).getDate();
  const lead=(first.getDay()+6)%7;            // Monday-first
  const counts={};
  jrnEntries().forEach(r=>{ const d=jrnEntryDay(r); counts[d]=(counts[d]||0)+1; });
  const today=getLocalDate();
  let cells='';
  for(let i=0;i<lead;i++) cells+='<button class="jrn-cal-day blank" disabled aria-hidden="true"></button>';
  for(let d=1;d<=days;d++){
    const ds=y+'-'+String(m).padStart(2,'0')+'-'+String(d).padStart(2,'0');
    const n=counts[ds]||0;
    const cls='jrn-cal-day'+(n?' has':'')+(ds===today?' today':'');
    const lbl=n?(n+' entr'+(n===1?'y':'ies')+' on '+jrnLongDay(ds)):jrnLongDay(ds);
    cells+='<button class="'+cls+'" '+(n?'data-jrn="cal-pick" data-date="'+ds+'"':'disabled')+' aria-label="'+escAttr(lbl)+'">'+
      '<span>'+d+'</span><span class="jrn-cal-dot'+(n?'':' none')+'"></span></button>';
  }
  const dow=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>'<div class="jrn-cal-dow">'+x+'</div>').join('');
  el.innerHTML='<div class="jrn-cal">'+
    '<div class="jrn-cal-hd">'+
      '<button class="jrn-cal-nav" data-jrn="cal-prev" aria-label="Previous month">‹</button>'+
      '<div class="jrn-cal-mon">'+escText(jrnMonthLabel(jrnCalMonth+'-01'))+'</div>'+
      '<button class="jrn-cal-nav" data-jrn="cal-next" aria-label="Next month">›</button>'+
    '</div>'+
    '<div class="jrn-cal-grid">'+dow+cells+'</div>'+
    '<div class="jrn-cal-note">Dotted days have entries. Days without one are simply days you did not write — nothing is missing.</div>'+
  '</div>';
}
function jrnJumpTo(ds){
  jrnCloseCal();
  jrnQuery=''; jrnSearchOpen=false; jrnTab='timeline';
  renderJournal();
  const first=jrnEntries().filter(r=>jrnEntryDay(r)===ds)
    .sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0))[0];
  if(first) jrnOpenEditor(first.id);
}

// ── The editor ──
let jrnEdId=null, jrnEdPending=null, jrnEdTimer=null, jrnEdStatusTimer=null, jrnEdTagsOpen=false;
function jrnEdRec(){
  if(!jrnEdId) return null;
  return loadNotes().find(r=>r.id===jrnEdId) || jrnEdPending || null;
}
function jrnEdStatus(txt){
  const el=document.getElementById('jrn-ed-status'); if(!el) return;
  clearTimeout(jrnEdStatusTimer);
  el.textContent=txt; el.style.opacity='1';
  // Fades rather than sitting there: a permanent "Saved" badge is noise, and a "Saving…"
  // that appears on every keystroke is a flicker.
  jrnEdStatusTimer=setTimeout(()=>{ el.style.opacity='0'; }, 1400);
}
// Loading the editor's FIELDS is separated from PRESENTING it, because the desktop pane has to
// be filled from inside renderJournal() (which is what draws the pane) and cannot re-enter it.
// Returns false if the id no longer resolves.
function jrnLoadEditor(id, kind){
  const rec = id ? loadNotes().find(r=>r.id===id&&!r.deletedAt) : null;
  if(id && !rec) return false;
  jrnEdTagsOpen=false;
  if(rec){ jrnEdId=rec.id; jrnEdPending=null; }
  else {
    // Not persisted until it has content — this is what stops "open and back out" leaving a
    // blank record behind, which the old editor did on every fullscreen jump. It is also what
    // makes the desktop "always open today" default safe: merely LOOKING at Journal builds
    // this object in memory and writes nothing.
    const fresh=jrnNewRecord(kind==='note'?'note':'entry');
    if(fresh.kind==='entry') fresh.dateAbout=getLocalDate();
    jrnEdId=fresh.id; jrnEdPending=fresh;
  }
  const r=jrnEdRec();
  const ed=document.getElementById('jrn-editor'); if(!ed) return false;
  const t=document.getElementById('jrn-ed-title'), b=document.getElementById('jrn-ed-body');
  const isEntry=r.kind==='entry';
  // The kind word ("Entry") told you nothing you could not see; the DATE is what a reader of
  // an open entry actually needs, and it is the heading in the desktop pane's own layout.
  document.getElementById('jrn-ed-kind').textContent =
    isEntry ? jrnLongDay(r.dateAbout||getLocalDate()) : 'Note';
  // "How was today?" is the prompt, so it belongs on the writing surface rather than on a
  // small card in the list column.
  t.placeholder=isEntry?'How was today?':'Title';
  b.placeholder=isEntry?'Write about your day…':'Details';
  t.value=String(r.title||'');
  b.value=String(r.body||'');
  const del=document.getElementById('jrn-ed-del');
  if(del) del.style.display = rec ? '' : 'none';
  jrnEdRenderFoot();
  jrnRenderDayContext();
  jrnEdStatus('');
  const status=document.getElementById('jrn-ed-status'); if(status) status.style.opacity='0';
  return true;
}
function jrnOpenEditor(id, kind){
  const existed = !!(id && loadNotes().find(r=>r.id===id&&!r.deletedAt));
  if(!jrnLoadEditor(id, kind)) return;
  const ed=document.getElementById('jrn-editor');
  if(jrnIsDesktop()){
    jrnSelId=jrnEdId;
    renderJournal();
  } else if(ed){
    ed.classList.remove('inline');
    ed.classList.add('open');
    jrnEdSyncViewport();
  }
  // A new entry goes straight to the body: the title is optional and asking for one first is
  // how a nightly habit dies.
  const isEntry=(jrnEdRec()||{}).kind==='entry';
  setTimeout(()=>{
    const bb=document.getElementById('jrn-ed-body');
    const tt=document.getElementById('jrn-ed-title');
    if(!existed && isEntry && bb) bb.focus();
    else if(!existed && !isEntry && tt) tt.focus();
  }, 60);
}
// Desktop opens editor-first: today's entry if there is one, otherwise a ready-to-write
// surface for today. Nothing is stored until the first meaningful edit (see jrnEdWrite and
// jrnEdPatch), so arriving on the screen never leaves a blank entry behind.
// Runs BEFORE the pane is drawn, and deliberately never calls renderJournal itself.
function jrnEnsureDesktopSelection(){
  if(!jrnIsDesktop()) return;
  if(jrnEdId && !jrnSelId) jrnSelId=jrnEdId;
  if(jrnSelId){
    const live = loadNotes().find(r=>r.id===jrnSelId&&!r.deletedAt)
      || ((jrnEdPending && jrnEdPending.id===jrnSelId) ? jrnEdPending : null);
    if(live && jrnEdId===jrnSelId) return;      // an open editor is never reloaded under the user
    if(live){ if(jrnLoadEditor(jrnSelId)) return; }
  }
  const today=getLocalDate();
  const mine=jrnEntries().filter(r=>jrnEntryDay(r)===today)
    .sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0));
  if(jrnLoadEditor(mine.length?mine[0].id:null, 'entry')) jrnSelId=jrnEdId;
}
function jrnEdRenderFoot(){
  const foot=document.getElementById('jrn-ed-foot'); if(!foot) return;
  const r=jrnEdRec(); if(!r){ foot.innerHTML=''; return; }
  const today=getLocalDate();
  let h='';
  if(r.kind==='entry'){
    const about=r.dateAbout||today;
    const y=localMidnight(today); y.setDate(y.getDate()-1);
    const yStr=dateStr(y);
    h+='<div class="jrn-ed-row">'+
      '<span class="jrn-ed-lbl">Date</span>'+
      '<button class="jrn-pill'+(about===today?' on':'')+'" data-jrn="ed-date" data-date="'+today+'">Today</button>'+
      '<button class="jrn-pill'+(about===yStr?' on':'')+'" data-jrn="ed-date" data-date="'+yStr+'">Yesterday</button>'+
      '<input type="date" class="jrn-ed-date" id="jrn-ed-about" value="'+escAttr(about)+'" max="'+today+'" aria-label="Date this entry is about">'+
    '</div>';
    h+='<div class="jrn-ed-row">'+
      '<span class="jrn-ed-lbl">Mood</span>'+
      JRN_MOODS.map(m=>'<button class="jrn-pill'+(r.mood===m.v?' on':'')+'" data-jrn="ed-mood" data-mood="'+m.v+'" aria-pressed="'+(r.mood===m.v?'true':'false')+'">'+m.label+'</button>').join('')+
      (r.mood?'<button class="jrn-ed-more" data-jrn="ed-mood" data-mood="0">Clear</button>':'')+
    '</div>';
    const tags=(Array.isArray(r.tags)?r.tags:[]).filter(t=>t!=='work'&&t!=='personal');
    if(jrnEdTagsOpen||tags.length){
      h+='<div class="jrn-ed-row">'+
        '<span class="jrn-ed-lbl">Tags</span>'+
        tags.map(t=>'<button class="jrn-pill on" data-jrn="ed-untag" data-tag="'+escAttr(t)+'" aria-label="Remove tag '+escAttr(t)+'">'+escText(t)+' ×</button>').join('')+
        '<input class="jrn-tag-in" id="jrn-ed-tag" placeholder="Add a tag, then Enter" aria-label="Add a tag" autocomplete="off">'+
      '</div>';
    } else {
      h+='<div class="jrn-ed-row"><button class="jrn-ed-more" data-jrn="ed-tags-open">+ Add tags</button></div>';
    }
  } else {
    const type=(Array.isArray(r.tags)&&r.tags.indexOf('work')>=0)?'work':'personal';
    h+='<div class="jrn-ed-row">'+
      '<span class="jrn-ed-lbl">Type</span>'+
      '<button class="jrn-pill'+(type==='personal'?' on':'')+'" data-jrn="ed-type" data-type="personal">Personal</button>'+
      '<button class="jrn-pill'+(type==='work'?' on':'')+'" data-jrn="ed-type" data-type="work">Work</button>'+
    '</div>';
    const dt=r.dateType||'none';
    h+='<div class="jrn-ed-row">'+
      '<span class="jrn-ed-lbl">Date</span>'+
      '<button class="jrn-pill'+(dt==='none'?' on':'')+'" data-jrn="ed-dtype" data-dtype="none">No date</button>'+
      '<button class="jrn-pill'+(dt==='reminder'?' on':'')+'" data-jrn="ed-dtype" data-dtype="reminder">Reminder</button>'+
      '<button class="jrn-pill'+(dt==='expiry'?' on':'')+'" data-jrn="ed-dtype" data-dtype="expiry">Expiry</button>'+
      (dt!=='none'?'<input type="date" class="jrn-ed-date" id="jrn-ed-due" value="'+escAttr(r.dueDate||'')+'" aria-label="Due date">':'')+
    '</div>';
  }
  foot.innerHTML=h;
  const pin=document.getElementById('jrn-ed-pin');
  if(pin){ pin.classList.toggle('on', !!r.pinned); pin.setAttribute('aria-pressed', r.pinned?'true':'false'); }
  jrnRenderDayContext();
}
// Metadata is a discrete action, so it writes immediately; only typing is debounced.
// On a record that has never been stored the patch normally stays in memory — but picking a
// mood or adding a tag IS the user saying something about the day, and losing it because they
// hadn't typed a sentence yet would be a silent data loss. Those promote the pending record
// into storage; the ones that only describe an empty shell (which day it is about, whether it
// is a reminder) do not, or the desktop's default-to-today editor would save a blank entry
// the moment anything touched its date.
const JRN_MEANINGFUL_KEYS=['mood','tags','pinned','title','body'];
function jrnEdPatch(patch){
  if(!jrnEdId) return;
  const stored=loadNotes().find(r=>r.id===jrnEdId);
  if(stored){ jrnPut(Object.assign({}, stored, patch)); }
  else {
    jrnEdPending=jrnNormalise(Object.assign({}, jrnEdPending||{}, patch));
    const meaningful=Object.keys(patch).some(k=>JRN_MEANINGFUL_KEYS.indexOf(k)>=0);
    // A tags patch that empties the list is a removal, not a statement — don't let it be the
    // thing that creates the record.
    const hasSubstance = jrnEdPending.mood
      || (Array.isArray(jrnEdPending.tags) && jrnEdPending.tags.filter(t=>t!=='work'&&t!=='personal').length)
      || jrnEdPending.pinned
      || String(jrnEdPending.title||'').trim()
      || String(jrnEdPending.body||'').trim();
    if(meaningful && hasSubstance){
      jrnPut(jrnEdPending);
      jrnEdPending=null;
      const del=document.getElementById('jrn-ed-del'); if(del) del.style.display='';
      jrnEdStatus('Saved');
    }
  }
  jrnEdRenderFoot();
  jrnRefreshLists();
}
function jrnEdWrite(){
  clearTimeout(jrnEdTimer); jrnEdTimer=null;
  if(!jrnEdId) return;
  const t=document.getElementById('jrn-ed-title'), b=document.getElementById('jrn-ed-body');
  if(!t||!b) return;
  const title=t.value.trim(), body=b.value;
  const stored=loadNotes().find(r=>r.id===jrnEdId);
  if(stored){
    if(stored.title===title && stored.body===body) return;   // no-op: don't churn the cloud
    jrnPut(Object.assign({}, stored, {title, body}));
  } else {
    if(!title && !body.trim()) return;
    jrnPut(Object.assign({}, jrnEdPending||{id:jrnEdId}, {title, body}));
    jrnEdPending=null;
    const del=document.getElementById('jrn-ed-del'); if(del) del.style.display='';
  }
  jrnEdStatus('Saved');
  jrnRefreshLists();
}
function jrnEdQueue(){ clearTimeout(jrnEdTimer); jrnEdTimer=setTimeout(jrnEdWrite, 600); }
// iOS suspends a backgrounded PWA without warning, so a debounce is not a promise.
function jrnEdFlush(){ if(jrnEdTimer) jrnEdWrite(); }
function jrnCloseEditor(){
  jrnEdFlush();
  const ed=document.getElementById('jrn-editor');
  if(ed){ ed.classList.remove('open','inline'); ed.style.top=''; ed.style.height=''; ed.style.bottom=''; }
  jrnDetachEditor();
  jrnEdId=null; jrnEdPending=null; jrnSelId=null;
  jrnListsDirty=false;
  renderJournal();
  if(typeof renderHomeNotesBubble==='function') renderHomeNotesBubble();
}
function jrnEdDelete(){
  const r=jrnEdRec(); if(!r) return;
  if(!loadNotes().find(x=>x.id===r.id)){ jrnCloseEditor(); return; }   // never persisted
  const label=String(r.title||'').trim();
  const what=r.kind==='entry'?'entry':'note';
  if(!confirm('Move '+(label?'“'+label+'”':'this '+what)+' to Trash?\n\nYou can restore it for 30 days.')) return;
  jrnDelete(r.id);
  jrnCloseEditor();
}
function jrnEdCopy(){
  const t=document.getElementById('jrn-ed-title'), b=document.getElementById('jrn-ed-body');
  const text=((t&&t.value.trim())?t.value.trim()+'\n\n':'')+((b&&b.value)||'');
  const done=()=>jrnEdStatus('Copied');
  try{
    if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(text).then(done,()=>{}); return; }
  }catch(e){}
  try{
    const ta=document.createElement('textarea'); ta.value=text; ta.style.position='fixed'; ta.style.opacity='0';
    document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); done();
  }catch(e){}
}
// The keyboard covers a fixed-bottom footer on iOS. Sizing the editor to visualViewport keeps
// the metadata row reachable instead of buried, and avoids dvh, which mis-computes at cold
// launch in a standalone PWA (see CLAUDE.md).
function jrnEdSyncViewport(){
  const ed=document.getElementById('jrn-editor');
  if(!ed || !ed.classList.contains('open') || ed.classList.contains('inline')) return;
  const vv=window.visualViewport;
  if(!vv){ ed.style.top=''; ed.style.height=''; ed.style.bottom=''; return; }
  ed.style.top=vv.offsetTop+'px';
  ed.style.height=vv.height+'px';
  ed.style.bottom='auto';
}
if(window.visualViewport){
  window.visualViewport.addEventListener('resize', jrnEdSyncViewport);
  window.visualViewport.addEventListener('scroll', jrnEdSyncViewport);
}
document.addEventListener('visibilitychange',function(){ if(document.visibilityState==='hidden') jrnEdFlush(); });
window.addEventListener('pagehide', jrnEdFlush);
let _jrnResizeT=null;
window.addEventListener('resize',function(){
  clearTimeout(_jrnResizeT);
  _jrnResizeT=setTimeout(function(){
    const view=(typeof S==='object')?S.view:'';
    if(view!=='notes') return;
    // Crossing the desktop boundary swaps the editor between overlay and detail column.
    if(jrnEdId && jrnIsDesktop()){ jrnSelId=jrnEdId; }
    renderJournal();
    if(jrnEdId && !jrnIsDesktop()){
      const ed=document.getElementById('jrn-editor');
      if(ed){ ed.classList.remove('inline'); ed.classList.add('open'); }
      jrnEdSyncViewport();
    }
  }, 160);
});

// ── Events ──
document.addEventListener('input',function(e){
  const t=e.target; if(!t||!t.id) return;
  if(t.id==='jrn-ed-title'||t.id==='jrn-ed-body'){ jrnEdQueue(); return; }
  if(t.id==='jrn-search'){ jrnQuery=t.value; jrnRefreshListsKeepFocus(); return; }
});
document.addEventListener('change',function(e){
  const t=e.target; if(!t||!t.id) return;
  if(t.id==='jrn-ed-about'){ jrnEdPatch({dateAbout:t.value||getLocalDate()}); return; }
  if(t.id==='jrn-ed-due'){ jrnEdPatch({dueDate:t.value||''}); return; }
});
document.addEventListener('keydown',function(e){
  if(e.target&&e.target.id==='jrn-ed-tag'&&e.key==='Enter'){
    e.preventDefault();
    const v=e.target.value.trim().replace(/^#/,'');
    if(!v) return;
    const r=jrnEdRec(); if(!r) return;
    const tags=(Array.isArray(r.tags)?r.tags.slice():[]);
    if(tags.indexOf(v)<0) tags.push(v);
    e.target.value='';
    jrnEdPatch({tags});
  }
});
// Search re-renders the lists but must not steal the caret back from the field being typed in.
function jrnRefreshListsKeepFocus(){
  const wrap=document.getElementById('notes-content'); if(!wrap) return;
  const s=document.getElementById('jrn-search');
  const pos=s?s.selectionStart:null;
  renderJournal();
  const s2=document.getElementById('jrn-search');
  if(s2){ s2.focus(); if(pos!=null){ try{ s2.setSelectionRange(pos,pos); }catch(e){} } }
}
document.addEventListener('click',function(e){
  if(!e.target||!e.target.closest) return;
  const el=e.target.closest('[data-jrn]'); if(!el) return;
  const act=el.getAttribute('data-jrn');
  const id=el.getAttribute('data-id');
  if(act==='new-entry'){ jrnOpenEditor(null,'entry'); return; }
  if(act==='new-note'){ jrnOpenEditor(null,'note'); return; }
  if(act==='open'&&id){ jrnOpenEditor(id); return; }
  if(act==='restore'&&id){ jrnRestore(id); jrnRefreshLists(); return; }
  if(act==='tab'){ jrnTab=el.getAttribute('data-tab-id')||'timeline'; renderJournal(); return; }
  if(act==='search-toggle'){ jrnSearchOpen=!jrnSearchOpen; if(!jrnSearchOpen) jrnQuery=''; renderJournal();
    if(jrnSearchOpen){ const s=document.getElementById('jrn-search'); if(s) s.focus(); } return; }
  if(act==='search-clear'){ jrnQuery=''; jrnRefreshListsKeepFocus(); return; }
  if(act==='cal'){ jrnOpenCal(); return; }
  if(act==='cal-prev'){ jrnCalShift(-1); return; }
  if(act==='cal-next'){ jrnCalShift(1); return; }
  if(act==='cal-pick'){ jrnJumpTo(el.getAttribute('data-date')); return; }
  if(act==='reflect'){ jrnOpenReflection(); return; }
  if(act==='reflect-write'){ jrnStartReflection(); return; }
  if(act==='day-source'){ jrnOpenDaySource(el.getAttribute('data-source'),el.getAttribute('data-date')); return; }
  if(act==='ed-date'){ jrnEdPatch({dateAbout:el.getAttribute('data-date')}); return; }
  if(act==='ed-mood'){ const v=parseInt(el.getAttribute('data-mood'),10); jrnEdPatch({mood:v>0?v:null}); return; }
  if(act==='ed-tags-open'){ jrnEdTagsOpen=true; jrnEdRenderFoot();
    const i=document.getElementById('jrn-ed-tag'); if(i) i.focus(); return; }
  if(act==='ed-untag'){
    const r=jrnEdRec(); if(!r) return;
    const tag=el.getAttribute('data-tag');
    jrnEdPatch({tags:(Array.isArray(r.tags)?r.tags:[]).filter(x=>x!==tag)});
    return;
  }
  if(act==='ed-type'){
    const r=jrnEdRec(); if(!r) return;
    const want=el.getAttribute('data-type')==='work'?'work':'personal';
    const keep=(Array.isArray(r.tags)?r.tags:[]).filter(t=>t!=='work'&&t!=='personal');
    jrnEdPatch({tags:keep.concat([want])});
    return;
  }
  if(act==='ed-dtype'){
    const d=el.getAttribute('data-dtype');
    jrnEdPatch(d==='none'?{dateType:'none'}:{dateType:d, dueDate:(jrnEdRec()||{}).dueDate||getLocalDate()});
    return;
  }
});
document.addEventListener('click',function(e){
  if(!e.target||!e.target.closest) return;
  if(e.target.closest('#jrn-ed-pin')){ const r=jrnEdRec(); if(r) jrnEdPatch({pinned:!r.pinned}); return; }
  if(e.target.closest('#jrn-ed-del')){ jrnEdDelete(); return; }
  if(e.target.closest('#jrn-ed-copy')){ jrnEdCopy(); return; }
});

// ── Home card ──
// Its job is the one thing the Journal screen cannot do: get you into the write in one tap from
// the screen you already have open. It deliberately does NOT list note titles — that duplicated
// the destination it links to, which is what made Home feel busy without being informative.
// No streak, no missed-day count, no guilt language.
function buildHomeNotesCard(){
  const today=getLocalDate();
  const mine=jrnEntries().filter(r=>jrnEntryDay(r)===today)
    .sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0));
  const latest=mine[0];
  const L=jrnOpenLoops();
  const rows=L.pinned.concat(L.due).slice(0,3);
  let h='<div class="card">';
  h+='<div style="font-size:13px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:10px">Journal</div>';
  if(latest){
    const line=String(latest.title||'').trim()||String(latest.body||'').trim().split('\n')[0]||'Untitled';
    h+='<button class="jrn-composer" data-jrn-home="open" data-id="'+escAttr(latest.id)+'" style="margin-bottom:'+(rows.length?'10px':'0')+'">'+
      '<div class="jrn-comp-top"><span class="jrn-comp-eyebrow">Today\'s entry</span></div>'+
      '<div class="jrn-comp-line">'+escText(line)+'</div>'+
      (mine.length>1?'<div class="jrn-comp-meta">'+mine.length+' entries today</div>':'')+
    '</button>';
  } else {
    h+='<button class="jrn-composer" data-jrn-home="new" style="margin-bottom:'+(rows.length?'10px':'0')+'">'+
      '<div class="jrn-comp-line is-empty">Write about today →</div>'+
    '</button>';
  }
  if(rows.length){
    rows.forEach(n=>{
      const diff=notesDayDiff(String(n.dueDate||''), today);
      const dated=n.dueDate&&n.dateType!=='none';
      const dot=n.pinned?'var(--accent)':(dated?jrnDueColour(diff):'var(--muted)');
      const right=n.pinned
        ? '<span style="font-size:12px;font-weight:700;color:var(--accent-text)">Pinned</span>'
        : (dated?'<span style="font-size:12px;font-weight:600;color:'+jrnDueColour(diff)+'">'+escText(jrnDueText(diff,n.dueDate))+'</span>':'');
      h+='<button class="jrn-loop" data-jrn-home="open" data-id="'+escAttr(n.id)+'">'+
        '<span class="jrn-loop-dot" style="background:'+dot+'"></span>'+
        '<span class="jrn-loop-ttl">'+escText(String(n.title||'').trim()||'Untitled note')+'</span>'+
        right+
      '</button>';
    });
  } else if(latest){
    h+='<div style="font-size:13px;color:var(--muted);padding-top:2px">Nothing due.</div>';
  } else {
    h+='<div style="font-size:13px;color:var(--muted);padding-top:8px">Nothing due. Nothing written yet today.</div>';
  }
  return h+'</div>';
}
function renderHomeNotesBubble(){
  const el=document.querySelector('#home-content [data-card-id="notes"]');
  if(el) el.innerHTML=buildHomeNotesCard();
}
document.addEventListener('click',function(e){
  if(!e.target||!e.target.closest) return;
  const el=e.target.closest('[data-jrn-home]'); if(!el) return;
  const act=el.getAttribute('data-jrn-home');
  setView('notes');
  if(act==='new') jrnOpenEditor(null,'entry');
  else { const id=el.getAttribute('data-id'); if(id) jrnOpenEditor(id); }
});

// ── Plans ──────────────────────────────────────────────────────────
function renderPlans(){
  const wrap=document.getElementById('plans-content'); if(!wrap) return;
  const data=loadPlans();
  const active=data.plans.find(p=>p.id===data.activePlanId)||data.plans[0]||null;

  const today=getLocalDate();
  if(active && data.streak.lastDate!==today){
    const yesterday=new Date(today); yesterday.setDate(yesterday.getDate()-1);
    const yStr=dateStr(yesterday);
    if(data.streak.lastDate===yStr){
      data.streak.count++;
    } else if(data.streak.lastDate!==today){
      data.streak.count=0;
    }
    data.streak.lastDate=today;
    savePlans(data);
  }

  let html='';

  if(active){
    html+=`<div style="background:linear-gradient(135deg,rgba(var(--accent-rgb),.15),rgba(var(--accent-rgb),.05));border-radius:16px;padding:16px 20px;margin-bottom:16px;display:flex;align-items:center;gap:14px">
      <div style="font-size:32px">🔥</div>
      <div>
        <div style="font-size:24px;font-weight:800;color:var(--accent-text);font-family:var(--font-num)">${data.streak.count} day streak</div>
        <div style="font-size:13px;color:var(--muted)">Active: ${active.name}</div>
      </div>
    </div>`;
  }

  // Saving the current split is the primary action now — it's the only one that produces a
  // program you can actually train, so it leads and the import/export tools follow.
  html+=`<button onclick="plansSaveCurrentAsProgram()" style="width:100%;padding:13px;border-radius:12px;border:none;background:var(--accent);color:#fff;font-size:15px;font-weight:700;margin-bottom:8px">+ Save current split as a program</button>`;
  html+=`<div style="display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap">
    <button onclick="plansImport()" style="flex:1;padding:10px;border-radius:12px;border:1px solid var(--border);background:var(--card);color:var(--text);font-size:13px;font-weight:600">⬆ JSON</button>
    <button onclick="plansImportHTML()" style="flex:1;padding:10px;border-radius:12px;border:1px solid var(--border);background:var(--card);color:var(--text);font-size:13px;font-weight:600">⬆ HTML</button>
    <button onclick="plansExport()" style="flex:1;padding:10px;border-radius:12px;border:1px solid var(--border);background:var(--card);color:var(--text);font-size:13px;font-weight:600">⬇ Export</button>
  </div>`;

  if(!data.plans.length){
    html+=`<div style="text-align:center;padding:60px 20px;color:var(--muted)"><div style="font-size:40px;margin-bottom:12px">🗂️</div><div style="font-size:16px;font-weight:600;margin-bottom:6px;color:var(--text)">No programs yet</div><div style="font-size:14px;line-height:1.5">Save your current training split as a program, then build others and switch between them any time.</div></div>`;
  } else {
    html+=`<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px">${data.plans.map(p=>`<button onclick="plansSetActive('${p.id}')" style="padding:6px 14px;border-radius:20px;border:none;background:${p.id===data.activePlanId?'var(--accent)':'var(--card-2)'};color:${p.id===data.activePlanId?'#fff':'var(--text)'};font-size:13px;font-weight:600">${p.name}</button>`).join('')}</div>`;

    if(active){
      if(planIsProgram(active)){
        // A saved training split: its real days and exercises, plus whether it's the one
        // currently driving the Log.
        const applied=planAppliedState(active)==='active';
        const types=active.cfg.types||[], sched=active.cfg.schedule||[];
        html+=`<div style="background:var(--card);border-radius:16px;padding:16px;margin-bottom:12px">`;
        html+=`<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">
          <div style="font-size:16px;font-weight:700;color:var(--text);flex:1;min-width:0">${_catEscHtml(active.name)}</div>
          ${applied?`<span style="font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;padding:3px 9px;border-radius:999px;background:rgba(var(--accent-rgb),.16);color:var(--accent-text)">Training now</span>`:''}
        </div>`;
        html+=`<div style="font-size:12px;color:var(--muted);margin-bottom:12px">${types.length} day${types.length===1?'':'s'} · ${sched.length}-day rotation</div>`;
        types.forEach((t,i)=>{
          const exs=t.exercises||[];
          html+=`<div style="border-bottom:1px solid var(--border);padding:10px 0">
            <div style="display:flex;align-items:center;gap:8px;margin-bottom:${exs.length?6:0}px">
              <div style="width:32px;height:32px;border-radius:8px;background:rgba(var(--accent-rgb),.12);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:var(--accent-text)">${i+1}</div>
              <div style="font-weight:600;color:var(--text);font-size:14px">${_catEscHtml(t.name||'Day '+(i+1))}</div>
              <div style="margin-left:auto;font-size:12px;color:var(--muted)">${exs.length} ex</div>
            </div>
            ${exs.map(e=>`<div style="padding:3px 0 3px 40px;font-size:13px;color:var(--text-2)">${_catEscHtml(e.name||'')}</div>`).join('')}
          </div>`;
        });
        html+=`</div>`;
        html+=`<button onclick="plansApply('${active.id}')" ${applied?'disabled':''} style="width:100%;padding:13px;border-radius:12px;border:none;background:${applied?'var(--card-2)':'var(--accent)'};color:${applied?'var(--muted)':'#fff'};font-size:15px;font-weight:700;margin-bottom:8px">${applied?'Currently training this':'Switch to this program'}</button>`;
        html+=`<div style="display:flex;gap:8px;margin-bottom:8px">
          <button onclick="plansUpdateFromCurrent('${active.id}')" style="flex:1;padding:10px;border-radius:12px;border:1px solid var(--border);background:transparent;color:var(--text);font-size:13px;font-weight:600">Save current split into this</button>
          <button onclick="plansRename('${active.id}')" style="flex:1;padding:10px;border-radius:12px;border:1px solid var(--border);background:transparent;color:var(--text);font-size:13px;font-weight:600">Rename</button>
        </div>`;
      } else if(active.type==='html'){
        // HTML plan — show open button and a preview description
        html+=`<div style="background:var(--card);border-radius:16px;padding:20px;margin-bottom:12px;text-align:center">
          <div style="font-size:36px;margin-bottom:10px">📄</div>
          <div style="font-size:16px;font-weight:700;margin-bottom:6px;color:var(--text)">${active.name}</div>
          <div style="font-size:13px;color:var(--muted);margin-bottom:16px">HTML plan · tap to open full screen</div>
          <button onclick="plansOpenHTML('${active.id}')" style="width:100%;padding:13px;border-radius:12px;border:none;background:var(--accent);color:#fff;font-size:15px;font-weight:700">Open</button>
        </div>`;
      } else if(!active.days && Array.isArray(active.exercises)){
        // Legacy "daily routine" plan — a flat exercise list, no 7-day grid. Render the list
        // so the plan's real content shows instead of an empty week of rest days.
        html+=`<div style="background:var(--card);border-radius:16px;padding:16px;margin-bottom:12px">`;
        html+=`<div style="font-size:16px;font-weight:700;margin-bottom:${active.description?6:12}px;color:var(--text)">${active.name}</div>`;
        if(active.description) html+=`<div style="font-size:13px;color:var(--muted);margin-bottom:12px">${active.description}</div>`;
        active.exercises.forEach(e=>{
          const detail=e.detail||(e.sets&&e.reps?e.sets+'×'+e.reps:'');
          html+=`<div style="border-bottom:1px solid var(--border);padding:10px 0">
            <div style="font-weight:600;color:var(--text);font-size:14px">${e.name||''}</div>
            ${detail?`<div style="font-size:12px;color:var(--muted);margin-top:2px">${detail}</div>`:''}
          </div>`;
        });
        html+=`</div>`;
      } else {
        // Workout plan — existing 7-day grid
        const dayNames=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
        html+=`<div style="background:var(--card);border-radius:16px;padding:16px;margin-bottom:12px">`;
        html+=`<div style="font-size:16px;font-weight:700;margin-bottom:12px;color:var(--text)">${active.name}</div>`;
        if(active.description) html+=`<div style="font-size:13px;color:var(--muted);margin-bottom:12px">${active.description}</div>`;
        for(let d=0;d<7;d++){
          const day=active.days&&active.days[String(d)];
          const dayLabel=day?.name||dayNames[d];
          const exs=day?.exercises||[];
          const isRest=!exs.length;
          html+=`<div style="border-bottom:1px solid var(--border);padding:10px 0">
            <div style="display:flex;align-items:center;gap:8px;margin-bottom:${isRest?0:6}px">
              <div style="width:32px;height:32px;border-radius:8px;background:${isRest?'var(--card-2)':'rgba(var(--accent-rgb),.12)'};display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:${isRest?'var(--muted)':'var(--accent)'}">${dayNames[d]}</div>
              <div style="font-weight:600;color:${isRest?'var(--muted)':'var(--text)'};font-size:14px">${dayLabel}</div>
            </div>
            ${exs.map(e=>`<div style="padding:4px 0 4px 40px;font-size:13px;color:var(--text)">${e.name}${e.sets&&e.reps?' — '+e.sets+'×'+e.reps:''}</div>`).join('')}
          </div>`;
        }
        html+=`</div>`;
      }
      html+=`<button onclick="plansDelete('${active.id}')" style="width:100%;padding:10px;border-radius:12px;border:1px solid var(--danger);background:transparent;color:var(--danger);font-size:14px;font-weight:600">Delete this plan</button>`;
    }
  }

  wrap.innerHTML=html;
}

// ── Programs ───────────────────────────────────────────────────────
// The Log holds exactly ONE training split (splitCfg). A program is a saved snapshot of that
// split, so Plans can hold many and swap between them — the one job the Log genuinely cannot
// do, and the reason this tab was previously an island: nothing outside it ever read a plan,
// and plansNew() built a seven-day shell with no UI anywhere to put exercises in it.
function planSnapshotSplit(){
  const c=splitCfg();
  return JSON.parse(JSON.stringify({types:c.types||[],schedule:c.schedule||[]}));
}
// Compared as normalised JSON so "is this the program I'm running?" survives key order and
// can also tell you the split has been edited since it was saved.
function planCfgFingerprint(cfg){
  if(!cfg||!Array.isArray(cfg.types)) return '';
  return JSON.stringify({
    types:cfg.types.map(t=>({name:t.name||'',exercises:(t.exercises||[]).map(e=>e.name||'')})),
    schedule:cfg.schedule||[]
  });
}
function planIsProgram(p){ return p&&p.kind==='split'&&p.cfg&&Array.isArray(p.cfg.types); }
function planAppliedState(p){
  if(!planIsProgram(p)) return 'n/a';
  return planCfgFingerprint(p.cfg)===planCfgFingerprint(splitCfg())?'active':'inactive';
}
function plansSaveCurrentAsProgram(){
  const cur=splitCfg();
  if(!cur||!Array.isArray(cur.types)||!cur.types.length){ alert('No training split to save yet.'); return; }
  const name=(prompt('Name this program?', cur.types.length+'-day split')||'').trim();
  if(!name) return;
  const data=loadPlans();
  const id='plan_'+Date.now();
  data.plans.push({id,name,kind:'split',description:'',cfg:planSnapshotSplit(),createdAt:Date.now()});
  data.activePlanId=id;
  savePlans(data);
  renderPlans();
}
// Overwrite a saved program with whatever the split looks like now.
function plansUpdateFromCurrent(id){
  const data=loadPlans();
  const p=data.plans.find(x=>x.id===id); if(!planIsProgram(p)) return;
  if(!confirm('Replace "'+p.name+'" with your current training split?')) return;
  p.cfg=planSnapshotSplit(); p.updatedAt=Date.now();
  savePlans(data);
  renderPlans();
}
// Write a program back into the Log's split. Mirrors the split editor's save path (9417):
// assign, persist, clamp the day index, then re-render the Log.
function plansApply(id){
  const data=loadPlans();
  const p=data.plans.find(x=>x.id===id);
  if(!planIsProgram(p)) return;
  const clean=sanitizeSplit(JSON.parse(JSON.stringify(p.cfg)));
  if(!clean){ alert('That program has no training days saved in it.'); return; }
  if(!confirm('Switch your training split to "'+p.name+'"?\n\nThis changes the days and exercises the Log shows. Your logged sessions and history are not touched.')) return;
  splitConfig=clean;
  saveSplit();
  if(S.dayIdx>=scheduleLen()) S.dayIdx=0;
  p.lastAppliedAt=Date.now();
  savePlans(data);
  if(typeof applyDayColour==='function') applyDayColour();
  if(S.view==='log'&&typeof renderLog==='function') renderLog();
  renderPlans();
  if(typeof showToast==='function') showToast('Now training "'+p.name+'"');
}
function plansRename(id){
  const data=loadPlans();
  const p=data.plans.find(x=>x.id===id); if(!p) return;
  const name=(prompt('Rename program', p.name)||'').trim();
  if(!name) return;
  p.name=name; savePlans(data); renderPlans();
}
function plansSetActive(id){
  const data=loadPlans();
  data.activePlanId=id;
  savePlans(data);
  renderPlans();
}

function plansDelete(id){
  if(!confirm('Delete this plan?')) return;
  const data=loadPlans();
  data.plans=data.plans.filter(p=>p.id!==id);
  if(data.activePlanId===id) data.activePlanId=data.plans[0]?.id||null;
  savePlans(data);
  renderPlans();
}

// plansNew() removed: it created a plan with seven empty days, and no screen anywhere could
// add an exercise to it, so it could only ever produce an empty shell. Programs are captured
// from the real training split now (plansSaveCurrentAsProgram), which is editable in the Log.

function plansImport(){
  const inp=document.createElement('input');
  inp.type='file'; inp.accept='.json';
  inp.onchange=e=>{
    const file=e.target.files[0]; if(!file) return;
    const reader=new FileReader();
    reader.onload=ev=>{
      try{
        const plan=JSON.parse(ev.target.result);
        if(!plan.name||!plan.days) throw new Error('Invalid plan format');
        const data=loadPlans();
        if(!plan.id) plan.id='plan_'+Date.now();
        data.plans=data.plans.filter(p=>p.id!==plan.id);
        data.plans.push(plan);
        if(!data.activePlanId) data.activePlanId=plan.id;
        savePlans(data);
        renderPlans();
      }catch(err){ alert('Import failed: '+err.message); }
    };
    reader.readAsText(file);
  };
  inp.click();
}

function plansImportHTML(){
  const inp=document.createElement('input');
  inp.type='file'; inp.accept='.html,.htm';
  inp.onchange=e=>{
    const file=e.target.files[0]; if(!file) return;
    const name=prompt('Name this plan?', file.name.replace(/\.html?$/i,'').replace(/[-_]/g,' '))||file.name;
    const reader=new FileReader();
    reader.onload=ev=>{
      try{
        const content=ev.target.result;
        const data=loadPlans();
        const id='plan_'+Date.now();
        data.plans.push({id, name, type:'html', content});
        if(!data.activePlanId) data.activePlanId=id;
        savePlans(data);
        renderPlans();
      }catch(err){ alert('Import failed: '+err.message); }
    };
    reader.readAsText(file);
  };
  inp.click();
}

function plansOpenHTML(id){
  const data=loadPlans();
  const plan=data.plans.find(p=>p.id===id);
  if(!plan||plan.type!=='html') return;
  const overlay=document.getElementById('plan-html-overlay');
  const frame=document.getElementById('plan-html-frame');
  const title=document.getElementById('plan-html-title');
  if(!overlay||!frame) return;
  if(title) title.textContent=plan.name;
  frame.srcdoc=plan.content;
  overlay.style.display='flex';
}

function plansCloseHTML(){
  const overlay=document.getElementById('plan-html-overlay');
  const frame=document.getElementById('plan-html-frame');
  if(overlay) overlay.style.display='none';
  if(frame) frame.srcdoc='';
}

function plansExport(){
  const data=loadPlans();
  const active=data.plans.find(p=>p.id===data.activePlanId)||data.plans[0];
  if(!active){ alert('No plan to export'); return; }
  if(active.type==='html'){
    const blob=new Blob([active.content],{type:'text/html'});
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download=active.name.replace(/\s+/g,'_')+'.html';
    a.click();
  } else {
    const blob=new Blob([JSON.stringify(active,null,2)],{type:'application/json'});
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download=active.name.replace(/\s+/g,'_')+'.json';
    a.click();
  }
}

// ── Central viewport lifecycle ─────────────────────────────────────
// ONE owner of "what size is the app, and what size is the keyboard-bound overlay". There
// used to be three partial systems: a --kb-inset custom property that no stylesheet ever
// read, a --txn-kb-inset lift on the expense modal, and pinAppHeight. The expense modal
// could therefore end up sized against a stale inset, and — the reported bug — #app kept
// WebKit's keyboard-reduced fixed-element box after the keyboard closed and the device
// rotated, leaving every tab stopping half way down a landscape screen with black below.
//
// Two rules, and nothing else touches this geometry:
//   1. A keyboard-bound overlay is anchored to the VISUAL viewport (offsetTop, offsetLeft,
//      width and height — not height alone, or it pans sideways when WebKit offsets it).
//   2. Whenever no such overlay is up, #app matches the LAYOUT viewport, with any inline
//      correction from a previous cycle cleared first so nothing stale can survive.

// The overlay that owns the viewport while the keyboard is up. Only the expense modal
// qualifies: every other sheet is short enough for the margin lift above.
function vpKeyboardOverlay(){
  const m=document.getElementById('txn-modal');
  return (m && !m.classList.contains('hidden')) ? m : null;
}
function vpClearOverlayGeometry(m){
  m=m||document.getElementById('txn-modal'); if(!m) return;
  ['top','left','right','bottom','width','height'].forEach(function(p){ m.style.removeProperty(p); });
}
function vpSyncOverlay(){
  const m=vpKeyboardOverlay();
  if(!m){ vpClearOverlayGeometry(); return; }
  const vv=window.visualViewport;
  // Desktop keeps the plain centred sheet; there is no keyboard stealing the viewport there.
  if(!vv || window.innerWidth>=1024){ vpClearOverlayGeometry(m); return; }
  m.style.top=Math.round(vv.offsetTop)+'px';
  m.style.left=Math.round(vv.offsetLeft)+'px';
  m.style.width=Math.round(vv.width)+'px';
  m.style.height=Math.round(vv.height)+'px';
  m.style.right='auto';
  m.style.bottom='auto';
}
let _vpAppPinned=false;
function vpSyncApp(){
  const app=document.getElementById('app'); if(!app) return;
  if(vpKeyboardOverlay()) return;             // the overlay owns geometry while it is up
  // Always hand it back to CSS first: measuring against our own correction would keep a
  // stale height alive forever once one was applied.
  if(_vpAppPinned){ app.style.height=''; app.style.top=''; _vpAppPinned=false; }
  // Two independent reads of the layout viewport. Mid-rotation WebKit updates them at
  // different moments, and pinning an explicit pixel height to whichever one is momentarily
  // stale would freeze the shell at the WRONG size — the exact failure this exists to
  // prevent. When they disagree, do nothing and let CSS's inset:0 hold until they settle.
  const a=Math.round(window.innerHeight), b=Math.round(document.documentElement.clientHeight);
  if(!a||!b||Math.abs(a-b)>2) return;
  const want=Math.max(a,b);
  const r=app.getBoundingClientRect();
  // Only correct the failure that actually happens — a shell SHORTER than the viewport, or
  // one no longer anchored at the top. Never force a width (#app is centre-capped at 480px
  // in portrait), and tolerate a few pixels so URL-bar jitter doesn't start a fight.
  if(want-Math.round(r.height)>4 || Math.abs(Math.round(r.top))>1){
    app.style.top='0px';
    app.style.height=want+'px';
    _vpAppPinned=true;
  }
}
// #swipe-deck is sized in PERCENT by CSS but positioned by a PIXEL transform
// (-idx * panel width), so the two only agree while that measurement is current. iOS fires
// `resize` after `orientationchange` BEFORE it reflows to the new orientation, so the single
// resize handler recomputes the stride from the OLD width and never re-checks — parking the
// deck between two panels, which is the "stuck halfway" screen. Re-assert it whenever the
// measured width actually changes, driven from the settle loop that waits out the rotation.
// Setting the position also writes transition:none, so this recovers a snap that was
// interrupted mid-animation and stranded at a fractional offset.
// How far the active panel is from where it should be — 0 when the deck is correctly paged.
// Checking the OUTCOME rather than trying to detect the cause means the deck self-corrects
// however it got stranded: a stale stride, a snap interrupted mid-animation, or a rotation
// that reported the old orientation's width. Watching for a width *change* did not work,
// because while WebKit is still reporting the old orientation that width is perfectly stable.
function deckMisalignPx(){
  const deck=document.getElementById('swipe-deck'); if(!deck) return 0;
  const main=document.getElementById('app-main'); if(!main) return 0;
  const panel=deck.querySelector('.swipe-panel.deck-active'); if(!panel) return 0;
  return Math.round(panel.getBoundingClientRect().left - main.getBoundingClientRect().left);
}
function vpSyncDeck(){
  if(typeof deckPanelW!=='function'||typeof setDeckPosition!=='function') return;
  if(window.innerWidth>=1024) return;                 // desktop pages via .deck-active
  if(deckDragging||deckRaf||deckSnapH) return;        // a finger or a running snap owns it
  if(Math.abs(deckMisalignPx())<=1) return;           // already where it belongs
  if(typeof deckTextInputMode!=='undefined'&&deckTextInputMode) deckApplyTextInputPosition();
  else setDeckPosition(deckIdx,false);
}
function vpSync(){ vpSyncOverlay(); vpSyncApp(); vpSyncDeck(); swapSyncKeyboard(); if(typeof syncNavPadding==='function') syncNavPadding(); }
// WebKit settles keyboard dismissal and rotation over several frames, and reports the OLD
// orientation's metrics for the first of them. A fixed list of timeouts was guessing when
// that ends and could stop while the numbers were still moving; this watches until the
// measurement stops changing instead. Bounded two ways — three identical frames, or a hard
// cap — so it can never spin. Every pass is idempotent, so a redundant one costs nothing.
let _vpSettleRaf=0, _vpSettleTail=0, _vpSettleUntil=0, _vpSettleSig='', _vpSettleSame=0;
function vpSettleSignature(){
  const app=document.getElementById('app');
  const r=app?app.getBoundingClientRect():{width:0,height:0};
  return [window.innerWidth, window.innerHeight,
    document.documentElement.clientWidth, document.documentElement.clientHeight,
    Math.round(r.width), Math.round(r.height),
    (typeof deckPanelW==='function'?Math.round(deckPanelW()):0)].join('|');
}
function vpSettle(){
  _vpSettleUntil=Date.now()+2000;
  _vpSettleSig=''; _vpSettleSame=0;
  // One late pass regardless of the frame loop: WebKit can deliver a final metric correction
  // after the per-frame readings have already gone quiet.
  clearTimeout(_vpSettleTail);
  _vpSettleTail=setTimeout(vpSync, 350);
  vpSync();
  if(!_vpSettleRaf) _vpSettleRaf=requestAnimationFrame(vpSettleStep);
}
function vpSettleStep(){
  _vpSettleRaf=0;
  vpSync();
  const sig=vpSettleSignature();
  _vpSettleSame = (sig===_vpSettleSig) ? _vpSettleSame+1 : 0;
  _vpSettleSig=sig;
  // "The numbers stopped changing" is NOT sufficient on its own — a stale reading is stable
  // too, which is exactly how the old timer-based settle exited while the deck was still
  // paged to the previous orientation. Require the deck to be genuinely aligned as well.
  const settled = _vpSettleSame>=3 && Math.abs(deckMisalignPx())<=1;
  if(settled || Date.now()>=_vpSettleUntil) return;
  _vpSettleRaf=requestAnimationFrame(vpSettleStep);
}
if(window.visualViewport){
  window.visualViewport.addEventListener('resize', vpSync);
  window.visualViewport.addEventListener('scroll', vpSync);
}
window.addEventListener('resize', vpSettle);
window.addEventListener('orientationchange', vpSettle);
window.addEventListener('pageshow', vpSettle);
// Keyboard dismissal fires focusout but no reliable resize on iOS; this is the transition
// the half-height shell was reproduced from.
document.addEventListener('focusout', function(){ vpSettle(); });
document.addEventListener('visibilitychange', function(){ if(!document.hidden) vpSettle(); });
vpSync();

// Pin as early as possible (deferred script runs before first paint) and on every
// viewport change, so the dvh mis-measurement is corrected without waiting for a rotation.
pinAppHeight();
requestAnimationFrame(function(){ pinAppHeight(); nudgeLayout(); });
window.addEventListener('resize', pinAppHeight);
window.addEventListener('orientationchange', function(){ setTimeout(pinAppHeight,150); });
window.addEventListener('load', function(){ nudgeLayout(); setTimeout(nudgeLayout,300); setTimeout(nudgeLayout,800);
  if(typeof weatherEnsureFresh==='function') weatherEnsureFresh(); });
document.addEventListener('visibilitychange', function(){ if(!document.hidden){ setTimeout(nudgeLayout,80);
  if(typeof weatherEnsureFresh==='function') weatherEnsureFresh(); } });
window.addEventListener('pageshow', function(){ setTimeout(nudgeLayout,80); if(typeof applyLogoDayColour==='function') applyLogoDayColour();
  if(typeof weatherEnsureFresh==='function') weatherEnsureFresh(); });
